-- Canonical wire checks are separate from authorization and full closed-core
-- shape validation. A successful result does not construct or approve a row.
CREATE FUNCTION public.pro273_qualifier_numeric_vector_valid(p_record JSONB,p_kind TEXT) RETURNS BOOLEAN
LANGUAGE plpgsql IMMUTABLE SET search_path=pg_catalog AS $$
DECLARE v_key TEXT; v_required TEXT[]; v_nonnegative TEXT[];
BEGIN
 IF pg_catalog.jsonb_typeof(p_record) IS DISTINCT FROM 'object' THEN RETURN FALSE; END IF;
 IF p_kind='LAYOUT' THEN
  v_required:=ARRAY[]::TEXT[];
  v_nonnegative:=ARRAY['observerOtherBackendBytes','observerOtherSharedBytes','nonQualifierOtherBackendBytes','nonQualifierOtherSharedBytes','qualifierBudgetBackendBytes','qualifierBudgetSharedBytes'];
 ELSIF p_kind='ALLOCATION' THEN
  v_required:=ARRAY['reservedBackendBytes','reservedSharedBytes','reservedTemporaryBytes','maxAllocationBytes','stackBytes','parentBytes','maxInputBytes','maxOutputBytes','concurrency','maxProcessCount','maxBackendCount','maxLaunchAttempts','maxPublicationEvents','maxArenaBodies','maxArenaTokens','maxTempCatalogEvents','maxDurableBytes','timeoutMillis'];
  v_nonnegative:=ARRAY['backendProcessBytes','qualifierRuntimeBytes','launcherSupervisorBytes','retainedParentBytes','driverSocketIpcBytes','inputEvidenceSerializationBytes','primitiveParserCacheBytes','rollbackCleanupBytes','sharedRuntimeBytes'];
 ELSE RETURN FALSE; END IF;
 FOREACH v_key IN ARRAY v_required LOOP
  IF pg_catalog.jsonb_typeof(p_record->v_key) IS DISTINCT FROM 'string' OR COALESCE(p_record->>v_key,'') !~ '^[1-9][0-9]*$' THEN RETURN FALSE; END IF;
 END LOOP;
 FOREACH v_key IN ARRAY v_nonnegative LOOP
  IF pg_catalog.jsonb_typeof(p_record->v_key) IS DISTINCT FROM 'string' OR COALESCE(p_record->>v_key,'') !~ '^(0|[1-9][0-9]*)$' THEN RETURN FALSE; END IF;
 END LOOP;
 RETURN TRUE;
END $$;
REVOKE ALL ON FUNCTION public.pro273_qualifier_numeric_vector_valid(JSONB,TEXT) FROM PUBLIC;

-- A semantic core contains no publisher, capture, trust or charge provenance.
-- This shape check is private and does not authorize publication or funding.
CREATE FUNCTION public.pro273_qualifier_core_valid(p_record JSONB,p_kind TEXT) RETURNS BOOLEAN
LANGUAGE plpgsql IMMUTABLE SET search_path=pg_catalog AS $$
DECLARE v_keys TEXT[]; v_hashes TEXT[]; v_key TEXT; v_from TIMESTAMPTZ; v_until TIMESTAMPTZ;
BEGIN
 IF pg_catalog.jsonb_typeof(p_record) IS DISTINCT FROM 'object' THEN RETURN FALSE; END IF;
 IF p_kind='LAYOUT' THEN
  v_keys:=ARRAY['schemaVersion','physicalIdentity','physicalProofIdentity','physicalEvidenceHash','observerOtherBackendBytes','observerOtherSharedBytes','nonQualifierOtherBackendBytes','nonQualifierOtherSharedBytes','qualifierBudgetBackendBytes','qualifierBudgetSharedBytes','sourceClosureHash','buildClosureHash','installationClosureHash','validFrom','validUntil'];
  v_hashes:=ARRAY['physicalEvidenceHash','sourceClosureHash','buildClosureHash','installationClosureHash'];
  IF p_record->>'schemaVersion' IS DISTINCT FROM 'pro273-qualifier-layout-v1' THEN RETURN FALSE; END IF;
 ELSIF p_kind='ALLOCATION' THEN
  v_keys:=ARRAY['schemaVersion','allocationId','partitionId','physicalIdentity','physicalProofIdentity','layoutCoreHash','controlId','principalOid','principalName','credentialEpoch','launchEpoch','namespace','project','deployment','environment','sourceIdentity','sourceClosureHash','supervisorClosureHash','driverClosureHash','nativeClosureHash','runtimeClosureHash','executableHash','installationClosureHash','host','boot','parentProcessTree','reservedBackendBytes','reservedSharedBytes','reservedTemporaryBytes','maxAllocationBytes','stackBytes','parentBytes','maxInputBytes','maxOutputBytes','concurrency','maxProcessCount','maxBackendCount','maxLaunchAttempts','maxPublicationEvents','maxArenaBodies','maxArenaTokens','maxTempCatalogEvents','maxDurableBytes','timeoutMillis','backendProcessBytes','qualifierRuntimeBytes','launcherSupervisorBytes','retainedParentBytes','driverSocketIpcBytes','inputEvidenceSerializationBytes','primitiveParserCacheBytes','rollbackCleanupBytes','sharedRuntimeBytes','validFrom','validUntil'];
  v_hashes:=ARRAY['layoutCoreHash','sourceClosureHash','supervisorClosureHash','driverClosureHash','nativeClosureHash','runtimeClosureHash','executableHash','installationClosureHash'];
  IF p_record->>'schemaVersion' IS DISTINCT FROM 'pro273-qualifier-allocation-v1' OR COALESCE(p_record->>'principalOid','') !~ '^[1-9][0-9]{0,9}$' OR (p_record->>'principalOid')::NUMERIC>4294967295 OR p_record->>'principalName' IS DISTINCT FROM (p_record->>'principalName')::NAME::TEXT OR p_record->>'namespace'='*' OR p_record->>'project'='*' OR p_record->>'deployment'='*' OR p_record->>'environment'='*' THEN RETURN FALSE; END IF;
 ELSE RETURN FALSE; END IF;
 IF (SELECT pg_catalog.count(*) FROM pg_catalog.jsonb_object_keys(p_record))<>pg_catalog.cardinality(v_keys) OR NOT (p_record ?& v_keys) OR public.pro273_qualifier_numeric_vector_valid(p_record,p_kind) IS DISTINCT FROM TRUE THEN RETURN FALSE; END IF;
 FOREACH v_key IN ARRAY v_keys LOOP
  IF pg_catalog.jsonb_typeof(p_record->v_key) IS DISTINCT FROM 'string' OR COALESCE(p_record->>v_key,'')='' THEN RETURN FALSE; END IF;
 END LOOP;
 FOREACH v_key IN ARRAY v_hashes LOOP IF p_record->>v_key !~ '^[a-f0-9]{64}$' THEN RETURN FALSE; END IF; END LOOP;
 FOREACH v_key IN ARRAY ARRAY['validFrom','validUntil'] LOOP
  IF p_record->>v_key !~ '^[0-9]{4}-[0-9]{2}-[0-9]{2}T[0-9]{2}:[0-9]{2}:[0-9]{2}\.[0-9]{3}Z$' OR pg_catalog.substring(p_record->>v_key,1,4)='0000' OR pg_catalog.to_char((p_record->>v_key)::TIMESTAMPTZ AT TIME ZONE 'UTC','YYYY-MM-DD"T"HH24:MI:SS.MS"Z"') IS DISTINCT FROM p_record->>v_key THEN RETURN FALSE; END IF;
 END LOOP;
 v_from:=(p_record->>'validFrom')::TIMESTAMPTZ;v_until:=(p_record->>'validUntil')::TIMESTAMPTZ;
 RETURN v_until>v_from;
EXCEPTION WHEN OTHERS THEN RETURN FALSE; END $$;
REVOKE ALL ON FUNCTION public.pro273_qualifier_core_valid(JSONB,TEXT) FROM PUBLIC;

-- Called only within the owner-held global/physical critical section. Allocation
-- rows are never filtered by lifecycle: RELEASED and unclaimed remain charged.
CREATE FUNCTION public.pro273_qualifier_assert_baseline(p_physical_identity TEXT) RETURNS VOID
LANGUAGE plpgsql SECURITY DEFINER SET search_path=pg_catalog AS $$
DECLARE v_domain public."Pro262CapacityPhysicalDomain"%ROWTYPE; v_layout public."Pro273QualifierBaselineLayout"%ROWTYPE; v_backend NUMERIC; v_shared NUMERIC; v_observer_backend NUMERIC; v_observer_shared NUMERIC;
BEGIN
 SELECT d.* INTO STRICT v_domain FROM public."Pro262CapacityPhysicalDomain" d WHERE d."physicalIdentity"=p_physical_identity FOR UPDATE NOWAIT;
 SELECT l.* INTO STRICT v_layout FROM public."Pro273QualifierBaselineLayout" l WHERE l."physicalIdentity"=p_physical_identity FOR SHARE NOWAIT;
 IF NOT v_domain."enabled" OR v_layout."physicalProofIdentity" IS DISTINCT FROM v_domain."proofIdentity" OR v_layout."physicalEvidenceHash" IS DISTINCT FROM v_domain."evidenceHash" THEN RAISE EXCEPTION 'SELECTION_UNAVAILABLE'; END IF;
 SELECT COALESCE(pg_catalog.sum(a."reservedBackendBytes"),0),COALESCE(pg_catalog.sum(a."reservedSharedBytes"),0) INTO v_backend,v_shared FROM public."Pro273QualifierAllocation" a WHERE a."physicalIdentity"=p_physical_identity;
 SELECT COALESCE(pg_catalog.sum(o."backendBytes"),0),COALESCE(pg_catalog.sum(o."sharedBytes"),0) INTO v_observer_backend,v_observer_shared FROM public."Pro262CapacityObserverInputReservation" o WHERE o."physicalIdentity"=p_physical_identity;
 IF EXISTS(SELECT 1 FROM public."Pro262CapacityObserverInputReservation" o WHERE o."physicalIdentity"=p_physical_identity AND (o."physicalProofIdentity" IS DISTINCT FROM v_layout."physicalProofIdentity" OR o."otherBaselineBackend" IS DISTINCT FROM v_layout."observerOtherBackendBytes" OR o."otherBaselineShared" IS DISTINCT FROM v_layout."observerOtherSharedBytes")) OR v_backend>v_layout."qualifierBudgetBackendBytes" OR v_shared>v_layout."qualifierBudgetSharedBytes" OR v_observer_backend+v_layout."observerOtherBackendBytes">v_domain."baselineBackend" OR v_observer_shared+v_layout."observerOtherSharedBytes">v_domain."baselineShared" THEN RAISE EXCEPTION 'SELECTION_UNAVAILABLE'; END IF;
END $$;
REVOKE ALL ON FUNCTION public.pro273_qualifier_assert_baseline(TEXT) FROM PUBLIC;

-- Independently qualified nonqualifier baseline. Insertion requires the
-- installation-only bootstrap path and cannot be funded by the target qualifier.
-- Installation-root expectations are independently provisioned and empty by
-- default. They cover the installer itself, not the target control-plane row.
CREATE TABLE public."Pro273ControlPlaneInstallerExpectation" (
 "expectationId" TEXT PRIMARY KEY, "bootstrapKind" TEXT NOT NULL UNIQUE REFERENCES public."Pro262CapacityBootstrapBaseline"("kind") ON UPDATE RESTRICT ON DELETE RESTRICT,
 "physicalIdentity" TEXT NOT NULL REFERENCES public."Pro262CapacityPhysicalDomain"("physicalIdentity") ON UPDATE RESTRICT ON DELETE RESTRICT,
 "physicalProofIdentity" TEXT NOT NULL, "physicalEvidenceHash" TEXT NOT NULL,
 "namespace" TEXT NOT NULL CHECK ("namespace"<>'' AND "namespace"<>'*'), "project" TEXT NOT NULL CHECK ("project"<>'' AND "project"<>'*'),
 "deployment" TEXT NOT NULL CHECK ("deployment"<>'' AND "deployment"<>'*'), "environment" TEXT NOT NULL CHECK ("environment"<>'' AND "environment"<>'*'),
 "kind" TEXT NOT NULL CHECK ("kind"='INSTALLER_ROOT'),
 "installerOid" OID NOT NULL, "installerName" NAME NOT NULL, "installerPid" INTEGER NOT NULL CHECK ("installerPid">0), "installerBackendStart" TIMESTAMPTZ NOT NULL,
 "credentialEpoch" TEXT NOT NULL, "launchEpoch" TEXT NOT NULL, "host" TEXT NOT NULL, "boot" TEXT NOT NULL, "processTree" TEXT NOT NULL, "parentProcessTree" TEXT NOT NULL,
 "sourceClosureHash" TEXT NOT NULL, "installationClosureHash" TEXT NOT NULL,
 "expectedCoreHash" TEXT NOT NULL CHECK ("expectedCoreHash" ~ '^[a-f0-9]{64}$'), "expectedEvidenceHash" TEXT NOT NULL CHECK ("expectedEvidenceHash" ~ '^[a-f0-9]{64}$'),
 "constructorKind" TEXT NOT NULL CHECK ("constructorKind" IN ('CONTROL_PLANE_BASELINE','QUALIFIER_LAYOUT','QUALIFIER_ALLOCATION','RESOURCE_SCHEDULE','INPUT_DOMAIN','INVOCATION_SCHEDULE_GRANT_PAIR','QUALIFIER_DESCRIPTOR')),
 "expectedTargetId" TEXT NOT NULL, "parserAbiVersion" TEXT NOT NULL, "parserSourceClosureHash" TEXT NOT NULL CHECK ("parserSourceClosureHash" ~ '^[a-f0-9]{64}$'),
 "dispatchAttemptId" TEXT NOT NULL UNIQUE, "receiverClosureHash" TEXT NOT NULL CHECK ("receiverClosureHash" ~ '^[a-f0-9]{64}$'),
 "expectedFutureLayoutCoreHash" TEXT NOT NULL CHECK ("expectedFutureLayoutCoreHash" ~ '^[a-f0-9]{64}$'),
 "maxInputBytes" NUMERIC NOT NULL CHECK ("maxInputBytes">0 AND "maxInputBytes"=pg_catalog.trunc("maxInputBytes") AND "maxInputBytes"::TEXT NOT IN ('NaN','Infinity','-Infinity')),
 "maxDepthCapacity" NUMERIC NOT NULL CHECK ("maxDepthCapacity">0 AND "maxDepthCapacity"=pg_catalog.trunc("maxDepthCapacity") AND "maxDepthCapacity"::TEXT NOT IN ('NaN','Infinity','-Infinity')),
 "maxTokenCapacity" NUMERIC NOT NULL CHECK ("maxTokenCapacity">0 AND "maxTokenCapacity"=pg_catalog.trunc("maxTokenCapacity") AND "maxTokenCapacity"::TEXT NOT IN ('NaN','Infinity','-Infinity')),
 "maxDecodedUnits" NUMERIC NOT NULL CHECK ("maxDecodedUnits">0 AND "maxDecodedUnits"=pg_catalog.trunc("maxDecodedUnits") AND "maxDecodedUnits"::TEXT NOT IN ('NaN','Infinity','-Infinity')),
 "maxParserWorkspaceBytes" NUMERIC NOT NULL CHECK ("maxParserWorkspaceBytes">0 AND "maxParserWorkspaceBytes"=pg_catalog.trunc("maxParserWorkspaceBytes") AND "maxParserWorkspaceBytes"::TEXT NOT IN ('NaN','Infinity','-Infinity')),
 "maxDecodedEvidenceBytes" NUMERIC NOT NULL CHECK ("maxDecodedEvidenceBytes">0 AND "maxDecodedEvidenceBytes"=pg_catalog.trunc("maxDecodedEvidenceBytes") AND "maxDecodedEvidenceBytes"::TEXT NOT IN ('NaN','Infinity','-Infinity')),
 "maxOutputBytes" NUMERIC NOT NULL CHECK ("maxOutputBytes">0 AND "maxOutputBytes"=pg_catalog.trunc("maxOutputBytes") AND "maxOutputBytes"::TEXT NOT IN ('NaN','Infinity','-Infinity')),
 "qualifiedNonQualifierBackend" NUMERIC NOT NULL CHECK ("qualifiedNonQualifierBackend">0 AND "qualifiedNonQualifierBackend"=pg_catalog.trunc("qualifiedNonQualifierBackend") AND "qualifiedNonQualifierBackend"::TEXT NOT IN ('NaN','Infinity','-Infinity')),
 "qualifiedNonQualifierShared" NUMERIC NOT NULL CHECK ("qualifiedNonQualifierShared">0 AND "qualifiedNonQualifierShared"=pg_catalog.trunc("qualifiedNonQualifierShared") AND "qualifiedNonQualifierShared"::TEXT NOT IN ('NaN','Infinity','-Infinity')),
 "constructorInputReservationId" TEXT NOT NULL UNIQUE REFERENCES public."Pro262CapacityObserverInputReservation"("reservationId") ON UPDATE RESTRICT ON DELETE RESTRICT DEFERRABLE INITIALLY DEFERRED,
 "constructorInputPhase" TEXT NOT NULL, "sessionClaimId" TEXT NOT NULL, "eventId" TEXT NOT NULL UNIQUE, "trustId" TEXT NOT NULL, "trustGeneration" BIGINT NOT NULL,
 "trustRecordHash" TEXT CHECK ("trustRecordHash" ~ '^[a-f0-9]{64}$'),
 "chargeKind" TEXT NOT NULL, "chargeEventKey" TEXT NOT NULL UNIQUE, "chargeBindingHash" TEXT NOT NULL,
 "validFrom" TIMESTAMPTZ NOT NULL, "validUntil" TIMESTAMPTZ NOT NULL, CHECK ("validUntil">"validFrom"),
 CHECK ("constructorKind"<>'QUALIFIER_DESCRIPTOR' OR ("trustRecordHash" IS NOT NULL AND "bootstrapKind"='SELECTION_QUALIFIER_CONTROL:'||"expectedTargetId")),
 UNIQUE ("expectationId","credentialEpoch","launchEpoch"),
 FOREIGN KEY ("trustId","trustGeneration") REFERENCES public."Pro262CapacityTrust"("trustId","generation") ON UPDATE RESTRICT ON DELETE RESTRICT,
 FOREIGN KEY ("chargeKind","chargeEventKey") REFERENCES public."Pro262CapacityControlCharge"("kind","eventKey") ON UPDATE RESTRICT ON DELETE RESTRICT
);
CREATE TRIGGER "Pro273ControlPlaneInstallerExpectation_immutable" BEFORE UPDATE OR DELETE ON public."Pro273ControlPlaneInstallerExpectation" FOR EACH ROW EXECUTE FUNCTION public.pro273_sel_immutable();
-- Immutable session claim is independently committed before installer launch.
CREATE TABLE public."Pro273InstallerSessionClaim" (
 "sessionClaimId" TEXT PRIMARY KEY, "expectationId" TEXT NOT NULL UNIQUE REFERENCES public."Pro273ControlPlaneInstallerExpectation"("expectationId") ON UPDATE RESTRICT ON DELETE RESTRICT,
 "principalOid" OID NOT NULL, "principalName" NAME NOT NULL, "credentialEpoch" TEXT NOT NULL, "launchEpoch" TEXT NOT NULL,
 "sourceClosureHash" TEXT NOT NULL, "installationClosureHash" TEXT NOT NULL, "receiverClosureHash" TEXT NOT NULL,
 "chargeKind" TEXT NOT NULL, "chargeEventKey" TEXT NOT NULL, "chargeBindingHash" TEXT NOT NULL,
 "creationTransactionId" xid8 NOT NULL, "claimedAt" TIMESTAMPTZ NOT NULL, UNIQUE ("expectationId","sessionClaimId"), UNIQUE ("chargeKind","chargeEventKey"),
 FOREIGN KEY ("chargeKind","chargeEventKey") REFERENCES public."Pro262CapacityControlCharge"("kind","eventKey") ON UPDATE RESTRICT ON DELETE RESTRICT
);
CREATE TRIGGER "Pro273InstallerSessionClaim_immutable" BEFORE UPDATE OR DELETE ON public."Pro273InstallerSessionClaim" FOR EACH ROW EXECUTE FUNCTION public.pro273_sel_immutable();
-- A precommitted one-use dispatch is independent of the constructor it funds.
CREATE TABLE public."Pro273InstallerDispatchAttempt" (
 "attemptId" TEXT PRIMARY KEY, "expectationId" TEXT NOT NULL UNIQUE REFERENCES public."Pro273ControlPlaneInstallerExpectation"("expectationId") ON UPDATE RESTRICT ON DELETE RESTRICT,
 "sessionClaimId" TEXT NOT NULL, "receiverClosureHash" TEXT NOT NULL CHECK ("receiverClosureHash" ~ '^[a-f0-9]{64}$'),
 "inputClaimId" TEXT NOT NULL UNIQUE REFERENCES public."Pro262CapacityObserverInputClaim"("inputClaimId") ON UPDATE RESTRICT ON DELETE RESTRICT,
 "chargeKind" TEXT NOT NULL, "chargeEventKey" TEXT NOT NULL, "chargeBindingHash" TEXT NOT NULL CHECK ("chargeBindingHash" ~ '^[a-f0-9]{64}$'),
 "deliveryChargeKind" TEXT NOT NULL, "deliveryChargeEventKey" TEXT NOT NULL UNIQUE, "deliveryChargeBindingHash" TEXT NOT NULL CHECK ("deliveryChargeBindingHash" ~ '^[a-f0-9]{64}$'),
 "creationTransactionId" xid8 NOT NULL, "claimedAt" TIMESTAMPTZ NOT NULL,
 CHECK (("chargeKind","chargeEventKey") IS DISTINCT FROM ("deliveryChargeKind","deliveryChargeEventKey")),
 FOREIGN KEY ("deliveryChargeKind","deliveryChargeEventKey") REFERENCES public."Pro262CapacityControlCharge"("kind","eventKey") ON UPDATE RESTRICT ON DELETE RESTRICT,
 FOREIGN KEY ("expectationId","sessionClaimId") REFERENCES public."Pro273InstallerSessionClaim"("expectationId","sessionClaimId") ON UPDATE RESTRICT ON DELETE RESTRICT,
 FOREIGN KEY ("chargeKind","chargeEventKey") REFERENCES public."Pro262CapacityControlCharge"("kind","eventKey") ON UPDATE RESTRICT ON DELETE RESTRICT,
 UNIQUE ("chargeKind","chargeEventKey"),
 UNIQUE ("attemptId","expectationId","sessionClaimId","inputClaimId","receiverClosureHash","deliveryChargeKind","deliveryChargeEventKey","deliveryChargeBindingHash")
);
CREATE TRIGGER "Pro273InstallerDispatchAttempt_immutable" BEFORE UPDATE OR DELETE ON public."Pro273InstallerDispatchAttempt" FOR EACH ROW EXECUTE FUNCTION public.pro273_sel_immutable();
-- A delivery reservation is permanent and separately prepaid. It is not a
-- success receipt and never becomes reusable after failure or uncertain I/O.
CREATE TABLE public."Pro273InstallerDelivery" (
 "attemptId" TEXT PRIMARY KEY REFERENCES public."Pro273InstallerDispatchAttempt"("attemptId") ON UPDATE RESTRICT ON DELETE RESTRICT,
 "expectationId" TEXT NOT NULL UNIQUE REFERENCES public."Pro273ControlPlaneInstallerExpectation"("expectationId") ON UPDATE RESTRICT ON DELETE RESTRICT,
 "sessionClaimId" TEXT NOT NULL, "inputClaimId" TEXT NOT NULL UNIQUE REFERENCES public."Pro262CapacityObserverInputClaim"("inputClaimId") ON UPDATE RESTRICT ON DELETE RESTRICT,
 "eventId" TEXT NOT NULL UNIQUE, "receiverClosureHash" TEXT NOT NULL, "chargeKind" TEXT NOT NULL, "chargeEventKey" TEXT NOT NULL, "chargeBindingHash" TEXT NOT NULL,
 "creationTransactionId" xid8 NOT NULL, "createdAt" TIMESTAMPTZ NOT NULL, UNIQUE ("chargeKind","chargeEventKey"),
 FOREIGN KEY ("attemptId","expectationId","sessionClaimId","inputClaimId","receiverClosureHash","chargeKind","chargeEventKey","chargeBindingHash") REFERENCES public."Pro273InstallerDispatchAttempt"("attemptId","expectationId","sessionClaimId","inputClaimId","receiverClosureHash","deliveryChargeKind","deliveryChargeEventKey","deliveryChargeBindingHash") ON UPDATE RESTRICT ON DELETE RESTRICT,
 FOREIGN KEY ("chargeKind","chargeEventKey") REFERENCES public."Pro262CapacityControlCharge"("kind","eventKey") ON UPDATE RESTRICT ON DELETE RESTRICT
);
CREATE TRIGGER "Pro273InstallerDelivery_immutable" BEFORE UPDATE OR DELETE ON public."Pro273InstallerDelivery" FOR EACH ROW EXECUTE FUNCTION public.pro273_sel_immutable();

-- Observation and constructor input are separate permanent reservations.
CREATE TABLE public."Pro273InstallerSlotBinding" (
 "reservationId" TEXT PRIMARY KEY REFERENCES public."Pro262CapacityObserverInputReservation"("reservationId") ON UPDATE RESTRICT ON DELETE RESTRICT,
 "expectationId" TEXT NOT NULL, "credentialEpoch" TEXT NOT NULL, "launchEpoch" TEXT NOT NULL, "phase" TEXT NOT NULL, "expectedEventKey" TEXT NOT NULL,
 "bindingKind" TEXT NOT NULL CHECK ("bindingKind" IN ('INSTALLER_OBSERVATION','INSTALLER_CONSTRUCTOR_INPUT')),
 FOREIGN KEY ("expectationId","credentialEpoch","launchEpoch") REFERENCES public."Pro273ControlPlaneInstallerExpectation"("expectationId","credentialEpoch","launchEpoch") ON UPDATE RESTRICT ON DELETE RESTRICT,
 CHECK ("bindingKind"<>'INSTALLER_OBSERVATION' OR "phase"='INSTALL_PROCESS')
);
CREATE TRIGGER "Pro273InstallerSlotBinding_immutable" BEFORE UPDATE OR DELETE ON public."Pro273InstallerSlotBinding" FOR EACH ROW EXECUTE FUNCTION public.pro273_sel_immutable();
-- Exact protected installer-target registration. This is a predicate over
-- already provisioned rows and is never a claim or a new allocation.
CREATE FUNCTION public.pro273_installer_slot_matches(p_reservation_id TEXT) RETURNS BOOLEAN
LANGUAGE plpgsql SECURITY DEFINER SET search_path=pg_catalog AS $$
DECLARE v_binding public."Pro273InstallerSlotBinding"%ROWTYPE; v_slot public."Pro262CapacityObserverInputReservation"%ROWTYPE;
 v_expected public."Pro273ControlPlaneInstallerExpectation"%ROWTYPE; v_trust public."Pro262CapacityTrust"%ROWTYPE; v_domain public."Pro262CapacityPhysicalDomain"%ROWTYPE; v_now TIMESTAMPTZ; v_global RECORD;
BEGIN
 SELECT b.* INTO STRICT v_binding FROM public."Pro273InstallerSlotBinding" b WHERE b."reservationId"=p_reservation_id;
 SELECT r.* INTO STRICT v_slot FROM public."Pro262CapacityObserverInputReservation" r WHERE r."reservationId"=p_reservation_id;
 SELECT g."physicalIdentity",g."proofIdentity" INTO STRICT v_global FROM public."Pro311ControlDomain" g WHERE g."id"='global-v1' FOR SHARE NOWAIT;
 SELECT d.* INTO STRICT v_domain FROM public."Pro262CapacityPhysicalDomain" d WHERE d."physicalIdentity"=v_global."physicalIdentity" FOR SHARE NOWAIT;
 SELECT t.* INTO STRICT v_trust FROM public."Pro262CapacityTrust" t WHERE (t."trustId",t."generation")=(v_slot."observerTrustId",v_slot."observerTrustGeneration") FOR SHARE NOWAIT;
 SELECT e.* INTO STRICT v_expected FROM public."Pro273ControlPlaneInstallerExpectation" e WHERE (e."expectationId",e."credentialEpoch",e."launchEpoch")=(v_binding."expectationId",v_binding."credentialEpoch",v_binding."launchEpoch") FOR SHARE NOWAIT;
 SELECT b.* INTO STRICT v_binding FROM public."Pro273InstallerSlotBinding" b WHERE b."reservationId"=p_reservation_id FOR SHARE NOWAIT;
 SELECT r.* INTO STRICT v_slot FROM public."Pro262CapacityObserverInputReservation" r WHERE r."reservationId"=p_reservation_id AND (r."observerTrustId",r."observerTrustGeneration")=(v_trust."trustId",v_trust."generation") FOR SHARE NOWAIT;
 v_now:=pg_catalog.clock_timestamp();
 IF NOT v_domain."enabled" OR v_domain."physicalIdentity" IS DISTINCT FROM v_expected."physicalIdentity" OR v_domain."proofIdentity" IS DISTINCT FROM v_global."proofIdentity" OR v_domain."proofIdentity" IS DISTINCT FROM v_expected."physicalProofIdentity" OR v_domain."evidenceHash" IS DISTINCT FROM v_expected."physicalEvidenceHash" OR v_expected."validFrom">v_now OR v_expected."validUntil"<=v_now OR
    v_trust."revoked" OR v_trust."validFrom">v_now OR v_trust."validUntil"<=v_now OR v_slot."physicalIdentity" IS DISTINCT FROM v_domain."physicalIdentity" OR v_slot."physicalProofIdentity" IS DISTINCT FROM v_domain."proofIdentity" OR
    v_slot."record"->>'targetKind' IS DISTINCT FROM 'INSTALLER_ROOT' OR v_slot."record"->>'targetControlKey' IS DISTINCT FROM v_expected."expectationId" OR v_slot."record"->>'targetCredentialEpoch' IS DISTINCT FROM v_expected."credentialEpoch" OR v_slot."record"->>'targetLaunchEpoch' IS DISTINCT FROM v_expected."launchEpoch" OR
    v_binding."phase" IS DISTINCT FROM v_slot."phase" OR v_binding."expectedEventKey" IS DISTINCT FROM v_slot."record"->>'expectedEventKey' OR v_trust."supplierPrincipal" IS DISTINCT FROM v_slot."observerPrincipalName" THEN RETURN FALSE; END IF;
 IF v_binding."bindingKind"='INSTALLER_OBSERVATION' THEN
  RETURN v_binding."phase"='INSTALL_PROCESS' AND v_slot."reservationId"<>v_expected."constructorInputReservationId" AND v_slot."observerPrincipalOid"<>v_expected."installerOid" AND v_trust."purpose"='INSTALL_OBSERVATION' AND v_trust."scope"->>'observerHolderId'=v_slot."baselineAllocationProof" AND v_trust."scope"->'lane'=pg_catalog.jsonb_build_object('namespace',v_expected."namespace",'project',v_expected."project",'deployment',v_expected."deployment",'environment',v_expected."environment",'kind','INSTALLER_ROOT');
 ELSIF v_binding."bindingKind"='INSTALLER_CONSTRUCTOR_INPUT' THEN
  RETURN v_slot."reservationId"=v_expected."constructorInputReservationId" AND v_binding."phase"=v_expected."constructorInputPhase" AND v_binding."expectedEventKey"=v_expected."eventId" AND v_slot."observerPrincipalOid"=v_expected."installerOid" AND v_slot."observerPrincipalName"=v_expected."installerName" AND v_slot."maxInputBytes"<=v_expected."maxInputBytes" AND v_slot."record"->>'observerSourceClosure'=v_expected."sourceClosureHash" AND v_slot."record"->>'observerHost'=v_expected."host" AND v_slot."record"->>'observerBoot'=v_expected."boot" AND v_slot."record"->>'observerProcessTree'=v_expected."processTree" AND v_slot."record"->>'observerCredentialEpoch'=v_expected."credentialEpoch" AND v_slot."record"->>'observerLaunchEpoch'=v_expected."launchEpoch" AND v_slot."record"->>'observerBackendPid'=v_expected."installerPid"::TEXT AND (v_slot."record"->>'observerBackendStart')::TIMESTAMPTZ=v_expected."installerBackendStart" AND v_trust."purpose"='CONTROL_ALLOCATOR' AND (CASE WHEN v_expected."constructorKind"='QUALIFIER_DESCRIPTOR' THEN CASE WHEN pg_catalog.jsonb_typeof(v_trust."scope")='object' AND (SELECT pg_catalog.count(*) FROM pg_catalog.jsonb_object_keys(v_trust."scope"))=3 AND v_trust."scope" ?& ARRAY['kind','inputEnvelope','inputBound'] AND pg_catalog.jsonb_typeof(v_trust."scope"->'kind')='string' AND v_trust."scope"->>'kind'='INSTALLER_CONSTRUCTOR_INPUT' AND pg_catalog.jsonb_typeof(v_trust."scope"->'inputEnvelope')='string' AND COALESCE(v_trust."scope"->>'inputEnvelope','')<>'' AND v_trust."scope"->>'inputEnvelope'=v_slot."baselineAllocationProof" AND pg_catalog.jsonb_typeof(v_trust."scope"->'inputBound')='string' AND COALESCE(v_trust."scope"->>'inputBound','') ~ '^[1-9][0-9]{0,18}$' THEN (v_trust."scope"->>'inputBound')::NUMERIC<=9223372036854775807 AND v_slot."maxInputBytes"<=(v_trust."scope"->>'inputBound')::NUMERIC ELSE FALSE END ELSE v_trust."scope"=pg_catalog.jsonb_build_object('kind','INSTALLER_CONSTRUCTOR_INPUT') END);
 END IF;
 RETURN FALSE;
EXCEPTION WHEN OTHERS THEN RETURN FALSE; END $$;
REVOKE ALL ON FUNCTION public.pro273_installer_slot_matches(TEXT) FROM PUBLIC;

CREATE TABLE public."Pro273InstallerProcessObservation" (
 "expectationId" TEXT NOT NULL, "credentialEpoch" TEXT NOT NULL, "launchEpoch" TEXT NOT NULL, "observationId" TEXT NOT NULL UNIQUE, "receiptId" TEXT NOT NULL UNIQUE,
 "trustId" TEXT NOT NULL, "trustGeneration" BIGINT NOT NULL, "inputClaimId" TEXT NOT NULL UNIQUE REFERENCES public."Pro262CapacityObserverInputClaim"("inputClaimId") ON UPDATE RESTRICT ON DELETE RESTRICT,
 "targetOid" OID NOT NULL, "targetPrincipal" NAME NOT NULL, "targetPid" INTEGER NOT NULL CHECK ("targetPid">0), "targetBackendStart" TIMESTAMPTZ NOT NULL,
 "host" TEXT NOT NULL, "boot" TEXT NOT NULL, "processTree" TEXT NOT NULL, "observerOid" OID NOT NULL, "observerPrincipal" NAME NOT NULL, "observerPid" INTEGER NOT NULL CHECK ("observerPid">0), "observerBackendStart" TIMESTAMPTZ NOT NULL,
 "lane" JSONB NOT NULL, "installation" JSONB NOT NULL, "installationGeneration" TEXT NOT NULL, "installationEvidenceHash" TEXT NOT NULL, "validUntil" TIMESTAMPTZ NOT NULL,
 "capturedBytes" BYTEA NOT NULL, "capturedLength" BIGINT NOT NULL, "capturedHash" TEXT NOT NULL, "evidenceBytes" BYTEA NOT NULL, "evidenceLength" BIGINT NOT NULL, "evidenceHash" TEXT NOT NULL,
 "chargeKind" TEXT NOT NULL, "chargeEventKey" TEXT NOT NULL, "chargeBindingHash" TEXT NOT NULL,
 PRIMARY KEY ("expectationId","credentialEpoch","launchEpoch"), UNIQUE ("chargeKind","chargeEventKey"),
 FOREIGN KEY ("expectationId","credentialEpoch","launchEpoch") REFERENCES public."Pro273ControlPlaneInstallerExpectation"("expectationId","credentialEpoch","launchEpoch") ON UPDATE RESTRICT ON DELETE RESTRICT,
 FOREIGN KEY ("trustId","trustGeneration") REFERENCES public."Pro262CapacityTrust"("trustId","generation") ON UPDATE RESTRICT ON DELETE RESTRICT,
 FOREIGN KEY ("chargeKind","chargeEventKey") REFERENCES public."Pro262CapacityControlCharge"("kind","eventKey") ON UPDATE RESTRICT ON DELETE RESTRICT,
 CHECK ("observerOid"<>"targetOid" AND "capturedLength">0 AND "capturedLength"=pg_catalog.octet_length("capturedBytes") AND "evidenceLength">0 AND "evidenceLength"=pg_catalog.octet_length("evidenceBytes"))
);
CREATE TRIGGER "Pro273InstallerProcessObservation_immutable" BEFORE UPDATE OR DELETE ON public."Pro273InstallerProcessObservation" FOR EACH ROW EXECUTE FUNCTION public.pro273_sel_immutable();

CREATE TABLE public."Pro273ControlPlaneBaseline" (
 "baselineId" TEXT PRIMARY KEY, "purpose" TEXT NOT NULL CHECK ("purpose" IN ('QUALIFIER_BASELINE_INITIAL','SELECTION_PROFILE_REVOKE')),
 "physicalIdentity" TEXT NOT NULL REFERENCES public."Pro262CapacityPhysicalDomain"("physicalIdentity") ON UPDATE RESTRICT ON DELETE RESTRICT,
 "physicalProofIdentity" TEXT NOT NULL, "sourceClosureHash" TEXT NOT NULL CHECK ("sourceClosureHash" ~ '^[a-f0-9]{64}$'),
 "installationClosureHash" TEXT NOT NULL CHECK ("installationClosureHash" ~ '^[a-f0-9]{64}$'),
 "expectedFutureLayoutCoreHash" TEXT NOT NULL CHECK ("expectedFutureLayoutCoreHash" ~ '^[a-f0-9]{64}$'),
 "principalOid" OID NOT NULL CHECK ("principalOid"<>0), "principalName" NAME NOT NULL,
 "credentialEpoch" TEXT NOT NULL, "launchEpoch" TEXT NOT NULL, "host" TEXT NOT NULL, "boot" TEXT NOT NULL,
 "processTree" TEXT NOT NULL, "parentProcessTree" TEXT NOT NULL,
 "reservedBackendBytes" NUMERIC NOT NULL CHECK ("reservedBackendBytes" > 0 AND "reservedBackendBytes"=pg_catalog.trunc("reservedBackendBytes") AND "reservedBackendBytes"::TEXT NOT IN ('NaN','Infinity','-Infinity')),
 "reservedSharedBytes" NUMERIC NOT NULL CHECK ("reservedSharedBytes" > 0 AND "reservedSharedBytes"=pg_catalog.trunc("reservedSharedBytes") AND "reservedSharedBytes"::TEXT NOT IN ('NaN','Infinity','-Infinity')),
 "reservedTemporaryBytes" NUMERIC NOT NULL CHECK ("reservedTemporaryBytes" > 0 AND "reservedTemporaryBytes"=pg_catalog.trunc("reservedTemporaryBytes") AND "reservedTemporaryBytes"::TEXT NOT IN ('NaN','Infinity','-Infinity')),
 "maxInputBytes" NUMERIC NOT NULL CHECK ("maxInputBytes" > 0 AND "maxInputBytes"=pg_catalog.trunc("maxInputBytes") AND "maxInputBytes"::TEXT NOT IN ('NaN','Infinity','-Infinity')),
 "maxOutputBytes" NUMERIC NOT NULL CHECK ("maxOutputBytes" > 0 AND "maxOutputBytes"=pg_catalog.trunc("maxOutputBytes") AND "maxOutputBytes"::TEXT NOT IN ('NaN','Infinity','-Infinity')),
 "maxAllocationBytes" NUMERIC NOT NULL CHECK ("maxAllocationBytes" > 0 AND "maxAllocationBytes"=pg_catalog.trunc("maxAllocationBytes") AND "maxAllocationBytes"::TEXT NOT IN ('NaN','Infinity','-Infinity')),
 "stackBytes" NUMERIC NOT NULL CHECK ("stackBytes" > 0 AND "stackBytes"=pg_catalog.trunc("stackBytes") AND "stackBytes"::TEXT NOT IN ('NaN','Infinity','-Infinity')),
 "parentBytes" NUMERIC NOT NULL CHECK ("parentBytes" > 0 AND "parentBytes"=pg_catalog.trunc("parentBytes") AND "parentBytes"::TEXT NOT IN ('NaN','Infinity','-Infinity')),
 "maxProcessCount" NUMERIC NOT NULL CHECK ("maxProcessCount" > 0 AND "maxProcessCount"=pg_catalog.trunc("maxProcessCount") AND "maxProcessCount"::TEXT NOT IN ('NaN','Infinity','-Infinity')),
 "maxBackendCount" NUMERIC NOT NULL CHECK ("maxBackendCount" > 0 AND "maxBackendCount"=pg_catalog.trunc("maxBackendCount") AND "maxBackendCount"::TEXT NOT IN ('NaN','Infinity','-Infinity')),
 "maxLaunchAttempts" NUMERIC NOT NULL CHECK ("maxLaunchAttempts" > 0 AND "maxLaunchAttempts"=pg_catalog.trunc("maxLaunchAttempts") AND "maxLaunchAttempts"::TEXT NOT IN ('NaN','Infinity','-Infinity')),
 "maxEvents" NUMERIC NOT NULL CHECK ("maxEvents" > 0 AND "maxEvents"=pg_catalog.trunc("maxEvents") AND "maxEvents"::TEXT NOT IN ('NaN','Infinity','-Infinity')),
 "backendProcessBytes" NUMERIC NOT NULL CHECK ("backendProcessBytes" >= 0 AND "backendProcessBytes"=pg_catalog.trunc("backendProcessBytes") AND "backendProcessBytes"::TEXT NOT IN ('NaN','Infinity','-Infinity')),
 "qualifierRuntimeBytes" NUMERIC NOT NULL CHECK ("qualifierRuntimeBytes" >= 0 AND "qualifierRuntimeBytes"=pg_catalog.trunc("qualifierRuntimeBytes") AND "qualifierRuntimeBytes"::TEXT NOT IN ('NaN','Infinity','-Infinity')),
 "launcherSupervisorBytes" NUMERIC NOT NULL CHECK ("launcherSupervisorBytes" >= 0 AND "launcherSupervisorBytes"=pg_catalog.trunc("launcherSupervisorBytes") AND "launcherSupervisorBytes"::TEXT NOT IN ('NaN','Infinity','-Infinity')),
 "retainedParentBytes" NUMERIC NOT NULL CHECK ("retainedParentBytes" >= 0 AND "retainedParentBytes"=pg_catalog.trunc("retainedParentBytes") AND "retainedParentBytes"::TEXT NOT IN ('NaN','Infinity','-Infinity')),
 "driverSocketIpcBytes" NUMERIC NOT NULL CHECK ("driverSocketIpcBytes" >= 0 AND "driverSocketIpcBytes"=pg_catalog.trunc("driverSocketIpcBytes") AND "driverSocketIpcBytes"::TEXT NOT IN ('NaN','Infinity','-Infinity')),
 "inputEvidenceSerializationBytes" NUMERIC NOT NULL CHECK ("inputEvidenceSerializationBytes" >= 0 AND "inputEvidenceSerializationBytes"=pg_catalog.trunc("inputEvidenceSerializationBytes") AND "inputEvidenceSerializationBytes"::TEXT NOT IN ('NaN','Infinity','-Infinity')),
 "primitiveParserCacheBytes" NUMERIC NOT NULL CHECK ("primitiveParserCacheBytes" >= 0 AND "primitiveParserCacheBytes"=pg_catalog.trunc("primitiveParserCacheBytes") AND "primitiveParserCacheBytes"::TEXT NOT IN ('NaN','Infinity','-Infinity')),
 "rollbackCleanupBytes" NUMERIC NOT NULL CHECK ("rollbackCleanupBytes" >= 0 AND "rollbackCleanupBytes"=pg_catalog.trunc("rollbackCleanupBytes") AND "rollbackCleanupBytes"::TEXT NOT IN ('NaN','Infinity','-Infinity')),
 "sharedRuntimeBytes" NUMERIC NOT NULL CHECK ("sharedRuntimeBytes" >= 0 AND "sharedRuntimeBytes"=pg_catalog.trunc("sharedRuntimeBytes") AND "sharedRuntimeBytes"::TEXT NOT IN ('NaN','Infinity','-Infinity')),
 "coreHash" TEXT NOT NULL CHECK ("coreHash" ~ '^[a-f0-9]{64}$'), "validFrom" TIMESTAMPTZ NOT NULL, "validUntil" TIMESTAMPTZ NOT NULL,
 CHECK ("validFrom"<"validUntil"), CHECK ("reservedBackendBytes">="backendProcessBytes"+"qualifierRuntimeBytes"+"launcherSupervisorBytes"+"retainedParentBytes"+"driverSocketIpcBytes"+"inputEvidenceSerializationBytes"+"primitiveParserCacheBytes"+"rollbackCleanupBytes"),
 CHECK ("reservedSharedBytes">="sharedRuntimeBytes"+"reservedTemporaryBytes"), CHECK ("parentBytes"<="retainedParentBytes"),
 CHECK ("maxAllocationBytes"<="reservedBackendBytes" AND "stackBytes"<="reservedBackendBytes"),
 UNIQUE ("baselineId","coreHash"), UNIQUE ("principalOid","credentialEpoch"), UNIQUE ("principalOid","launchEpoch")
);
CREATE TABLE public."Pro273ControlPlaneBaselineProvenance" (
 "baselineId" TEXT PRIMARY KEY, "coreHash" TEXT NOT NULL, "bootstrapKind" TEXT NOT NULL REFERENCES public."Pro262CapacityBootstrapBaseline"("kind") ON UPDATE RESTRICT ON DELETE RESTRICT,
 "bootstrapRecordHash" TEXT NOT NULL, "bootstrapEvidenceHash" TEXT NOT NULL, "trustId" TEXT NOT NULL, "trustGeneration" BIGINT NOT NULL,
 "trustRecordHash" TEXT NOT NULL, "publisherPrincipalOid" OID NOT NULL, "publisherPrincipalName" NAME NOT NULL,
 "inputClaimId" TEXT NOT NULL UNIQUE REFERENCES public."Pro262CapacityObserverInputClaim"("inputClaimId") ON UPDATE RESTRICT ON DELETE RESTRICT,
 "sessionClaimId" TEXT NOT NULL, "eventId" TEXT NOT NULL UNIQUE,
 "capturedBytes" BYTEA NOT NULL, "capturedLength" BIGINT NOT NULL, "capturedHash" TEXT NOT NULL,
 "evidenceBytes" BYTEA NOT NULL, "evidenceLength" BIGINT NOT NULL, "evidenceHash" TEXT NOT NULL,
 "chargeKind" TEXT NOT NULL, "chargeEventKey" TEXT NOT NULL, "chargeBindingHash" TEXT NOT NULL, "constructionTransactionId" xid8 NOT NULL,
 FOREIGN KEY ("baselineId","coreHash") REFERENCES public."Pro273ControlPlaneBaseline"("baselineId","coreHash") ON UPDATE RESTRICT ON DELETE RESTRICT,
 FOREIGN KEY ("trustId","trustGeneration") REFERENCES public."Pro262CapacityTrust"("trustId","generation") ON UPDATE RESTRICT ON DELETE RESTRICT,
 FOREIGN KEY ("chargeKind","chargeEventKey") REFERENCES public."Pro262CapacityControlCharge"("kind","eventKey") ON UPDATE RESTRICT ON DELETE RESTRICT,
 CHECK ("capturedLength">0 AND "capturedLength"=pg_catalog.octet_length("capturedBytes") AND "evidenceLength">0 AND "evidenceLength"=pg_catalog.octet_length("evidenceBytes"))
);
CREATE TABLE public."Pro273ControlPlaneLaunchAttempt" (
 "attemptId" TEXT PRIMARY KEY, "baselineId" TEXT NOT NULL REFERENCES public."Pro273ControlPlaneBaseline"("baselineId") ON UPDATE RESTRICT ON DELETE RESTRICT,
 "creationTransactionId" xid8 NOT NULL,
 "attemptOrdinal" BIGINT NOT NULL CHECK ("attemptOrdinal">0), "receiverIdentity" TEXT NOT NULL, "requestHash" TEXT NOT NULL CHECK ("requestHash" ~ '^[a-f0-9]{64}$'),
 "chargeKind" TEXT NOT NULL, "chargeEventKey" TEXT NOT NULL UNIQUE, "chargeBindingHash" TEXT NOT NULL CHECK ("chargeBindingHash" ~ '^[a-f0-9]{64}$'),
 "sessionChargeKind" TEXT NOT NULL, "sessionChargeEventKey" TEXT NOT NULL UNIQUE, "sessionChargeBindingHash" TEXT NOT NULL CHECK ("sessionChargeBindingHash" ~ '^[a-f0-9]{64}$'),
 "claimedAt" TIMESTAMPTZ NOT NULL, UNIQUE ("baselineId","attemptOrdinal"), UNIQUE ("baselineId","attemptId"),
 CHECK (("chargeKind","chargeEventKey") IS DISTINCT FROM ("sessionChargeKind","sessionChargeEventKey")),
 FOREIGN KEY ("chargeKind","chargeEventKey") REFERENCES public."Pro262CapacityControlCharge"("kind","eventKey") ON UPDATE RESTRICT ON DELETE RESTRICT,
 FOREIGN KEY ("sessionChargeKind","sessionChargeEventKey") REFERENCES public."Pro262CapacityControlCharge"("kind","eventKey") ON UPDATE RESTRICT ON DELETE RESTRICT
);
CREATE TABLE public."Pro273ControlPlaneSessionClaim" (
 "sessionClaimId" TEXT PRIMARY KEY, "baselineId" TEXT NOT NULL, "attemptId" TEXT NOT NULL UNIQUE,
 "creationTransactionId" xid8 NOT NULL,
 "principalOid" OID NOT NULL, "principalName" NAME NOT NULL, "credentialEpoch" TEXT NOT NULL, "launchEpoch" TEXT NOT NULL,
 "receiverIdentity" TEXT NOT NULL, "claimedAt" TIMESTAMPTZ NOT NULL,
 FOREIGN KEY ("baselineId","attemptId") REFERENCES public."Pro273ControlPlaneLaunchAttempt"("baselineId","attemptId") ON UPDATE RESTRICT ON DELETE RESTRICT,
 UNIQUE ("baselineId","sessionClaimId")
);
-- A permanent reservation is bound once to an exact protected target and
-- event before capture. No caller-provided target is accepted as authority.
CREATE TABLE public."Pro273ControlPlaneInputBinding" (
 "reservationId" TEXT PRIMARY KEY REFERENCES public."Pro262CapacityObserverInputReservation"("reservationId") ON UPDATE RESTRICT ON DELETE RESTRICT,
 "creationTransactionId" xid8 NOT NULL,
 "baselineId" TEXT NOT NULL REFERENCES public."Pro273ControlPlaneBaseline"("baselineId") ON UPDATE RESTRICT ON DELETE RESTRICT,
 "purpose" TEXT NOT NULL CHECK ("purpose" IN ('QUALIFIER_BASELINE_INITIAL','SELECTION_PROFILE_REVOKE')),
 "eventId" TEXT NOT NULL UNIQUE, "target" JSONB NOT NULL,
 "trustId" TEXT NOT NULL, "trustGeneration" BIGINT NOT NULL,
 "chargeKind" TEXT NOT NULL, "chargeEventKey" TEXT NOT NULL, "chargeBindingHash" TEXT NOT NULL,
 FOREIGN KEY ("trustId","trustGeneration") REFERENCES public."Pro262CapacityTrust"("trustId","generation") ON UPDATE RESTRICT ON DELETE RESTRICT,
 FOREIGN KEY ("chargeKind","chargeEventKey") REFERENCES public."Pro262CapacityControlCharge"("kind","eventKey") ON UPDATE RESTRICT ON DELETE RESTRICT,
 UNIQUE ("reservationId","baselineId","purpose","eventId"), UNIQUE ("chargeKind","chargeEventKey")
);
CREATE TRIGGER "Pro273ControlPlaneInputBinding_immutable" BEFORE UPDATE OR DELETE ON public."Pro273ControlPlaneInputBinding" FOR EACH ROW EXECUTE FUNCTION public.pro273_sel_immutable();
CREATE TABLE public."Pro273ControlPlaneInputClaim" (
 "inputClaimId" TEXT PRIMARY KEY REFERENCES public."Pro262CapacityObserverInputClaim"("inputClaimId") ON UPDATE RESTRICT ON DELETE RESTRICT,
 "creationTransactionId" xid8 NOT NULL,
 "baselineId" TEXT NOT NULL, "sessionClaimId" TEXT NOT NULL, "reservationId" TEXT NOT NULL UNIQUE REFERENCES public."Pro262CapacityObserverInputReservation"("reservationId") ON UPDATE RESTRICT ON DELETE RESTRICT,
 "purpose" TEXT NOT NULL CHECK ("purpose" IN ('QUALIFIER_BASELINE_INITIAL','SELECTION_PROFILE_REVOKE')),
 "eventId" TEXT NOT NULL UNIQUE, "target" JSONB NOT NULL, "chargeKind" TEXT NOT NULL, "chargeEventKey" TEXT NOT NULL, "chargeBindingHash" TEXT NOT NULL,
 FOREIGN KEY ("baselineId","sessionClaimId") REFERENCES public."Pro273ControlPlaneSessionClaim"("baselineId","sessionClaimId") ON UPDATE RESTRICT ON DELETE RESTRICT,
 FOREIGN KEY ("reservationId","baselineId","purpose","eventId") REFERENCES public."Pro273ControlPlaneInputBinding"("reservationId","baselineId","purpose","eventId") ON UPDATE RESTRICT ON DELETE RESTRICT,
 FOREIGN KEY ("chargeKind","chargeEventKey") REFERENCES public."Pro262CapacityControlCharge"("kind","eventKey") ON UPDATE RESTRICT ON DELETE RESTRICT
);
CREATE TABLE public."Pro273ControlPlaneInputReceipt" (
 "inputClaimId" TEXT PRIMARY KEY REFERENCES public."Pro273ControlPlaneInputClaim"("inputClaimId") ON UPDATE RESTRICT ON DELETE RESTRICT,
 "capturedBytes" BYTEA NOT NULL, "capturedLength" BIGINT NOT NULL, "capturedHash" TEXT NOT NULL CHECK ("capturedHash" ~ '^[a-f0-9]{64}$'),
 "operationReceipt" TEXT NOT NULL, CHECK ("capturedLength">0 AND "capturedLength"=pg_catalog.octet_length("capturedBytes"))
);
-- Preinput evidence is separate from the post-capture operation receipt. A row
-- alone is never capture authority; the independently qualified fence remains
-- required before dispatch. No producer is enabled without durability proof.
CREATE TABLE public."Pro273InitialPreinputReceipt" (
 "inputClaimId" TEXT PRIMARY KEY REFERENCES public."Pro273ControlPlaneInputClaim"("inputClaimId") ON UPDATE RESTRICT ON DELETE RESTRICT,
 "receiptId" TEXT NOT NULL UNIQUE, "reservationId" TEXT NOT NULL UNIQUE REFERENCES public."Pro273ControlPlaneInputBinding"("reservationId") ON UPDATE RESTRICT ON DELETE RESTRICT,
 "baselineId" TEXT NOT NULL, "baselineCoreHash" TEXT NOT NULL, "sessionClaimId" TEXT NOT NULL, "attemptId" TEXT NOT NULL,
 "eventId" TEXT NOT NULL, "receiverIdentity" TEXT NOT NULL, "target" JSONB NOT NULL,
 "principalOid" OID NOT NULL, "principalName" NAME NOT NULL, "credentialEpoch" TEXT NOT NULL, "launchEpoch" TEXT NOT NULL,
 "backendPid" INTEGER NOT NULL CHECK ("backendPid">0), "backendStart" TIMESTAMPTZ NOT NULL,
 "sourceClosureHash" TEXT NOT NULL CHECK ("sourceClosureHash" ~ '^[a-f0-9]{64}$'),
 "installationClosureHash" TEXT NOT NULL CHECK ("installationClosureHash" ~ '^[a-f0-9]{64}$'),
 "chargeKind" TEXT NOT NULL, "chargeEventKey" TEXT NOT NULL, "chargeBindingHash" TEXT NOT NULL,
 "creationTransactionId" xid8 NOT NULL,
 -- Closed INITIAL target shape only; equality with a publication and its
 -- protected provenance still requires the ordered same-row assertion.
 CONSTRAINT "Pro273InitialPreinputReceipt_target_shape" CHECK (
  pg_catalog.jsonb_typeof("target") IS NOT DISTINCT FROM 'object' AND
  ("target" - ARRAY['kind','bootstrapKind','expectedCoreHash','expectedEvidenceHash']::TEXT[]) = '{}'::JSONB AND
  pg_catalog.jsonb_typeof("target"->'kind') IS NOT DISTINCT FROM 'string' AND
  "target"->>'kind' IS NOT DISTINCT FROM 'INITIAL' AND
  pg_catalog.jsonb_typeof("target"->'bootstrapKind') IS NOT DISTINCT FROM 'string' AND
  COALESCE("target"->>'bootstrapKind','') <> '' AND
  pg_catalog.jsonb_typeof("target"->'expectedCoreHash') IS NOT DISTINCT FROM 'string' AND
  COALESCE("target"->>'expectedCoreHash','') ~ '^[a-f0-9]{64}$' AND
  pg_catalog.jsonb_typeof("target"->'expectedEvidenceHash') IS NOT DISTINCT FROM 'string' AND
  COALESCE("target"->>'expectedEvidenceHash','') ~ '^[a-f0-9]{64}$'
 ),
 FOREIGN KEY ("baselineId","baselineCoreHash") REFERENCES public."Pro273ControlPlaneBaseline"("baselineId","coreHash") ON UPDATE RESTRICT ON DELETE RESTRICT,
 FOREIGN KEY ("baselineId","sessionClaimId") REFERENCES public."Pro273ControlPlaneSessionClaim"("baselineId","sessionClaimId") ON UPDATE RESTRICT ON DELETE RESTRICT,
 FOREIGN KEY ("baselineId","attemptId") REFERENCES public."Pro273ControlPlaneLaunchAttempt"("baselineId","attemptId") ON UPDATE RESTRICT ON DELETE RESTRICT,
 FOREIGN KEY ("chargeKind","chargeEventKey") REFERENCES public."Pro262CapacityControlCharge"("kind","eventKey") ON UPDATE RESTRICT ON DELETE RESTRICT
);
-- Structural placeholders only: no insert is authorized by these keys. In
-- particular, the admission FK does not authenticate the duplicated tuple and
-- the allocation FK does not prove its layout equals the bound layout.
-- Every 256-byte bound in these three scaffold tables is provisional and
-- unqualified: it is not a published ABI or evidence of compatibility or
-- resource qualification. A retry must read the original publication; no
-- writer is enabled by these constraints.
CREATE TABLE public."Pro273InitialLayoutPublication" (
 "inputClaimId" TEXT PRIMARY KEY CHECK (pg_catalog.octet_length("inputClaimId") BETWEEN 1 AND 256),
 "admissionReceiptId" TEXT NOT NULL UNIQUE CHECK (pg_catalog.octet_length("admissionReceiptId") BETWEEN 1 AND 256),
 "admissionReservationId" TEXT NOT NULL, "admissionSessionClaimId" TEXT NOT NULL,
 "admissionAttemptId" TEXT NOT NULL, "admissionReceiverIdentity" TEXT NOT NULL,
 "admissionTarget" JSONB NOT NULL, "admissionCreationTransactionId" xid8 NOT NULL,
 "evidenceHash" TEXT NOT NULL CHECK ("evidenceHash" ~ '^[a-f0-9]{64}$'),
 "eventId" TEXT NOT NULL UNIQUE CHECK (pg_catalog.octet_length("eventId") BETWEEN 1 AND 256),
 "baselineId" TEXT NOT NULL CHECK (pg_catalog.octet_length("baselineId") BETWEEN 1 AND 256),
 "baselineCoreHash" TEXT NOT NULL CHECK ("baselineCoreHash" ~ '^[a-f0-9]{64}$'),
 "physicalIdentity" TEXT NOT NULL CHECK (pg_catalog.octet_length("physicalIdentity") BETWEEN 1 AND 256),
 "physicalProofIdentity" TEXT NOT NULL CHECK (pg_catalog.octet_length("physicalProofIdentity") BETWEEN 1 AND 256),
 "layoutCoreHash" TEXT NOT NULL CHECK ("layoutCoreHash" ~ '^[a-f0-9]{64}$'),
 "receiptHash" TEXT NOT NULL CHECK ("receiptHash" ~ '^[a-f0-9]{64}$'), "constructionTransactionId" xid8 NOT NULL,
 CONSTRAINT "Pro273InitialLayoutPublication_original_physical_key" UNIQUE ("physicalIdentity"),
 UNIQUE ("baselineId","baselineCoreHash","inputClaimId"),
 FOREIGN KEY ("inputClaimId") REFERENCES public."Pro273InitialPreinputReceipt"("inputClaimId") ON UPDATE RESTRICT ON DELETE RESTRICT,
 FOREIGN KEY ("baselineId","baselineCoreHash") REFERENCES public."Pro273ControlPlaneBaseline"("baselineId","coreHash") ON UPDATE RESTRICT ON DELETE RESTRICT,
 FOREIGN KEY ("physicalIdentity","physicalProofIdentity","layoutCoreHash") REFERENCES public."Pro273QualifierBaselineLayout"("physicalIdentity","physicalProofIdentity","coreHash") ON UPDATE RESTRICT ON DELETE RESTRICT
);
CREATE TABLE public."Pro273InitialBaselineLayoutBinding" (
 "baselineId" TEXT NOT NULL CHECK (pg_catalog.octet_length("baselineId") BETWEEN 1 AND 256),
 "baselineCoreHash" TEXT NOT NULL CHECK ("baselineCoreHash" ~ '^[a-f0-9]{64}$'),
 "layoutInputClaimId" TEXT NOT NULL CHECK (pg_catalog.octet_length("layoutInputClaimId") BETWEEN 1 AND 256),
 "constructionTransactionId" xid8 NOT NULL,
 PRIMARY KEY ("baselineId","baselineCoreHash","layoutInputClaimId"), UNIQUE ("baselineId","baselineCoreHash"),
 FOREIGN KEY ("baselineId","baselineCoreHash") REFERENCES public."Pro273ControlPlaneBaseline"("baselineId","coreHash") ON UPDATE RESTRICT ON DELETE RESTRICT,
 FOREIGN KEY ("baselineId","baselineCoreHash","layoutInputClaimId") REFERENCES public."Pro273InitialLayoutPublication"("baselineId","baselineCoreHash","inputClaimId") ON UPDATE RESTRICT ON DELETE RESTRICT
);
CREATE TABLE public."Pro273InitialAllocationPublication" (
 "inputClaimId" TEXT PRIMARY KEY CHECK (pg_catalog.octet_length("inputClaimId") BETWEEN 1 AND 256),
 "admissionReceiptId" TEXT NOT NULL UNIQUE CHECK (pg_catalog.octet_length("admissionReceiptId") BETWEEN 1 AND 256),
 "admissionReservationId" TEXT NOT NULL, "admissionSessionClaimId" TEXT NOT NULL,
 "admissionAttemptId" TEXT NOT NULL, "admissionReceiverIdentity" TEXT NOT NULL,
 "admissionTarget" JSONB NOT NULL, "admissionCreationTransactionId" xid8 NOT NULL,
 "evidenceHash" TEXT NOT NULL CHECK ("evidenceHash" ~ '^[a-f0-9]{64}$'),
 "eventId" TEXT NOT NULL UNIQUE CHECK (pg_catalog.octet_length("eventId") BETWEEN 1 AND 256),
 "baselineId" TEXT NOT NULL CHECK (pg_catalog.octet_length("baselineId") BETWEEN 1 AND 256),
 "baselineCoreHash" TEXT NOT NULL CHECK ("baselineCoreHash" ~ '^[a-f0-9]{64}$'),
 "layoutInputClaimId" TEXT NOT NULL CHECK (pg_catalog.octet_length("layoutInputClaimId") BETWEEN 1 AND 256),
 "allocationId" TEXT NOT NULL CHECK (pg_catalog.octet_length("allocationId") BETWEEN 1 AND 256),
 "allocationCoreHash" TEXT NOT NULL CHECK ("allocationCoreHash" ~ '^[a-f0-9]{64}$'),
 "receiptHash" TEXT NOT NULL CHECK ("receiptHash" ~ '^[a-f0-9]{64}$'), "constructionTransactionId" xid8 NOT NULL,
 CONSTRAINT "Pro273InitialAllocationPublication_original_allocation_key" UNIQUE ("allocationId"),
 FOREIGN KEY ("inputClaimId") REFERENCES public."Pro273InitialPreinputReceipt"("inputClaimId") ON UPDATE RESTRICT ON DELETE RESTRICT,
 FOREIGN KEY ("allocationId","allocationCoreHash") REFERENCES public."Pro273QualifierAllocation"("allocationId","coreHash") ON UPDATE RESTRICT ON DELETE RESTRICT,
 FOREIGN KEY ("baselineId","baselineCoreHash","layoutInputClaimId") REFERENCES public."Pro273InitialBaselineLayoutBinding"("baselineId","baselineCoreHash","layoutInputClaimId") ON UPDATE RESTRICT ON DELETE RESTRICT
);
-- Structural equality only: the caller must already have locked the original
-- receipt. This does not prove issuance, absence races or resource authority.
CREATE FUNCTION public.pro273_initial_assert_publication_receipt(
 p_receipt public."Pro273InitialPreinputReceipt", p_input_claim TEXT, p_receipt_id TEXT,
 p_reservation TEXT, p_baseline TEXT, p_baseline_hash TEXT, p_session TEXT,
 p_attempt TEXT, p_event TEXT, p_receiver TEXT, p_target JSONB, p_creation xid8,
 p_evidence TEXT, p_bootstrap_kind TEXT, p_core_hash TEXT, p_current_xid xid8
) RETURNS VOID LANGUAGE plpgsql IMMUTABLE SECURITY INVOKER SET search_path=pg_catalog AS $$
BEGIN
 IF p_receipt."inputClaimId" IS NULL OR p_input_claim IS NULL OR p_receipt_id IS NULL OR p_reservation IS NULL OR p_baseline IS NULL OR p_baseline_hash IS NULL OR p_session IS NULL OR p_attempt IS NULL OR p_event IS NULL OR p_receiver IS NULL OR p_target IS NULL OR p_creation IS NULL OR p_current_xid IS NULL OR
    (p_receipt."inputClaimId",p_receipt."receiptId",p_receipt."reservationId",p_receipt."baselineId",p_receipt."baselineCoreHash",
     p_receipt."sessionClaimId",p_receipt."attemptId",p_receipt."eventId",p_receipt."receiverIdentity",p_receipt."target",p_receipt."creationTransactionId") IS DISTINCT FROM
    (p_input_claim,p_receipt_id,p_reservation,p_baseline,p_baseline_hash,p_session,p_attempt,p_event,p_receiver,p_target,p_creation) OR
    p_receipt."creationTransactionId" IS NOT DISTINCT FROM p_current_xid OR
    p_receipt."target"->>'kind' IS DISTINCT FROM 'INITIAL' OR
    p_receipt."target"->>'expectedEvidenceHash' IS DISTINCT FROM p_evidence OR
    p_receipt."target"->>'bootstrapKind' IS DISTINCT FROM p_bootstrap_kind OR
    p_receipt."target"->>'expectedCoreHash' IS DISTINCT FROM p_core_hash OR
    p_evidence IS NULL OR p_bootstrap_kind IS NULL OR p_core_hash IS NULL THEN RAISE EXCEPTION 'SELECTION_UNAVAILABLE'; END IF;
END $$;
REVOKE ALL ON FUNCTION public.pro273_initial_assert_publication_receipt(public."Pro273InitialPreinputReceipt",TEXT,TEXT,TEXT,TEXT,TEXT,TEXT,TEXT,TEXT,TEXT,JSONB,xid8,TEXT,TEXT,TEXT,xid8) FROM PUBLIC;

-- The stamp is deliberately followed by unconditional denial. It cannot be
-- changed to return NEW without the full reviewed tuple and lock protocol.
CREATE FUNCTION public.pro273_initial_linkage_block_insert() RETURNS TRIGGER
LANGUAGE plpgsql SECURITY DEFINER SET search_path=pg_catalog AS $$
DECLARE v_admission public."Pro273InitialPreinputReceipt"%ROWTYPE;
BEGIN
 NEW."constructionTransactionId":=pg_catalog.pg_current_xact_id();
 IF TG_TABLE_NAME IN ('Pro273InitialLayoutPublication','Pro273InitialAllocationPublication') THEN
  SELECT r.* INTO v_admission FROM public."Pro273InitialPreinputReceipt" r
   WHERE r."inputClaimId"=NEW."inputClaimId" FOR SHARE NOWAIT;
  IF NOT FOUND THEN RAISE EXCEPTION 'SELECTION_UNAVAILABLE'; END IF;
  IF TG_TABLE_NAME='Pro273InitialLayoutPublication' THEN
   PERFORM public.pro273_initial_assert_publication_receipt(v_admission,NEW."inputClaimId",NEW."admissionReceiptId",NEW."admissionReservationId",NEW."baselineId",NEW."baselineCoreHash",NEW."admissionSessionClaimId",NEW."admissionAttemptId",NEW."eventId",NEW."admissionReceiverIdentity",NEW."admissionTarget",NEW."admissionCreationTransactionId",NEW."evidenceHash",'SELECTION_QUALIFIER_LAYOUT:'||NEW."physicalIdentity",NEW."layoutCoreHash",pg_catalog.pg_current_xact_id());
  ELSE
   PERFORM public.pro273_initial_assert_publication_receipt(v_admission,NEW."inputClaimId",NEW."admissionReceiptId",NEW."admissionReservationId",NEW."baselineId",NEW."baselineCoreHash",NEW."admissionSessionClaimId",NEW."admissionAttemptId",NEW."eventId",NEW."admissionReceiverIdentity",NEW."admissionTarget",NEW."admissionCreationTransactionId",NEW."evidenceHash",'SELECTION_QUALIFIER_ALLOCATION:'||NEW."allocationId",NEW."allocationCoreHash",pg_catalog.pg_current_xact_id());
  END IF;
 END IF;
 RAISE EXCEPTION 'SELECTION_UNAVAILABLE';
END $$;
CREATE FUNCTION public.pro273_initial_linkage_immutable() RETURNS TRIGGER
LANGUAGE plpgsql SECURITY DEFINER SET search_path=pg_catalog AS $$
BEGIN
 RAISE EXCEPTION 'SELECTION_UNAVAILABLE';
END $$;
REVOKE ALL ON FUNCTION public.pro273_initial_linkage_block_insert(),public.pro273_initial_linkage_immutable() FROM PUBLIC;
REVOKE ALL ON TABLE public."Pro273InitialLayoutPublication",public."Pro273InitialBaselineLayoutBinding",public."Pro273InitialAllocationPublication" FROM PUBLIC;
CREATE TRIGGER "Pro273InitialLayoutPublication_block_insert" BEFORE INSERT ON public."Pro273InitialLayoutPublication" FOR EACH ROW EXECUTE FUNCTION public.pro273_initial_linkage_block_insert();
CREATE TRIGGER "Pro273InitialBaselineLayoutBinding_block_insert" BEFORE INSERT ON public."Pro273InitialBaselineLayoutBinding" FOR EACH ROW EXECUTE FUNCTION public.pro273_initial_linkage_block_insert();
CREATE TRIGGER "Pro273InitialAllocationPublication_block_insert" BEFORE INSERT ON public."Pro273InitialAllocationPublication" FOR EACH ROW EXECUTE FUNCTION public.pro273_initial_linkage_block_insert();
CREATE TRIGGER "Pro273InitialLayoutPublication_immutable" BEFORE UPDATE OR DELETE ON public."Pro273InitialLayoutPublication" FOR EACH ROW EXECUTE FUNCTION public.pro273_initial_linkage_immutable();
CREATE TRIGGER "Pro273InitialBaselineLayoutBinding_immutable" BEFORE UPDATE OR DELETE ON public."Pro273InitialBaselineLayoutBinding" FOR EACH ROW EXECUTE FUNCTION public.pro273_initial_linkage_immutable();
CREATE TRIGGER "Pro273InitialAllocationPublication_immutable" BEFORE UPDATE OR DELETE ON public."Pro273InitialAllocationPublication" FOR EACH ROW EXECUTE FUNCTION public.pro273_initial_linkage_immutable();
-- The stored xid is assigned by the database, never supplied as authority by a
-- caller. Consumers must still prove a later transaction before using a row.
CREATE FUNCTION public.pro273_control_plane_stamp_creation_xid() RETURNS TRIGGER
LANGUAGE plpgsql SET search_path=pg_catalog AS $$
BEGIN
 NEW."creationTransactionId":=pg_catalog.pg_current_xact_id();
 RETURN NEW;
END $$;
REVOKE ALL ON FUNCTION public.pro273_control_plane_stamp_creation_xid() FROM PUBLIC;
CREATE TRIGGER "Pro273ControlPlaneLaunchAttempt_creation_xid" BEFORE INSERT ON public."Pro273ControlPlaneLaunchAttempt" FOR EACH ROW EXECUTE FUNCTION public.pro273_control_plane_stamp_creation_xid();
CREATE TRIGGER "Pro273ControlPlaneSessionClaim_creation_xid" BEFORE INSERT ON public."Pro273ControlPlaneSessionClaim" FOR EACH ROW EXECUTE FUNCTION public.pro273_control_plane_stamp_creation_xid();
CREATE TRIGGER "Pro273ControlPlaneInputBinding_creation_xid" BEFORE INSERT ON public."Pro273ControlPlaneInputBinding" FOR EACH ROW EXECUTE FUNCTION public.pro273_control_plane_stamp_creation_xid();
CREATE TRIGGER "Pro273ControlPlaneInputClaim_creation_xid" BEFORE INSERT ON public."Pro273ControlPlaneInputClaim" FOR EACH ROW EXECUTE FUNCTION public.pro273_control_plane_stamp_creation_xid();
CREATE TRIGGER "Pro273InitialPreinputReceipt_creation_xid" BEFORE INSERT ON public."Pro273InitialPreinputReceipt" FOR EACH ROW EXECUTE FUNCTION public.pro273_control_plane_stamp_creation_xid();
CREATE TRIGGER "Pro273ControlPlaneBaseline_immutable" BEFORE UPDATE OR DELETE ON public."Pro273ControlPlaneBaseline" FOR EACH ROW EXECUTE FUNCTION public.pro273_sel_immutable();
CREATE TRIGGER "Pro273ControlPlaneBaselineProvenance_immutable" BEFORE UPDATE OR DELETE ON public."Pro273ControlPlaneBaselineProvenance" FOR EACH ROW EXECUTE FUNCTION public.pro273_sel_immutable();
CREATE TRIGGER "Pro273ControlPlaneLaunchAttempt_immutable" BEFORE UPDATE OR DELETE ON public."Pro273ControlPlaneLaunchAttempt" FOR EACH ROW EXECUTE FUNCTION public.pro273_sel_immutable();
CREATE TRIGGER "Pro273ControlPlaneSessionClaim_immutable" BEFORE UPDATE OR DELETE ON public."Pro273ControlPlaneSessionClaim" FOR EACH ROW EXECUTE FUNCTION public.pro273_sel_immutable();
CREATE TRIGGER "Pro273ControlPlaneInputClaim_immutable" BEFORE UPDATE OR DELETE ON public."Pro273ControlPlaneInputClaim" FOR EACH ROW EXECUTE FUNCTION public.pro273_sel_immutable();
CREATE TRIGGER "Pro273ControlPlaneInputReceipt_immutable" BEFORE UPDATE OR DELETE ON public."Pro273ControlPlaneInputReceipt" FOR EACH ROW EXECUTE FUNCTION public.pro273_sel_immutable();
CREATE TRIGGER "Pro273InitialPreinputReceipt_immutable" BEFORE UPDATE OR DELETE ON public."Pro273InitialPreinputReceipt" FOR EACH ROW EXECUTE FUNCTION public.pro273_sel_immutable();

-- One preregistered launch attempt yields one permanent session claim.
-- The launcher must commit this before opening the qualified target process.
CREATE FUNCTION public.pro273_control_plane_claim_session(p_baseline_id TEXT,p_attempt_id TEXT) RETURNS TEXT
LANGUAGE plpgsql SECURITY DEFINER SET search_path=pg_catalog AS $$
DECLARE v_global RECORD; v_domain public."Pro262CapacityPhysicalDomain"%ROWTYPE; v_trust public."Pro262CapacityTrust"%ROWTYPE;
 v_baseline public."Pro273ControlPlaneBaseline"%ROWTYPE; v_attempt public."Pro273ControlPlaneLaunchAttempt"%ROWTYPE;
 v_prior public."Pro273ControlPlaneSessionClaim"%ROWTYPE; v_claim_id TEXT; v_now TIMESTAMPTZ;
BEGIN
 IF COALESCE(p_baseline_id,'')='' OR COALESCE(p_attempt_id,'')='' OR pg_catalog.current_setting('transaction_isolation')<>'read committed' THEN RAISE EXCEPTION 'SELECTION_UNAVAILABLE'; END IF;
 SELECT b.* INTO STRICT v_baseline FROM public."Pro273ControlPlaneBaseline" b WHERE b."baselineId"=p_baseline_id;
 LOCK TABLE public."Pro311ControlDomain" IN ACCESS SHARE MODE NOWAIT;
 SELECT g."physicalIdentity",g."proofIdentity" INTO STRICT v_global FROM public."Pro311ControlDomain" g WHERE g."id"='global-v1' FOR UPDATE NOWAIT;
 SELECT d.* INTO STRICT v_domain FROM public."Pro262CapacityPhysicalDomain" d WHERE d."physicalIdentity"=v_baseline."physicalIdentity" FOR UPDATE NOWAIT;
 SELECT t.* INTO STRICT v_trust FROM public."Pro262CapacityTrust" t WHERE t."purpose"='SUPERVISOR' AND t."supplierPrincipal"=SESSION_USER::NAME AND t."scope"->>'controlKey'=p_baseline_id FOR SHARE NOWAIT;
 SELECT b.* INTO STRICT v_baseline FROM public."Pro273ControlPlaneBaseline" b WHERE b."baselineId"=p_baseline_id FOR SHARE NOWAIT;
 SELECT a.* INTO STRICT v_attempt FROM public."Pro273ControlPlaneLaunchAttempt" a WHERE (a."baselineId",a."attemptId")=(p_baseline_id,p_attempt_id) FOR SHARE NOWAIT;
 v_now:=pg_catalog.clock_timestamp();
 IF NOT v_domain."enabled" OR v_global."physicalIdentity" IS DISTINCT FROM v_domain."physicalIdentity" OR v_global."proofIdentity" IS DISTINCT FROM v_domain."proofIdentity" OR v_baseline."physicalProofIdentity" IS DISTINCT FROM v_domain."proofIdentity" OR
    v_trust."revoked" OR v_trust."validFrom">v_now OR v_trust."validUntil"<=v_now OR v_baseline."validFrom">v_now OR v_baseline."validUntil"<=v_now OR
    v_trust."scope"->>'credentialEpoch' IS DISTINCT FROM v_baseline."credentialEpoch" OR v_trust."scope"->>'sourceIdentity' IS DISTINCT FROM v_baseline."sourceClosureHash" OR v_trust."scope"->>'supervisorIdentity' IS DISTINCT FROM v_attempt."receiverIdentity" OR v_baseline."principalName"=SESSION_USER::NAME OR
    NOT EXISTS (SELECT 1 FROM public."Pro262CapacityControlCharge" c WHERE (c."kind",c."eventKey",c."bindingHash")=(v_attempt."chargeKind",v_attempt."chargeEventKey",v_attempt."chargeBindingHash")) OR
    NOT EXISTS (SELECT 1 FROM public."Pro262CapacityControlCharge" c WHERE (c."kind",c."eventKey",c."bindingHash")=(v_attempt."sessionChargeKind",v_attempt."sessionChargeEventKey",v_attempt."sessionChargeBindingHash")) OR
    v_attempt."attemptOrdinal">v_baseline."maxLaunchAttempts" OR (SELECT pg_catalog.count(*) FROM public."Pro273ControlPlaneLaunchAttempt" a WHERE a."baselineId"=p_baseline_id)>v_baseline."maxLaunchAttempts" THEN RAISE EXCEPTION 'SELECTION_UNAVAILABLE'; END IF;
 v_claim_id:=pg_catalog.encode(int4_crypto.digest(pg_catalog.convert_to('pro273.control-plane.session.v1:'||p_attempt_id,'UTF8'),'sha256'),'hex');
 SELECT c.* INTO v_prior FROM public."Pro273ControlPlaneSessionClaim" c WHERE c."attemptId"=p_attempt_id;
 IF FOUND THEN
  IF (v_prior."sessionClaimId",v_prior."baselineId",v_prior."principalOid",v_prior."principalName",v_prior."credentialEpoch",v_prior."launchEpoch",v_prior."receiverIdentity") IS DISTINCT FROM (v_claim_id,p_baseline_id,v_baseline."principalOid",v_baseline."principalName",v_baseline."credentialEpoch",v_baseline."launchEpoch",v_attempt."receiverIdentity") THEN RAISE EXCEPTION 'SELECTION_UNAVAILABLE'; END IF;
  RETURN v_claim_id;
 END IF;
 INSERT INTO public."Pro273ControlPlaneSessionClaim"("sessionClaimId","baselineId","attemptId","principalOid","principalName","credentialEpoch","launchEpoch","receiverIdentity","claimedAt") VALUES(v_claim_id,p_baseline_id,p_attempt_id,v_baseline."principalOid",v_baseline."principalName",v_baseline."credentialEpoch",v_baseline."launchEpoch",v_attempt."receiverIdentity",v_now);
 RETURN v_claim_id;
EXCEPTION WHEN OTHERS THEN RAISE EXCEPTION 'SELECTION_UNAVAILABLE'; END $$;
REVOKE ALL ON FUNCTION public.pro273_control_plane_claim_session(TEXT,TEXT) FROM PUBLIC;

-- Immutable, independently published process observation; no observation or
-- trust is seeded by this migration. The publication path still must be wired.
CREATE TABLE public."Pro273ControlPlaneProcessObservation" (
 "sessionClaimId" TEXT PRIMARY KEY REFERENCES public."Pro273ControlPlaneSessionClaim"("sessionClaimId") ON UPDATE RESTRICT ON DELETE RESTRICT,
 "trustId" TEXT NOT NULL, "trustGeneration" BIGINT NOT NULL, "observerOid" OID NOT NULL, "observerPrincipal" NAME NOT NULL,
 "principalOid" OID NOT NULL, "principalName" NAME NOT NULL, "backendPid" INTEGER NOT NULL CHECK ("backendPid">0), "backendStart" TIMESTAMPTZ NOT NULL,
 "credentialEpoch" TEXT NOT NULL, "launchEpoch" TEXT NOT NULL, "host" TEXT NOT NULL, "boot" TEXT NOT NULL, "processTree" TEXT NOT NULL, "parentProcessTree" TEXT NOT NULL,
 "sourceClosureHash" TEXT NOT NULL, "installationClosureHash" TEXT NOT NULL, "validUntil" TIMESTAMPTZ NOT NULL,
 "capturedBytes" BYTEA NOT NULL, "capturedHash" TEXT NOT NULL, "inputClaimId" TEXT NOT NULL UNIQUE REFERENCES public."Pro262CapacityObserverInputClaim"("inputClaimId") ON UPDATE RESTRICT ON DELETE RESTRICT,
 FOREIGN KEY ("trustId","trustGeneration") REFERENCES public."Pro262CapacityTrust"("trustId","generation") ON UPDATE RESTRICT ON DELETE RESTRICT
);
CREATE TRIGGER "Pro273ControlPlaneProcessObservation_immutable" BEFORE UPDATE OR DELETE ON public."Pro273ControlPlaneProcessObservation" FOR EACH ROW EXECUTE FUNCTION public.pro273_sel_immutable();
ALTER TABLE public."Pro273InitialPreinputReceipt" ADD FOREIGN KEY ("sessionClaimId") REFERENCES public."Pro273ControlPlaneProcessObservation"("sessionClaimId") ON UPDATE RESTRICT ON DELETE RESTRICT;

-- Deny-only Source scaffold. Bounds are provisional and unqualified, not an ABI
-- or a resource guarantee. No issuer, lane, writer, backfill or acceptance exists.
-- Disconnected fixed-shape candidate only: decoded UTF-16BE keys and values
-- must eventually come from an authenticated, raw-byte-validating lexer. Neither
-- the selection arena nor installer metadata context qualifies this observation
-- lane. Raw/detoast, individual and aggregate strings, lexer workspace and
-- simultaneous decoded/evidence/JSONB/storage/WAL/rollback peaks need independent
-- prepaid bounds. A 45-token count is not a memory bound. No raw parsing,
-- JSONB conversion, materialization or successful validation is authorized here.
-- Raw-to-span correspondence, lexer authenticity and resource qualification are
-- unproved; shape alone does not establish value semantics or authorization.
CREATE FUNCTION public.pro273_control_observation_shape_candidate(p_raw BYTEA,p_kinds TEXT[],p_parents INTEGER[],p_edges TEXT[],p_ordinals INTEGER[],p_units BYTEA[]) RETURNS VOID
LANGUAGE plpgsql SECURITY DEFINER SET search_path=pg_catalog AS $$
DECLARE v_names CONSTANT BYTEA[]:=ARRAY['\x0073006300680065006d006100560065007200730069006f006e'::BYTEA,'\x0062006100730065006c0069006e006500490064'::BYTEA,'\x0062006100730065006c0069006e00650043006f007200650048006100730068'::BYTEA,'\x00730065007300730069006f006e0043006c00610069006d00490064'::BYTEA,'\x0061007400740065006d0070007400490064'::BYTEA,'\x006500760065006e007400490064'::BYTEA,'\x007400610072006700650074004f00690064'::BYTEA,'\x007400610072006700650074005000720069006e0063006900700061006c'::BYTEA,'\x007400610072006700650074005000690064'::BYTEA,'\x007400610072006700650074004200610063006b0065006e006400530074006100720074'::BYTEA,'\x00630072006500640065006e007400690061006c00450070006f00630068'::BYTEA,'\x006c00610075006e0063006800450070006f00630068'::BYTEA,'\x0068006f00730074'::BYTEA,'\x0062006f006f0074'::BYTEA,'\x00700072006f00630065007300730054007200650065'::BYTEA,'\x0070006100720065006e007400500072006f00630065007300730054007200650065'::BYTEA,'\x0073006f00750072006300650043006c006f00730075007200650048006100730068'::BYTEA,'\x0069006e007300740061006c006c006100740069006f006e0043006c006f00730075007200650048006100730068'::BYTEA,'\x006f006200730065007200760065006400410074'::BYTEA,'\x00760061006c006900640055006e00740069006c'::BYTEA,'\x00650076006900640065006e00630065004200610073006500360034'::BYTEA,'\x00650076006900640065006e006300650048006100730068'::BYTEA];
 v_i INTEGER; v_j INTEGER; v_key_index INTEGER; v_mask INTEGER:=0;
BEGIN
 RAISE EXCEPTION 'SELECTION_UNAVAILABLE';
 -- Unreachable shape stage; the caller must first prove fatal UTF-8, no BOM,
 -- NUL or unpaired surrogate, and preserve decoded UTF-16 units before JSONB.
 IF p_raw IS NULL OR pg_catalog.array_ndims(p_kinds) IS DISTINCT FROM 1 OR pg_catalog.array_ndims(p_parents) IS DISTINCT FROM 1 OR pg_catalog.array_ndims(p_edges) IS DISTINCT FROM 1 OR pg_catalog.array_ndims(p_ordinals) IS DISTINCT FROM 1 OR pg_catalog.array_ndims(p_units) IS DISTINCT FROM 1 OR
    pg_catalog.array_lower(p_kinds,1) IS DISTINCT FROM 1 OR pg_catalog.array_lower(p_parents,1) IS DISTINCT FROM 1 OR pg_catalog.array_lower(p_edges,1) IS DISTINCT FROM 1 OR pg_catalog.array_lower(p_ordinals,1) IS DISTINCT FROM 1 OR pg_catalog.array_lower(p_units,1) IS DISTINCT FROM 1 OR
    pg_catalog.cardinality(p_kinds) IS DISTINCT FROM 45 OR pg_catalog.cardinality(p_parents) IS DISTINCT FROM 45 OR pg_catalog.cardinality(p_edges) IS DISTINCT FROM 45 OR pg_catalog.cardinality(p_ordinals) IS DISTINCT FROM 45 OR pg_catalog.cardinality(p_units) IS DISTINCT FROM 45 OR
    p_kinds[1] IS DISTINCT FROM 'OBJECT' OR p_parents[1] IS NOT NULL OR p_edges[1] IS DISTINCT FROM 'ROOT' OR p_ordinals[1] IS DISTINCT FROM 0 OR p_units[1] IS NOT NULL THEN RAISE EXCEPTION 'SELECTION_UNAVAILABLE'; END IF;
 FOR v_i IN 0..21 LOOP
  IF p_kinds[2+2*v_i] IS DISTINCT FROM 'STRING' OR p_kinds[3+2*v_i] IS DISTINCT FROM 'STRING' OR
     p_parents[2+2*v_i] IS DISTINCT FROM 0 OR p_parents[3+2*v_i] IS DISTINCT FROM 0 OR
     p_edges[2+2*v_i] IS DISTINCT FROM 'KEY' OR p_edges[3+2*v_i] IS DISTINCT FROM 'VALUE' OR
     p_ordinals[2+2*v_i] IS DISTINCT FROM v_i OR p_ordinals[3+2*v_i] IS DISTINCT FROM v_i OR
     p_units[2+2*v_i] IS NULL OR p_units[3+2*v_i] IS NULL THEN RAISE EXCEPTION 'SELECTION_UNAVAILABLE'; END IF;
  v_key_index:=0;
  FOR v_j IN 1..22 LOOP
   IF p_units[2+2*v_i]=v_names[v_j] THEN v_key_index:=v_j; EXIT; END IF;
  END LOOP;
  IF v_key_index=0 OR (v_mask & (1 << (v_key_index-1)))<>0 THEN RAISE EXCEPTION 'SELECTION_UNAVAILABLE'; END IF;
  v_mask:=v_mask | (1 << (v_key_index-1));
  IF v_key_index=1 AND p_units[3+2*v_i] IS DISTINCT FROM '\x00700072006f003200370033002d0063006f006e00740072006f006c002d0070006c0061006e0065002d00700072006f0063006500730073002d00760031'::BYTEA THEN RAISE EXCEPTION 'SELECTION_UNAVAILABLE'; END IF;
 END LOOP;
 IF v_mask<>4194303 THEN RAISE EXCEPTION 'SELECTION_UNAVAILABLE'; END IF;
 RAISE EXCEPTION 'SELECTION_UNAVAILABLE';
END $$;
REVOKE ALL ON FUNCTION public.pro273_control_observation_shape_candidate(BYTEA,TEXT[],INTEGER[],TEXT[],INTEGER[],BYTEA[]) FROM PUBLIC;

-- Disconnected correspondence subset, not a lexer or an admission path. Offsets
-- are zero-based half-open spans into the original BYTEA: root, then 22 pairs
-- of string tokens. Printable ASCII, JSON escapes and direct UTF-8 scalar
-- correspondence are modeled; raw/token composition and full semantics remain
-- unimplemented. This subset does not provide resource authority.
-- No input array or raw payload may be scanned or buffered until independent
-- limits cover raw/detoast, token arrays, decoded units and concurrent peaks.
-- The NULLs are deliberate: no qualified limits have been supplied. Even after
-- qualification this subset cannot authorize the shape candidate or JSONB.
CREATE FUNCTION public.pro273_control_observation_span_candidate(p_raw BYTEA,p_starts INTEGER[],p_ends INTEGER[],p_units BYTEA[]) RETURNS VOID
LANGUAGE plpgsql SECURITY DEFINER SET search_path=pg_catalog AS $$
DECLARE
 v_raw_limit BIGINT:=NULL; v_token_workspace_limit BIGINT:=NULL;
 v_decoded_limit BIGINT:=NULL; v_concurrent_peak_limit BIGINT:=NULL;
 v_len INTEGER; v_pos INTEGER:=0; v_i INTEGER; v_j INTEGER; v_end INTEGER; v_byte INTEGER;
 v_unit INTEGER; v_hex INTEGER; v_digit INTEGER; v_unit_bytes INTEGER; v_pending_high BOOLEAN;
 v_count INTEGER; v_k INTEGER; v_scalar BIGINT; v_min BIGINT;
BEGIN
 RAISE EXCEPTION 'SELECTION_UNAVAILABLE';
 -- Qualification must include pre-detoast size/peak admission; octet_length
 -- alone cannot provide that guarantee. No caller-controlled limit is authority.
 IF v_raw_limit IS NULL OR v_token_workspace_limit IS NULL OR v_decoded_limit IS NULL OR v_concurrent_peak_limit IS NULL THEN RAISE EXCEPTION 'SELECTION_UNAVAILABLE'; END IF;
 -- The admission mechanism and enforcement of all four independent limits are
 -- not implemented. Replacing NULLs alone must never enable the scan.
 RAISE EXCEPTION 'SELECTION_UNAVAILABLE';
 IF p_raw IS NULL OR pg_catalog.array_ndims(p_starts) IS DISTINCT FROM 1 OR pg_catalog.array_ndims(p_ends) IS DISTINCT FROM 1 OR pg_catalog.array_ndims(p_units) IS DISTINCT FROM 1 OR
    pg_catalog.array_lower(p_starts,1) IS DISTINCT FROM 1 OR pg_catalog.array_lower(p_ends,1) IS DISTINCT FROM 1 OR pg_catalog.array_lower(p_units,1) IS DISTINCT FROM 1 OR
    pg_catalog.cardinality(p_starts) IS DISTINCT FROM 45 OR pg_catalog.cardinality(p_ends) IS DISTINCT FROM 45 OR pg_catalog.cardinality(p_units) IS DISTINCT FROM 45 THEN RAISE EXCEPTION 'SELECTION_UNAVAILABLE'; END IF;
 v_len:=pg_catalog.octet_length(p_raw);
 IF v_len::BIGINT>v_raw_limit OR p_units[1] IS NOT NULL THEN RAISE EXCEPTION 'SELECTION_UNAVAILABLE'; END IF;
 WHILE CASE WHEN v_pos<v_len THEN pg_catalog.get_byte(p_raw,v_pos) IN (9,10,13,32) ELSE FALSE END LOOP v_pos:=v_pos+1; END LOOP;
 IF p_starts[1] IS DISTINCT FROM v_pos OR v_pos>=v_len THEN RAISE EXCEPTION 'SELECTION_UNAVAILABLE'; END IF;
 IF pg_catalog.get_byte(p_raw,v_pos)<>123 THEN RAISE EXCEPTION 'SELECTION_UNAVAILABLE'; END IF;
 v_pos:=v_pos+1;
 FOR v_i IN 2..45 LOOP
  WHILE CASE WHEN v_pos<v_len THEN pg_catalog.get_byte(p_raw,v_pos) IN (9,10,13,32) ELSE FALSE END LOOP v_pos:=v_pos+1; END LOOP;
  IF p_starts[v_i] IS DISTINCT FROM v_pos OR p_ends[v_i] IS NULL OR p_units[v_i] IS NULL OR v_pos>=v_len THEN RAISE EXCEPTION 'SELECTION_UNAVAILABLE'; END IF;
  v_end:=p_ends[v_i];
  IF v_end::BIGINT<v_pos::BIGINT+2 OR v_end>v_len OR pg_catalog.get_byte(p_raw,v_pos)<>34 THEN RAISE EXCEPTION 'SELECTION_UNAVAILABLE'; END IF;
  -- Correspondence is only a denied candidate; it does not enable admission.
  v_unit_bytes:=pg_catalog.octet_length(p_units[v_i]);
  IF v_unit_bytes%2<>0 THEN RAISE EXCEPTION 'SELECTION_UNAVAILABLE'; END IF;
  v_pos:=v_pos+1; v_j:=0; v_pending_high:=FALSE;
  WHILE v_pos<v_end-1 LOOP
   v_byte:=pg_catalog.get_byte(p_raw,v_pos);
   v_pos:=v_pos+1;
   IF v_byte=92 THEN
    IF v_pos>=v_end-1 THEN RAISE EXCEPTION 'SELECTION_UNAVAILABLE'; END IF;
    v_byte:=pg_catalog.get_byte(p_raw,v_pos); v_pos:=v_pos+1;
    IF v_byte IN (34,47,92) THEN v_unit:=v_byte;
    ELSIF v_byte=98 THEN v_unit:=8;
    ELSIF v_byte=102 THEN v_unit:=12;
    ELSIF v_byte=110 THEN v_unit:=10;
    ELSIF v_byte=114 THEN v_unit:=13;
    ELSIF v_byte=116 THEN v_unit:=9;
    ELSIF v_byte=117 THEN
     IF v_pos::BIGINT+4>v_end::BIGINT-1 THEN RAISE EXCEPTION 'SELECTION_UNAVAILABLE'; END IF;
     v_unit:=0;
     FOR v_hex IN 1..4 LOOP
      v_digit:=pg_catalog.get_byte(p_raw,v_pos); v_pos:=v_pos+1;
      IF v_digit BETWEEN 48 AND 57 THEN v_digit:=v_digit-48;
      ELSIF v_digit BETWEEN 65 AND 70 THEN v_digit:=v_digit-55;
      ELSIF v_digit BETWEEN 97 AND 102 THEN v_digit:=v_digit-87;
      ELSE RAISE EXCEPTION 'SELECTION_UNAVAILABLE'; END IF;
      v_unit:=v_unit*16+v_digit;
     END LOOP;
    ELSE RAISE EXCEPTION 'SELECTION_UNAVAILABLE'; END IF;
   ELSIF v_byte>=128 THEN
    IF v_pending_high THEN RAISE EXCEPTION 'SELECTION_UNAVAILABLE'; END IF;
    IF v_byte BETWEEN 194 AND 223 THEN v_count:=1; v_scalar:=v_byte-192; v_min:=128;
    ELSIF v_byte BETWEEN 224 AND 239 THEN v_count:=2; v_scalar:=v_byte-224; v_min:=2048;
    ELSIF v_byte BETWEEN 240 AND 244 THEN v_count:=3; v_scalar:=v_byte-240; v_min:=65536;
    ELSE RAISE EXCEPTION 'SELECTION_UNAVAILABLE'; END IF;
    IF v_pos::BIGINT+v_count::BIGINT>v_end::BIGINT-1 THEN RAISE EXCEPTION 'SELECTION_UNAVAILABLE'; END IF;
    FOR v_k IN 1..v_count LOOP
     v_digit:=pg_catalog.get_byte(p_raw,v_pos); v_pos:=v_pos+1;
     IF v_digit NOT BETWEEN 128 AND 191 THEN RAISE EXCEPTION 'SELECTION_UNAVAILABLE'; END IF;
     v_scalar:=v_scalar*64+(v_digit-128)::BIGINT;
    END LOOP;
    IF v_scalar<v_min OR v_scalar BETWEEN 55296 AND 57343 OR v_scalar>1114111 THEN RAISE EXCEPTION 'SELECTION_UNAVAILABLE'; END IF;
    IF v_scalar>=65536 THEN
     v_scalar:=v_scalar-65536;
     v_unit:=(55296+v_scalar/1024)::INTEGER;
     IF 2*v_j::BIGINT+2>v_unit_bytes::BIGINT THEN RAISE EXCEPTION 'SELECTION_UNAVAILABLE'; END IF;
     IF pg_catalog.get_byte(p_units[v_i],(2*v_j::BIGINT)::INTEGER)<>v_unit/256 OR pg_catalog.get_byte(p_units[v_i],(2*v_j::BIGINT+1)::INTEGER)<>v_unit%256 THEN RAISE EXCEPTION 'SELECTION_UNAVAILABLE'; END IF;
     v_j:=v_j+1;
     v_unit:=(56320+v_scalar%1024)::INTEGER;
     -- The generated low unit belongs to this scalar, never to an escape.
     v_pending_high:=TRUE;
    ELSE v_unit:=v_scalar::INTEGER; END IF;
   ELSE
    IF v_byte NOT BETWEEN 32 AND 127 OR v_byte=34 THEN RAISE EXCEPTION 'SELECTION_UNAVAILABLE'; END IF;
    v_unit:=v_byte;
   END IF;
   IF v_unit=0 THEN RAISE EXCEPTION 'SELECTION_UNAVAILABLE'; END IF;
   IF v_pending_high THEN
    IF v_unit NOT BETWEEN 56320 AND 57343 THEN RAISE EXCEPTION 'SELECTION_UNAVAILABLE'; END IF;
    v_pending_high:=FALSE;
   ELSIF v_unit BETWEEN 55296 AND 56319 THEN v_pending_high:=TRUE;
   ELSIF v_unit BETWEEN 56320 AND 57343 THEN RAISE EXCEPTION 'SELECTION_UNAVAILABLE'; END IF;
   IF 2*v_j::BIGINT+2>v_unit_bytes::BIGINT THEN RAISE EXCEPTION 'SELECTION_UNAVAILABLE'; END IF;
   IF pg_catalog.get_byte(p_units[v_i],(2*v_j::BIGINT)::INTEGER)<>v_unit/256 OR pg_catalog.get_byte(p_units[v_i],(2*v_j::BIGINT+1)::INTEGER)<>v_unit%256 THEN RAISE EXCEPTION 'SELECTION_UNAVAILABLE'; END IF;
   v_j:=v_j+1;
  END LOOP;
  IF v_pending_high OR 2*v_j::BIGINT<>v_unit_bytes::BIGINT OR pg_catalog.get_byte(p_raw,v_pos)<>34 THEN RAISE EXCEPTION 'SELECTION_UNAVAILABLE'; END IF;
  v_pos:=v_pos+1;
  WHILE CASE WHEN v_pos<v_len THEN pg_catalog.get_byte(p_raw,v_pos) IN (9,10,13,32) ELSE FALSE END LOOP v_pos:=v_pos+1; END LOOP;
  IF v_pos>=v_len THEN RAISE EXCEPTION 'SELECTION_UNAVAILABLE'; END IF;
  IF v_i%2=0 THEN v_byte:=58; ELSIF v_i<45 THEN v_byte:=44; ELSE v_byte:=125; END IF;
  IF pg_catalog.get_byte(p_raw,v_pos)<>v_byte THEN RAISE EXCEPTION 'SELECTION_UNAVAILABLE'; END IF;
  v_pos:=v_pos+1;
 END LOOP;
 IF p_ends[1] IS DISTINCT FROM v_pos THEN RAISE EXCEPTION 'SELECTION_UNAVAILABLE'; END IF;
 WHILE CASE WHEN v_pos<v_len THEN pg_catalog.get_byte(p_raw,v_pos) IN (9,10,13,32) ELSE FALSE END LOOP v_pos:=v_pos+1; END LOOP;
 IF v_pos<>v_len THEN RAISE EXCEPTION 'SELECTION_UNAVAILABLE'; END IF;
 RAISE EXCEPTION 'SELECTION_UNAVAILABLE';
END $$;
REVOKE ALL ON FUNCTION public.pro273_control_observation_span_candidate(BYTEA,INTEGER[],INTEGER[],BYTEA[]) FROM PUBLIC;

-- Separate FKs do not prove the same session/attempt/reservation/claim tuple;
-- future provisioning and every consumer must compare the complete protected row,
-- including receiver/epochs, provenance, observer, charges and transaction ids.
CREATE TABLE public."Pro273ControlPlaneObservationBinding" (
 "reservationId" TEXT PRIMARY KEY REFERENCES public."Pro262CapacityObserverInputReservation"("reservationId") ON UPDATE RESTRICT ON DELETE RESTRICT,
 "baselineId" TEXT NOT NULL, "baselineCoreHash" TEXT NOT NULL CHECK ("baselineCoreHash" ~ '^[a-f0-9]{64}$'),
 "sessionClaimId" TEXT NOT NULL UNIQUE, "attemptId" TEXT NOT NULL,
 "expectedEventKey" TEXT NOT NULL UNIQUE, "trustId" TEXT NOT NULL, "trustGeneration" BIGINT NOT NULL,
 "qualificationHash" TEXT NOT NULL CHECK ("qualificationHash" ~ '^[a-f0-9]{64}$'),
 "chargeKind" TEXT NOT NULL, "chargeEventKey" TEXT NOT NULL, "chargeBindingHash" TEXT NOT NULL CHECK ("chargeBindingHash" ~ '^[a-f0-9]{64}$'),
 "creationTransactionId" xid8 NOT NULL,
 FOREIGN KEY ("baselineId","baselineCoreHash") REFERENCES public."Pro273ControlPlaneBaseline"("baselineId","coreHash") ON UPDATE RESTRICT ON DELETE RESTRICT,
 FOREIGN KEY ("baselineId","sessionClaimId") REFERENCES public."Pro273ControlPlaneSessionClaim"("baselineId","sessionClaimId") ON UPDATE RESTRICT ON DELETE RESTRICT,
 FOREIGN KEY ("baselineId","attemptId") REFERENCES public."Pro273ControlPlaneLaunchAttempt"("baselineId","attemptId") ON UPDATE RESTRICT ON DELETE RESTRICT,
 FOREIGN KEY ("trustId","trustGeneration") REFERENCES public."Pro262CapacityTrust"("trustId","generation") ON UPDATE RESTRICT ON DELETE RESTRICT,
 FOREIGN KEY ("chargeKind","chargeEventKey") REFERENCES public."Pro262CapacityControlCharge"("kind","eventKey") ON UPDATE RESTRICT ON DELETE RESTRICT,
 UNIQUE ("chargeKind","chargeEventKey"),
 CHECK (pg_catalog.octet_length("reservationId") BETWEEN 1 AND 256 AND pg_catalog.octet_length("baselineId") BETWEEN 1 AND 256 AND pg_catalog.octet_length("sessionClaimId") BETWEEN 1 AND 256 AND pg_catalog.octet_length("attemptId") BETWEEN 1 AND 256 AND pg_catalog.octet_length("expectedEventKey") BETWEEN 1 AND 256 AND pg_catalog.octet_length("trustId") BETWEEN 1 AND 256 AND pg_catalog.octet_length("chargeKind") BETWEEN 1 AND 256 AND pg_catalog.octet_length("chargeEventKey") BETWEEN 1 AND 256 AND "trustGeneration">0)
);
CREATE TABLE public."Pro273ControlPlaneObservationLinkage" (
 "sessionClaimId" TEXT PRIMARY KEY REFERENCES public."Pro273ControlPlaneProcessObservation"("sessionClaimId") ON UPDATE RESTRICT ON DELETE RESTRICT,
 "reservationId" TEXT NOT NULL UNIQUE REFERENCES public."Pro273ControlPlaneObservationBinding"("reservationId") ON UPDATE RESTRICT ON DELETE RESTRICT,
 "inputClaimId" TEXT NOT NULL UNIQUE REFERENCES public."Pro262CapacityObserverInputClaim"("inputClaimId") ON UPDATE RESTRICT ON DELETE RESTRICT,
 "eventId" TEXT NOT NULL UNIQUE, "observedAt" TIMESTAMPTZ NOT NULL,
 "evidenceBytes" BYTEA NOT NULL, "evidenceHash" TEXT NOT NULL CHECK ("evidenceHash" ~ '^[a-f0-9]{64}$'),
 "chargeKind" TEXT NOT NULL, "chargeEventKey" TEXT NOT NULL, "chargeBindingHash" TEXT NOT NULL CHECK ("chargeBindingHash" ~ '^[a-f0-9]{64}$'),
 "constructionTransactionId" xid8 NOT NULL,
 FOREIGN KEY ("chargeKind","chargeEventKey") REFERENCES public."Pro262CapacityControlCharge"("kind","eventKey") ON UPDATE RESTRICT ON DELETE RESTRICT,
 UNIQUE ("chargeKind","chargeEventKey"),
 CHECK (pg_catalog.octet_length("sessionClaimId") BETWEEN 1 AND 256 AND pg_catalog.octet_length("reservationId") BETWEEN 1 AND 256 AND pg_catalog.octet_length("inputClaimId") BETWEEN 1 AND 256 AND pg_catalog.octet_length("eventId") BETWEEN 1 AND 256 AND pg_catalog.octet_length("chargeKind") BETWEEN 1 AND 256 AND pg_catalog.octet_length("chargeEventKey") BETWEEN 1 AND 256 AND pg_catalog.octet_length("evidenceBytes") BETWEEN 1 AND 1048576)
);
-- Denied private companion only. Separate keys do not prove same-row claim,
-- reservation, binding or issuer correspondence; hashes authenticate nothing.
-- Issuer authorization, receiver fence and durable issuance-attempt/UNKNOWN
-- proof are absent. Bounds are provisional and unqualified; NAME must be
-- validated before casting by any future issuer. No issuer or acceptance exists.
CREATE TABLE public."Pro273ControlPlaneObservationAdmission" (
 "inputClaimId" TEXT PRIMARY KEY REFERENCES public."Pro262CapacityObserverInputClaim"("inputClaimId") ON UPDATE RESTRICT ON DELETE RESTRICT,
 "reservationId" TEXT NOT NULL UNIQUE REFERENCES public."Pro273ControlPlaneObservationBinding"("reservationId") ON UPDATE RESTRICT ON DELETE RESTRICT,
 "issuerTrustId" TEXT NOT NULL, "issuerTrustGeneration" BIGINT NOT NULL,
 "issuerTrustRecordHash" TEXT NOT NULL CHECK ("issuerTrustRecordHash" ~ '^[a-f0-9]{64}$'),
 "issuerPrincipalOid" OID NOT NULL, "issuerPrincipalName" NAME NOT NULL,
 "issuerBackendPid" INTEGER NOT NULL, "issuerBackendStart" TIMESTAMPTZ NOT NULL,
 "qualificationHash" TEXT NOT NULL CHECK ("qualificationHash" ~ '^[a-f0-9]{64}$'),
 "chargeKind" TEXT NOT NULL, "chargeEventKey" TEXT NOT NULL,
 "chargeBindingHash" TEXT NOT NULL CHECK ("chargeBindingHash" ~ '^[a-f0-9]{64}$'),
 "creationTransactionId" xid8 NOT NULL,
 FOREIGN KEY ("issuerTrustId","issuerTrustGeneration") REFERENCES public."Pro262CapacityTrust"("trustId","generation") ON UPDATE RESTRICT ON DELETE RESTRICT,
 FOREIGN KEY ("chargeKind","chargeEventKey") REFERENCES public."Pro262CapacityControlCharge"("kind","eventKey") ON UPDATE RESTRICT ON DELETE RESTRICT,
 UNIQUE ("chargeKind","chargeEventKey"),
 CHECK (pg_catalog.octet_length("inputClaimId") BETWEEN 1 AND 256 AND pg_catalog.octet_length("reservationId") BETWEEN 1 AND 256 AND pg_catalog.octet_length("issuerTrustId") BETWEEN 1 AND 256 AND pg_catalog.octet_length("issuerPrincipalName"::TEXT) BETWEEN 1 AND 256 AND pg_catalog.octet_length("chargeKind") BETWEEN 1 AND 256 AND pg_catalog.octet_length("chargeEventKey") BETWEEN 1 AND 256 AND "issuerTrustGeneration">0 AND "issuerPrincipalOid">0 AND "issuerBackendPid">0)
);
CREATE FUNCTION public.pro273_control_observation_admission_deny_insert() RETURNS TRIGGER
LANGUAGE plpgsql SET search_path=pg_catalog AS $$
BEGIN
 NEW."creationTransactionId":=pg_catalog.pg_current_xact_id();
 RAISE EXCEPTION 'SELECTION_UNAVAILABLE';
 -- Unreachable tuple candidate only: independently authenticated issuer and
 -- receiver/physical/source/install qualification are absent; the scoped
 -- receiver hash is only a shaped identifier. Durable issuance-attempt/UNKNOWN
 -- handling, full charge coverage and disjointness, and claim/fence commitment
 -- are absent. Neither distinct xids nor copied hashes establish those proofs.
 IF NOT EXISTS (
  SELECT 1 FROM public."Pro262CapacityObserverInputClaim" c
  JOIN public."Pro262CapacityObserverInputReservation" slot ON slot."reservationId"=c."reservationId"
  JOIN public."Pro273ControlPlaneObservationBinding" b ON b."reservationId"=c."reservationId"
  JOIN public."Pro273ControlPlaneBaseline" base ON (base."baselineId",base."coreHash")=(b."baselineId",b."baselineCoreHash")
  JOIN public."Pro273ControlPlaneSessionClaim" s ON (s."baselineId",s."sessionClaimId",s."attemptId")=(b."baselineId",b."sessionClaimId",b."attemptId")
  JOIN public."Pro273ControlPlaneLaunchAttempt" a ON (a."baselineId",a."attemptId",a."receiverIdentity")=(s."baselineId",s."attemptId",s."receiverIdentity")
  JOIN public."Pro262CapacityTrust" issuer ON (issuer."trustId",issuer."generation")=(NEW."issuerTrustId",NEW."issuerTrustGeneration")
  JOIN public."Pro262CapacityBootstrapTrust" issuer_boot ON (issuer_boot."trustId",issuer_boot."generation",issuer_boot."recordHash")=(issuer."trustId",issuer."generation",NEW."issuerTrustRecordHash")
  JOIN public."Pro262CapacityControlCharge" charge ON (charge."kind",charge."eventKey",charge."bindingHash")=(NEW."chargeKind",NEW."chargeEventKey",NEW."chargeBindingHash")
  WHERE (c."inputClaimId",c."reservationId")=(NEW."inputClaimId",NEW."reservationId")
   AND issuer."purpose" IS NOT DISTINCT FROM 'CONTROL_ALLOCATOR'
   AND issuer."supplierPrincipal" IS NOT DISTINCT FROM NEW."issuerPrincipalName"
   AND issuer_boot."principal" IS NOT DISTINCT FROM issuer."supplierPrincipal"
   AND issuer_boot."channelId" IS NOT DISTINCT FROM issuer."channelId"
   AND NEW."issuerTrustGeneration">0 AND NEW."issuerPrincipalOid">0 AND NEW."issuerBackendPid">0
   AND pg_catalog.octet_length(NEW."inputClaimId") BETWEEN 1 AND 256 AND pg_catalog.octet_length(NEW."reservationId") BETWEEN 1 AND 256
   AND pg_catalog.octet_length(NEW."chargeKind") BETWEEN 1 AND 256 AND pg_catalog.octet_length(NEW."chargeEventKey") BETWEEN 1 AND 256
   AND NEW."qualificationHash" ~ '^[a-f0-9]{64}$' AND NEW."chargeBindingHash" ~ '^[a-f0-9]{64}$'
   AND CASE WHEN pg_catalog.jsonb_typeof(issuer."scope")='object' THEN
    (SELECT pg_catalog.count(*) FROM pg_catalog.jsonb_object_keys(issuer."scope"))=13
    AND issuer."scope" ?& ARRAY['kind','reservationId','bindingCreationTransactionId','expectedInputClaimId','issuerPrincipalOid','issuerPrincipalName','issuerBackendPid','issuerBackendStart','issuerReceiverClosureHash','qualificationHash','chargeKind','chargeEventKey','chargeBindingHash']
    AND NOT EXISTS (SELECT 1 FROM pg_catalog.jsonb_each(issuer."scope") field WHERE pg_catalog.jsonb_typeof(field.value) IS DISTINCT FROM 'string')
    AND issuer."scope"->>'kind' IS NOT DISTINCT FROM 'CONTROL_PLANE_OBSERVATION_ADMISSION'
    AND issuer."scope"->>'reservationId' IS NOT DISTINCT FROM b."reservationId"
    AND issuer."scope"->>'bindingCreationTransactionId' ~ '^[1-9][0-9]{0,19}$'
    AND issuer."scope"->>'bindingCreationTransactionId' IS NOT DISTINCT FROM b."creationTransactionId"::TEXT
    AND issuer."scope"->>'expectedInputClaimId' IS NOT DISTINCT FROM c."inputClaimId"
    AND issuer."scope"->>'issuerPrincipalOid' ~ '^[1-9][0-9]{0,9}$'
    AND issuer."scope"->>'issuerPrincipalOid' IS NOT DISTINCT FROM NEW."issuerPrincipalOid"::TEXT
    AND pg_catalog.octet_length(issuer."scope"->>'issuerPrincipalName') BETWEEN 1 AND 256
    AND issuer."scope"->>'issuerPrincipalName' IS NOT DISTINCT FROM NEW."issuerPrincipalName"::TEXT
    AND issuer."scope"->>'issuerBackendPid' ~ '^[1-9][0-9]{0,9}$'
    AND issuer."scope"->>'issuerBackendPid' IS NOT DISTINCT FROM NEW."issuerBackendPid"::TEXT
    AND CASE WHEN NEW."issuerBackendStart" IS NOT NULL AND pg_catalog.isfinite(NEW."issuerBackendStart")
      AND (NEW."issuerBackendStart" AT TIME ZONE 'UTC')>=TIMESTAMP '0001-01-01 00:00:00'
      AND (NEW."issuerBackendStart" AT TIME ZONE 'UTC')<TIMESTAMP '10000-01-01 00:00:00'
     THEN issuer."scope"->>'issuerBackendStart' IS NOT DISTINCT FROM pg_catalog.to_char(NEW."issuerBackendStart" AT TIME ZONE 'UTC','YYYY-MM-DD"T"HH24:MI:SS.US"Z"')
     ELSE FALSE END
    AND issuer."scope"->>'issuerReceiverClosureHash' ~ '^[a-f0-9]{64}$'
    AND issuer."scope"->>'qualificationHash' IS NOT DISTINCT FROM NEW."qualificationHash"
    AND issuer."scope"->>'chargeKind' IS NOT DISTINCT FROM NEW."chargeKind"
    AND issuer."scope"->>'chargeEventKey' IS NOT DISTINCT FROM NEW."chargeEventKey"
    AND issuer."scope"->>'chargeBindingHash' IS NOT DISTINCT FROM NEW."chargeBindingHash"
   ELSE FALSE END
   AND (slot."observerTrustId",slot."observerTrustGeneration",slot."physicalIdentity",slot."physicalProofIdentity")=(b."trustId",b."trustGeneration",base."physicalIdentity",base."physicalProofIdentity")
   AND (s."principalOid",s."principalName",s."credentialEpoch",s."launchEpoch")=(base."principalOid",base."principalName",base."credentialEpoch",base."launchEpoch")
   AND slot."observerPrincipalOid" IS DISTINCT FROM s."principalOid"
   AND (c."phase",c."observerPrincipalOid",c."observerPrincipalName")=(slot."phase",slot."observerPrincipalOid",slot."observerPrincipalName")
   AND slot."phase"='INSTALL_PROCESS' AND slot."record"->>'targetKind'='CONTROL_PLANE'
   AND (c."eventKey",slot."record"->>'expectedEventKey')=(b."expectedEventKey",b."expectedEventKey")
   AND (slot."record"->>'targetControlKey',slot."record"->>'targetCredentialEpoch',slot."record"->>'targetLaunchEpoch')=(base."baselineId",s."credentialEpoch",s."launchEpoch")
   AND b."creationTransactionId" IS DISTINCT FROM NEW."creationTransactionId"
   AND s."creationTransactionId" IS DISTINCT FROM NEW."creationTransactionId"
   AND a."creationTransactionId" IS DISTINCT FROM NEW."creationTransactionId"
 ) THEN RAISE EXCEPTION 'SELECTION_UNAVAILABLE'; END IF;
 RAISE EXCEPTION 'SELECTION_UNAVAILABLE';
END $$;
CREATE TRIGGER "Pro273ControlPlaneObservationAdmission_deny_insert" BEFORE INSERT ON public."Pro273ControlPlaneObservationAdmission" FOR EACH ROW EXECUTE FUNCTION public.pro273_control_observation_admission_deny_insert();
REVOKE ALL ON TABLE public."Pro273ControlPlaneObservationAdmission" FROM PUBLIC;
REVOKE ALL ON FUNCTION public.pro273_control_observation_admission_deny_insert() FROM PUBLIC;
-- The original observation retains captured bytes; these references alone do
-- not establish that its input/session equals this linkage or that charges are
-- disjoint across tables. No xid stamped here can represent acceptance.
CREATE FUNCTION public.pro273_control_observation_deny_insert() RETURNS TRIGGER
LANGUAGE plpgsql SET search_path=pg_catalog AS $$
BEGIN
 IF TG_TABLE_SCHEMA='public' AND TG_TABLE_NAME='Pro273ControlPlaneObservationBinding' THEN
  NEW."creationTransactionId":=pg_catalog.pg_current_xact_id();
 ELSIF TG_TABLE_SCHEMA='public' AND TG_TABLE_NAME='Pro273ControlPlaneObservationLinkage' THEN
  NEW."constructionTransactionId":=pg_catalog.pg_current_xact_id();
 ELSE
  RAISE EXCEPTION 'SELECTION_UNAVAILABLE';
 END IF;
 RAISE EXCEPTION 'SELECTION_UNAVAILABLE';
 -- Unreachable candidate only. Removing the denial requires a separately adopted
 -- global/physical, trust/bootstrap/provenance, baseline, attempt/session,
 -- reservation/binding/claim, observation, baseline/charge lock order. Supplier
 -- lane, atomic issuer, prepaid durable/index/WAL resources, original observer
 -- capability, receiver/inspector/fence, closed ABI and all consumers are absent.
 -- Qualification hashes are identifiers here, not authentication of evidence.
 -- Distinct xids alone prove neither prior claim/fence commitment nor charge
 -- concurrency safety or authorization.
 IF TG_TABLE_SCHEMA='public' AND TG_TABLE_NAME='Pro273ControlPlaneObservationBinding' THEN
  IF NOT EXISTS (
   SELECT 1 FROM public."Pro262CapacityObserverInputReservation" slot
   JOIN public."Pro273ControlPlaneBaseline" base ON (base."baselineId",base."coreHash")=(NEW."baselineId",NEW."baselineCoreHash")
   JOIN public."Pro273ControlPlaneBaselineProvenance" prov ON (prov."baselineId",prov."coreHash")=(base."baselineId",base."coreHash")
   JOIN public."Pro273ControlPlaneInstallerExpectation" exp ON exp."bootstrapKind"=prov."bootstrapKind"
   JOIN public."Pro273ControlPlaneSessionClaim" s ON (s."baselineId",s."sessionClaimId",s."attemptId")=(NEW."baselineId",NEW."sessionClaimId",NEW."attemptId")
   JOIN public."Pro273ControlPlaneLaunchAttempt" a ON (a."baselineId",a."attemptId",a."receiverIdentity")=(s."baselineId",s."attemptId",s."receiverIdentity")
   JOIN public."Pro262CapacityControlCharge" charge ON (charge."kind",charge."eventKey",charge."bindingHash")=(NEW."chargeKind",NEW."chargeEventKey",NEW."chargeBindingHash")
   WHERE slot."reservationId"=NEW."reservationId"
    AND (slot."physicalIdentity",slot."physicalProofIdentity",slot."observerTrustId",slot."observerTrustGeneration")=(base."physicalIdentity",base."physicalProofIdentity",NEW."trustId",NEW."trustGeneration")
    AND (s."principalOid",s."principalName",s."credentialEpoch",s."launchEpoch")=(base."principalOid",base."principalName",base."credentialEpoch",base."launchEpoch")
    AND slot."observerPrincipalOid" IS DISTINCT FROM s."principalOid"
    AND slot."record"->>'targetKind'='CONTROL_PLANE' AND slot."phase"='INSTALL_PROCESS'
    AND s."creationTransactionId" IS DISTINCT FROM NEW."creationTransactionId"
    AND a."creationTransactionId" IS DISTINCT FROM NEW."creationTransactionId"
    AND (slot."record"->>'targetControlKey',slot."record"->>'targetCredentialEpoch',slot."record"->>'targetLaunchEpoch',slot."record"->>'expectedEventKey')=(base."baselineId",s."credentialEpoch",s."launchEpoch",NEW."expectedEventKey")
    AND (base."physicalIdentity",base."physicalProofIdentity",base."expectedFutureLayoutCoreHash")=(exp."physicalIdentity",exp."physicalProofIdentity",exp."expectedFutureLayoutCoreHash")
    AND (exp."constructorKind",exp."expectedTargetId",exp."expectedCoreHash",exp."expectedEvidenceHash",exp."sessionClaimId",exp."eventId",exp."installerOid",exp."installerName",exp."trustId",exp."trustGeneration",exp."chargeKind",exp."chargeEventKey",exp."chargeBindingHash")=('CONTROL_PLANE_BASELINE',prov."baselineId",prov."coreHash",prov."evidenceHash",prov."sessionClaimId",prov."eventId",prov."publisherPrincipalOid",prov."publisherPrincipalName",prov."trustId",prov."trustGeneration",prov."chargeKind",prov."chargeEventKey",prov."chargeBindingHash")
    AND (NEW."chargeKind",NEW."chargeEventKey") IS DISTINCT FROM ('OBSERVER_INPUT_SLOT',slot."prepaidEventKey")
    AND (NEW."chargeKind",NEW."chargeEventKey") IS DISTINCT FROM (a."chargeKind",a."chargeEventKey")
    AND (NEW."chargeKind",NEW."chargeEventKey") IS DISTINCT FROM (a."sessionChargeKind",a."sessionChargeEventKey")
    AND (NEW."chargeKind",NEW."chargeEventKey") IS DISTINCT FROM (prov."chargeKind",prov."chargeEventKey")
    AND NOT EXISTS (SELECT 1 FROM public."Pro273ControlPlaneObservationLinkage" l WHERE (l."chargeKind",l."chargeEventKey")=(NEW."chargeKind",NEW."chargeEventKey"))
  ) THEN RAISE EXCEPTION 'SELECTION_UNAVAILABLE'; END IF;
 ELSIF TG_TABLE_SCHEMA='public' AND TG_TABLE_NAME='Pro273ControlPlaneObservationLinkage' THEN
  IF NOT EXISTS (
   SELECT 1 FROM public."Pro273ControlPlaneObservationBinding" b
   JOIN public."Pro262CapacityObserverInputReservation" slot ON slot."reservationId"=b."reservationId"
   JOIN public."Pro262CapacityObserverInputClaim" c ON (c."reservationId",c."inputClaimId",c."eventKey")=(b."reservationId",NEW."inputClaimId",b."expectedEventKey")
   JOIN public."Pro273ControlPlaneSessionClaim" s ON (s."baselineId",s."sessionClaimId",s."attemptId")=(b."baselineId",b."sessionClaimId",b."attemptId")
   JOIN public."Pro273ControlPlaneLaunchAttempt" a ON (a."baselineId",a."attemptId",a."receiverIdentity")=(s."baselineId",s."attemptId",s."receiverIdentity")
   JOIN public."Pro273ControlPlaneBaseline" base ON (base."baselineId",base."coreHash")=(b."baselineId",b."baselineCoreHash")
   JOIN public."Pro273ControlPlaneBaselineProvenance" prov ON (prov."baselineId",prov."coreHash")=(base."baselineId",base."coreHash")
   JOIN public."Pro273ControlPlaneProcessObservation" o ON (o."sessionClaimId",o."inputClaimId")=(s."sessionClaimId",c."inputClaimId")
   JOIN public."Pro262CapacityControlCharge" charge ON (charge."kind",charge."eventKey",charge."bindingHash")=(NEW."chargeKind",NEW."chargeEventKey",NEW."chargeBindingHash")
   WHERE (NEW."reservationId",NEW."sessionClaimId",NEW."eventId")=(b."reservationId",b."sessionClaimId",b."expectedEventKey")
    AND (s."principalOid",s."principalName",s."credentialEpoch",s."launchEpoch")=(base."principalOid",base."principalName",base."credentialEpoch",base."launchEpoch")
    AND slot."observerPrincipalOid" IS DISTINCT FROM s."principalOid"
    AND slot."record"->>'targetKind'='CONTROL_PLANE' AND slot."phase"='INSTALL_PROCESS'
    AND (c."phase",c."eventKey")=(slot."phase",slot."record"->>'expectedEventKey')
    AND s."creationTransactionId" IS DISTINCT FROM NEW."constructionTransactionId"
    AND a."creationTransactionId" IS DISTINCT FROM NEW."constructionTransactionId"
    AND (o."principalOid",o."principalName",o."credentialEpoch",o."launchEpoch",o."host",o."boot",o."processTree",o."parentProcessTree",o."sourceClosureHash",o."installationClosureHash")=(base."principalOid",base."principalName",base."credentialEpoch",base."launchEpoch",base."host",base."boot",base."processTree",base."parentProcessTree",base."sourceClosureHash",base."installationClosureHash")
    AND (c."phase",c."observerPrincipalOid",c."observerPrincipalName")=(slot."phase",slot."observerPrincipalOid",slot."observerPrincipalName")
    AND (o."observerOid",o."observerPrincipal",o."trustId",o."trustGeneration")=(slot."observerPrincipalOid",slot."observerPrincipalName",b."trustId",b."trustGeneration")
    AND (slot."observerTrustId",slot."observerTrustGeneration",slot."physicalIdentity",slot."physicalProofIdentity")=(b."trustId",b."trustGeneration",base."physicalIdentity",base."physicalProofIdentity")
    AND b."creationTransactionId" IS DISTINCT FROM NEW."constructionTransactionId"
    AND (NEW."chargeKind",NEW."chargeEventKey") IS DISTINCT FROM ('OBSERVER_INPUT_SLOT',slot."prepaidEventKey")
    AND (NEW."chargeKind",NEW."chargeEventKey") IS DISTINCT FROM (a."chargeKind",a."chargeEventKey")
    AND (NEW."chargeKind",NEW."chargeEventKey") IS DISTINCT FROM (a."sessionChargeKind",a."sessionChargeEventKey")
    AND (NEW."chargeKind",NEW."chargeEventKey") IS DISTINCT FROM (prov."chargeKind",prov."chargeEventKey")
    AND NOT EXISTS (SELECT 1 FROM public."Pro273ControlPlaneObservationBinding" other WHERE (other."chargeKind",other."chargeEventKey")=(NEW."chargeKind",NEW."chargeEventKey"))
  ) THEN RAISE EXCEPTION 'SELECTION_UNAVAILABLE'; END IF;
 ELSE
  RAISE EXCEPTION 'SELECTION_UNAVAILABLE';
 END IF;
 RAISE EXCEPTION 'SELECTION_UNAVAILABLE';
END $$;
CREATE FUNCTION public.pro273_control_observation_deny_mutation() RETURNS TRIGGER
LANGUAGE plpgsql SET search_path=pg_catalog AS $$
BEGIN
 RAISE EXCEPTION 'SELECTION_UNAVAILABLE';
END $$;
CREATE TRIGGER "Pro273ControlPlaneObservationBinding_deny_insert" BEFORE INSERT ON public."Pro273ControlPlaneObservationBinding" FOR EACH ROW EXECUTE FUNCTION public.pro273_control_observation_deny_insert();
CREATE TRIGGER "Pro273ControlPlaneObservationLinkage_deny_insert" BEFORE INSERT ON public."Pro273ControlPlaneObservationLinkage" FOR EACH ROW EXECUTE FUNCTION public.pro273_control_observation_deny_insert();
CREATE TRIGGER "Pro273ControlPlaneObservationBinding_immutable" BEFORE UPDATE OR DELETE ON public."Pro273ControlPlaneObservationBinding" FOR EACH ROW EXECUTE FUNCTION public.pro273_control_observation_deny_mutation();
CREATE TRIGGER "Pro273ControlPlaneObservationLinkage_immutable" BEFORE UPDATE OR DELETE ON public."Pro273ControlPlaneObservationLinkage" FOR EACH ROW EXECUTE FUNCTION public.pro273_control_observation_deny_mutation();
CREATE TRIGGER "Pro273ControlPlaneObservationAdmission_immutable" BEFORE UPDATE OR DELETE ON public."Pro273ControlPlaneObservationAdmission" FOR EACH ROW EXECUTE FUNCTION public.pro273_control_observation_deny_mutation();
REVOKE ALL ON TABLE public."Pro273ControlPlaneObservationBinding",public."Pro273ControlPlaneObservationLinkage" FROM PUBLIC;
REVOKE ALL ON FUNCTION public.pro273_control_observation_deny_insert(),public.pro273_control_observation_deny_mutation() FROM PUBLIC;

-- Private scalar discovery candidate only: no locks, authorization or historical
-- qualification. The two denials keep this unreachable until separate review.
-- The 256-byte input cap is provisional and unqualified; it establishes neither
-- an identifier ABI nor resource qualification.
CREATE FUNCTION public.pro273_initial_discover_installer_history(p_baseline_id TEXT) RETURNS VOID
LANGUAGE plpgsql SECURITY DEFINER SET search_path=pg_catalog AS $$
DECLARE
 v_baseline_id TEXT; v_core_hash TEXT; v_bootstrap_kind TEXT; v_expectation_id TEXT;
 v_credential_epoch TEXT; v_launch_epoch TEXT; v_event_id TEXT;
 v_constructor_claim_id TEXT; v_constructor_reservation_id TEXT; v_constructor_event TEXT; v_constructor_phase TEXT;
 v_constructor_trust_id TEXT; v_constructor_trust_generation BIGINT; v_constructor_slot_event TEXT; v_constructor_slot_hash TEXT;
 v_provenance_trust_id TEXT; v_provenance_trust_generation BIGINT; v_evidence_hash TEXT;
 v_expectation_charge_kind TEXT; v_expectation_charge_event TEXT; v_expectation_charge_hash TEXT;
 v_observation_id TEXT; v_observation_receipt_id TEXT; v_observation_claim_id TEXT; v_observation_reservation_id TEXT;
 v_observation_event TEXT; v_observation_phase TEXT; v_observation_trust_id TEXT; v_observation_trust_generation BIGINT;
 v_observation_slot_trust_id TEXT; v_observation_slot_trust_generation BIGINT; v_observation_slot_event TEXT; v_observation_slot_hash TEXT;
 v_observation_charge_kind TEXT; v_observation_charge_event TEXT; v_observation_charge_hash TEXT;
 v_session_id TEXT; v_session_charge_kind TEXT; v_session_charge_event TEXT; v_session_charge_hash TEXT;
 v_attempt_id TEXT; v_dispatch_charge_kind TEXT; v_dispatch_charge_event TEXT; v_dispatch_charge_hash TEXT;
 v_delivery_charge_kind TEXT; v_delivery_charge_event TEXT; v_delivery_charge_hash TEXT; v_receiver_hash TEXT;
BEGIN
 RAISE EXCEPTION 'SELECTION_UNAVAILABLE';
 IF p_baseline_id IS NULL OR pg_catalog.octet_length(p_baseline_id) NOT BETWEEN 1 AND 256 THEN RAISE EXCEPTION 'SELECTION_UNAVAILABLE'; END IF;
 -- Fixed installer subroute snapshot only. Inner joins represent required presence;
 -- a missing component denies. No bytes or whole JSON values are projected.
 -- This is not the complete INITIAL route, a frozen set, or qualification.
 SELECT base."baselineId",base."coreHash",prov."bootstrapKind",exp."expectationId",
        exp."credentialEpoch",exp."launchEpoch",exp."eventId",
        constructor_claim."inputClaimId",constructor_slot."reservationId",constructor_claim."eventKey",constructor_claim."phase",
        constructor_slot."observerTrustId",constructor_slot."observerTrustGeneration",constructor_slot."prepaidEventKey",constructor_slot."recordHash",
        prov."trustId",prov."trustGeneration",prov."evidenceHash",exp."chargeKind",exp."chargeEventKey",exp."chargeBindingHash",
        observation."observationId",observation."receiptId",observation_claim."inputClaimId",observation_slot."reservationId",
        observation_claim."eventKey",observation_claim."phase",observation."trustId",observation."trustGeneration",
        observation_slot."observerTrustId",observation_slot."observerTrustGeneration",observation_slot."prepaidEventKey",observation_slot."recordHash",
        observation."chargeKind",observation."chargeEventKey",observation."chargeBindingHash",
        session_claim."sessionClaimId",session_claim."chargeKind",session_claim."chargeEventKey",session_claim."chargeBindingHash",
        attempt."attemptId",attempt."chargeKind",attempt."chargeEventKey",attempt."chargeBindingHash",
        delivery."chargeKind",delivery."chargeEventKey",delivery."chargeBindingHash",delivery."receiverClosureHash"
 INTO STRICT v_baseline_id,v_core_hash,v_bootstrap_kind,v_expectation_id,
        v_credential_epoch,v_launch_epoch,v_event_id,
        v_constructor_claim_id,v_constructor_reservation_id,v_constructor_event,v_constructor_phase,
        v_constructor_trust_id,v_constructor_trust_generation,v_constructor_slot_event,v_constructor_slot_hash,
        v_provenance_trust_id,v_provenance_trust_generation,v_evidence_hash,v_expectation_charge_kind,v_expectation_charge_event,v_expectation_charge_hash,
        v_observation_id,v_observation_receipt_id,v_observation_claim_id,v_observation_reservation_id,
        v_observation_event,v_observation_phase,v_observation_trust_id,v_observation_trust_generation,
        v_observation_slot_trust_id,v_observation_slot_trust_generation,v_observation_slot_event,v_observation_slot_hash,
        v_observation_charge_kind,v_observation_charge_event,v_observation_charge_hash,
        v_session_id,v_session_charge_kind,v_session_charge_event,v_session_charge_hash,
        v_attempt_id,v_dispatch_charge_kind,v_dispatch_charge_event,v_dispatch_charge_hash,
        v_delivery_charge_kind,v_delivery_charge_event,v_delivery_charge_hash,v_receiver_hash
 FROM public."Pro273ControlPlaneBaseline" base
 JOIN public."Pro273ControlPlaneBaselineProvenance" prov ON (prov."baselineId",prov."coreHash")=(base."baselineId",base."coreHash")
 JOIN public."Pro273ControlPlaneInstallerExpectation" exp ON exp."bootstrapKind"=prov."bootstrapKind"
 JOIN public."Pro262CapacityObserverInputClaim" constructor_claim ON constructor_claim."inputClaimId"=prov."inputClaimId"
 JOIN public."Pro262CapacityObserverInputReservation" constructor_slot ON constructor_slot."reservationId"=constructor_claim."reservationId"
 JOIN public."Pro273InstallerSlotBinding" constructor_binding ON constructor_binding."reservationId"=constructor_slot."reservationId"
 JOIN public."Pro273InstallerProcessObservation" observation ON (observation."expectationId",observation."credentialEpoch",observation."launchEpoch")=(exp."expectationId",exp."credentialEpoch",exp."launchEpoch")
 JOIN public."Pro262CapacityObserverInputClaim" observation_claim ON observation_claim."inputClaimId"=observation."inputClaimId"
 JOIN public."Pro262CapacityObserverInputReservation" observation_slot ON observation_slot."reservationId"=observation_claim."reservationId"
 JOIN public."Pro273InstallerSlotBinding" observation_binding ON observation_binding."reservationId"=observation_slot."reservationId"
 JOIN public."Pro273InstallerSessionClaim" session_claim ON (session_claim."expectationId",session_claim."sessionClaimId")=(exp."expectationId",exp."sessionClaimId")
 JOIN public."Pro273InstallerDispatchAttempt" attempt ON (attempt."attemptId",attempt."expectationId",attempt."sessionClaimId",attempt."inputClaimId")=(exp."dispatchAttemptId",exp."expectationId",session_claim."sessionClaimId",constructor_claim."inputClaimId")
 JOIN public."Pro273InstallerDelivery" delivery ON (delivery."attemptId",delivery."expectationId",delivery."sessionClaimId",delivery."inputClaimId",delivery."receiverClosureHash",delivery."chargeKind",delivery."chargeEventKey",delivery."chargeBindingHash")=(attempt."attemptId",attempt."expectationId",attempt."sessionClaimId",attempt."inputClaimId",attempt."receiverClosureHash",attempt."deliveryChargeKind",attempt."deliveryChargeEventKey",attempt."deliveryChargeBindingHash")
 WHERE base."baselineId"=p_baseline_id
 AND (base."physicalIdentity",base."physicalProofIdentity",base."expectedFutureLayoutCoreHash") IS NOT DISTINCT FROM (exp."physicalIdentity",exp."physicalProofIdentity",exp."expectedFutureLayoutCoreHash")
 AND (exp."constructorKind",exp."expectedTargetId",exp."expectedCoreHash",exp."expectedEvidenceHash",exp."sessionClaimId",exp."eventId",exp."installerOid",exp."installerName",exp."trustId",exp."trustGeneration",exp."chargeKind",exp."chargeEventKey",exp."chargeBindingHash")=('CONTROL_PLANE_BASELINE',prov."baselineId",prov."coreHash",prov."evidenceHash",prov."sessionClaimId",prov."eventId",prov."publisherPrincipalOid",prov."publisherPrincipalName",prov."trustId",prov."trustGeneration",prov."chargeKind",prov."chargeEventKey",prov."chargeBindingHash")
 AND (constructor_claim."reservationId",constructor_claim."eventKey",constructor_claim."phase",constructor_claim."observerPrincipalOid",constructor_claim."observerPrincipalName")=(exp."constructorInputReservationId",exp."eventId",exp."constructorInputPhase",exp."installerOid",exp."installerName")
 AND (constructor_slot."phase",constructor_slot."observerPrincipalOid",constructor_slot."observerPrincipalName")=(constructor_claim."phase",constructor_claim."observerPrincipalOid",constructor_claim."observerPrincipalName")
 AND (constructor_slot."physicalIdentity",constructor_slot."physicalProofIdentity")=(exp."physicalIdentity",exp."physicalProofIdentity")
 AND (constructor_binding."expectationId",constructor_binding."credentialEpoch",constructor_binding."launchEpoch",constructor_binding."phase",constructor_binding."expectedEventKey",constructor_binding."bindingKind")=(exp."expectationId",exp."credentialEpoch",exp."launchEpoch",constructor_claim."phase",constructor_claim."eventKey",'INSTALLER_CONSTRUCTOR_INPUT')
 AND (observation_claim."phase",observation_claim."observerPrincipalOid",observation_claim."observerPrincipalName")=('INSTALL_PROCESS',observation."observerOid",observation."observerPrincipal")
 AND (observation_slot."phase",observation_slot."observerPrincipalOid",observation_slot."observerPrincipalName")=(observation_claim."phase",observation_claim."observerPrincipalOid",observation_claim."observerPrincipalName")
 AND (observation_slot."observerTrustId",observation_slot."observerTrustGeneration") IS NOT DISTINCT FROM (observation."trustId",observation."trustGeneration")
 AND observation."observerOid" IS DISTINCT FROM exp."installerOid"
 AND (observation_slot."physicalIdentity",observation_slot."physicalProofIdentity")=(exp."physicalIdentity",exp."physicalProofIdentity")
 AND (observation_binding."expectationId",observation_binding."credentialEpoch",observation_binding."launchEpoch",observation_binding."phase",observation_binding."expectedEventKey",observation_binding."bindingKind")=(exp."expectationId",exp."credentialEpoch",exp."launchEpoch",observation_claim."phase",observation_claim."eventKey",'INSTALLER_OBSERVATION')
 AND (observation."targetOid",observation."targetPrincipal",observation."targetPid",observation."targetBackendStart")=(exp."installerOid",exp."installerName",exp."installerPid",exp."installerBackendStart")
 AND (session_claim."principalOid",session_claim."principalName",session_claim."credentialEpoch",session_claim."launchEpoch",session_claim."sourceClosureHash",session_claim."installationClosureHash",session_claim."receiverClosureHash")=(exp."installerOid",exp."installerName",exp."credentialEpoch",exp."launchEpoch",exp."sourceClosureHash",exp."installationClosureHash",exp."receiverClosureHash")
 AND attempt."receiverClosureHash"=exp."receiverClosureHash" AND delivery."eventId"=exp."eventId";
 RAISE EXCEPTION 'SELECTION_UNAVAILABLE';
END $$;
REVOKE ALL ON FUNCTION public.pro273_initial_discover_installer_history(TEXT) FROM PUBLIC;

-- Disconnected current-layout route subset. This does not compose the installer
-- collector, optional layout/publication/binding/input-receipt presence, publisher
-- provenance, a frozen snapshot, authorization, or resource qualification.
-- The input ceiling is provisional and does not qualify identifier size or work.
CREATE FUNCTION public.pro273_initial_discover_current_layout(p_input_claim_id TEXT) RETURNS VOID
LANGUAGE plpgsql SECURITY DEFINER SET search_path=pg_catalog AS $$
DECLARE
 v_claim_id TEXT; v_reservation_id TEXT; v_baseline_id TEXT; v_baseline_core TEXT;
 v_physical_id TEXT; v_physical_proof TEXT; v_session_id TEXT; v_attempt_id TEXT;
 v_event_id TEXT; v_target_kind TEXT; v_target_bootstrap TEXT; v_target_core TEXT; v_target_evidence TEXT;
 v_publisher_trust TEXT; v_publisher_generation BIGINT; v_slot_event TEXT; v_slot_hash TEXT;
 v_operation_kind TEXT; v_operation_event TEXT; v_operation_hash TEXT;
 v_attempt_kind TEXT; v_attempt_event TEXT; v_attempt_hash TEXT;
 v_session_kind TEXT; v_session_event TEXT; v_session_hash TEXT;
 v_observation_trust TEXT; v_observation_generation BIGINT; v_capture_claim TEXT; v_capture_reservation TEXT;
 v_capture_trust TEXT; v_capture_generation BIGINT; v_capture_event TEXT; v_capture_hash TEXT;
 v_admission_id TEXT; v_receiver TEXT; v_claim_xid xid8; v_binding_xid xid8;
 v_session_xid xid8; v_attempt_xid xid8; v_admission_xid xid8;
BEGIN
 RAISE EXCEPTION 'SELECTION_UNAVAILABLE';
 IF p_input_claim_id IS NULL OR pg_catalog.octet_length(p_input_claim_id) NOT BETWEEN 1 AND 256 THEN RAISE EXCEPTION 'SELECTION_UNAVAILABLE'; END IF;
 SELECT c."inputClaimId",c."reservationId",base."baselineId",base."coreHash",
        base."physicalIdentity",base."physicalProofIdentity",s."sessionClaimId",a."attemptId",
        c."eventId",c."target"->>'kind',c."target"->>'bootstrapKind',c."target"->>'expectedCoreHash',c."target"->>'expectedEvidenceHash',
        b."trustId",b."trustGeneration",slot."prepaidEventKey",slot."recordHash",
        c."chargeKind",c."chargeEventKey",c."chargeBindingHash",
        a."chargeKind",a."chargeEventKey",a."chargeBindingHash",
        a."sessionChargeKind",a."sessionChargeEventKey",a."sessionChargeBindingHash",
        o."trustId",o."trustGeneration",capture."inputClaimId",capture_slot."reservationId",
        capture_slot."observerTrustId",capture_slot."observerTrustGeneration",capture_slot."prepaidEventKey",capture_slot."recordHash",
        admission."receiptId",admission."receiverIdentity",c."creationTransactionId",b."creationTransactionId",
        s."creationTransactionId",a."creationTransactionId",admission."creationTransactionId"
 INTO STRICT v_claim_id,v_reservation_id,v_baseline_id,v_baseline_core,
        v_physical_id,v_physical_proof,v_session_id,v_attempt_id,
        v_event_id,v_target_kind,v_target_bootstrap,v_target_core,v_target_evidence,
        v_publisher_trust,v_publisher_generation,v_slot_event,v_slot_hash,
        v_operation_kind,v_operation_event,v_operation_hash,
        v_attempt_kind,v_attempt_event,v_attempt_hash,
        v_session_kind,v_session_event,v_session_hash,
        v_observation_trust,v_observation_generation,v_capture_claim,v_capture_reservation,
        v_capture_trust,v_capture_generation,v_capture_event,v_capture_hash,
        v_admission_id,v_receiver,v_claim_xid,v_binding_xid,v_session_xid,v_attempt_xid,v_admission_xid
 FROM public."Pro273ControlPlaneInputClaim" c
 JOIN public."Pro273ControlPlaneInputBinding" b ON b."reservationId"=c."reservationId"
 JOIN public."Pro262CapacityObserverInputClaim" oc ON (oc."inputClaimId",oc."reservationId")=(c."inputClaimId",c."reservationId")
 JOIN public."Pro262CapacityObserverInputReservation" slot ON slot."reservationId"=oc."reservationId"
 JOIN public."Pro273ControlPlaneBaseline" base ON base."baselineId"=c."baselineId"
 JOIN public."Pro273ControlPlaneSessionClaim" s ON (s."baselineId",s."sessionClaimId")=(c."baselineId",c."sessionClaimId")
 JOIN public."Pro273ControlPlaneLaunchAttempt" a ON (a."baselineId",a."attemptId",a."receiverIdentity")=(s."baselineId",s."attemptId",s."receiverIdentity")
 JOIN public."Pro273ControlPlaneProcessObservation" o ON o."sessionClaimId"=s."sessionClaimId"
 JOIN public."Pro262CapacityObserverInputClaim" capture ON capture."inputClaimId"=o."inputClaimId"
 JOIN public."Pro262CapacityObserverInputReservation" capture_slot ON capture_slot."reservationId"=capture."reservationId"
 JOIN public."Pro273InitialPreinputReceipt" admission ON (admission."inputClaimId",admission."reservationId",admission."baselineId",admission."baselineCoreHash",admission."sessionClaimId",admission."attemptId",admission."eventId",admission."receiverIdentity")=(c."inputClaimId",c."reservationId",base."baselineId",base."coreHash",s."sessionClaimId",a."attemptId",c."eventId",a."receiverIdentity")
 WHERE c."inputClaimId"=p_input_claim_id
 AND (c."baselineId",c."purpose",c."eventId",c."chargeKind",c."chargeEventKey",c."chargeBindingHash")=(b."baselineId",b."purpose",b."eventId",b."chargeKind",b."chargeEventKey",b."chargeBindingHash")
 AND c."purpose"='QUALIFIER_BASELINE_INITIAL' AND base."purpose"=c."purpose"
 AND (oc."eventKey",oc."phase",oc."observerPrincipalOid",oc."observerPrincipalName")=(c."eventId",c."purpose",slot."observerPrincipalOid",slot."observerPrincipalName")
 AND (oc."observerPrincipalOid",oc."observerPrincipalName")=(admission."principalOid",admission."principalName")
 AND slot."phase"=oc."phase" AND (slot."physicalIdentity",slot."physicalProofIdentity")=(base."physicalIdentity",base."physicalProofIdentity")
 AND (b."trustId",b."trustGeneration")=(slot."observerTrustId",slot."observerTrustGeneration")
 AND (capture."phase",capture."observerPrincipalOid",capture."observerPrincipalName")=(capture_slot."phase",capture_slot."observerPrincipalOid",capture_slot."observerPrincipalName")
 AND capture."eventKey"=capture_slot."record"->>'expectedEventKey'
 AND (capture."observerPrincipalOid",capture."observerPrincipalName")=(o."observerOid",o."observerPrincipal")
 AND o."observerOid" IS DISTINCT FROM admission."principalOid"
 AND (capture_slot."observerTrustId",capture_slot."observerTrustGeneration")=(o."trustId",o."trustGeneration")
 AND (capture_slot."physicalIdentity",capture_slot."physicalProofIdentity")=(base."physicalIdentity",base."physicalProofIdentity")
 AND (admission."principalOid",admission."principalName",admission."credentialEpoch",admission."launchEpoch")=(s."principalOid",s."principalName",s."credentialEpoch",s."launchEpoch")
 AND (admission."principalOid",admission."principalName",admission."credentialEpoch",admission."launchEpoch",admission."backendPid",admission."backendStart",admission."sourceClosureHash",admission."installationClosureHash")=(o."principalOid",o."principalName",o."credentialEpoch",o."launchEpoch",o."backendPid",o."backendStart",o."sourceClosureHash",o."installationClosureHash")
 AND (admission."principalOid",admission."principalName",admission."credentialEpoch",admission."launchEpoch",admission."sourceClosureHash",admission."installationClosureHash")=(base."principalOid",base."principalName",base."credentialEpoch",base."launchEpoch",base."sourceClosureHash",base."installationClosureHash")
 AND (admission."chargeKind",admission."chargeEventKey",admission."chargeBindingHash")=(c."chargeKind",c."chargeEventKey",c."chargeBindingHash")
 AND c."target" IS NOT DISTINCT FROM b."target"
 AND c."target" IS NOT DISTINCT FROM admission."target"
 AND c."target"->>'kind'='INITIAL' AND c."target"->>'bootstrapKind'='SELECTION_QUALIFIER_LAYOUT:'||base."physicalIdentity"
 AND c."target"->>'expectedCoreHash'=base."expectedFutureLayoutCoreHash";
 RAISE EXCEPTION 'SELECTION_UNAVAILABLE';
EXCEPTION WHEN OTHERS THEN RAISE EXCEPTION 'SELECTION_UNAVAILABLE'; END $$;
REVOKE ALL ON FUNCTION public.pro273_initial_discover_current_layout(TEXT) FROM PUBLIC;

-- Fixed historical candidate only. The entry denial is unconditional: neither
