    (l."capturedBytes",l."capturedLength",l."capturedHash") IS DISTINCT FROM (cap."capturedBytes",cap."capturedLength",cap."capturedHash") OR cap."operationReceipt" IS DISTINCT FROM p."receiptHash" OR
    l."capturedHash" IS DISTINCT FROM pg_catalog.encode(int4_crypto.digest(l."capturedBytes",'sha256'),'hex') OR l."evidenceHash" IS DISTINCT FROM pg_catalog.encode(int4_crypto.digest(l."evidenceBytes",'sha256'),'hex') OR o."capturedHash" IS DISTINCT FROM pg_catalog.encode(int4_crypto.digest(o."capturedBytes",'sha256'),'hex') OR prov."capturedHash" IS DISTINCT FROM pg_catalog.encode(int4_crypto.digest(prov."capturedBytes",'sha256'),'hex') OR prov."evidenceHash" IS DISTINCT FROM pg_catalog.encode(int4_crypto.digest(prov."evidenceBytes",'sha256'),'hex') OR
    (l."controlChargeKind",l."controlChargeEventKey",l."chargeBindingHash") IS DISTINCT FROM (c."chargeKind",c."chargeEventKey",c."chargeBindingHash") OR
    NOT EXISTS (SELECT 1 FROM public."Pro262CapacityControlCharge" x WHERE (x."kind",x."eventKey",x."bindingHash")=(c."chargeKind",c."chargeEventKey",c."chargeBindingHash")) OR
    NOT EXISTS (SELECT 1 FROM public."Pro262CapacityControlCharge" x WHERE (x."kind",x."eventKey",x."bindingHash")=(a."chargeKind",a."chargeEventKey",a."chargeBindingHash")) OR
    NOT EXISTS (SELECT 1 FROM public."Pro262CapacityControlCharge" x WHERE (x."kind",x."eventKey",x."bindingHash")=(a."sessionChargeKind",a."sessionChargeEventKey",a."sessionChargeBindingHash")) OR
    NOT EXISTS (SELECT 1 FROM public."Pro262CapacityControlCharge" x WHERE (x."kind",x."eventKey",x."bindingHash")=(prov."chargeKind",prov."chargeEventKey",prov."chargeBindingHash")) OR
    NOT EXISTS (SELECT 1 FROM public."Pro262CapacityControlCharge" x WHERE (x."kind",x."eventKey",x."bindingHash")=(tp."chargeKind",tp."chargeEventKey",tp."recordHash")) OR
    a."creationTransactionId"=pg_catalog.pg_current_xact_id() OR s."creationTransactionId"=pg_catalog.pg_current_xact_id() OR b."creationTransactionId"=pg_catalog.pg_current_xact_id() OR c."creationTransactionId"=pg_catalog.pg_current_xact_id() OR r."creationTransactionId"=pg_catalog.pg_current_xact_id() OR prov."constructionTransactionId"=pg_catalog.pg_current_xact_id() OR p."constructionTransactionId"=pg_catalog.pg_current_xact_id() OR lb."constructionTransactionId"=pg_catalog.pg_current_xact_id() OR
    a."creationTransactionId"=p."constructionTransactionId" OR s."creationTransactionId"=p."constructionTransactionId" OR b."creationTransactionId"=p."constructionTransactionId" OR c."creationTransactionId"=p."constructionTransactionId" OR r."creationTransactionId"=p."constructionTransactionId" OR prov."constructionTransactionId"=p."constructionTransactionId" THEN RAISE EXCEPTION 'SELECTION_UNAVAILABLE'; END IF;
 -- The publication receiptId is a lowercase SHA256; InputReceipt.operationReceipt
 -- equals that publication ID, and p.receiptHash stores the same hash.
 -- Actual canonical publication receipt hash recomputation is still missing;
 -- receipt/core derivation, qualification and missing provenance remain unresolved.
 RAISE EXCEPTION 'SELECTION_UNAVAILABLE';
EXCEPTION WHEN OTHERS THEN RAISE EXCEPTION 'SELECTION_UNAVAILABLE'; END $$;
REVOKE ALL ON FUNCTION public.pro273_initial_verify_committed_layout(TEXT) FROM PUBLIC;
-- Fixed allocation historical candidate: original layout provenance is a
-- separate fixed stored-chain dependency, never an old live receiver session.
-- No complete ordered lock union, canonical hash, resources, fence or installed
-- provenance/ACL qualification exists. Entry and terminal denial are mandatory.
CREATE FUNCTION public.pro273_initial_verify_committed_allocation(p_input_claim_id TEXT) RETURNS VOID
LANGUAGE plpgsql SECURITY DEFINER SET search_path=pg_catalog AS $$
DECLARE
 p public."Pro273InitialAllocationPublication"%ROWTYPE; lp public."Pro273InitialLayoutPublication"%ROWTYPE; lb public."Pro273InitialBaselineLayoutBinding"%ROWTYPE;
 l public."Pro273QualifierBaselineLayout"%ROWTYPE; q public."Pro273QualifierAllocation"%ROWTYPE; r public."Pro273InitialPreinputReceipt"%ROWTYPE;
 c public."Pro273ControlPlaneInputClaim"%ROWTYPE; b public."Pro273ControlPlaneInputBinding"%ROWTYPE;
 oc public."Pro262CapacityObserverInputClaim"%ROWTYPE; slot public."Pro262CapacityObserverInputReservation"%ROWTYPE;
 base public."Pro273ControlPlaneBaseline"%ROWTYPE; prov public."Pro273ControlPlaneBaselineProvenance"%ROWTYPE;
 a public."Pro273ControlPlaneLaunchAttempt"%ROWTYPE; s public."Pro273ControlPlaneSessionClaim"%ROWTYPE;
 o public."Pro273ControlPlaneProcessObservation"%ROWTYPE; cc public."Pro262CapacityObserverInputClaim"%ROWTYPE;
 cs public."Pro262CapacityObserverInputReservation"%ROWTYPE; cap public."Pro273ControlPlaneInputReceipt"%ROWTYPE;
 t public."Pro262CapacityTrust"%ROWTYPE; bt public."Pro262CapacityBootstrapTrust"%ROWTYPE;
 tp public."Pro273PublisherTrustProvenance"%ROWTYPE; btp public."Pro273BaselineTrustProvenance"%ROWTYPE; boot public."Pro262CapacityBootstrapBaseline"%ROWTYPE;
 pb public."Pro262CapacityBootstrapBaseline"%ROWTYPE; pt public."Pro262CapacityBootstrapTrust"%ROWTYPE;
 exp public."Pro273ControlPlaneInstallerExpectation"%ROWTYPE; pc public."Pro262CapacityObserverInputClaim"%ROWTYPE;
 ps public."Pro262CapacityObserverInputReservation"%ROWTYPE; ptrust public."Pro262CapacityTrust"%ROWTYPE;
 ot public."Pro262CapacityTrust"%ROWTYPE;
BEGIN
 RAISE EXCEPTION 'SELECTION_UNAVAILABLE';
 IF COALESCE(p_input_claim_id,'')='' THEN RAISE EXCEPTION 'SELECTION_UNAVAILABLE'; END IF;
 SELECT x.* INTO STRICT p FROM public."Pro273InitialAllocationPublication" x WHERE x."inputClaimId"=p_input_claim_id;
 SELECT x.* INTO STRICT lb FROM public."Pro273InitialBaselineLayoutBinding" x WHERE (x."baselineId",x."baselineCoreHash",x."layoutInputClaimId")=(p."baselineId",p."baselineCoreHash",p."layoutInputClaimId");
 SELECT x.* INTO STRICT lp FROM public."Pro273InitialLayoutPublication" x WHERE (x."baselineId",x."baselineCoreHash",x."inputClaimId")=(lb."baselineId",lb."baselineCoreHash",lb."layoutInputClaimId");
 SELECT x.* INTO STRICT l FROM public."Pro273QualifierBaselineLayout" x WHERE (x."physicalIdentity",x."physicalProofIdentity",x."coreHash")=(lp."physicalIdentity",lp."physicalProofIdentity",lp."layoutCoreHash");
 SELECT x.* INTO STRICT q FROM public."Pro273QualifierAllocation" x WHERE (x."allocationId",x."coreHash")=(p."allocationId",p."allocationCoreHash");
 -- This fixed stored-chain verifier is itself deny-only; no old live session is used.
 PERFORM public.pro273_initial_verify_committed_layout(lp."inputClaimId");
 SELECT x.* INTO STRICT r FROM public."Pro273InitialPreinputReceipt" x WHERE x."inputClaimId"=p."inputClaimId";
 SELECT x.* INTO STRICT c FROM public."Pro273ControlPlaneInputClaim" x WHERE x."inputClaimId"=p."inputClaimId";
 SELECT x.* INTO STRICT b FROM public."Pro273ControlPlaneInputBinding" x WHERE x."reservationId"=c."reservationId";
 SELECT x.* INTO STRICT oc FROM public."Pro262CapacityObserverInputClaim" x WHERE x."inputClaimId"=c."inputClaimId";
 SELECT x.* INTO STRICT slot FROM public."Pro262CapacityObserverInputReservation" x WHERE x."reservationId"=oc."reservationId";
 SELECT x.* INTO STRICT base FROM public."Pro273ControlPlaneBaseline" x WHERE (x."baselineId",x."coreHash")=(p."baselineId",p."baselineCoreHash");
 SELECT x.* INTO STRICT prov FROM public."Pro273ControlPlaneBaselineProvenance" x WHERE (x."baselineId",x."coreHash")=(base."baselineId",base."coreHash");
 SELECT x.* INTO STRICT s FROM public."Pro273ControlPlaneSessionClaim" x WHERE (x."baselineId",x."sessionClaimId")=(c."baselineId",c."sessionClaimId");
 SELECT x.* INTO STRICT a FROM public."Pro273ControlPlaneLaunchAttempt" x WHERE (x."baselineId",x."attemptId")=(s."baselineId",s."attemptId");
 SELECT x.* INTO STRICT o FROM public."Pro273ControlPlaneProcessObservation" x WHERE x."sessionClaimId"=s."sessionClaimId";
 SELECT x.* INTO STRICT cc FROM public."Pro262CapacityObserverInputClaim" x WHERE x."inputClaimId"=o."inputClaimId";
 SELECT x.* INTO STRICT cs FROM public."Pro262CapacityObserverInputReservation" x WHERE x."reservationId"=cc."reservationId";
 SELECT x.* INTO STRICT cap FROM public."Pro273ControlPlaneInputReceipt" x WHERE x."inputClaimId"=c."inputClaimId";
 SELECT x.* INTO STRICT t FROM public."Pro262CapacityTrust" x WHERE (x."trustId",x."generation")=(q."trustId",q."trustGeneration");
 SELECT x.* INTO STRICT bt FROM public."Pro262CapacityBootstrapTrust" x WHERE (x."trustId",x."generation")=(t."trustId",t."generation");
 SELECT x.* INTO STRICT tp FROM public."Pro273PublisherTrustProvenance" x WHERE (x."trustId",x."generation")=(t."trustId",t."generation");
 SELECT x.* INTO STRICT boot FROM public."Pro262CapacityBootstrapBaseline" x WHERE x."kind"=q."bootstrapKind";
 SELECT x.* INTO STRICT pb FROM public."Pro262CapacityBootstrapBaseline" x WHERE x."kind"=prov."bootstrapKind";
 SELECT x.* INTO STRICT pt FROM public."Pro262CapacityBootstrapTrust" x WHERE (x."trustId",x."generation")=(prov."trustId",prov."trustGeneration");
 SELECT x.* INTO STRICT btp FROM public."Pro273BaselineTrustProvenance" x WHERE (x."trustId",x."generation")=(prov."trustId",prov."trustGeneration");
 SELECT x.* INTO STRICT ptrust FROM public."Pro262CapacityTrust" x WHERE (x."trustId",x."generation")=(prov."trustId",prov."trustGeneration");
 SELECT x.* INTO STRICT exp FROM public."Pro273ControlPlaneInstallerExpectation" x WHERE x."bootstrapKind"=prov."bootstrapKind";
 SELECT x.* INTO STRICT pc FROM public."Pro262CapacityObserverInputClaim" x WHERE x."inputClaimId"=prov."inputClaimId";
 SELECT x.* INTO STRICT ps FROM public."Pro262CapacityObserverInputReservation" x WHERE x."reservationId"=pc."reservationId";
 SELECT x.* INTO STRICT ot FROM public."Pro262CapacityTrust" x WHERE (x."trustId",x."generation")=(o."trustId",o."trustGeneration");
 IF (p."admissionReceiptId",p."eventId",p."baselineId",p."baselineCoreHash") IS DISTINCT FROM (r."receiptId",r."eventId",r."baselineId",r."baselineCoreHash") OR
    (q."inputClaimId",q."sessionClaimId",q."eventId",q."allocationId",q."coreHash",q."physicalIdentity",q."physicalProofIdentity",q."layoutCoreHash") IS DISTINCT FROM (c."inputClaimId",s."sessionClaimId",c."eventId",p."allocationId",p."allocationCoreHash",l."physicalIdentity",l."physicalProofIdentity",l."coreHash") OR
    (l."physicalIdentity",l."physicalProofIdentity",l."coreHash") IS DISTINCT FROM (base."physicalIdentity",base."physicalProofIdentity",base."expectedFutureLayoutCoreHash") OR
    (r."inputClaimId",r."reservationId",r."baselineId",r."sessionClaimId",r."eventId",r."target",r."chargeKind",r."chargeEventKey",r."chargeBindingHash") IS DISTINCT FROM (c."inputClaimId",c."reservationId",c."baselineId",c."sessionClaimId",c."eventId",c."target",c."chargeKind",c."chargeEventKey",c."chargeBindingHash") OR
    (c."reservationId",c."baselineId",c."purpose",c."eventId",c."target",c."chargeKind",c."chargeEventKey",c."chargeBindingHash") IS DISTINCT FROM (b."reservationId",b."baselineId",b."purpose",b."eventId",b."target",b."chargeKind",b."chargeEventKey",b."chargeBindingHash") OR
    (oc."reservationId",oc."eventKey",oc."phase",oc."observerPrincipalOid",oc."observerPrincipalName") IS DISTINCT FROM (slot."reservationId",c."eventId",c."purpose",slot."observerPrincipalOid",slot."observerPrincipalName") OR
    (slot."observerPrincipalOid",slot."observerPrincipalName") IS DISTINCT FROM (r."principalOid",r."principalName") OR
    (slot."record"->>'observerBackendPid',(slot."record"->>'observerBackendStart')::TIMESTAMPTZ,slot."record"->>'observerCredentialEpoch',slot."record"->>'observerLaunchEpoch',slot."record"->>'observerSourceClosure',slot."record"->>'observerHost',slot."record"->>'observerBoot',slot."record"->>'observerProcessTree') IS DISTINCT FROM (r."backendPid"::TEXT,r."backendStart",r."credentialEpoch",r."launchEpoch",r."sourceClosureHash",base."host",base."boot",base."processTree") OR
    (slot."observerTrustId",slot."observerTrustGeneration",slot."physicalIdentity",slot."physicalProofIdentity") IS DISTINCT FROM (b."trustId",b."trustGeneration",base."physicalIdentity",base."physicalProofIdentity") OR
    c."purpose" IS DISTINCT FROM 'QUALIFIER_BASELINE_INITIAL' OR base."purpose" IS DISTINCT FROM c."purpose" OR
    c."target" IS DISTINCT FROM pg_catalog.jsonb_build_object('kind','INITIAL','bootstrapKind',q."bootstrapKind",'expectedCoreHash',q."coreHash",'expectedEvidenceHash',q."evidenceHash") OR
    (r."attemptId",r."receiverIdentity",s."receiverIdentity") IS DISTINCT FROM (a."attemptId",a."receiverIdentity",a."receiverIdentity") OR
    (r."principalOid",r."principalName",r."credentialEpoch",r."launchEpoch",r."sourceClosureHash",r."installationClosureHash") IS DISTINCT FROM (base."principalOid",base."principalName",base."credentialEpoch",base."launchEpoch",base."sourceClosureHash",base."installationClosureHash") OR
    (s."principalOid",s."principalName",s."credentialEpoch",s."launchEpoch") IS DISTINCT FROM (base."principalOid",base."principalName",base."credentialEpoch",base."launchEpoch") OR
    (o."principalOid",o."principalName",o."credentialEpoch",o."launchEpoch",o."backendPid",o."backendStart",o."sourceClosureHash",o."installationClosureHash",o."host",o."boot",o."processTree",o."parentProcessTree") IS DISTINCT FROM (r."principalOid",r."principalName",r."credentialEpoch",r."launchEpoch",r."backendPid",r."backendStart",r."sourceClosureHash",r."installationClosureHash",base."host",base."boot",base."processTree",base."parentProcessTree") OR
    (cc."reservationId",cc."observerPrincipalOid",cc."observerPrincipalName") IS DISTINCT FROM (cs."reservationId",cs."observerPrincipalOid",cs."observerPrincipalName") OR
    (cc."observerPrincipalOid",cc."observerPrincipalName",cs."observerTrustId",cs."observerTrustGeneration") IS DISTINCT FROM (o."observerOid",o."observerPrincipal",o."trustId",o."trustGeneration") OR
    (q."publisherPrincipalOid",q."publisherPrincipalName",q."trustId",q."trustGeneration") IS DISTINCT FROM (slot."observerPrincipalOid",slot."observerPrincipalName",b."trustId",b."trustGeneration") OR
    q."bootstrapKind" IS DISTINCT FROM 'SELECTION_QUALIFIER_ALLOCATION:'||q."allocationId" OR t."scope"->>'bootstrapKind' IS DISTINCT FROM q."bootstrapKind" OR
    boot."recordHash" IS DISTINCT FROM q."coreHash" OR boot."evidenceHash" IS DISTINCT FROM q."evidenceHash" OR
    t."purpose" IS DISTINCT FROM 'QUALIFIER_BASELINE_PUBLISHER' OR t."supplierPrincipal" IS DISTINCT FROM q."publisherPrincipalName" OR t."scope"->'target' IS DISTINCT FROM c."target" OR t."scope"->>'publisherPrincipalOid' IS DISTINCT FROM q."publisherPrincipalOid"::TEXT OR t."scope"->>'publisherPrincipalName' IS DISTINCT FROM q."publisherPrincipalName"::TEXT OR t."scope"->>'physicalIdentity' IS DISTINCT FROM q."physicalIdentity" OR t."scope"->>'physicalProofIdentity' IS DISTINCT FROM q."physicalProofIdentity" OR t."scope"->>'sourceClosureHash' IS DISTINCT FROM base."sourceClosureHash" OR t."scope"->>'inputEnvelope' IS DISTINCT FROM slot."baselineAllocationProof" OR
    (q."bootstrapRecordHash",q."bootstrapEvidenceHash",q."publisherPrincipalName") IS DISTINCT FROM (boot."recordHash",boot."evidenceHash",boot."publisherPrincipal") OR
    q."trustRecordHash" IS DISTINCT FROM bt."recordHash" OR tp."recordHash" IS DISTINCT FROM bt."recordHash" OR
    tp."provisionerOid" IS NULL OR tp."provisionerName" IS NULL OR tp."provisioningTransactionId" IS NULL OR tp."provisionedAt" IS NULL OR
    tp."provisionerName" IS DISTINCT FROM bt."principal" OR
    (prov."bootstrapRecordHash",prov."bootstrapEvidenceHash",prov."publisherPrincipalName") IS DISTINCT FROM (pb."recordHash",pb."evidenceHash",pb."publisherPrincipal") OR prov."trustRecordHash" IS DISTINCT FROM pt."recordHash" OR btp."recordHash" IS DISTINCT FROM pt."recordHash" OR
    btp."provisionerOid" IS NULL OR btp."provisionerName" IS NULL OR btp."provisioningTransactionId" IS NULL OR btp."provisionedAt" IS NULL OR
    btp."provisionerName" IS DISTINCT FROM pt."principal" OR
    ptrust."purpose" IS DISTINCT FROM 'CONTROL_ALLOCATOR' OR NOT (CASE WHEN pg_catalog.jsonb_typeof(ptrust."scope") IS DISTINCT FROM 'object' THEN FALSE
      WHEN pg_catalog.jsonb_typeof(ptrust."scope"->'kind') IS DISTINCT FROM 'string' OR ptrust."scope"->>'kind' IS DISTINCT FROM 'INSTALLER_CONSTRUCTOR_INPUT' THEN FALSE
      WHEN (SELECT pg_catalog.count(*) FROM pg_catalog.jsonb_object_keys(ptrust."scope"))=1 THEN TRUE
      WHEN (SELECT pg_catalog.count(*) FROM pg_catalog.jsonb_object_keys(ptrust."scope"))=3 AND ptrust."scope" ?& ARRAY['kind','inputEnvelope','inputBound']
       AND pg_catalog.jsonb_typeof(ptrust."scope"->'inputEnvelope')='string' AND COALESCE(ptrust."scope"->>'inputEnvelope','')<>''
       AND pg_catalog.jsonb_typeof(ptrust."scope"->'inputBound')='string' AND COALESCE(ptrust."scope"->>'inputBound','') ~ '^[1-9][0-9]{0,18}$'
       THEN (ptrust."scope"->>'inputBound')::NUMERIC<=9223372036854775807 ELSE FALSE END) OR
    NOT (
     (btp."fundingMode"='CHARGE' AND btp."chargeKind" IS NOT NULL AND btp."chargeKind"='TRUST_PROVISION'
      AND btp."chargeEventKey" IS NOT NULL AND btp."chargeEventKey"=btp."trustId"||':'||btp."generation"::TEXT
      AND btp."baselineKind" IS NULL AND btp."baselineCoverageEvidenceHash" IS NULL AND btp."baselineEnabledAtProvisioning" IS NULL
      AND EXISTS (SELECT 1 FROM public."Pro262CapacityControlCharge" x WHERE (x."kind",x."eventKey",x."bindingHash")=(btp."chargeKind",btp."chargeEventKey",btp."recordHash")))
     OR (btp."fundingMode"='CONTROL_BASELINE' AND btp."chargeKind" IS NULL AND btp."chargeEventKey" IS NULL
      AND btp."baselineKind" IS NOT NULL AND btp."baselineKind"='TRUST_PROVISION'
      AND btp."baselineCoverageEvidenceHash" IS NOT NULL AND btp."baselineCoverageEvidenceHash" ~ '^[a-f0-9]{64}$'
      AND btp."baselineEnabledAtProvisioning" IS NOT NULL AND btp."baselineEnabledAtProvisioning" IS TRUE
      AND ptrust."purpose" IS NOT DISTINCT FROM 'CONTROL_ALLOCATOR'
      AND btp."baselineCoverageEvidenceHash" IS NOT DISTINCT FROM pt."evidenceHash"
      AND EXISTS (SELECT 1 FROM public."Pro262CapacityControlBaseline" x WHERE x."kind"=btp."baselineKind" AND x."coverageEvidenceHash"=btp."baselineCoverageEvidenceHash"))
    ) OR
    (prov."bootstrapKind",prov."coreHash",prov."evidenceHash",prov."publisherPrincipalOid",prov."publisherPrincipalName",prov."sessionClaimId",prov."eventId",prov."trustId",prov."trustGeneration",prov."chargeKind",prov."chargeEventKey",prov."chargeBindingHash") IS DISTINCT FROM (exp."bootstrapKind",exp."expectedCoreHash",exp."expectedEvidenceHash",exp."installerOid",exp."installerName",exp."sessionClaimId",exp."eventId",exp."trustId",exp."trustGeneration",exp."chargeKind",exp."chargeEventKey",exp."chargeBindingHash") OR
    exp."constructorKind" IS DISTINCT FROM 'CONTROL_PLANE_BASELINE' OR exp."expectedTargetId" IS DISTINCT FROM base."baselineId" OR exp."expectedFutureLayoutCoreHash" IS DISTINCT FROM l."coreHash" OR
    (pc."reservationId",pc."eventKey",pc."phase",pc."observerPrincipalOid",pc."observerPrincipalName") IS DISTINCT FROM (exp."constructorInputReservationId",exp."eventId",exp."constructorInputPhase",exp."installerOid",exp."installerName") OR
    (ps."observerPrincipalOid",ps."observerPrincipalName") IS DISTINCT FROM (pc."observerPrincipalOid",pc."observerPrincipalName") OR ptrust."supplierPrincipal" IS DISTINCT FROM prov."publisherPrincipalName" OR ot."supplierPrincipal" IS DISTINCT FROM o."observerPrincipal" OR
    (q."capturedBytes",q."capturedLength",q."capturedHash") IS DISTINCT FROM (cap."capturedBytes",cap."capturedLength",cap."capturedHash") OR cap."operationReceipt" IS DISTINCT FROM p."receiptHash" OR
    q."capturedHash" IS DISTINCT FROM pg_catalog.encode(int4_crypto.digest(q."capturedBytes",'sha256'),'hex') OR q."evidenceHash" IS DISTINCT FROM pg_catalog.encode(int4_crypto.digest(q."evidenceBytes",'sha256'),'hex') OR o."capturedHash" IS DISTINCT FROM pg_catalog.encode(int4_crypto.digest(o."capturedBytes",'sha256'),'hex') OR prov."capturedHash" IS DISTINCT FROM pg_catalog.encode(int4_crypto.digest(prov."capturedBytes",'sha256'),'hex') OR prov."evidenceHash" IS DISTINCT FROM pg_catalog.encode(int4_crypto.digest(prov."evidenceBytes",'sha256'),'hex') OR
    (q."controlChargeKind",q."controlChargeEventKey",q."chargeBindingHash") IS DISTINCT FROM (c."chargeKind",c."chargeEventKey",c."chargeBindingHash") OR
    (slot."record"->>'expectedEventKey',slot."phase") IS DISTINCT FROM (c."eventId",c."purpose") OR
    (cs."record"->>'expectedEventKey',cs."phase") IS DISTINCT FROM (cc."eventKey",cc."phase") OR
    (ps."record"->>'expectedEventKey',ps."phase") IS DISTINCT FROM (pc."eventKey",pc."phase") OR
    NOT EXISTS (SELECT 1 FROM public."Pro262CapacityControlCharge" x WHERE (x."kind",x."eventKey",x."bindingHash")=('OBSERVER_INPUT_SLOT',slot."prepaidEventKey",slot."recordHash")) OR
    NOT EXISTS (SELECT 1 FROM public."Pro262CapacityControlCharge" x WHERE (x."kind",x."eventKey",x."bindingHash")=('OBSERVER_INPUT_SLOT',cs."prepaidEventKey",cs."recordHash")) OR
    NOT EXISTS (SELECT 1 FROM public."Pro262CapacityControlCharge" x WHERE (x."kind",x."eventKey",x."bindingHash")=('OBSERVER_INPUT_SLOT',ps."prepaidEventKey",ps."recordHash")) OR
    NOT EXISTS (SELECT 1 FROM public."Pro262CapacityControlCharge" x WHERE (x."kind",x."eventKey",x."bindingHash")=(c."chargeKind",c."chargeEventKey",c."chargeBindingHash")) OR
    NOT EXISTS (SELECT 1 FROM public."Pro262CapacityControlCharge" x WHERE (x."kind",x."eventKey",x."bindingHash")=(a."chargeKind",a."chargeEventKey",a."chargeBindingHash")) OR
    NOT EXISTS (SELECT 1 FROM public."Pro262CapacityControlCharge" x WHERE (x."kind",x."eventKey",x."bindingHash")=(a."sessionChargeKind",a."sessionChargeEventKey",a."sessionChargeBindingHash")) OR
    NOT EXISTS (SELECT 1 FROM public."Pro262CapacityControlCharge" x WHERE (x."kind",x."eventKey",x."bindingHash")=(prov."chargeKind",prov."chargeEventKey",prov."chargeBindingHash")) OR
    NOT EXISTS (SELECT 1 FROM public."Pro262CapacityControlCharge" x WHERE (x."kind",x."eventKey",x."bindingHash")=(tp."chargeKind",tp."chargeEventKey",tp."recordHash")) OR
    a."creationTransactionId" IS NOT DISTINCT FROM pg_catalog.pg_current_xact_id() OR s."creationTransactionId" IS NOT DISTINCT FROM pg_catalog.pg_current_xact_id() OR b."creationTransactionId" IS NOT DISTINCT FROM pg_catalog.pg_current_xact_id() OR c."creationTransactionId" IS NOT DISTINCT FROM pg_catalog.pg_current_xact_id() OR r."creationTransactionId" IS NOT DISTINCT FROM pg_catalog.pg_current_xact_id() OR prov."constructionTransactionId" IS NOT DISTINCT FROM pg_catalog.pg_current_xact_id() OR p."constructionTransactionId" IS NOT DISTINCT FROM pg_catalog.pg_current_xact_id() OR lb."constructionTransactionId" IS NOT DISTINCT FROM pg_catalog.pg_current_xact_id() OR lp."constructionTransactionId" IS NOT DISTINCT FROM pg_catalog.pg_current_xact_id() OR
    a."creationTransactionId" IS NOT DISTINCT FROM p."constructionTransactionId" OR s."creationTransactionId" IS NOT DISTINCT FROM p."constructionTransactionId" OR b."creationTransactionId" IS NOT DISTINCT FROM p."constructionTransactionId" OR c."creationTransactionId" IS NOT DISTINCT FROM p."constructionTransactionId" OR r."creationTransactionId" IS NOT DISTINCT FROM p."constructionTransactionId" OR prov."constructionTransactionId" IS NOT DISTINCT FROM p."constructionTransactionId" OR lp."constructionTransactionId" IS NOT DISTINCT FROM p."constructionTransactionId" OR lb."constructionTransactionId" IS NOT DISTINCT FROM p."constructionTransactionId" THEN RAISE EXCEPTION 'SELECTION_UNAVAILABLE'; END IF;
 -- The publication receiptId is a lowercase SHA256; InputReceipt.operationReceipt
 -- equals that publication ID, and p.receiptHash stores the same hash.
 -- Allocation closure hashes identify the qualifier target in its semantic core,
 -- not the INITIAL publisher; target qualification remains incomplete.
 -- Actual canonical publication receipt and allocation core hash recomputation are missing;
 -- receipt/core derivation, qualification and missing provenance remain unresolved.
 RAISE EXCEPTION 'SELECTION_UNAVAILABLE';
EXCEPTION WHEN OTHERS THEN RAISE EXCEPTION 'SELECTION_UNAVAILABLE'; END $$;
REVOKE ALL ON FUNCTION public.pro273_initial_verify_committed_allocation(TEXT) FROM PUBLIC;

-- Route only through protected identities, then pin every trust before pinning
-- lifecycle rows.  The independent observation has its own input slot.
CREATE FUNCTION public.pro273_control_plane_lock_input_authority(p_session_claim_id TEXT,p_reservation_id TEXT) RETURNS VOID
LANGUAGE plpgsql SECURITY DEFINER SET search_path=pg_catalog AS $$
DECLARE v_session public."Pro273ControlPlaneSessionClaim"%ROWTYPE; v_baseline public."Pro273ControlPlaneBaseline"%ROWTYPE;
 v_provenance public."Pro273ControlPlaneBaselineProvenance"%ROWTYPE; v_binding public."Pro273ControlPlaneInputBinding"%ROWTYPE;
 v_slot public."Pro262CapacityObserverInputReservation"%ROWTYPE; v_observation public."Pro273ControlPlaneProcessObservation"%ROWTYPE;
 v_capture public."Pro262CapacityObserverInputClaim"%ROWTYPE; v_capture_slot public."Pro262CapacityObserverInputReservation"%ROWTYPE;
 v_input public."Pro273ControlPlaneInputClaim"%ROWTYPE; v_observer_input public."Pro262CapacityObserverInputClaim"%ROWTYPE;
 v_attempt public."Pro273ControlPlaneLaunchAttempt"%ROWTYPE; v_charge public."Pro262CapacityControlCharge"%ROWTYPE;
 v_receipt public."Pro273InitialPreinputReceipt"%ROWTYPE;
 v_pair RECORD; v_global RECORD; v_domain public."Pro262CapacityPhysicalDomain"%ROWTYPE;
BEGIN
 IF COALESCE(p_session_claim_id,'')='' OR COALESCE(p_reservation_id,'')='' OR pg_catalog.current_setting('transaction_isolation')<>'read committed' THEN RAISE EXCEPTION 'SELECTION_UNAVAILABLE'; END IF;
 SELECT s.* INTO STRICT v_session FROM public."Pro273ControlPlaneSessionClaim" s WHERE s."sessionClaimId"=p_session_claim_id;
 SELECT b.* INTO STRICT v_baseline FROM public."Pro273ControlPlaneBaseline" b WHERE b."baselineId"=v_session."baselineId";
 SELECT p.* INTO STRICT v_provenance FROM public."Pro273ControlPlaneBaselineProvenance" p WHERE p."baselineId"=v_baseline."baselineId";
 SELECT b.* INTO STRICT v_binding FROM public."Pro273ControlPlaneInputBinding" b WHERE b."reservationId"=p_reservation_id;
 -- INITIAL has no authenticated receiver closure, durable one-shot fence or
 -- independently qualified shared coverage contract. A shape is not authority.
 IF v_binding."purpose"='QUALIFIER_BASELINE_INITIAL' THEN RAISE EXCEPTION 'SELECTION_UNAVAILABLE'; END IF;
 SELECT r.* INTO STRICT v_slot FROM public."Pro262CapacityObserverInputReservation" r WHERE r."reservationId"=p_reservation_id;
 SELECT o.* INTO STRICT v_observation FROM public."Pro273ControlPlaneProcessObservation" o WHERE o."sessionClaimId"=p_session_claim_id;
 SELECT c.* INTO STRICT v_capture FROM public."Pro262CapacityObserverInputClaim" c WHERE c."inputClaimId"=v_observation."inputClaimId";
 SELECT r.* INTO STRICT v_capture_slot FROM public."Pro262CapacityObserverInputReservation" r WHERE r."reservationId"=v_capture."reservationId";
 LOCK TABLE public."Pro311ControlDomain" IN ACCESS SHARE MODE NOWAIT;
 SELECT g."physicalIdentity",g."proofIdentity" INTO STRICT v_global FROM public."Pro311ControlDomain" g WHERE g."id"='global-v1' FOR SHARE NOWAIT;
 SELECT d.* INTO STRICT v_domain FROM public."Pro262CapacityPhysicalDomain" d WHERE d."physicalIdentity"=v_baseline."physicalIdentity" FOR SHARE NOWAIT;
 IF (v_global."physicalIdentity",v_global."proofIdentity") IS DISTINCT FROM (v_domain."physicalIdentity",v_domain."proofIdentity") OR
    (v_binding."baselineId",v_slot."observerTrustId",v_slot."observerTrustGeneration") IS DISTINCT FROM (v_session."baselineId",v_binding."trustId",v_binding."trustGeneration") OR
    (v_capture_slot."observerTrustId",v_capture_slot."observerTrustGeneration") IS DISTINCT FROM (v_observation."trustId",v_observation."trustGeneration") THEN RAISE EXCEPTION 'SELECTION_UNAVAILABLE'; END IF;
 FOR v_pair IN SELECT DISTINCT x.id COLLATE "C" AS id,x.generation FROM (VALUES
   (v_provenance."trustId",v_provenance."trustGeneration"),(v_observation."trustId",v_observation."trustGeneration"),
   (v_binding."trustId",v_binding."trustGeneration"),(v_slot."observerTrustId",v_slot."observerTrustGeneration"),
   (v_capture_slot."observerTrustId",v_capture_slot."observerTrustGeneration")) AS x(id,generation) ORDER BY id,generation LOOP
  PERFORM 1 FROM public."Pro262CapacityTrust" t WHERE (t."trustId",t."generation")=(v_pair.id,v_pair.generation) FOR SHARE NOWAIT;
  IF NOT FOUND THEN RAISE EXCEPTION 'SELECTION_UNAVAILABLE'; END IF;
 END LOOP;
 PERFORM 1 FROM public."Pro262CapacityBootstrapBaseline" b WHERE b."kind"=v_provenance."bootstrapKind" FOR SHARE NOWAIT;
 IF NOT FOUND THEN RAISE EXCEPTION 'SELECTION_UNAVAILABLE'; END IF;
 IF v_binding."purpose"='QUALIFIER_BASELINE_INITIAL' THEN
  PERFORM 1 FROM public."Pro262CapacityBootstrapBaseline" b WHERE b."kind"=v_binding."target"->>'bootstrapKind' FOR SHARE NOWAIT;
  IF NOT FOUND THEN RAISE EXCEPTION 'SELECTION_UNAVAILABLE'; END IF;
 END IF;
 PERFORM 1 FROM public."Pro273ControlPlaneBaseline" b WHERE (b."baselineId",b."coreHash",b."physicalIdentity")=(v_baseline."baselineId",v_baseline."coreHash",v_baseline."physicalIdentity") FOR SHARE NOWAIT;
 IF NOT FOUND THEN RAISE EXCEPTION 'SELECTION_UNAVAILABLE'; END IF;
 PERFORM 1 FROM public."Pro273ControlPlaneBaselineProvenance" p WHERE (p."baselineId",p."coreHash",p."bootstrapKind",p."trustId",p."trustGeneration")=(v_provenance."baselineId",v_provenance."coreHash",v_provenance."bootstrapKind",v_provenance."trustId",v_provenance."trustGeneration") FOR SHARE NOWAIT;
 IF NOT FOUND THEN RAISE EXCEPTION 'SELECTION_UNAVAILABLE'; END IF;
 IF v_binding."purpose"='QUALIFIER_BASELINE_INITIAL' AND pg_catalog.starts_with(v_binding."target"->>'bootstrapKind','SELECTION_QUALIFIER_ALLOCATION:') THEN
  PERFORM 1 FROM public."Pro273QualifierBaselineLayout" l WHERE l."physicalIdentity"=v_baseline."physicalIdentity" AND l."coreHash"=v_baseline."expectedFutureLayoutCoreHash" FOR SHARE NOWAIT;
  IF NOT FOUND THEN RAISE EXCEPTION 'SELECTION_UNAVAILABLE'; END IF;
 END IF;
 SELECT a.* INTO v_attempt FROM public."Pro273ControlPlaneLaunchAttempt" a WHERE (a."baselineId",a."attemptId")=(v_session."baselineId",v_session."attemptId") FOR SHARE NOWAIT;
 IF NOT FOUND THEN RAISE EXCEPTION 'SELECTION_UNAVAILABLE'; END IF;
 PERFORM 1 FROM public."Pro273ControlPlaneSessionClaim" s WHERE s."sessionClaimId"=p_session_claim_id AND s IS NOT DISTINCT FROM v_session FOR SHARE NOWAIT;
 IF NOT FOUND THEN RAISE EXCEPTION 'SELECTION_UNAVAILABLE'; END IF;
 PERFORM 1 FROM public."Pro262CapacityObserverInputReservation" r WHERE r."reservationId"=p_reservation_id AND r IS NOT DISTINCT FROM v_slot FOR SHARE NOWAIT;
 IF NOT FOUND THEN RAISE EXCEPTION 'SELECTION_UNAVAILABLE'; END IF;
 PERFORM 1 FROM public."Pro273ControlPlaneInputBinding" b WHERE b."reservationId"=p_reservation_id AND b IS NOT DISTINCT FROM v_binding FOR SHARE NOWAIT;
 IF NOT FOUND THEN RAISE EXCEPTION 'SELECTION_UNAVAILABLE'; END IF;
 SELECT c.* INTO v_observer_input FROM public."Pro262CapacityObserverInputClaim" c WHERE c."reservationId"=p_reservation_id FOR SHARE NOWAIT;
 IF NOT FOUND THEN RAISE EXCEPTION 'SELECTION_UNAVAILABLE'; END IF;
 SELECT c.* INTO v_input FROM public."Pro273ControlPlaneInputClaim" c WHERE c."reservationId"=p_reservation_id FOR SHARE NOWAIT;
 PERFORM 1 FROM public."Pro273ControlPlaneProcessObservation" o WHERE o."sessionClaimId"=p_session_claim_id AND o IS NOT DISTINCT FROM v_observation FOR SHARE NOWAIT;
 IF NOT FOUND THEN RAISE EXCEPTION 'SELECTION_UNAVAILABLE'; END IF;
 PERFORM 1 FROM public."Pro262CapacityObserverInputClaim" c WHERE c."inputClaimId"=v_capture."inputClaimId" AND c IS NOT DISTINCT FROM v_capture FOR SHARE NOWAIT;
 IF NOT FOUND THEN RAISE EXCEPTION 'SELECTION_UNAVAILABLE'; END IF;
 PERFORM 1 FROM public."Pro262CapacityObserverInputReservation" r WHERE r."reservationId"=v_capture_slot."reservationId" AND r IS NOT DISTINCT FROM v_capture_slot FOR SHARE NOWAIT;
 IF NOT FOUND THEN RAISE EXCEPTION 'SELECTION_UNAVAILABLE'; END IF;
 SELECT c.* INTO v_charge FROM public."Pro262CapacityControlCharge" c WHERE (c."kind",c."eventKey",c."bindingHash")=(v_binding."chargeKind",v_binding."chargeEventKey",v_binding."chargeBindingHash") FOR SHARE NOWAIT;
 IF NOT FOUND THEN RAISE EXCEPTION 'SELECTION_UNAVAILABLE'; END IF;
 -- Preparation permits no receipt for either purpose. A present row must be
 -- pinned last and checked against the independently protected tuple.
 SELECT r.* INTO v_receipt FROM public."Pro273InitialPreinputReceipt" r WHERE r."reservationId"=p_reservation_id FOR SHARE NOWAIT;
 IF FOUND THEN
  IF v_input."inputClaimId" IS NULL OR
     (v_receipt."inputClaimId",v_receipt."reservationId",v_receipt."baselineId",v_receipt."sessionClaimId",v_receipt."eventId",v_receipt."target",v_receipt."chargeKind",v_receipt."chargeEventKey",v_receipt."chargeBindingHash") IS DISTINCT FROM (v_input."inputClaimId",v_input."reservationId",v_input."baselineId",v_input."sessionClaimId",v_input."eventId",v_input."target",v_input."chargeKind",v_input."chargeEventKey",v_input."chargeBindingHash") OR
     (v_input."inputClaimId",v_input."reservationId",v_input."eventId",v_input."purpose") IS DISTINCT FROM (v_observer_input."inputClaimId",v_observer_input."reservationId",v_observer_input."eventKey",v_observer_input."phase") OR
     (v_input."reservationId",v_input."baselineId",v_input."purpose",v_input."eventId",v_input."target",v_input."chargeKind",v_input."chargeEventKey",v_input."chargeBindingHash") IS DISTINCT FROM (v_binding."reservationId",v_binding."baselineId",v_binding."purpose",v_binding."eventId",v_binding."target",v_binding."chargeKind",v_binding."chargeEventKey",v_binding."chargeBindingHash") OR
     (v_receipt."reservationId",v_receipt."baselineId",v_receipt."baselineCoreHash",v_receipt."sessionClaimId",v_receipt."attemptId",v_receipt."receiverIdentity") IS DISTINCT FROM (v_slot."reservationId",v_baseline."baselineId",v_baseline."coreHash",v_session."sessionClaimId",v_attempt."attemptId",v_session."receiverIdentity") OR
     (v_session."baselineId",v_session."attemptId",v_session."receiverIdentity") IS DISTINCT FROM (v_attempt."baselineId",v_attempt."attemptId",v_attempt."receiverIdentity") OR
     (v_receipt."principalOid",v_receipt."principalName",v_receipt."credentialEpoch",v_receipt."launchEpoch") IS DISTINCT FROM (v_session."principalOid",v_session."principalName",v_session."credentialEpoch",v_session."launchEpoch") OR
     (v_receipt."principalOid",v_receipt."principalName",v_receipt."credentialEpoch",v_receipt."launchEpoch",v_receipt."backendPid",v_receipt."backendStart",v_receipt."sourceClosureHash",v_receipt."installationClosureHash") IS DISTINCT FROM (v_observation."principalOid",v_observation."principalName",v_observation."credentialEpoch",v_observation."launchEpoch",v_observation."backendPid",v_observation."backendStart",v_observation."sourceClosureHash",v_observation."installationClosureHash") OR
     (v_receipt."principalOid",v_receipt."principalName",v_receipt."credentialEpoch",v_receipt."launchEpoch",v_receipt."sourceClosureHash",v_receipt."installationClosureHash") IS DISTINCT FROM (v_baseline."principalOid",v_baseline."principalName",v_baseline."credentialEpoch",v_baseline."launchEpoch",v_baseline."sourceClosureHash",v_baseline."installationClosureHash") OR
     (v_receipt."chargeKind",v_receipt."chargeEventKey",v_receipt."chargeBindingHash") IS DISTINCT FROM (v_charge."kind",v_charge."eventKey",v_charge."bindingHash") THEN RAISE EXCEPTION 'SELECTION_UNAVAILABLE'; END IF;
  -- The admission primary-key reference needs a final-tuple assertion to associate
  -- the original row; that assertion is not implemented. Receipt implementation and qualification,
  -- together with the remaining authority and resource proofs, are still absent.
  RAISE EXCEPTION 'SELECTION_UNAVAILABLE';
 END IF;
EXCEPTION WHEN OTHERS THEN RAISE EXCEPTION 'SELECTION_UNAVAILABLE'; END $$;
REVOKE ALL ON FUNCTION public.pro273_control_plane_lock_input_authority(TEXT,TEXT) FROM PUBLIC;

-- Unreachable source-only partial evaluator. It never confers authority; a
-- complete proof interpretation and ordered locking are still required.
CREATE FUNCTION public.pro273_control_plane_evaluate_initial(p_input_claim_id TEXT) RETURNS VOID
LANGUAGE plpgsql SECURITY DEFINER SET search_path=pg_catalog AS $$
DECLARE c public."Pro273ControlPlaneInputClaim"%ROWTYPE; b public."Pro273ControlPlaneInputBinding"%ROWTYPE;
 s public."Pro262CapacityObserverInputReservation"%ROWTYPE; base public."Pro273ControlPlaneBaseline"%ROWTYPE;
 provenance public."Pro273ControlPlaneBaselineProvenance"%ROWTYPE; publisher public."Pro262CapacityTrust"%ROWTYPE;
 bootstrap public."Pro262CapacityBootstrapTrust"%ROWTYPE; charge public."Pro262CapacityControlCharge"%ROWTYPE;
 control public."Pro262CapacityControlBaseline"%ROWTYPE; q JSONB; input_bound NUMERIC; field TEXT; bound NUMERIC;
BEGIN
 SELECT x.* INTO STRICT c FROM public."Pro273ControlPlaneInputClaim" x WHERE x."inputClaimId"=p_input_claim_id;
 SELECT x.* INTO STRICT b FROM public."Pro273ControlPlaneInputBinding" x WHERE x."reservationId"=c."reservationId";
 SELECT x.* INTO STRICT s FROM public."Pro262CapacityObserverInputReservation" x WHERE x."reservationId"=b."reservationId";
 SELECT x.* INTO STRICT base FROM public."Pro273ControlPlaneBaseline" x WHERE x."baselineId"=c."baselineId";
 SELECT x.* INTO STRICT provenance FROM public."Pro273ControlPlaneBaselineProvenance" x WHERE (x."baselineId",x."coreHash")=(base."baselineId",base."coreHash");
 SELECT x.* INTO STRICT publisher FROM public."Pro262CapacityTrust" x WHERE (x."trustId",x."generation")=(b."trustId",b."trustGeneration");
 SELECT x.* INTO STRICT bootstrap FROM public."Pro262CapacityBootstrapTrust" x WHERE (x."trustId",x."generation")=(b."trustId",b."trustGeneration");
 SELECT x.* INTO STRICT charge FROM public."Pro262CapacityControlCharge" x WHERE (x."kind",x."eventKey",x."bindingHash")=(b."chargeKind",b."chargeEventKey",b."chargeBindingHash");
 SELECT x.* INTO STRICT control FROM public."Pro262CapacityControlBaseline" x WHERE x."kind"=charge."kind";
 q:=publisher."scope"->'initialQualification';
 IF c."purpose" IS DISTINCT FROM 'QUALIFIER_BASELINE_INITIAL' OR base."purpose" IS DISTINCT FROM c."purpose" OR
    (c."reservationId",c."baselineId",c."purpose",c."eventId",c."target",c."chargeKind",c."chargeEventKey",c."chargeBindingHash") IS DISTINCT FROM (b."reservationId",b."baselineId",b."purpose",b."eventId",b."target",b."chargeKind",b."chargeEventKey",b."chargeBindingHash") OR
    (s."observerTrustId",s."observerTrustGeneration") IS DISTINCT FROM (b."trustId",b."trustGeneration") OR
    publisher."purpose" IS DISTINCT FROM 'QUALIFIER_BASELINE_PUBLISHER' OR publisher."supplierPrincipal" IS DISTINCT FROM SESSION_USER::NAME OR publisher."revoked" OR publisher."validFrom">pg_catalog.clock_timestamp() OR publisher."validUntil"<=pg_catalog.clock_timestamp() OR bootstrap."validUntil"<=pg_catalog.clock_timestamp() OR
    publisher."scope"->>'publisherPrincipalName' IS DISTINCT FROM SESSION_USER::TEXT OR publisher."scope"->>'publisherPrincipalOid' IS DISTINCT FROM s."observerPrincipalOid"::TEXT OR
    publisher."scope"->>'physicalIdentity' IS DISTINCT FROM base."physicalIdentity" OR publisher."scope"->>'physicalProofIdentity' IS DISTINCT FROM base."physicalProofIdentity" OR publisher."scope"->>'sourceClosureHash' IS DISTINCT FROM base."sourceClosureHash" OR publisher."scope"->>'inputEnvelope' IS DISTINCT FROM s."baselineAllocationProof" OR
    publisher."scope"->'target' IS DISTINCT FROM b."target" OR publisher."scope"->>'bootstrapKind' IS DISTINCT FROM b."target"->>'bootstrapKind' OR
    pg_catalog.jsonb_typeof(q) IS DISTINCT FROM 'object' OR (SELECT pg_catalog.count(*) FROM pg_catalog.jsonb_object_keys(publisher."scope"))<>10 THEN RAISE EXCEPTION 'SELECTION_UNAVAILABLE'; END IF;
 -- Validate the complete authenticated qualification here, independently of
 -- provisioning; no nullable JSON value may evade a later comparison.
 IF q->>'schemaVersion'='pro273-initial-qualification-v1' AND ((SELECT pg_catalog.count(*) FROM pg_catalog.jsonb_object_keys(q))<>21 OR NOT (q ?& ARRAY['schemaVersion','baselineId','baselineCoreHash','parserAbiVersion','sourceClosureHash','installationClosureHash','receiverIdentity','receiverClosureHash','maxInputBytes','maxOutputBytes','parserPeakBytes','serializationPeakBytes','jsonbPeakBytes','largestAllocationBytes','stackPeakBytes','eventDurableBytes','closedScopeDurableBytes','memoryEvidenceHash','durabilityEvidenceHash','fenceEvidenceHash','fenceAbiVersion'])) THEN RAISE EXCEPTION 'SELECTION_UNAVAILABLE'; END IF;
  IF q->>'schemaVersion'='pro273-initial-qualification-v2' AND ((SELECT pg_catalog.count(*) FROM pg_catalog.jsonb_object_keys(q))<>23 OR NOT (q ?& ARRAY['schemaVersion','baselineId','baselineCoreHash','parserAbiVersion','sourceClosureHash','installationClosureHash','receiverIdentity','receiverClosureHash','maxInputBytes','maxOutputBytes','parserPeakBytes','serializationPeakBytes','jsonbPeakBytes','largestAllocationBytes','stackPeakBytes','eventDurableBytes','closedScopeDurableBytes','memoryEvidenceHash','durabilityEvidenceHash','fenceEvidenceHash','fenceAbiVersion','decoderOverheadBytes','decoderWorkBytes'])) THEN RAISE EXCEPTION 'SELECTION_UNAVAILABLE'; END IF;
 IF EXISTS(SELECT 1 FROM pg_catalog.jsonb_each(q) e WHERE pg_catalog.jsonb_typeof(e.value) IS DISTINCT FROM 'string' OR e.value#>>'{}'='') THEN RAISE EXCEPTION 'SELECTION_UNAVAILABLE'; END IF;
 IF (q->>'schemaVersion' IS DISTINCT FROM 'pro273-initial-qualification-v1' AND q->>'schemaVersion' IS DISTINCT FROM 'pro273-initial-qualification-v2') OR (q->>'schemaVersion'='pro273-initial-qualification-v1' AND q->>'parserAbiVersion' IS DISTINCT FROM 'pro273-initial-metadata-v1') OR (q->>'schemaVersion'='pro273-initial-qualification-v2' AND q->>'parserAbiVersion' IS DISTINCT FROM 'pro273-initial-metadata-v2') OR q->>'fenceAbiVersion' IS DISTINCT FROM 'pro273-initial-one-shot-v1' THEN RAISE EXCEPTION 'SELECTION_UNAVAILABLE'; END IF;
 FOREACH field IN ARRAY ARRAY['baselineCoreHash','sourceClosureHash','installationClosureHash','receiverClosureHash','memoryEvidenceHash','durabilityEvidenceHash','fenceEvidenceHash'] LOOP
  IF q->>field !~ '^[a-f0-9]{64}$' THEN RAISE EXCEPTION 'SELECTION_UNAVAILABLE'; END IF;
 END LOOP;
 FOREACH field IN ARRAY ARRAY['maxInputBytes','maxOutputBytes','parserPeakBytes','serializationPeakBytes','jsonbPeakBytes','largestAllocationBytes','stackPeakBytes','eventDurableBytes','closedScopeDurableBytes'] LOOP
  IF q->>field !~ '^[1-9][0-9]{0,18}$' THEN RAISE EXCEPTION 'SELECTION_UNAVAILABLE'; END IF;
  IF (q->>field)::NUMERIC>9223372036854775807 THEN RAISE EXCEPTION 'SELECTION_UNAVAILABLE'; END IF;
 END LOOP;
  IF q->>'schemaVersion'='pro273-initial-qualification-v2' THEN
   FOREACH field IN ARRAY ARRAY['decoderOverheadBytes','decoderWorkBytes'] LOOP
    IF q->>field !~ '^[1-9][0-9]{0,18}$' THEN RAISE EXCEPTION 'SELECTION_UNAVAILABLE'; END IF;
    IF (q->>field)::NUMERIC>9223372036854775807 THEN RAISE EXCEPTION 'SELECTION_UNAVAILABLE'; END IF;
   END LOOP;
  END IF;
 IF q->>'baselineId' IS DISTINCT FROM base."baselineId" OR q->>'baselineCoreHash' IS DISTINCT FROM provenance."coreHash" OR q->>'sourceClosureHash' IS DISTINCT FROM base."sourceClosureHash" OR q->>'installationClosureHash' IS DISTINCT FROM base."installationClosureHash" THEN RAISE EXCEPTION 'SELECTION_UNAVAILABLE'; END IF;
 IF pg_catalog.jsonb_typeof(publisher."scope"->'inputBound') IS DISTINCT FROM 'string' OR COALESCE(publisher."scope"->>'inputBound','') !~ '^[1-9][0-9]{0,18}$' THEN RAISE EXCEPTION 'SELECTION_UNAVAILABLE'; END IF;
 IF (publisher."scope"->>'inputBound')::NUMERIC>9223372036854775807 THEN RAISE EXCEPTION 'SELECTION_UNAVAILABLE'; END IF;
 -- LEAST ignores NULL; validate every operand and each compared capacity first.
 FOREACH bound IN ARRAY ARRAY[s."maxInputBytes",base."maxInputBytes",base."reservedBackendBytes",base."reservedSharedBytes",base."reservedTemporaryBytes",base."maxOutputBytes",base."primitiveParserCacheBytes",base."inputEvidenceSerializationBytes",base."maxAllocationBytes",base."stackBytes",charge."amount",control."eventWorstCase",control."maxClosedScopeBytes"] LOOP
  IF bound IS NULL OR bound<=0 OR bound::TEXT IN ('NaN','Infinity','-Infinity') OR bound<>pg_catalog.trunc(bound) THEN RAISE EXCEPTION 'SELECTION_UNAVAILABLE'; END IF;
 END LOOP;
 input_bound:=LEAST(s."maxInputBytes",base."maxInputBytes",(publisher."scope"->>'inputBound')::NUMERIC);
 IF (q->>'maxInputBytes')::NUMERIC<input_bound OR (q->>'maxOutputBytes')::NUMERIC<base."maxOutputBytes" OR
    (q->>'parserPeakBytes')::NUMERIC>base."primitiveParserCacheBytes" OR (q->>'serializationPeakBytes')::NUMERIC>base."inputEvidenceSerializationBytes" OR
    (q->>'jsonbPeakBytes')::NUMERIC>(q->>'serializationPeakBytes')::NUMERIC OR (q->>'largestAllocationBytes')::NUMERIC>base."maxAllocationBytes" OR (q->>'stackPeakBytes')::NUMERIC>base."stackBytes" OR
    NOT control."enabled" OR (control."physicalIdentity",control."controlProofIdentity") IS DISTINCT FROM (base."physicalIdentity",base."physicalProofIdentity") OR
    control."coverageContract" IS DISTINCT FROM 'pro273-initial-event-v1' OR control."coverageEvidenceHash" IS DISTINCT FROM q->>'durabilityEvidenceHash' OR
    charge."amount" IS DISTINCT FROM control."eventWorstCase" OR (q->>'eventDurableBytes')::NUMERIC>charge."amount" OR (q->>'closedScopeDurableBytes')::NUMERIC>control."maxClosedScopeBytes" THEN RAISE EXCEPTION 'SELECTION_UNAVAILABLE'; END IF;
 -- v2 uses the same full provisioning-record UTF8 SHA-256 interpretation as v1;
 -- bootstrap."recordHash" cannot be checked without the exact serialized provisioning record.
 -- Independent proof of overlap,
 -- shared coverage, receiver closure and durable one-shot fence are absent.
 RAISE EXCEPTION 'SELECTION_UNAVAILABLE';
EXCEPTION WHEN OTHERS THEN RAISE EXCEPTION 'SELECTION_UNAVAILABLE'; END $$;
REVOKE ALL ON FUNCTION public.pro273_control_plane_evaluate_initial(TEXT) FROM PUBLIC;

-- Resolves authority exclusively through protected rows and the live session.
-- The claim/publisher and baseline bootstrap constructors are separately required.
CREATE FUNCTION public.pro273_control_plane_assert_input(p_input_claim_id TEXT,p_purpose TEXT) RETURNS JSONB
LANGUAGE plpgsql SECURITY DEFINER SET search_path=pg_catalog AS $$
DECLARE v_claim public."Pro273ControlPlaneInputClaim"%ROWTYPE; v_hint public."Pro273ControlPlaneInputClaim"%ROWTYPE; v_session public."Pro273ControlPlaneSessionClaim"%ROWTYPE;
 v_baseline public."Pro273ControlPlaneBaseline"%ROWTYPE; v_provenance public."Pro273ControlPlaneBaselineProvenance"%ROWTYPE;
 v_slot public."Pro262CapacityObserverInputReservation"%ROWTYPE; v_observer_claim public."Pro262CapacityObserverInputClaim"%ROWTYPE;
 v_binding public."Pro273ControlPlaneInputBinding"%ROWTYPE; v_input_trust public."Pro262CapacityTrust"%ROWTYPE;
 v_observation public."Pro273ControlPlaneProcessObservation"%ROWTYPE; v_trust public."Pro262CapacityTrust"%ROWTYPE;
 v_install public."Pro262CapacityTrust"%ROWTYPE; v_domain public."Pro262CapacityPhysicalDomain"%ROWTYPE;
 v_charge public."Pro262CapacityControlCharge"%ROWTYPE; v_now TIMESTAMPTZ; v_principal OID;
BEGIN
 IF p_input_claim_id IS NULL OR p_purpose IS NULL OR p_purpose NOT IN ('QUALIFIER_BASELINE_INITIAL','SELECTION_PROFILE_REVOKE') OR pg_catalog.current_setting('transaction_isolation')<>'read committed' THEN RAISE EXCEPTION 'SELECTION_UNAVAILABLE'; END IF;
 SELECT c.* INTO STRICT v_hint FROM public."Pro273ControlPlaneInputClaim" c WHERE c."inputClaimId"=p_input_claim_id;
 PERFORM public.pro273_control_plane_lock_input_authority(v_hint."sessionClaimId",v_hint."reservationId");
 SELECT c.* INTO STRICT v_claim FROM public."Pro273ControlPlaneInputClaim" c WHERE c."inputClaimId"=p_input_claim_id FOR SHARE NOWAIT;
 IF v_claim IS DISTINCT FROM v_hint THEN RAISE EXCEPTION 'SELECTION_UNAVAILABLE'; END IF;
 SELECT s.* INTO STRICT v_session FROM public."Pro273ControlPlaneSessionClaim" s WHERE (s."baselineId",s."sessionClaimId")=(v_claim."baselineId",v_claim."sessionClaimId") FOR SHARE NOWAIT;
 SELECT b.* INTO STRICT v_baseline FROM public."Pro273ControlPlaneBaseline" b WHERE b."baselineId"=v_claim."baselineId" FOR SHARE NOWAIT;
 SELECT p.* INTO STRICT v_provenance FROM public."Pro273ControlPlaneBaselineProvenance" p WHERE (p."baselineId",p."coreHash")=(v_baseline."baselineId",v_baseline."coreHash") FOR SHARE NOWAIT;
 SELECT d.* INTO STRICT v_domain FROM public."Pro262CapacityPhysicalDomain" d WHERE d."physicalIdentity"=v_baseline."physicalIdentity" FOR SHARE NOWAIT;
 SELECT t.* INTO STRICT v_trust FROM public."Pro262CapacityTrust" t WHERE (t."trustId",t."generation")=(v_provenance."trustId",v_provenance."trustGeneration") FOR SHARE NOWAIT;
 SELECT o.* INTO STRICT v_observation FROM public."Pro273ControlPlaneProcessObservation" o WHERE o."sessionClaimId"=v_session."sessionClaimId" FOR SHARE NOWAIT;
 SELECT t.* INTO STRICT v_install FROM public."Pro262CapacityTrust" t WHERE (t."trustId",t."generation")=(v_observation."trustId",v_observation."trustGeneration") FOR SHARE NOWAIT;
 SELECT r.* INTO STRICT v_slot FROM public."Pro262CapacityObserverInputReservation" r WHERE r."reservationId"=v_claim."reservationId" FOR SHARE NOWAIT;
 SELECT c.* INTO STRICT v_observer_claim FROM public."Pro262CapacityObserverInputClaim" c WHERE c."inputClaimId"=p_input_claim_id FOR SHARE NOWAIT;
 SELECT b.* INTO STRICT v_binding FROM public."Pro273ControlPlaneInputBinding" b WHERE b."reservationId"=v_slot."reservationId" FOR SHARE NOWAIT;
 SELECT t.* INTO STRICT v_input_trust FROM public."Pro262CapacityTrust" t WHERE (t."trustId",t."generation")=(v_binding."trustId",v_binding."trustGeneration") FOR SHARE NOWAIT;
 SELECT c.* INTO STRICT v_charge FROM public."Pro262CapacityControlCharge" c WHERE (c."kind",c."eventKey")=(v_claim."chargeKind",v_claim."chargeEventKey") FOR SHARE NOWAIT;
 SELECT r.oid INTO STRICT v_principal FROM pg_catalog.pg_roles r WHERE r.rolname=SESSION_USER::NAME AND r.rolcanlogin AND NOT r.rolsuper;
 v_now:=pg_catalog.clock_timestamp();
 -- Validate the wire domain before formatting; use a UTC timestamp without time zone
 -- for truncation so session TimeZone cannot change the alignment check.
 IF v_baseline."validUntil" IS NULL OR NOT pg_catalog.isfinite(v_baseline."validUntil") THEN RAISE EXCEPTION 'SELECTION_UNAVAILABLE'; END IF;
 IF (v_baseline."validUntil" AT TIME ZONE 'UTC') < TIMESTAMP '0001-01-01 00:00:00' OR (v_baseline."validUntil" AT TIME ZONE 'UTC') >= TIMESTAMP '10000-01-01 00:00:00' OR
    (v_baseline."validUntil" AT TIME ZONE 'UTC') IS DISTINCT FROM pg_catalog.date_trunc('milliseconds',v_baseline."validUntil" AT TIME ZONE 'UTC') THEN RAISE EXCEPTION 'SELECTION_UNAVAILABLE'; END IF;
 IF v_claim."purpose" IS DISTINCT FROM p_purpose OR v_baseline."purpose" IS DISTINCT FROM p_purpose OR NOT v_domain."enabled" OR v_domain."proofIdentity" IS DISTINCT FROM v_baseline."physicalProofIdentity" OR
    v_baseline."validFrom">v_now OR v_baseline."validUntil"<=v_now OR v_trust."revoked" OR v_trust."validFrom">v_now OR v_trust."validUntil"<=v_now OR
    v_install."purpose"<>'INSTALL_OBSERVATION' OR v_install."revoked" OR v_install."validFrom">v_now OR v_install."validUntil"<=v_now OR v_observation."validUntil"<=v_now OR
    v_observation."observerOid"=v_principal OR v_observation."observerPrincipal" IS DISTINCT FROM v_install."supplierPrincipal" OR
    v_observation."principalOid" IS DISTINCT FROM v_principal OR v_observation."principalName" IS DISTINCT FROM SESSION_USER::NAME OR v_observation."backendPid" IS DISTINCT FROM pg_catalog.pg_backend_pid() OR v_observation."backendStart" IS DISTINCT FROM public.pro262_capacity_backend_start() OR
    (v_session."principalOid",v_session."principalName",v_session."credentialEpoch",v_session."launchEpoch") IS DISTINCT FROM (v_baseline."principalOid",v_baseline."principalName",v_baseline."credentialEpoch",v_baseline."launchEpoch") OR
    (v_observation."principalOid",v_observation."principalName",v_observation."credentialEpoch",v_observation."launchEpoch",v_observation."host",v_observation."boot",v_observation."processTree",v_observation."parentProcessTree",v_observation."sourceClosureHash",v_observation."installationClosureHash") IS DISTINCT FROM (v_baseline."principalOid",v_baseline."principalName",v_baseline."credentialEpoch",v_baseline."launchEpoch",v_baseline."host",v_baseline."boot",v_baseline."processTree",v_baseline."parentProcessTree",v_baseline."sourceClosureHash",v_baseline."installationClosureHash") OR
    v_slot."physicalIdentity" IS DISTINCT FROM v_baseline."physicalIdentity" OR v_slot."physicalProofIdentity" IS DISTINCT FROM v_baseline."physicalProofIdentity" OR v_slot."phase" IS DISTINCT FROM p_purpose OR v_slot."maxInputBytes">v_baseline."maxInputBytes" OR (v_binding."chargeKind",v_binding."chargeEventKey") IS NOT DISTINCT FROM ('OBSERVER_INPUT_SLOT',v_slot."prepaidEventKey") OR
    (v_binding."baselineId",v_binding."purpose",v_binding."eventId",v_binding."target",v_binding."chargeKind",v_binding."chargeEventKey",v_binding."chargeBindingHash") IS DISTINCT FROM (v_claim."baselineId",v_claim."purpose",v_claim."eventId",v_claim."target",v_claim."chargeKind",v_claim."chargeEventKey",v_claim."chargeBindingHash") OR
    (v_slot."observerTrustId",v_slot."observerTrustGeneration") IS DISTINCT FROM (v_binding."trustId",v_binding."trustGeneration") OR v_input_trust."revoked" OR v_input_trust."validFrom">v_now OR v_input_trust."validUntil"<=v_now OR v_input_trust."supplierPrincipal" IS DISTINCT FROM SESSION_USER::NAME OR
    (p_purpose='QUALIFIER_BASELINE_INITIAL' AND (v_input_trust."purpose"<>'QUALIFIER_BASELINE_PUBLISHER' OR v_input_trust."scope"->>'physicalIdentity' IS DISTINCT FROM v_baseline."physicalIdentity" OR v_input_trust."scope"->>'physicalProofIdentity' IS DISTINCT FROM v_baseline."physicalProofIdentity" OR v_input_trust."scope"->>'publisherPrincipalOid' IS DISTINCT FROM v_principal::TEXT OR v_input_trust."scope"->>'publisherPrincipalName' IS DISTINCT FROM SESSION_USER::TEXT OR v_input_trust."scope"->>'sourceClosureHash' IS DISTINCT FROM v_baseline."sourceClosureHash" OR v_input_trust."scope"->>'inputEnvelope' IS DISTINCT FROM v_slot."baselineAllocationProof" OR v_slot."maxInputBytes">(v_input_trust."scope"->>'inputBound')::NUMERIC OR v_input_trust."scope"->'target' IS DISTINCT FROM v_binding."target" OR v_input_trust."scope"->>'bootstrapKind' IS DISTINCT FROM v_binding."target"->>'bootstrapKind')) OR
    v_observer_claim."reservationId" IS DISTINCT FROM v_slot."reservationId" OR v_observer_claim."eventKey" IS DISTINCT FROM v_claim."eventId" OR v_observer_claim."phase" IS DISTINCT FROM p_purpose OR v_observer_claim."observerPrincipalOid" IS DISTINCT FROM v_principal OR v_observer_claim."observerPrincipalName" IS DISTINCT FROM SESSION_USER::NAME OR v_charge."bindingHash" IS DISTINCT FROM v_claim."chargeBindingHash" THEN RAISE EXCEPTION 'SELECTION_UNAVAILABLE'; END IF;
 IF pg_catalog.jsonb_typeof(v_claim."target") IS DISTINCT FROM 'object' OR (p_purpose='QUALIFIER_BASELINE_INITIAL' AND ((SELECT pg_catalog.count(*) FROM pg_catalog.jsonb_object_keys(v_claim."target"))<>4 OR NOT (v_claim."target" ?& ARRAY['kind','bootstrapKind','expectedCoreHash','expectedEvidenceHash']) OR v_claim."target"->>'kind'<>'INITIAL' OR COALESCE(v_claim."target"->>'expectedCoreHash','') !~ '^[a-f0-9]{64}$' OR COALESCE(v_claim."target"->>'expectedEvidenceHash','') !~ '^[a-f0-9]{64}$')) OR (p_purpose='SELECTION_PROFILE_REVOKE' AND ((SELECT pg_catalog.count(*) FROM pg_catalog.jsonb_object_keys(v_claim."target"))<>5 OR NOT (v_claim."target" ?& ARRAY['kind','profileId','generation','expectedRecordHash','eventId']) OR v_claim."target"->>'kind'<>'REVOKE' OR v_claim."target"->>'eventId' IS DISTINCT FROM v_claim."eventId" OR COALESCE(v_claim."target"->>'generation','') !~ '^[1-9][0-9]*$' OR COALESCE(v_claim."target"->>'expectedRecordHash','') !~ '^[a-f0-9]{64}$')) THEN RAISE EXCEPTION 'SELECTION_UNAVAILABLE'; END IF;
 RETURN pg_catalog.jsonb_build_object('schemaVersion','pro273-control-plane-input-v1','purpose',p_purpose,'baselineId',v_baseline."baselineId",'baselineCoreHash',v_baseline."coreHash",'reservationId',v_slot."reservationId",'inputClaimId',v_claim."inputClaimId",'sessionClaimId',v_session."sessionClaimId",'eventId',v_claim."eventId",'target',v_claim."target",'principal',pg_catalog.jsonb_build_object('oid',v_principal::TEXT,'name',SESSION_USER::TEXT,'credentialEpoch',v_baseline."credentialEpoch",'launchEpoch',v_baseline."launchEpoch",'pid',v_observation."backendPid"::TEXT,'backendStart',pg_catalog.to_char(v_observation."backendStart" AT TIME ZONE 'UTC','YYYY-MM-DD"T"HH24:MI:SS.US"Z"'),'host',v_baseline."host",'boot',v_baseline."boot",'processTree',v_baseline."processTree",'parentProcessTree',v_baseline."parentProcessTree"),'sourceClosureHash',v_baseline."sourceClosureHash",'installationClosureHash',v_baseline."installationClosureHash",'inputLimitBytes',v_slot."maxInputBytes"::TEXT,'outputLimitBytes',v_baseline."maxOutputBytes"::TEXT,'prepaidCharge',pg_catalog.jsonb_build_object('kind',v_claim."chargeKind",'eventKey',v_claim."chargeEventKey",'bindingHash',v_claim."chargeBindingHash"),'expiresAt',pg_catalog.to_char(v_baseline."validUntil" AT TIME ZONE 'UTC','YYYY-MM-DD"T"HH24:MI:SS.MS"Z"'));
EXCEPTION WHEN OTHERS THEN RAISE EXCEPTION 'SELECTION_UNAVAILABLE';
END $$;
REVOKE ALL ON FUNCTION public.pro273_control_plane_assert_input(TEXT,TEXT) FROM PUBLIC;

-- Binds a permanently claimed observer slot to the preregistered session.
-- The existing independent slot allocator must have committed the claim first.
CREATE FUNCTION public.pro273_control_plane_claim_input(p_session_claim_id TEXT,p_reservation_id TEXT) RETURNS TEXT
LANGUAGE plpgsql SECURITY DEFINER SET search_path=pg_catalog AS $$
DECLARE v_session public."Pro273ControlPlaneSessionClaim"%ROWTYPE; v_binding public."Pro273ControlPlaneInputBinding"%ROWTYPE;
 v_claim public."Pro262CapacityObserverInputClaim"%ROWTYPE; v_prior public."Pro273ControlPlaneInputClaim"%ROWTYPE;
 v_baseline public."Pro273ControlPlaneBaseline"%ROWTYPE; v_global RECORD; v_domain public."Pro262CapacityPhysicalDomain"%ROWTYPE;
BEGIN
 IF COALESCE(p_session_claim_id,'')='' OR COALESCE(p_reservation_id,'')='' OR pg_catalog.current_setting('transaction_isolation')<>'read committed' THEN RAISE EXCEPTION 'SELECTION_UNAVAILABLE'; END IF;
 SELECT s.* INTO STRICT v_session FROM public."Pro273ControlPlaneSessionClaim" s WHERE s."sessionClaimId"=p_session_claim_id;
 SELECT b.* INTO STRICT v_baseline FROM public."Pro273ControlPlaneBaseline" b WHERE b."baselineId"=v_session."baselineId";
 SELECT b.* INTO STRICT v_binding FROM public."Pro273ControlPlaneInputBinding" b WHERE b."reservationId"=p_reservation_id;
 IF v_binding."purpose"='QUALIFIER_BASELINE_INITIAL' THEN RAISE EXCEPTION 'SELECTION_UNAVAILABLE'; END IF;
 LOCK TABLE public."Pro311ControlDomain" IN ACCESS SHARE MODE NOWAIT;
 SELECT g."physicalIdentity",g."proofIdentity" INTO STRICT v_global FROM public."Pro311ControlDomain" g WHERE g."id"='global-v1' FOR UPDATE NOWAIT;
 SELECT d.* INTO STRICT v_domain FROM public."Pro262CapacityPhysicalDomain" d WHERE d."physicalIdentity"=v_baseline."physicalIdentity" FOR UPDATE NOWAIT;
 IF (v_global."physicalIdentity",v_global."proofIdentity") IS DISTINCT FROM (v_domain."physicalIdentity",v_domain."proofIdentity") THEN RAISE EXCEPTION 'SELECTION_UNAVAILABLE'; END IF;
 PERFORM public.pro273_control_plane_lock_input_authority(p_session_claim_id,p_reservation_id);
 SELECT s.* INTO STRICT v_session FROM public."Pro273ControlPlaneSessionClaim" s WHERE s."sessionClaimId"=p_session_claim_id FOR SHARE NOWAIT;
 SELECT b.* INTO STRICT v_binding FROM public."Pro273ControlPlaneInputBinding" b WHERE b."reservationId"=p_reservation_id FOR SHARE NOWAIT;
 SELECT c.* INTO STRICT v_claim FROM public."Pro262CapacityObserverInputClaim" c WHERE c."reservationId"=p_reservation_id FOR SHARE NOWAIT;
 IF v_session."baselineId" IS DISTINCT FROM v_binding."baselineId" OR v_claim."eventKey" IS DISTINCT FROM v_binding."eventId" OR v_claim."phase" IS DISTINCT FROM v_binding."purpose" THEN RAISE EXCEPTION 'SELECTION_UNAVAILABLE'; END IF;
 SELECT c.* INTO v_prior FROM public."Pro273ControlPlaneInputClaim" c WHERE c."reservationId"=p_reservation_id;
 IF FOUND THEN
  IF (v_prior."inputClaimId",v_prior."baselineId",v_prior."sessionClaimId",v_prior."purpose",v_prior."eventId",v_prior."target",v_prior."chargeKind",v_prior."chargeEventKey",v_prior."chargeBindingHash") IS DISTINCT FROM (v_claim."inputClaimId",v_binding."baselineId",p_session_claim_id,v_binding."purpose",v_binding."eventId",v_binding."target",v_binding."chargeKind",v_binding."chargeEventKey",v_binding."chargeBindingHash") THEN RAISE EXCEPTION 'SELECTION_UNAVAILABLE'; END IF;
 ELSE
  INSERT INTO public."Pro273ControlPlaneInputClaim"("inputClaimId","baselineId","sessionClaimId","reservationId","purpose","eventId","target","chargeKind","chargeEventKey","chargeBindingHash") VALUES(v_claim."inputClaimId",v_binding."baselineId",p_session_claim_id,p_reservation_id,v_binding."purpose",v_binding."eventId",v_binding."target",v_binding."chargeKind",v_binding."chargeEventKey",v_binding."chargeBindingHash");
 END IF;
 PERFORM public.pro273_control_plane_assert_input(v_claim."inputClaimId",v_binding."purpose");
 RETURN v_claim."inputClaimId";
EXCEPTION WHEN OTHERS THEN RAISE EXCEPTION 'SELECTION_UNAVAILABLE'; END $$;
REVOKE ALL ON FUNCTION public.pro273_control_plane_claim_input(TEXT,TEXT) FROM PUBLIC;

-- Routing hints confer no authority. Fence global and physical state, then the
-- complete installer trust set in a deduplicated, deterministic order. Re-read
-- the routing records under their existing locks before accepting the hints.
CREATE FUNCTION public.pro273_installer_acquire_authority(p_expectation_id TEXT) RETURNS VOID
LANGUAGE plpgsql SECURITY DEFINER SET search_path=pg_catalog AS $$
DECLARE v_hint public."Pro273ControlPlaneInstallerExpectation"%ROWTYPE;
 v_expected public."Pro273ControlPlaneInstallerExpectation"%ROWTYPE;
 v_observation_hint public."Pro273InstallerProcessObservation"%ROWTYPE;
 v_observation public."Pro273InstallerProcessObservation"%ROWTYPE;
 v_input_hint public."Pro262CapacityObserverInputReservation"%ROWTYPE; v_input public."Pro262CapacityObserverInputReservation"%ROWTYPE;
 v_binding_hint public."Pro273InstallerSlotBinding"%ROWTYPE; v_binding public."Pro273InstallerSlotBinding"%ROWTYPE;
 v_claim_hint public."Pro262CapacityObserverInputClaim"%ROWTYPE; v_claim public."Pro262CapacityObserverInputClaim"%ROWTYPE;
 v_obs_claim_hint public."Pro262CapacityObserverInputClaim"%ROWTYPE; v_obs_claim public."Pro262CapacityObserverInputClaim"%ROWTYPE;
 v_obs_slot_hint public."Pro262CapacityObserverInputReservation"%ROWTYPE; v_obs_slot public."Pro262CapacityObserverInputReservation"%ROWTYPE;
 v_global RECORD; v_domain public."Pro262CapacityPhysicalDomain"%ROWTYPE; v_key RECORD; v_trust public."Pro262CapacityTrust"%ROWTYPE; v_input_trust public."Pro262CapacityTrust"%ROWTYPE; v_now TIMESTAMPTZ;
BEGIN
 IF pg_catalog.current_setting('transaction_isolation') IS DISTINCT FROM 'read committed' THEN RAISE EXCEPTION 'SELECTION_UNAVAILABLE'; END IF;
 SELECT e.* INTO STRICT v_hint FROM public."Pro273ControlPlaneInstallerExpectation" e WHERE e."expectationId"=p_expectation_id;
 SELECT o.* INTO STRICT v_observation_hint FROM public."Pro273InstallerProcessObservation" o WHERE (o."expectationId",o."credentialEpoch",o."launchEpoch")=(v_hint."expectationId",v_hint."credentialEpoch",v_hint."launchEpoch");
 SELECT r.* INTO STRICT v_input_hint FROM public."Pro262CapacityObserverInputReservation" r WHERE r."reservationId"=v_hint."constructorInputReservationId";
 SELECT b.* INTO STRICT v_binding_hint FROM public."Pro273InstallerSlotBinding" b WHERE b."reservationId"=v_input_hint."reservationId";
 SELECT c.* INTO STRICT v_claim_hint FROM public."Pro262CapacityObserverInputClaim" c WHERE c."reservationId"=v_input_hint."reservationId";
 SELECT c.* INTO STRICT v_obs_claim_hint FROM public."Pro262CapacityObserverInputClaim" c WHERE c."inputClaimId"=v_observation_hint."inputClaimId";
 SELECT r.* INTO STRICT v_obs_slot_hint FROM public."Pro262CapacityObserverInputReservation" r WHERE r."reservationId"=v_obs_claim_hint."reservationId";
 SELECT g."physicalIdentity",g."proofIdentity" INTO STRICT v_global FROM public."Pro311ControlDomain" g WHERE g."id"='global-v1' FOR SHARE NOWAIT;
 SELECT d.* INTO STRICT v_domain FROM public."Pro262CapacityPhysicalDomain" d WHERE d."physicalIdentity"=v_global."physicalIdentity" FOR SHARE NOWAIT;
 FOR v_key IN SELECT DISTINCT k.trust_id COLLATE "C" AS trust_id,k.generation FROM (VALUES (v_hint."trustId",v_hint."trustGeneration"),(v_observation_hint."trustId",v_observation_hint."trustGeneration"),(v_input_hint."observerTrustId",v_input_hint."observerTrustGeneration"),(v_obs_slot_hint."observerTrustId",v_obs_slot_hint."observerTrustGeneration")) AS k(trust_id,generation) ORDER BY trust_id,generation LOOP
  SELECT t.* INTO STRICT v_trust FROM public."Pro262CapacityTrust" t WHERE (t."trustId",t."generation")=(v_key.trust_id,v_key.generation) FOR SHARE NOWAIT;
 END LOOP;
 SELECT e.* INTO STRICT v_expected FROM public."Pro273ControlPlaneInstallerExpectation" e WHERE e."expectationId"=p_expectation_id FOR SHARE NOWAIT;
 SELECT o.* INTO STRICT v_observation FROM public."Pro273InstallerProcessObservation" o WHERE (o."expectationId",o."credentialEpoch",o."launchEpoch")=(v_expected."expectationId",v_expected."credentialEpoch",v_expected."launchEpoch") FOR SHARE NOWAIT;
 SELECT r.* INTO STRICT v_input FROM public."Pro262CapacityObserverInputReservation" r WHERE r."reservationId"=v_expected."constructorInputReservationId" FOR SHARE NOWAIT;
 SELECT b.* INTO STRICT v_binding FROM public."Pro273InstallerSlotBinding" b WHERE b."reservationId"=v_input."reservationId" FOR SHARE NOWAIT;
 SELECT c.* INTO STRICT v_claim FROM public."Pro262CapacityObserverInputClaim" c WHERE c."reservationId"=v_input."reservationId" FOR SHARE NOWAIT;
 SELECT c.* INTO STRICT v_obs_claim FROM public."Pro262CapacityObserverInputClaim" c WHERE c."inputClaimId"=v_observation."inputClaimId" FOR SHARE NOWAIT;
 SELECT r.* INTO STRICT v_obs_slot FROM public."Pro262CapacityObserverInputReservation" r WHERE r."reservationId"=v_obs_claim."reservationId" FOR SHARE NOWAIT;
 IF v_expected IS DISTINCT FROM v_hint OR v_observation IS DISTINCT FROM v_observation_hint OR v_input IS DISTINCT FROM v_input_hint OR v_binding IS DISTINCT FROM v_binding_hint OR v_claim IS DISTINCT FROM v_claim_hint OR v_obs_claim IS DISTINCT FROM v_obs_claim_hint OR v_obs_slot IS DISTINCT FROM v_obs_slot_hint OR
    (v_obs_slot."observerTrustId",v_obs_slot."observerTrustGeneration") IS DISTINCT FROM (v_observation."trustId",v_observation."trustGeneration") THEN RAISE EXCEPTION 'SELECTION_UNAVAILABLE'; END IF;
 -- Reacquire only the already ordered input identity, never a newly discovered trust.
 SELECT t.* INTO STRICT v_input_trust FROM public."Pro262CapacityTrust" t WHERE (t."trustId",t."generation")=(v_input_hint."observerTrustId",v_input_hint."observerTrustGeneration") FOR SHARE NOWAIT;
 v_now:=pg_catalog.clock_timestamp();
 IF v_input_trust."purpose" IS DISTINCT FROM 'CONTROL_ALLOCATOR' OR v_input_trust."scope"->>'kind' IS DISTINCT FROM 'INSTALLER_CONSTRUCTOR_INPUT' OR v_input_trust."supplierPrincipal" IS DISTINCT FROM v_expected."installerName" OR v_input_trust."revoked" OR v_input_trust."validFrom">v_now OR v_input_trust."validUntil"<=v_now OR
    v_binding."bindingKind" IS DISTINCT FROM 'INSTALLER_CONSTRUCTOR_INPUT' OR v_binding."expectationId" IS DISTINCT FROM v_expected."expectationId" OR v_binding."credentialEpoch" IS DISTINCT FROM v_expected."credentialEpoch" OR v_binding."launchEpoch" IS DISTINCT FROM v_expected."launchEpoch" OR v_binding."phase" IS DISTINCT FROM v_expected."constructorInputPhase" OR v_binding."expectedEventKey" IS DISTINCT FROM v_expected."eventId" OR
    v_claim."reservationId" IS DISTINCT FROM v_input."reservationId" OR v_claim."phase" IS DISTINCT FROM v_expected."constructorInputPhase" OR v_claim."eventKey" IS DISTINCT FROM v_expected."eventId" OR v_claim."observerPrincipalOid" IS DISTINCT FROM v_expected."installerOid" OR v_claim."observerPrincipalName" IS DISTINCT FROM v_expected."installerName" OR public.pro273_installer_slot_matches(v_input."reservationId") IS DISTINCT FROM TRUE THEN RAISE EXCEPTION 'SELECTION_UNAVAILABLE'; END IF;
 IF v_expected."physicalIdentity" IS DISTINCT FROM v_domain."physicalIdentity" OR v_expected."physicalProofIdentity" IS DISTINCT FROM v_global."proofIdentity" OR v_domain."proofIdentity" IS DISTINCT FROM v_global."proofIdentity" THEN RAISE EXCEPTION 'SELECTION_UNAVAILABLE'; END IF;
EXCEPTION WHEN OTHERS THEN RAISE EXCEPTION 'SELECTION_UNAVAILABLE'; END $$;
REVOKE ALL ON FUNCTION public.pro273_installer_acquire_authority(TEXT) FROM PUBLIC;

-- Reader and constructor share the same independently captured observation.
CREATE FUNCTION public.pro273_installer_assert_observed(p_expectation_id TEXT) RETURNS VOID
LANGUAGE plpgsql SECURITY DEFINER SET search_path=pg_catalog AS $$
DECLARE v_expected public."Pro273ControlPlaneInstallerExpectation"%ROWTYPE; v_observation public."Pro273InstallerProcessObservation"%ROWTYPE;
 v_trust public."Pro262CapacityTrust"%ROWTYPE; v_domain public."Pro262CapacityPhysicalDomain"%ROWTYPE;
 v_claim public."Pro262CapacityObserverInputClaim"%ROWTYPE; v_binding public."Pro273InstallerSlotBinding"%ROWTYPE; v_oid OID; v_now TIMESTAMPTZ; v_global RECORD;
BEGIN
 IF pg_catalog.current_setting('transaction_isolation') IS DISTINCT FROM 'read committed' THEN RAISE EXCEPTION 'SELECTION_UNAVAILABLE'; END IF;
 PERFORM public.pro273_installer_acquire_authority(p_expectation_id);
 -- Unlocked identity lookups are only routing hints; each identity is re-read
 -- under the ordered locks before it can authorize anything.
 SELECT e.* INTO STRICT v_expected FROM public."Pro273ControlPlaneInstallerExpectation" e WHERE e."expectationId"=p_expectation_id;
 SELECT o.* INTO STRICT v_observation FROM public."Pro273InstallerProcessObservation" o WHERE (o."expectationId",o."credentialEpoch",o."launchEpoch")=(v_expected."expectationId",v_expected."credentialEpoch",v_expected."launchEpoch");
 SELECT g."physicalIdentity",g."proofIdentity" INTO STRICT v_global FROM public."Pro311ControlDomain" g WHERE g."id"='global-v1' FOR SHARE NOWAIT;
 SELECT d.* INTO STRICT v_domain FROM public."Pro262CapacityPhysicalDomain" d WHERE d."physicalIdentity"=v_global."physicalIdentity" FOR SHARE NOWAIT;
 SELECT t.* INTO STRICT v_trust FROM public."Pro262CapacityTrust" t WHERE (t."trustId",t."generation")=(v_observation."trustId",v_observation."trustGeneration") FOR SHARE NOWAIT;
 SELECT e.* INTO STRICT v_expected FROM public."Pro273ControlPlaneInstallerExpectation" e WHERE e."expectationId"=p_expectation_id FOR SHARE NOWAIT;
 SELECT c.* INTO STRICT v_claim FROM public."Pro262CapacityObserverInputClaim" c WHERE c."inputClaimId"=v_observation."inputClaimId";
 SELECT b.* INTO STRICT v_binding FROM public."Pro273InstallerSlotBinding" b WHERE b."reservationId"=v_claim."reservationId" FOR SHARE NOWAIT;
 SELECT c.* INTO STRICT v_claim FROM public."Pro262CapacityObserverInputClaim" c WHERE c."inputClaimId"=v_observation."inputClaimId" FOR SHARE NOWAIT;
 SELECT o.* INTO STRICT v_observation FROM public."Pro273InstallerProcessObservation" o WHERE (o."expectationId",o."credentialEpoch",o."launchEpoch",o."trustId",o."trustGeneration",o."inputClaimId")=(v_expected."expectationId",v_expected."credentialEpoch",v_expected."launchEpoch",v_trust."trustId",v_trust."generation",v_claim."inputClaimId") FOR SHARE NOWAIT;
 SELECT r.oid INTO STRICT v_oid FROM pg_catalog.pg_roles r WHERE r.rolname=SESSION_USER::NAME AND r.rolcanlogin AND NOT r.rolsuper;
 v_now:=pg_catalog.clock_timestamp();
 IF NOT v_domain."enabled" OR v_domain."physicalIdentity" IS DISTINCT FROM v_expected."physicalIdentity" OR v_domain."proofIdentity" IS DISTINCT FROM v_global."proofIdentity" OR v_domain."proofIdentity" IS DISTINCT FROM v_expected."physicalProofIdentity" OR v_domain."evidenceHash" IS DISTINCT FROM v_expected."physicalEvidenceHash" OR v_expected."validFrom">v_now OR v_expected."validUntil"<=v_now OR
    v_trust."purpose"<>'INSTALL_OBSERVATION' OR v_trust."revoked" OR v_trust."validFrom">v_now OR v_trust."validUntil"<=v_now OR v_observation."validUntil"<=v_now OR v_trust."supplierPrincipal" IS DISTINCT FROM v_observation."observerPrincipal" OR
    v_observation."observerOid"=v_oid OR v_expected."installerOid" IS DISTINCT FROM v_oid OR v_expected."installerName" IS DISTINCT FROM SESSION_USER::NAME OR v_expected."installerPid" IS DISTINCT FROM pg_catalog.pg_backend_pid() OR v_expected."installerBackendStart" IS DISTINCT FROM public.pro262_capacity_backend_start() OR
    (v_observation."targetOid",v_observation."targetPrincipal",v_observation."targetPid",v_observation."targetBackendStart",v_observation."host",v_observation."boot",v_observation."processTree") IS DISTINCT FROM (v_expected."installerOid",v_expected."installerName",v_expected."installerPid",v_expected."installerBackendStart",v_expected."host",v_expected."boot",v_expected."processTree") OR
    v_observation."lane" IS DISTINCT FROM pg_catalog.jsonb_build_object('namespace',v_expected."namespace",'project',v_expected."project",'deployment',v_expected."deployment",'environment',v_expected."environment",'kind','INSTALLER_ROOT') OR v_trust."scope"->'lane' IS DISTINCT FROM v_observation."lane" OR v_trust."scope"->'installation' IS DISTINCT FROM v_observation."installation" OR v_observation."installation"->>'sourceClosure' IS DISTINCT FROM v_expected."sourceClosureHash" OR
    pg_catalog.encode(int4_crypto.digest(pg_catalog.convert_to(v_observation."installation"::TEXT,'UTF8'),'sha256'),'hex') IS DISTINCT FROM v_expected."installationClosureHash" OR
    v_binding."bindingKind"<>'INSTALLER_OBSERVATION' OR v_binding."expectationId" IS DISTINCT FROM p_expectation_id OR v_binding."credentialEpoch" IS DISTINCT FROM v_expected."credentialEpoch" OR v_binding."launchEpoch" IS DISTINCT FROM v_expected."launchEpoch" OR v_binding."expectedEventKey" IS DISTINCT FROM v_claim."eventKey" OR v_claim."reservationId"=v_expected."constructorInputReservationId" THEN RAISE EXCEPTION 'SELECTION_UNAVAILABLE'; END IF;
END $$;
REVOKE ALL ON FUNCTION public.pro273_installer_assert_observed(TEXT) FROM PUBLIC;

-- Read only a pre-existing installer input claim. This fixed gate is not a
-- substitute for independently authenticated installer process observation.
CREATE FUNCTION public.pro273_control_plane_read_installer_input(p_bootstrap_kind TEXT) RETURNS JSONB
LANGUAGE plpgsql SECURITY DEFINER SET search_path=pg_catalog AS $$
DECLARE v_expected public."Pro273ControlPlaneInstallerExpectation"%ROWTYPE; v_domain public."Pro262CapacityPhysicalDomain"%ROWTYPE;
 v_boot public."Pro262CapacityBootstrapBaseline"%ROWTYPE; v_trust public."Pro262CapacityTrust"%ROWTYPE; v_trust_boot public."Pro262CapacityBootstrapTrust"%ROWTYPE;
 v_claim public."Pro262CapacityObserverInputClaim"%ROWTYPE; v_slot public."Pro262CapacityObserverInputReservation"%ROWTYPE; v_input_binding public."Pro273InstallerSlotBinding"%ROWTYPE;
 v_charge public."Pro262CapacityControlCharge"%ROWTYPE; v_oid OID; v_now TIMESTAMPTZ;
BEGIN
 IF pg_catalog.current_setting('transaction_isolation') IS DISTINCT FROM 'read committed' THEN RAISE EXCEPTION 'SELECTION_UNAVAILABLE'; END IF;
 IF COALESCE(p_bootstrap_kind,'')='' OR NOT pg_catalog.pg_has_role(SESSION_USER,'pro273_install_bootstrap','MEMBER') THEN RAISE EXCEPTION 'SELECTION_UNAVAILABLE'; END IF;
 SELECT e.* INTO STRICT v_expected FROM public."Pro273ControlPlaneInstallerExpectation" e WHERE e."bootstrapKind"=p_bootstrap_kind;
 PERFORM public.pro273_installer_assert_observed(v_expected."expectationId");
 SELECT e.* INTO STRICT v_expected FROM public."Pro273ControlPlaneInstallerExpectation" e WHERE e."bootstrapKind"=p_bootstrap_kind FOR SHARE NOWAIT;
 SELECT d.* INTO STRICT v_domain FROM public."Pro262CapacityPhysicalDomain" d WHERE d."physicalIdentity"=v_expected."physicalIdentity" FOR SHARE NOWAIT;
 SELECT b.* INTO STRICT v_boot FROM public."Pro262CapacityBootstrapBaseline" b WHERE b."kind"=p_bootstrap_kind FOR SHARE NOWAIT;
 SELECT t.* INTO STRICT v_trust FROM public."Pro262CapacityTrust" t WHERE (t."trustId",t."generation")=(v_expected."trustId",v_expected."trustGeneration") FOR SHARE NOWAIT;
 IF v_expected."constructorKind"='QUALIFIER_DESCRIPTOR' THEN
  SELECT t.* INTO STRICT v_trust_boot FROM public."Pro262CapacityBootstrapTrust" t WHERE (t."trustId",t."generation")=(v_expected."trustId",v_expected."trustGeneration") FOR SHARE NOWAIT;
  IF v_trust_boot."recordHash" IS DISTINCT FROM v_expected."trustRecordHash" OR v_trust_boot."evidenceHash" IS DISTINCT FROM v_expected."expectedEvidenceHash" OR v_trust_boot."principal" IS DISTINCT FROM SESSION_USER::NAME OR v_trust_boot."validUntil"<=pg_catalog.clock_timestamp() OR v_trust."purpose" IS DISTINCT FROM 'CONTROL_ALLOCATOR' OR v_trust."scope"->>'kind' IS DISTINCT FROM 'SELECTION_QUALIFIER_CONTROL' THEN RAISE EXCEPTION 'SELECTION_UNAVAILABLE'; END IF;
 END IF;
 SELECT c.* INTO STRICT v_claim FROM public."Pro262CapacityObserverInputClaim" c WHERE c."reservationId"=v_expected."constructorInputReservationId" AND c."eventKey"=v_expected."eventId" AND c."phase"=v_expected."constructorInputPhase" FOR SHARE NOWAIT;
 SELECT r.* INTO STRICT v_slot FROM public."Pro262CapacityObserverInputReservation" r WHERE r."reservationId"=v_claim."reservationId" FOR SHARE NOWAIT;
 SELECT b.* INTO STRICT v_input_binding FROM public."Pro273InstallerSlotBinding" b WHERE b."reservationId"=v_slot."reservationId" FOR SHARE NOWAIT;
 SELECT c.* INTO STRICT v_charge FROM public."Pro262CapacityControlCharge" c WHERE (c."kind",c."eventKey")=(v_expected."chargeKind",v_expected."chargeEventKey") FOR SHARE NOWAIT;
 SELECT r.oid INTO STRICT v_oid FROM pg_catalog.pg_roles r WHERE r.rolname=SESSION_USER::NAME AND r.rolcanlogin AND NOT r.rolsuper;
 v_now:=pg_catalog.clock_timestamp();
 IF NOT v_domain."enabled" OR v_domain."proofIdentity" IS DISTINCT FROM v_expected."physicalProofIdentity" OR v_domain."evidenceHash" IS DISTINCT FROM v_expected."physicalEvidenceHash" OR
    v_expected."installerOid" IS DISTINCT FROM v_oid OR v_expected."installerName" IS DISTINCT FROM SESSION_USER::NAME OR v_expected."installerPid" IS DISTINCT FROM pg_catalog.pg_backend_pid() OR v_expected."installerBackendStart" IS DISTINCT FROM public.pro262_capacity_backend_start() OR
    v_expected."validFrom">v_now OR v_expected."validUntil"<=v_now OR v_boot."validUntil"<=v_now OR v_boot."publisherPrincipal" IS DISTINCT FROM SESSION_USER::NAME OR v_boot."recordHash" IS DISTINCT FROM v_expected."expectedCoreHash" OR v_boot."evidenceHash" IS DISTINCT FROM v_expected."expectedEvidenceHash" OR
    v_trust."revoked" OR v_trust."validFrom">v_now OR v_trust."validUntil"<=v_now OR v_trust."supplierPrincipal" IS DISTINCT FROM SESSION_USER::NAME OR
    v_input_binding."bindingKind"<>'INSTALLER_CONSTRUCTOR_INPUT' OR v_input_binding."expectationId" IS DISTINCT FROM v_expected."expectationId" OR v_input_binding."credentialEpoch" IS DISTINCT FROM v_expected."credentialEpoch" OR v_input_binding."launchEpoch" IS DISTINCT FROM v_expected."launchEpoch" OR v_input_binding."phase" IS DISTINCT FROM v_expected."constructorInputPhase" OR v_input_binding."expectedEventKey" IS DISTINCT FROM v_expected."eventId" OR v_claim."eventKey" IS DISTINCT FROM v_expected."eventId" OR v_claim."observerPrincipalOid" IS DISTINCT FROM v_oid OR v_claim."observerPrincipalName" IS DISTINCT FROM SESSION_USER::NAME OR
    v_slot."observerPrincipalOid" IS DISTINCT FROM v_oid OR v_slot."physicalIdentity" IS DISTINCT FROM v_domain."physicalIdentity" OR v_charge."bindingHash" IS DISTINCT FROM v_expected."chargeBindingHash" THEN RAISE EXCEPTION 'SELECTION_UNAVAILABLE'; END IF;
 RETURN pg_catalog.jsonb_build_object('inputClaimId',v_claim."inputClaimId",'reservationId',v_slot."reservationId",'eventId',v_expected."eventId",'maxInputBytes',LEAST(v_expected."maxInputBytes",v_slot."maxInputBytes")::TEXT);
EXCEPTION WHEN OTHERS THEN RAISE EXCEPTION 'SELECTION_UNAVAILABLE'; END $$;
REVOKE ALL ON FUNCTION public.pro273_control_plane_read_installer_input(TEXT) FROM PUBLIC;

-- Fixed, closed INSTALLER_ROOT context; an expectation ID selects protected
-- state, not a caller-provided parser mode, resource vector or grant.
CREATE FUNCTION public.pro273_installer_metadata_context(p_expectation_id TEXT) RETURNS JSONB
LANGUAGE plpgsql SECURITY DEFINER SET search_path=pg_catalog AS $$
DECLARE v_expected public."Pro273ControlPlaneInstallerExpectation"%ROWTYPE; v_session public."Pro273InstallerSessionClaim"%ROWTYPE;
 v_attempt public."Pro273InstallerDispatchAttempt"%ROWTYPE; v_charge public."Pro262CapacityControlCharge"%ROWTYPE;
 v_session_charge public."Pro262CapacityControlCharge"%ROWTYPE; v_input JSONB; v_now TIMESTAMPTZ;
BEGIN
 IF pg_catalog.current_setting('transaction_isolation') IS DISTINCT FROM 'read committed' THEN RAISE EXCEPTION 'SELECTION_UNAVAILABLE'; END IF;
 SELECT e.* INTO STRICT v_expected FROM public."Pro273ControlPlaneInstallerExpectation" e WHERE e."expectationId"=p_expectation_id;
 v_input:=public.pro273_control_plane_read_installer_input(v_expected."bootstrapKind");
 SELECT e.* INTO STRICT v_expected FROM public."Pro273ControlPlaneInstallerExpectation" e WHERE e."expectationId"=p_expectation_id FOR SHARE NOWAIT;
 SELECT a.* INTO STRICT v_attempt FROM public."Pro273InstallerDispatchAttempt" a WHERE (a."attemptId",a."expectationId")=(v_expected."dispatchAttemptId",v_expected."expectationId") FOR SHARE NOWAIT;
 SELECT c.* INTO STRICT v_session FROM public."Pro273InstallerSessionClaim" c WHERE (c."sessionClaimId",c."expectationId")=(v_expected."sessionClaimId",v_expected."expectationId") FOR SHARE NOWAIT;
 SELECT c.* INTO STRICT v_charge FROM public."Pro262CapacityControlCharge" c WHERE (c."kind",c."eventKey")=(v_attempt."chargeKind",v_attempt."chargeEventKey") FOR SHARE NOWAIT;
 SELECT c.* INTO STRICT v_session_charge FROM public."Pro262CapacityControlCharge" c WHERE (c."kind",c."eventKey")=(v_session."chargeKind",v_session."chargeEventKey") FOR SHARE NOWAIT;
 v_now:=pg_catalog.clock_timestamp();
 IF v_expected."validFrom">v_now OR v_expected."validUntil"<=v_now OR v_attempt."creationTransactionId"=pg_catalog.pg_current_xact_id() OR v_session."creationTransactionId"=pg_catalog.pg_current_xact_id() OR
    v_attempt."sessionClaimId" IS DISTINCT FROM v_session."sessionClaimId" OR v_attempt."inputClaimId" IS DISTINCT FROM v_input->>'inputClaimId' OR v_attempt."receiverClosureHash" IS DISTINCT FROM v_expected."receiverClosureHash" OR
    (v_session."principalOid",v_session."principalName",v_session."credentialEpoch",v_session."launchEpoch",v_session."sourceClosureHash",v_session."installationClosureHash",v_session."receiverClosureHash") IS DISTINCT FROM (v_expected."installerOid",v_expected."installerName",v_expected."credentialEpoch",v_expected."launchEpoch",v_expected."sourceClosureHash",v_expected."installationClosureHash",v_expected."receiverClosureHash") OR
    v_charge."bindingHash" IS DISTINCT FROM v_attempt."chargeBindingHash" OR v_session_charge."bindingHash" IS DISTINCT FROM v_session."chargeBindingHash" OR
    (v_attempt."chargeKind",v_attempt."chargeEventKey") IS NOT DISTINCT FROM (v_session."chargeKind",v_session."chargeEventKey") OR (v_attempt."chargeKind",v_attempt."chargeEventKey") IS NOT DISTINCT FROM (v_expected."chargeKind",v_expected."chargeEventKey") THEN RAISE EXCEPTION 'SELECTION_UNAVAILABLE'; END IF;
 RETURN pg_catalog.jsonb_build_object('schemaVersion','pro273-installer-metadata-context-v1','expectationId',v_expected."expectationId",'constructorKind',v_expected."constructorKind",'expectedTargetId',v_expected."expectedTargetId",'expectedCoreHash',v_expected."expectedCoreHash",'expectedEvidenceHash',v_expected."expectedEvidenceHash",'parserAbiVersion',v_expected."parserAbiVersion",'parserSourceClosureHash',v_expected."parserSourceClosureHash",'dispatchAttemptId',v_expected."dispatchAttemptId",'receiverClosureHash',v_expected."receiverClosureHash",'sessionClaimId',v_session."sessionClaimId",'principal',pg_catalog.jsonb_build_object('oid',v_expected."installerOid"::TEXT,'name',v_expected."installerName"::TEXT,'pid',v_expected."installerPid"::TEXT,'backendStart',pg_catalog.to_char(v_expected."installerBackendStart" AT TIME ZONE 'UTC','YYYY-MM-DD"T"HH24:MI:SS.MS"Z"'),'credentialEpoch',v_expected."credentialEpoch",'launchEpoch',v_expected."launchEpoch",'host',v_expected."host",'boot',v_expected."boot",'processTree',v_expected."processTree",'parentProcessTree',v_expected."parentProcessTree"),'physicalIdentity',v_expected."physicalIdentity",'physicalProofIdentity',v_expected."physicalProofIdentity",'sourceClosureHash',v_expected."sourceClosureHash",'installationClosureHash',v_expected."installationClosureHash",'inputClaimId',v_input->>'inputClaimId','inputReservationId',v_input->>'reservationId','eventId',v_input->>'eventId','charge',pg_catalog.jsonb_build_object('kind',v_expected."chargeKind",'eventKey',v_expected."chargeEventKey",'bindingHash',v_expected."chargeBindingHash"),'limits',pg_catalog.jsonb_build_object('maxInputBytes',v_input->>'maxInputBytes','maxDepthCapacity',v_expected."maxDepthCapacity"::TEXT,'maxTokenCapacity',v_expected."maxTokenCapacity"::TEXT,'maxDecodedUnits',v_expected."maxDecodedUnits"::TEXT,'maxParserWorkspaceBytes',v_expected."maxParserWorkspaceBytes"::TEXT,'maxDecodedEvidenceBytes',v_expected."maxDecodedEvidenceBytes"::TEXT,'maxOutputBytes',v_expected."maxOutputBytes"::TEXT),'validUntil',pg_catalog.to_char(v_expected."validUntil" AT TIME ZONE 'UTC','YYYY-MM-DD"T"HH24:MI:SS.MS"Z"'));
EXCEPTION WHEN OTHERS THEN RAISE EXCEPTION 'SELECTION_UNAVAILABLE'; END $$;
REVOKE ALL ON FUNCTION public.pro273_installer_metadata_context(TEXT) FROM PUBLIC;

-- Called in its own transaction before any captured bytes are pulled. A
-- duplicate or uncertain response is spent and cannot authorize redispatch.
CREATE FUNCTION public.pro273_installer_commit_delivery(p_expectation_id TEXT) RETURNS TEXT
LANGUAGE plpgsql SECURITY DEFINER SET search_path=pg_catalog AS $$
DECLARE v_context JSONB; v_expected public."Pro273ControlPlaneInstallerExpectation"%ROWTYPE;
 v_attempt public."Pro273InstallerDispatchAttempt"%ROWTYPE; v_session public."Pro273InstallerSessionClaim"%ROWTYPE;
 v_charge public."Pro262CapacityControlCharge"%ROWTYPE;
BEGIN
 v_context:=public.pro273_installer_metadata_context(p_expectation_id);
 SELECT e.* INTO STRICT v_expected FROM public."Pro273ControlPlaneInstallerExpectation" e WHERE e."expectationId"=p_expectation_id FOR SHARE NOWAIT;
 SELECT a.* INTO STRICT v_attempt FROM public."Pro273InstallerDispatchAttempt" a WHERE (a."attemptId",a."expectationId")=(v_expected."dispatchAttemptId",p_expectation_id) FOR SHARE NOWAIT;
 SELECT c.* INTO STRICT v_session FROM public."Pro273InstallerSessionClaim" c WHERE (c."sessionClaimId",c."expectationId")=(v_expected."sessionClaimId",p_expectation_id) FOR SHARE NOWAIT;
 SELECT c.* INTO STRICT v_charge FROM public."Pro262CapacityControlCharge" c WHERE (c."kind",c."eventKey")=(v_attempt."deliveryChargeKind",v_attempt."deliveryChargeEventKey") FOR SHARE NOWAIT;
 IF v_charge."bindingHash" IS DISTINCT FROM v_attempt."deliveryChargeBindingHash" OR (v_attempt."deliveryChargeKind",v_attempt."deliveryChargeEventKey") IS NOT DISTINCT FROM (v_expected."chargeKind",v_expected."chargeEventKey") OR (v_attempt."deliveryChargeKind",v_attempt."deliveryChargeEventKey") IS NOT DISTINCT FROM (v_session."chargeKind",v_session."chargeEventKey") OR EXISTS(SELECT 1 FROM public."Pro273InstallerDelivery" d WHERE d."attemptId"=v_attempt."attemptId" OR d."expectationId"=p_expectation_id OR d."inputClaimId"=v_attempt."inputClaimId") THEN RAISE EXCEPTION 'SELECTION_UNAVAILABLE'; END IF;
 INSERT INTO public."Pro273InstallerDelivery"("attemptId","expectationId","sessionClaimId","inputClaimId","eventId","receiverClosureHash","chargeKind","chargeEventKey","chargeBindingHash","creationTransactionId","createdAt") VALUES(v_attempt."attemptId",p_expectation_id,v_attempt."sessionClaimId",v_attempt."inputClaimId",v_context->>'eventId',v_attempt."receiverClosureHash",v_charge."kind",v_charge."eventKey",v_charge."bindingHash",pg_catalog.pg_current_xact_id(),pg_catalog.clock_timestamp());
 RETURN v_attempt."attemptId";
EXCEPTION WHEN OTHERS THEN RAISE EXCEPTION 'SELECTION_UNAVAILABLE'; END $$;
REVOKE ALL ON FUNCTION public.pro273_installer_commit_delivery(TEXT) FROM PUBLIC;

CREATE FUNCTION public.pro273_installer_assert_committed_delivery(p_expectation_id TEXT) RETURNS VOID
LANGUAGE plpgsql SECURITY DEFINER SET search_path=pg_catalog AS $$
DECLARE v_context JSONB; v_delivery public."Pro273InstallerDelivery"%ROWTYPE; v_charge public."Pro262CapacityControlCharge"%ROWTYPE;
BEGIN
 v_context:=public.pro273_installer_metadata_context(p_expectation_id);
 SELECT d.* INTO STRICT v_delivery FROM public."Pro273InstallerDelivery" d WHERE d."expectationId"=p_expectation_id FOR SHARE NOWAIT;
 SELECT c.* INTO STRICT v_charge FROM public."Pro262CapacityControlCharge" c WHERE (c."kind",c."eventKey")=(v_delivery."chargeKind",v_delivery."chargeEventKey") FOR SHARE NOWAIT;
 IF v_delivery."creationTransactionId"=pg_catalog.pg_current_xact_id() OR v_delivery."attemptId" IS DISTINCT FROM v_context->>'dispatchAttemptId' OR v_delivery."sessionClaimId" IS DISTINCT FROM v_context->>'sessionClaimId' OR v_delivery."inputClaimId" IS DISTINCT FROM v_context->>'inputClaimId' OR v_delivery."eventId" IS DISTINCT FROM v_context->>'eventId' OR v_delivery."receiverClosureHash" IS DISTINCT FROM v_context->>'receiverClosureHash' OR v_delivery."chargeBindingHash" IS DISTINCT FROM v_charge."bindingHash" THEN RAISE EXCEPTION 'SELECTION_UNAVAILABLE'; END IF;
END $$;
REVOKE ALL ON FUNCTION public.pro273_installer_assert_committed_delivery(TEXT) FROM PUBLIC;

-- Receipt must be read in a fresh transaction after the delivery commit.
-- It is a correlation frame, not permission to dispatch a second time.
CREATE FUNCTION public.pro273_installer_delivery_receipt(p_expectation_id TEXT) RETURNS JSONB
LANGUAGE plpgsql SECURITY DEFINER SET search_path=pg_catalog AS $$
DECLARE v_context JSONB; v_delivery public."Pro273InstallerDelivery"%ROWTYPE;
BEGIN
 PERFORM public.pro273_installer_assert_committed_delivery(p_expectation_id);
 v_context:=public.pro273_installer_metadata_context(p_expectation_id);
 SELECT d.* INTO STRICT v_delivery FROM public."Pro273InstallerDelivery" d WHERE d."expectationId"=p_expectation_id FOR SHARE NOWAIT;
 IF v_delivery."creationTransactionId"=pg_catalog.pg_current_xact_id() OR v_delivery."attemptId" IS DISTINCT FROM v_context->>'dispatchAttemptId' OR v_delivery."sessionClaimId" IS DISTINCT FROM v_context->>'sessionClaimId' OR v_delivery."inputClaimId" IS DISTINCT FROM v_context->>'inputClaimId' OR v_delivery."eventId" IS DISTINCT FROM v_context->>'eventId' THEN RAISE EXCEPTION 'SELECTION_UNAVAILABLE'; END IF;
 RETURN pg_catalog.jsonb_build_object('schemaVersion','pro273-installer-receipt-v1','phase','DELIVERY_COMMITTED','expectationId',p_expectation_id,'attemptId',v_delivery."attemptId",'sessionClaimId',v_delivery."sessionClaimId",'inputClaimId',v_delivery."inputClaimId",'eventId',v_delivery."eventId",'creationTransactionId',v_delivery."creationTransactionId"::TEXT);
EXCEPTION WHEN OTHERS THEN RAISE EXCEPTION 'SELECTION_UNAVAILABLE'; END $$;
REVOKE ALL ON FUNCTION public.pro273_installer_delivery_receipt(TEXT) FROM PUBLIC;

-- Allocation-free fatal UTF-8 scan for the independently funded installer
-- metadata parser. This checks source bytes before conversion or copying; it
-- does not itself grant parser capacity or accept a JSON document.
CREATE FUNCTION public.pro273_installer_utf8_valid(p_bytes BYTEA,p_maximum NUMERIC) RETURNS BOOLEAN
LANGUAGE plpgsql IMMUTABLE SET search_path=pg_catalog AS $$
DECLARE v_n INTEGER; v_i INTEGER:=0; v_a INTEGER; v_b INTEGER; v_c INTEGER; v_d INTEGER;
BEGIN
 IF p_bytes IS NULL OR p_maximum IS NULL OR p_maximum<=0 OR p_maximum<>pg_catalog.trunc(p_maximum) OR p_maximum::TEXT IN ('NaN','Infinity','-Infinity') THEN RETURN FALSE; END IF;
 v_n:=pg_catalog.octet_length(p_bytes); IF v_n=0 OR v_n::NUMERIC>p_maximum THEN RETURN FALSE; END IF;
 WHILE v_i<v_n LOOP
  v_a:=pg_catalog.get_byte(p_bytes,v_i);
  IF v_a<128 THEN v_i:=v_i+1;
  ELSIF v_a BETWEEN 194 AND 223 THEN
   IF v_i+1>=v_n THEN RETURN FALSE; END IF;v_b:=pg_catalog.get_byte(p_bytes,v_i+1);
   IF v_b NOT BETWEEN 128 AND 191 THEN RETURN FALSE; END IF;v_i:=v_i+2;
  ELSIF v_a BETWEEN 224 AND 239 THEN
   IF v_i+2>=v_n THEN RETURN FALSE; END IF;v_b:=pg_catalog.get_byte(p_bytes,v_i+1);v_c:=pg_catalog.get_byte(p_bytes,v_i+2);
   IF v_b NOT BETWEEN 128 AND 191 OR v_c NOT BETWEEN 128 AND 191 OR (v_a=224 AND v_b<160) OR (v_a=237 AND v_b>=160) THEN RETURN FALSE; END IF;v_i:=v_i+3;
  ELSIF v_a BETWEEN 240 AND 244 THEN
   IF v_i+3>=v_n THEN RETURN FALSE; END IF;v_b:=pg_catalog.get_byte(p_bytes,v_i+1);v_c:=pg_catalog.get_byte(p_bytes,v_i+2);v_d:=pg_catalog.get_byte(p_bytes,v_i+3);
   IF v_b NOT BETWEEN 128 AND 191 OR v_c NOT BETWEEN 128 AND 191 OR v_d NOT BETWEEN 128 AND 191 OR (v_a=240 AND v_b<144) OR (v_a=244 AND v_b>=144) THEN RETURN FALSE; END IF;v_i:=v_i+4;
  ELSE RETURN FALSE; END IF;
 END LOOP;
 RETURN TRUE;
EXCEPTION WHEN OTHERS THEN RETURN FALSE; END $$;
REVOKE ALL ON FUNCTION public.pro273_installer_utf8_valid(BYTEA,NUMERIC) FROM PUBLIC;

-- Installer-only metadata grammar. No token table, catalog writes, native
-- primitive or JSONB conversion is performed by this syntax guard.
CREATE FUNCTION public.pro273_installer_metadata_grammar(p_expectation_id TEXT,p_captured BYTEA) RETURNS VOID
LANGUAGE plpgsql SECURITY DEFINER SET search_path=pg_catalog AS $$
DECLARE v_context JSONB; v_limits JSONB; v_key TEXT; v_len INTEGER; v_pos INTEGER:=0; v_end INTEGER; v_ch INTEGER;
 v_depth INTEGER:=0; v_token_count BIGINT:=0; v_root BOOLEAN:=FALSE;
 v_types INTEGER[]:=ARRAY[]::INTEGER[]; v_states INTEGER[]:=ARRAY[]::INTEGER[]; v_ordinals BIGINT[]:=ARRAY[]::BIGINT[];
 v_workspace NUMERIC; v_needed NUMERIC;
BEGIN
 IF p_expectation_id IS NULL OR p_captured IS NULL THEN RAISE EXCEPTION 'SELECTION_UNAVAILABLE'; END IF;
 PERFORM public.pro273_installer_assert_committed_delivery(p_expectation_id);
 v_context:=public.pro273_installer_metadata_context(p_expectation_id);v_limits:=v_context->'limits';
 IF pg_catalog.jsonb_typeof(v_limits) IS DISTINCT FROM 'object' OR (SELECT pg_catalog.count(*) FROM pg_catalog.jsonb_object_keys(v_limits))<>7 OR NOT (v_limits ?& ARRAY['maxInputBytes','maxDepthCapacity','maxTokenCapacity','maxDecodedUnits','maxParserWorkspaceBytes','maxDecodedEvidenceBytes','maxOutputBytes']) THEN RAISE EXCEPTION 'SELECTION_UNAVAILABLE'; END IF;
 FOREACH v_key IN ARRAY ARRAY['maxInputBytes','maxDepthCapacity','maxTokenCapacity','maxDecodedUnits','maxParserWorkspaceBytes','maxDecodedEvidenceBytes','maxOutputBytes'] LOOP
  IF pg_catalog.jsonb_typeof(v_limits->v_key) IS DISTINCT FROM 'string' OR COALESCE(v_limits->>v_key,'') !~ '^[1-9][0-9]{0,18}$' OR (v_limits->>v_key)::NUMERIC>9223372036854775807 THEN RAISE EXCEPTION 'SELECTION_UNAVAILABLE'; END IF;
 END LOOP;
 v_len:=pg_catalog.octet_length(p_captured);v_workspace:=(v_limits->>'maxParserWorkspaceBytes')::NUMERIC;
 -- Reserve for the three stack arrays and simultaneous old/new array values
 -- during growth, using actual fixed one-element array representations. The
 -- independently qualified holder also covers PL/pgSQL and parser overhead.
 v_needed:=2::NUMERIC*(v_len::NUMERIC*(2::NUMERIC*pg_catalog.pg_column_size(ARRAY[0::INTEGER])+pg_catalog.pg_column_size(ARRAY[0::BIGINT]))+2::NUMERIC*pg_catalog.pg_column_size(ARRAY[]::INTEGER[])+pg_catalog.pg_column_size(ARRAY[]::BIGINT[]));
 IF v_len=0 OR v_len::NUMERIC>(v_limits->>'maxInputBytes')::NUMERIC OR v_len::NUMERIC>(v_limits->>'maxDepthCapacity')::NUMERIC OR v_len::NUMERIC>(v_limits->>'maxTokenCapacity')::NUMERIC OR v_len::NUMERIC>(v_limits->>'maxDecodedUnits')::NUMERIC OR v_needed>v_workspace OR public.pro273_installer_utf8_valid(p_captured,(v_limits->>'maxInputBytes')::NUMERIC) IS DISTINCT FROM TRUE THEN RAISE EXCEPTION 'SELECTION_UNAVAILABLE'; END IF;
 IF CASE WHEN v_len>=3 THEN pg_catalog.get_byte(p_captured,0)=239 AND pg_catalog.get_byte(p_captured,1)=187 AND pg_catalog.get_byte(p_captured,2)=191 ELSE FALSE END THEN v_pos:=3; END IF;
 LOOP
  WHILE CASE WHEN v_pos<v_len THEN pg_catalog.get_byte(p_captured,v_pos) IN (9,10,13,32) ELSE FALSE END LOOP v_pos:=v_pos+1; END LOOP;
  IF v_depth=0 AND v_root THEN IF v_pos<>v_len THEN RAISE EXCEPTION 'SELECTION_UNAVAILABLE'; END IF; RETURN; END IF;
  IF v_pos>=v_len THEN RAISE EXCEPTION 'SELECTION_UNAVAILABLE'; END IF;
  v_ch:=pg_catalog.get_byte(p_captured,v_pos);
  IF v_depth>0 AND v_types[v_depth]=1 THEN
   IF v_states[v_depth] IN (0,4) THEN
    IF v_ch=125 AND v_states[v_depth]=0 THEN v_pos:=v_pos+1;v_depth:=v_depth-1;CONTINUE; END IF;
    IF v_ch<>34 OR v_token_count+1>(v_limits->>'maxTokenCapacity')::NUMERIC THEN RAISE EXCEPTION 'SELECTION_UNAVAILABLE'; END IF;
    v_end:=public.pro273_sel_scan_string_end(p_captured,v_pos,v_len);v_token_count:=v_token_count+1;v_pos:=v_end;v_states[v_depth]:=1;CONTINUE;
   ELSIF v_states[v_depth]=1 THEN
    IF v_ch<>58 THEN RAISE EXCEPTION 'SELECTION_UNAVAILABLE'; END IF;v_pos:=v_pos+1;v_states[v_depth]:=2;CONTINUE;
   ELSIF v_states[v_depth]=3 THEN
    IF v_ch=125 THEN v_pos:=v_pos+1;v_depth:=v_depth-1;CONTINUE;
    ELSIF v_ch=44 THEN v_pos:=v_pos+1;v_states[v_depth]:=4;CONTINUE;
    ELSE RAISE EXCEPTION 'SELECTION_UNAVAILABLE'; END IF;
   END IF;
  ELSIF v_depth>0 AND v_types[v_depth]=2 THEN
   IF v_states[v_depth]=0 AND v_ch=93 THEN v_pos:=v_pos+1;v_depth:=v_depth-1;CONTINUE; END IF;
   IF v_states[v_depth]=3 THEN
    IF v_ch=93 THEN v_pos:=v_pos+1;v_depth:=v_depth-1;CONTINUE;
    ELSIF v_ch=44 THEN v_pos:=v_pos+1;v_states[v_depth]:=4;CONTINUE;
    ELSE RAISE EXCEPTION 'SELECTION_UNAVAILABLE'; END IF;
   END IF;
  END IF;
  IF v_depth=0 THEN v_root:=TRUE;
  ELSE v_states[v_depth]:=3;v_ordinals[v_depth]:=v_ordinals[v_depth]+1; END IF;
  IF v_token_count+1>(v_limits->>'maxTokenCapacity')::NUMERIC THEN RAISE EXCEPTION 'SELECTION_UNAVAILABLE'; END IF;v_token_count:=v_token_count+1;
  IF v_ch IN (123,91) THEN
   IF (v_depth+1)::NUMERIC>(v_limits->>'maxDepthCapacity')::NUMERIC THEN RAISE EXCEPTION 'SELECTION_UNAVAILABLE'; END IF;
   v_pos:=v_pos+1;v_depth:=v_depth+1;v_types[v_depth]:=CASE WHEN v_ch=123 THEN 1 ELSE 2 END;v_states[v_depth]:=0;v_ordinals[v_depth]:=0;CONTINUE;
  ELSIF v_ch=34 THEN v_pos:=public.pro273_sel_scan_string_end(p_captured,v_pos,v_len);
  ELSIF v_ch=116 AND pg_catalog.substring(p_captured,v_pos+1,4)=pg_catalog.convert_to('true','UTF8') THEN v_pos:=v_pos+4;
  ELSIF v_ch=102 AND pg_catalog.substring(p_captured,v_pos+1,5)=pg_catalog.convert_to('false','UTF8') THEN v_pos:=v_pos+5;
  ELSIF v_ch=110 AND pg_catalog.substring(p_captured,v_pos+1,4)=pg_catalog.convert_to('null','UTF8') THEN v_pos:=v_pos+4;
  ELSE RAISE EXCEPTION 'SELECTION_UNAVAILABLE'; END IF;
 END LOOP;
EXCEPTION WHEN OTHERS THEN RAISE EXCEPTION 'SELECTION_UNAVAILABLE'; END $$;
REVOKE ALL ON FUNCTION public.pro273_installer_metadata_grammar(TEXT,BYTEA) FROM PUBLIC;

-- Private data-only stage; it grants no authority and is not a complete parser.
-- Decoded-key, closed-shape, canonical and independently qualified peak checks
-- remain mandatory before any INITIAL publication can be enabled.
CREATE TYPE public.pro273_initial_parser_limits AS (
 "maxInputBytes" NUMERIC, "maxDepthCapacity" NUMERIC, "maxTokenCapacity" NUMERIC,
 "maxDecodedUnits" NUMERIC, "maxParserWorkspaceBytes" NUMERIC, "maxSerializationBytes" NUMERIC,
 "maxAllocationBytes" NUMERIC, "maxDecodedEvidenceBytes" NUMERIC, "maxOutputBytes" NUMERIC, "stackBytes" NUMERIC
);
REVOKE ALL ON TYPE public.pro273_initial_parser_limits FROM PUBLIC;
-- Allocation-free INITIAL scalar guard. The caller's grammar supplies each
-- string span; this function does not produce text or grant parser authority.
CREATE FUNCTION public.pro273_initial_string_scalars(p_body BYTEA,p_start INTEGER,p_end INTEGER) RETURNS VOID
LANGUAGE plpgsql SET search_path=pg_catalog AS $$
DECLARE v_len INTEGER; v_pos INTEGER; v_ch INTEGER; v_escape INTEGER; v_code INTEGER; v_digit INTEGER; v_i INTEGER; v_high BOOLEAN:=FALSE;
BEGIN
 IF p_body IS NULL OR p_start IS NULL OR p_end IS NULL THEN RAISE EXCEPTION 'SELECTION_UNAVAILABLE'; END IF;
 v_len:=pg_catalog.octet_length(p_body);
 -- Leave headroom for every integer position increment and lookahead.
