-- The caller must independently qualify simultaneous allocation, runtime and stack costs.
CREATE FUNCTION public.pro273_initial_string_units(p_limits public.pro273_initial_parser_limits,p_body BYTEA,p_start INTEGER,p_end INTEGER) RETURNS BYTEA
LANGUAGE plpgsql SET search_path=pg_catalog AS $initial_units$
DECLARE v_bound NUMERIC; v_len INTEGER; v_pass INTEGER; v_pos INTEGER; v_byte INTEGER; v_next INTEGER; v_code INTEGER; v_count INTEGER; v_i INTEGER; v_digit INTEGER;
