 FOREACH v_bound IN ARRAY ARRAY[p_limits."maxInputBytes",p_limits."maxDecodedUnits",p_limits."maxParserWorkspaceBytes",p_limits."maxAllocationBytes",p_limits."maxOutputBytes"] LOOP
  IF v_bound IS NULL OR v_bound<=0 OR v_bound<>pg_catalog.trunc(v_bound) OR v_bound::TEXT IN ('NaN','Infinity','-Infinity') OR v_bound>9223372036854775807 THEN RAISE EXCEPTION 'SELECTION_UNAVAILABLE'; END IF;
