CREATE FUNCTION public.pro273_initial_data_grammar(p_limits public.pro273_initial_parser_limits,p_captured BYTEA) RETURNS VOID
LANGUAGE plpgsql SET search_path=pg_catalog AS $$
DECLARE v_bound NUMERIC; v_len INTEGER; v_pos INTEGER:=0; v_end INTEGER; v_ch INTEGER;
 v_depth INTEGER:=0; v_token_count BIGINT:=0; v_root BOOLEAN:=FALSE;
 v_types INTEGER[]:=ARRAY[]::INTEGER[]; v_states INTEGER[]:=ARRAY[]::INTEGER[]; v_ordinals BIGINT[]:=ARRAY[]::BIGINT[];
 v_workspace NUMERIC; v_needed NUMERIC;
BEGIN
 IF p_limits IS NULL OR p_captured IS NULL THEN RAISE EXCEPTION 'SELECTION_UNAVAILABLE'; END IF;
 FOREACH v_bound IN ARRAY ARRAY[p_limits."maxInputBytes",p_limits."maxDepthCapacity",p_limits."maxTokenCapacity",p_limits."maxDecodedUnits",p_limits."maxParserWorkspaceBytes",p_limits."maxSerializationBytes",p_limits."maxAllocationBytes",p_limits."maxDecodedEvidenceBytes",p_limits."maxOutputBytes",p_limits."stackBytes"] LOOP
  IF v_bound IS NULL OR v_bound<=0 OR v_bound::TEXT IN ('NaN','Infinity','-Infinity') OR v_bound<>pg_catalog.trunc(v_bound) OR v_bound>9223372036854775807 THEN RAISE EXCEPTION 'SELECTION_UNAVAILABLE'; END IF;
 END LOOP;
