  IF v_token_count+1>p_limits."maxTokenCapacity" THEN RAISE EXCEPTION 'SELECTION_UNAVAILABLE'; END IF;v_token_count:=v_token_count+1;
  IF v_ch IN (123,91) THEN
   IF (v_depth+1)::NUMERIC>p_limits."maxDepthCapacity" THEN RAISE EXCEPTION 'SELECTION_UNAVAILABLE'; END IF;
