  ELSIF v_ch=34 THEN v_end:=public.pro273_sel_scan_string_end(p_captured,v_pos,v_len);PERFORM public.pro273_initial_string_scalars(p_captured,v_pos,v_end);v_pos:=v_end;
  ELSE RAISE EXCEPTION 'SELECTION_UNAVAILABLE'; END IF;
 END LOOP;
EXCEPTION WHEN OTHERS THEN RAISE EXCEPTION 'SELECTION_UNAVAILABLE'; END $$;
REVOKE ALL ON FUNCTION public.pro273_initial_data_grammar(public.pro273_initial_parser_limits,BYTEA) FROM PUBLIC;

-- Source-only prototype. Its discriminator is data, not authenticated authority.
-- The first statement denies unconditionally: raw/detoast representations,
-- allocation overhead, interpreter peak, work and serialization have not been
-- independently qualified. Do not remove the denial on structural estimates.
-- Tokens are object starts, keys and string values: success is exactly 2K+5.
-- At most K+2 keys are attempted; the final failing key scan, escape/scalar
-- passes and trie transitions also require an independently qualified fixed
-- multiple of B work budget, including malformed and overlong inputs. No memory
-- bound implies a work bound. Later schemaVersion, semantic, canonical, hash,
-- time and nonempty padded-base64 evidence checks remain mandatory.
CREATE TYPE public.pro273_initial_spans AS (core_start INTEGER,core_end INTEGER,evidence_start INTEGER,evidence_end INTEGER);
REVOKE ALL ON TYPE public.pro273_initial_spans FROM PUBLIC;
CREATE FUNCTION public.pro273_initial_schema_grammar(p_limits public.pro273_initial_parser_limits,p_captured BYTEA,p_schema INTEGER) RETURNS public.pro273_initial_spans
LANGUAGE plpgsql SET search_path=pg_catalog AS $initial_schema$
DECLARE v_len INTEGER; v_pos INTEGER:=0; v_end INTEGER; v_ord INTEGER; v_key INTEGER;
 v_k INTEGER; v_root INTEGER:=0; v_core BIGINT:=0; v_full BIGINT; v_bit BIGINT;
 v_core_start INTEGER; v_core_end INTEGER; v_evidence_start INTEGER; v_evidence_end INTEGER;
 v_bound NUMERIC; v_tokens INTEGER:=1; v_members INTEGER;
BEGIN
 RAISE EXCEPTION 'SELECTION_UNAVAILABLE'; -- unconditional missing independent resource proof
 IF p_limits IS NULL OR p_captured IS NULL OR p_schema IS NULL OR p_schema NOT IN (1,2) THEN RAISE EXCEPTION 'SELECTION_UNAVAILABLE'; END IF;
 FOREACH v_bound IN ARRAY ARRAY[p_limits."maxInputBytes",p_limits."maxDepthCapacity",p_limits."maxTokenCapacity",p_limits."maxDecodedUnits",p_limits."maxParserWorkspaceBytes",p_limits."maxSerializationBytes",p_limits."maxAllocationBytes",p_limits."maxDecodedEvidenceBytes",p_limits."maxOutputBytes",p_limits."stackBytes"] LOOP
  IF v_bound IS NULL OR v_bound<=0 OR v_bound::TEXT IN ('NaN','Infinity','-Infinity') OR v_bound<>pg_catalog.trunc(v_bound) OR v_bound>9223372036854775807 THEN RAISE EXCEPTION 'SELECTION_UNAVAILABLE'; END IF;
 END LOOP;
 v_len:=pg_catalog.octet_length(p_captured);v_k:=CASE p_schema WHEN 1 THEN 15 ELSE 55 END;
 IF v_len=0 OR v_len>2147483640 OR v_len::NUMERIC>p_limits."maxInputBytes" OR v_len::NUMERIC>p_limits."maxDecodedUnits" OR p_limits."maxDepthCapacity"<2 OR p_limits."maxTokenCapacity"<2*v_k+5 OR public.pro273_installer_utf8_valid(p_captured,p_limits."maxInputBytes") IS DISTINCT FROM TRUE THEN RAISE EXCEPTION 'SELECTION_UNAVAILABLE'; END IF;
 v_full:=(1::BIGINT << v_k)-1;
 WHILE CASE WHEN v_pos<v_len THEN pg_catalog.get_byte(p_captured,v_pos) IN (9,10,13,32) ELSE FALSE END LOOP v_pos:=v_pos+1; END LOOP;
 IF v_pos>=v_len OR pg_catalog.get_byte(p_captured,v_pos)<>123 THEN RAISE EXCEPTION 'SELECTION_UNAVAILABLE'; END IF;v_pos:=v_pos+1;
 FOR v_members IN 1..2 LOOP
  WHILE CASE WHEN v_pos<v_len THEN pg_catalog.get_byte(p_captured,v_pos) IN (9,10,13,32) ELSE FALSE END LOOP v_pos:=v_pos+1; END LOOP;
  IF v_pos>=v_len OR pg_catalog.get_byte(p_captured,v_pos)<>34 THEN RAISE EXCEPTION 'SELECTION_UNAVAILABLE'; END IF;
  v_end:=public.pro273_sel_scan_string_end(p_captured,v_pos,v_len);v_ord:=public.pro273_initial_key_ordinal(p_captured,v_pos,v_end,0);
  IF v_ord<0 OR v_ord>=2 THEN RAISE EXCEPTION 'SELECTION_UNAVAILABLE'; END IF;
  v_key:=1 << v_ord;IF (v_root & v_key)<>0 THEN RAISE EXCEPTION 'SELECTION_UNAVAILABLE'; END IF;v_root:=v_root | v_key;v_tokens:=v_tokens+1;v_pos:=v_end;
  WHILE CASE WHEN v_pos<v_len THEN pg_catalog.get_byte(p_captured,v_pos) IN (9,10,13,32) ELSE FALSE END LOOP v_pos:=v_pos+1; END LOOP;
  IF v_pos>=v_len OR pg_catalog.get_byte(p_captured,v_pos)<>58 THEN RAISE EXCEPTION 'SELECTION_UNAVAILABLE'; END IF;v_pos:=v_pos+1;
  WHILE CASE WHEN v_pos<v_len THEN pg_catalog.get_byte(p_captured,v_pos) IN (9,10,13,32) ELSE FALSE END LOOP v_pos:=v_pos+1; END LOOP;
  IF v_pos>=v_len THEN RAISE EXCEPTION 'SELECTION_UNAVAILABLE'; END IF;
  IF v_ord=0 THEN
   IF pg_catalog.get_byte(p_captured,v_pos)<>123 THEN RAISE EXCEPTION 'SELECTION_UNAVAILABLE'; END IF;
   v_core_start:=v_pos;v_pos:=v_pos+1;v_tokens:=v_tokens+1;
   FOR v_key IN 1..v_k LOOP
    WHILE CASE WHEN v_pos<v_len THEN pg_catalog.get_byte(p_captured,v_pos) IN (9,10,13,32) ELSE FALSE END LOOP v_pos:=v_pos+1; END LOOP;
    IF v_pos>=v_len OR pg_catalog.get_byte(p_captured,v_pos)<>34 THEN RAISE EXCEPTION 'SELECTION_UNAVAILABLE'; END IF;
    v_end:=public.pro273_sel_scan_string_end(p_captured,v_pos,v_len);v_ord:=public.pro273_initial_key_ordinal(p_captured,v_pos,v_end,p_schema);
    IF v_ord<0 OR v_ord>=v_k THEN RAISE EXCEPTION 'SELECTION_UNAVAILABLE'; END IF;
    v_bit:=1::BIGINT << v_ord;IF (v_core & v_bit)<>0 THEN RAISE EXCEPTION 'SELECTION_UNAVAILABLE'; END IF;v_core:=v_core | v_bit;v_tokens:=v_tokens+1;v_pos:=v_end;
    WHILE CASE WHEN v_pos<v_len THEN pg_catalog.get_byte(p_captured,v_pos) IN (9,10,13,32) ELSE FALSE END LOOP v_pos:=v_pos+1; END LOOP;
    IF v_pos>=v_len OR pg_catalog.get_byte(p_captured,v_pos)<>58 THEN RAISE EXCEPTION 'SELECTION_UNAVAILABLE'; END IF;v_pos:=v_pos+1;
    WHILE CASE WHEN v_pos<v_len THEN pg_catalog.get_byte(p_captured,v_pos) IN (9,10,13,32) ELSE FALSE END LOOP v_pos:=v_pos+1; END LOOP;
    IF v_pos>=v_len OR pg_catalog.get_byte(p_captured,v_pos)<>34 THEN RAISE EXCEPTION 'SELECTION_UNAVAILABLE'; END IF;
    v_end:=public.pro273_sel_scan_string_end(p_captured,v_pos,v_len);PERFORM public.pro273_initial_string_scalars(p_captured,v_pos,v_end);v_tokens:=v_tokens+1;v_pos:=v_end;
    WHILE CASE WHEN v_pos<v_len THEN pg_catalog.get_byte(p_captured,v_pos) IN (9,10,13,32) ELSE FALSE END LOOP v_pos:=v_pos+1; END LOOP;
    IF v_pos>=v_len THEN RAISE EXCEPTION 'SELECTION_UNAVAILABLE'; END IF;
    IF v_key<v_k THEN IF pg_catalog.get_byte(p_captured,v_pos)<>44 THEN RAISE EXCEPTION 'SELECTION_UNAVAILABLE'; END IF;v_pos:=v_pos+1;
    ELSE IF v_core<>v_full OR pg_catalog.get_byte(p_captured,v_pos)<>125 THEN RAISE EXCEPTION 'SELECTION_UNAVAILABLE'; END IF;v_pos:=v_pos+1;v_core_end:=v_pos; END IF;
   END LOOP;
  ELSE
   IF pg_catalog.get_byte(p_captured,v_pos)<>34 THEN RAISE EXCEPTION 'SELECTION_UNAVAILABLE'; END IF;
   v_evidence_start:=v_pos;v_end:=public.pro273_sel_scan_string_end(p_captured,v_pos,v_len);PERFORM public.pro273_initial_string_scalars(p_captured,v_pos,v_end);v_tokens:=v_tokens+1;v_pos:=v_end;v_evidence_end:=v_pos;
  END IF;
  WHILE CASE WHEN v_pos<v_len THEN pg_catalog.get_byte(p_captured,v_pos) IN (9,10,13,32) ELSE FALSE END LOOP v_pos:=v_pos+1; END LOOP;
  IF v_pos>=v_len THEN RAISE EXCEPTION 'SELECTION_UNAVAILABLE'; END IF;
  IF v_members=1 THEN IF pg_catalog.get_byte(p_captured,v_pos)<>44 THEN RAISE EXCEPTION 'SELECTION_UNAVAILABLE'; END IF;v_pos:=v_pos+1;
  ELSE IF v_root<>3 OR pg_catalog.get_byte(p_captured,v_pos)<>125 THEN RAISE EXCEPTION 'SELECTION_UNAVAILABLE'; END IF;v_pos:=v_pos+1; END IF;
 END LOOP;
 WHILE CASE WHEN v_pos<v_len THEN pg_catalog.get_byte(p_captured,v_pos) IN (9,10,13,32) ELSE FALSE END LOOP v_pos:=v_pos+1; END LOOP;
 IF v_pos<>v_len OR v_tokens<>2*v_k+5 THEN RAISE EXCEPTION 'SELECTION_UNAVAILABLE'; END IF;
 RETURN ROW(v_core_start,v_core_end,v_evidence_start,v_evidence_end)::public.pro273_initial_spans;
EXCEPTION WHEN OTHERS THEN RAISE EXCEPTION 'SELECTION_UNAVAILABLE'; END $initial_schema$;
REVOKE ALL ON FUNCTION public.pro273_initial_schema_grammar(public.pro273_initial_parser_limits,BYTEA,INTEGER) FROM PUBLIC;


-- Decode one validated raw string span into UTF16BE units. No SQL TEXT,
-- JSONB, normalization, locale operation or ordinary token arena is used.
CREATE FUNCTION public.pro273_installer_metadata_string_units(p_expectation_id TEXT,p_body BYTEA,p_start INTEGER,p_end INTEGER) RETURNS BYTEA
LANGUAGE plpgsql SECURITY DEFINER SET search_path=pg_catalog AS $$
DECLARE v_context JSONB; v_limits JSONB; v_key TEXT; v_len INTEGER; v_pass INTEGER; v_pos INTEGER; v_byte INTEGER; v_next INTEGER; v_code INTEGER; v_count INTEGER; v_i INTEGER; v_digit INTEGER;
 v_units INTEGER:=0; v_written INTEGER; v_high INTEGER; v_low INTEGER; v_result BYTEA; v_required NUMERIC; v_workspace NUMERIC; v_unit_limit NUMERIC; v_output_limit NUMERIC;
BEGIN
 IF p_expectation_id IS NULL OR p_body IS NULL OR p_start IS NULL OR p_end IS NULL THEN RAISE EXCEPTION 'SELECTION_UNAVAILABLE'; END IF;
 PERFORM public.pro273_installer_assert_committed_delivery(p_expectation_id);
 v_context:=public.pro273_installer_metadata_context(p_expectation_id);v_limits:=v_context->'limits';
 IF pg_catalog.jsonb_typeof(v_limits) IS DISTINCT FROM 'object' OR (SELECT pg_catalog.count(*) FROM pg_catalog.jsonb_object_keys(v_limits))<>7 OR NOT (v_limits ?& ARRAY['maxInputBytes','maxDepthCapacity','maxTokenCapacity','maxDecodedUnits','maxParserWorkspaceBytes','maxDecodedEvidenceBytes','maxOutputBytes']) THEN RAISE EXCEPTION 'SELECTION_UNAVAILABLE'; END IF;
 FOREACH v_key IN ARRAY ARRAY['maxInputBytes','maxDepthCapacity','maxTokenCapacity','maxDecodedUnits','maxParserWorkspaceBytes','maxDecodedEvidenceBytes','maxOutputBytes'] LOOP
  IF pg_catalog.jsonb_typeof(v_limits->v_key) IS DISTINCT FROM 'string' OR COALESCE(v_limits->>v_key,'') !~ '^[1-9][0-9]{0,18}$' OR (v_limits->>v_key)::NUMERIC>9223372036854775807 THEN RAISE EXCEPTION 'SELECTION_UNAVAILABLE'; END IF;
 END LOOP;
 v_len:=pg_catalog.octet_length(p_body);v_workspace:=(v_limits->>'maxParserWorkspaceBytes')::NUMERIC;v_unit_limit:=(v_limits->>'maxDecodedUnits')::NUMERIC;v_output_limit:=(v_limits->>'maxOutputBytes')::NUMERIC;
 IF v_len=0 OR v_len::NUMERIC>(v_limits->>'maxInputBytes')::NUMERIC OR v_len::NUMERIC>v_unit_limit OR p_start<0 OR p_end<=p_start OR p_end>v_len OR p_end-p_start<2 OR public.pro273_installer_utf8_valid(p_body,(v_limits->>'maxInputBytes')::NUMERIC) IS DISTINCT FROM TRUE THEN RAISE EXCEPTION 'SELECTION_UNAVAILABLE'; END IF;
 IF public.pro273_sel_scan_string_end(p_body,p_start,v_len) IS DISTINCT FROM p_end THEN RAISE EXCEPTION 'SELECTION_UNAVAILABLE'; END IF;
 -- The first pass counts decoded UTF16 units without building output. Before
 -- each output unit, reserve the bounded retained input and possible hex,
 -- bytea/set_byte old-and-new values, and output copies. The independently
 -- qualified root holder also covers surrounding parser/stack/runtime costs.
 FOR v_pass IN 1..2 LOOP
  v_pos:=p_start+1;v_written:=0;
  WHILE v_pos<p_end-1 LOOP
   v_byte:=pg_catalog.get_byte(p_body,v_pos);
   IF v_byte=92 THEN
    v_pos:=v_pos+1;IF v_pos>=p_end-1 THEN RAISE EXCEPTION 'SELECTION_UNAVAILABLE'; END IF;v_next:=pg_catalog.get_byte(p_body,v_pos);
    IF v_next=117 THEN
     IF v_pos+4>=p_end-1 THEN RAISE EXCEPTION 'SELECTION_UNAVAILABLE'; END IF;v_code:=0;
     FOR v_i IN 1..4 LOOP
      v_digit:=pg_catalog.get_byte(p_body,v_pos+v_i);
      IF v_digit BETWEEN 48 AND 57 THEN v_digit:=v_digit-48; ELSIF v_digit BETWEEN 65 AND 70 THEN v_digit:=v_digit-55; ELSIF v_digit BETWEEN 97 AND 102 THEN v_digit:=v_digit-87; ELSE RAISE EXCEPTION 'SELECTION_UNAVAILABLE'; END IF;
      v_code:=v_code*16+v_digit;
     END LOOP;v_pos:=v_pos+4;
    ELSE
     v_code:=CASE v_next WHEN 34 THEN 34 WHEN 47 THEN 47 WHEN 92 THEN 92 WHEN 98 THEN 8 WHEN 102 THEN 12 WHEN 110 THEN 10 WHEN 114 THEN 13 WHEN 116 THEN 9 ELSE -1 END;
     IF v_code<0 THEN RAISE EXCEPTION 'SELECTION_UNAVAILABLE'; END IF;
    END IF;
   ELSIF v_byte<128 THEN
    IF v_byte<32 OR v_byte=34 THEN RAISE EXCEPTION 'SELECTION_UNAVAILABLE'; END IF;v_code:=v_byte;
   ELSE
    IF v_byte BETWEEN 194 AND 223 THEN v_count:=2;v_code:=v_byte-192;
    ELSIF v_byte BETWEEN 224 AND 239 THEN v_count:=3;v_code:=v_byte-224;
    ELSIF v_byte BETWEEN 240 AND 244 THEN v_count:=4;v_code:=v_byte-240;
    ELSE RAISE EXCEPTION 'SELECTION_UNAVAILABLE'; END IF;
    IF v_pos+v_count>p_end-1 THEN RAISE EXCEPTION 'SELECTION_UNAVAILABLE'; END IF;
    FOR v_i IN 1..(v_count-1) LOOP
     v_next:=pg_catalog.get_byte(p_body,v_pos+v_i);IF v_next NOT BETWEEN 128 AND 191 THEN RAISE EXCEPTION 'SELECTION_UNAVAILABLE'; END IF;v_code:=v_code*64+(v_next-128);
    END LOOP;
    IF (v_count=2 AND v_code<128) OR (v_count=3 AND v_code<2048) OR (v_count=4 AND v_code<65536) OR v_code>1114111 OR v_code BETWEEN 55296 AND 57343 THEN RAISE EXCEPTION 'SELECTION_UNAVAILABLE'; END IF;
    v_pos:=v_pos+v_count-1;
   END IF;
   v_count:=CASE WHEN v_code>65535 THEN 2 ELSE 1 END;
   IF v_pass=1 THEN
    IF v_units::NUMERIC+v_count>v_unit_limit OR 2::NUMERIC*(v_units::NUMERIC+v_count)>v_output_limit OR 4::NUMERIC*(v_units::NUMERIC+v_count)>2147483647 THEN RAISE EXCEPTION 'SELECTION_UNAVAILABLE'; END IF;
    v_required:=2::NUMERIC*pg_catalog.pg_column_size(p_body)+12::NUMERIC*(v_units::NUMERIC+v_count)+6::NUMERIC*pg_catalog.pg_column_size(''::BYTEA);
    IF v_required>v_workspace THEN RAISE EXCEPTION 'SELECTION_UNAVAILABLE'; END IF;
    v_units:=v_units+v_count;
   ELSE
    IF v_written::NUMERIC+v_count>v_units OR v_written::NUMERIC+v_count>v_unit_limit OR v_required>v_workspace THEN RAISE EXCEPTION 'SELECTION_UNAVAILABLE'; END IF;
    IF v_code<=65535 THEN v_high:=v_code;v_low:=NULL;
    ELSE v_code:=v_code-65536;v_high:=55296+v_code/1024;v_low:=56320+v_code%1024; END IF;
    v_result:=pg_catalog.set_byte(v_result,v_written*2,v_high/256);v_result:=pg_catalog.set_byte(v_result,v_written*2+1,v_high%256);v_written:=v_written+1;
    IF v_low IS NOT NULL THEN v_result:=pg_catalog.set_byte(v_result,v_written*2,v_low/256);v_result:=pg_catalog.set_byte(v_result,v_written*2+1,v_low%256);v_written:=v_written+1; END IF;
   END IF;
   v_pos:=v_pos+1;
  END LOOP;
  IF v_pass=1 THEN
   v_required:=2::NUMERIC*pg_catalog.pg_column_size(p_body)+12::NUMERIC*v_units+6::NUMERIC*pg_catalog.pg_column_size(''::BYTEA);
   IF v_required>v_workspace THEN RAISE EXCEPTION 'SELECTION_UNAVAILABLE'; END IF;
   v_result:=pg_catalog.decode(pg_catalog.repeat('00',v_units*2),'hex');
  ELSIF v_written<>v_units THEN RAISE EXCEPTION 'SELECTION_UNAVAILABLE'; END IF;
 END LOOP;
 RETURN v_result;
EXCEPTION WHEN OTHERS THEN RAISE EXCEPTION 'SELECTION_UNAVAILABLE'; END $$;
REVOKE ALL ON FUNCTION public.pro273_installer_metadata_string_units(TEXT,BYTEA,INTEGER,INTEGER) FROM PUBLIC;

-- Installer metadata token arrays are private transient values. Node IDs are
-- one-based preorder; parent 0 denotes the sole document root.
CREATE TYPE public.pro273_installer_metadata_tokens AS (
 kinds INTEGER[], parents INTEGER[], ordinals BIGINT[], starts INTEGER[], ends INTEGER[], key_units BYTEA[], string_units BYTEA[]
);
CREATE FUNCTION public.pro273_installer_metadata_tokenize(p_expectation_id TEXT,p_body BYTEA) RETURNS public.pro273_installer_metadata_tokens
LANGUAGE plpgsql SECURITY DEFINER SET search_path=pg_catalog AS $$
DECLARE v_context JSONB; v_limits JSONB; v_len INTEGER; v_pos INTEGER:=0; v_end INTEGER; v_ch INTEGER; v_depth INTEGER:=0; v_count INTEGER:=0; v_root BOOLEAN:=FALSE;
 v_stack_kind INTEGER[]:=ARRAY[]::INTEGER[]; v_stack_state INTEGER[]:=ARRAY[]::INTEGER[]; v_stack_id INTEGER[]:=ARRAY[]::INTEGER[]; v_stack_ordinal BIGINT[]:=ARRAY[]::BIGINT[]; v_pending BYTEA[]:=ARRAY[]::BYTEA[];
 v_kinds INTEGER[]:=ARRAY[]::INTEGER[]; v_parents INTEGER[]:=ARRAY[]::INTEGER[]; v_ordinals BIGINT[]:=ARRAY[]::BIGINT[]; v_starts INTEGER[]:=ARRAY[]::INTEGER[]; v_ends INTEGER[]:=ARRAY[]::INTEGER[]; v_keys BYTEA[]:=ARRAY[]::BYTEA[]; v_strings BYTEA[]:=ARRAY[]::BYTEA[];
 v_parent INTEGER; v_ordinal BIGINT; v_key BYTEA; v_kind INTEGER; v_units BYTEA; v_needed NUMERIC; v_workspace NUMERIC;
BEGIN
 IF p_body IS NULL OR p_expectation_id IS NULL THEN RAISE EXCEPTION 'SELECTION_UNAVAILABLE'; END IF;
 v_context:=public.pro273_installer_metadata_context(p_expectation_id);v_limits:=v_context->'limits';
 PERFORM public.pro273_installer_metadata_grammar(p_expectation_id,p_body);
 v_len:=pg_catalog.octet_length(p_body);v_workspace:=(v_limits->>'maxParserWorkspaceBytes')::NUMERIC;
 -- Full-byte conservative token and stack bound, including old/new array
 -- representations, decoded keys/strings and one concurrent string decoder.
 -- The separately qualified holder covers PG runtime/allocation overhead.
 v_needed:=2::NUMERIC*v_len*(7::NUMERIC*pg_catalog.pg_column_size(ARRAY[0::INTEGER])+2::NUMERIC*pg_catalog.pg_column_size(ARRAY[0::BIGINT])+3::NUMERIC*pg_catalog.pg_column_size(ARRAY[''::BYTEA]))+20::NUMERIC*v_len+2::NUMERIC*pg_catalog.pg_column_size(p_body)+6::NUMERIC*pg_catalog.pg_column_size(''::BYTEA);
 IF v_len::NUMERIC>(v_limits->>'maxTokenCapacity')::NUMERIC OR v_len::NUMERIC>(v_limits->>'maxDepthCapacity')::NUMERIC OR v_len::NUMERIC>(v_limits->>'maxDecodedUnits')::NUMERIC OR v_needed>v_workspace THEN RAISE EXCEPTION 'SELECTION_UNAVAILABLE'; END IF;
 IF CASE WHEN v_len>=3 THEN pg_catalog.get_byte(p_body,0)=239 AND pg_catalog.get_byte(p_body,1)=187 AND pg_catalog.get_byte(p_body,2)=191 ELSE FALSE END THEN v_pos:=3; END IF;
 LOOP
  WHILE CASE WHEN v_pos<v_len THEN pg_catalog.get_byte(p_body,v_pos) IN (9,10,13,32) ELSE FALSE END LOOP v_pos:=v_pos+1; END LOOP;
  IF v_depth=0 AND v_root THEN IF v_pos<>v_len THEN RAISE EXCEPTION 'SELECTION_UNAVAILABLE'; END IF; EXIT; END IF;
  IF v_pos>=v_len THEN RAISE EXCEPTION 'SELECTION_UNAVAILABLE'; END IF;v_ch:=pg_catalog.get_byte(p_body,v_pos);
  IF v_depth>0 AND v_stack_kind[v_depth]=1 THEN
   IF v_stack_state[v_depth] IN (0,4) THEN
    IF v_ch=125 AND v_stack_state[v_depth]=0 THEN v_ends[v_stack_id[v_depth]]:=v_pos+1;v_pos:=v_pos+1;v_depth:=v_depth-1;CONTINUE; END IF;
    IF v_ch<>34 THEN RAISE EXCEPTION 'SELECTION_UNAVAILABLE'; END IF;
    v_end:=public.pro273_sel_scan_string_end(p_body,v_pos,v_len);v_pending[v_depth]:=public.pro273_installer_metadata_string_units(p_expectation_id,p_body,v_pos,v_end);v_pos:=v_end;v_stack_state[v_depth]:=1;CONTINUE;
   ELSIF v_stack_state[v_depth]=1 THEN IF v_ch<>58 THEN RAISE EXCEPTION 'SELECTION_UNAVAILABLE'; END IF;v_pos:=v_pos+1;v_stack_state[v_depth]:=2;CONTINUE;
   ELSIF v_stack_state[v_depth]=3 THEN
    IF v_ch=125 THEN v_ends[v_stack_id[v_depth]]:=v_pos+1;v_pos:=v_pos+1;v_depth:=v_depth-1;CONTINUE;
    ELSIF v_ch=44 THEN v_pos:=v_pos+1;v_stack_state[v_depth]:=4;CONTINUE;ELSE RAISE EXCEPTION 'SELECTION_UNAVAILABLE'; END IF;
   END IF;
  ELSIF v_depth>0 AND v_stack_kind[v_depth]=2 THEN
   IF v_stack_state[v_depth]=0 AND v_ch=93 THEN v_ends[v_stack_id[v_depth]]:=v_pos+1;v_pos:=v_pos+1;v_depth:=v_depth-1;CONTINUE; END IF;
   IF v_stack_state[v_depth]=3 THEN
    IF v_ch=93 THEN v_ends[v_stack_id[v_depth]]:=v_pos+1;v_pos:=v_pos+1;v_depth:=v_depth-1;CONTINUE;
    ELSIF v_ch=44 THEN v_pos:=v_pos+1;v_stack_state[v_depth]:=4;CONTINUE;ELSE RAISE EXCEPTION 'SELECTION_UNAVAILABLE'; END IF;
   END IF;
  END IF;
  IF v_depth=0 THEN v_parent:=0;v_ordinal:=0;v_key:=NULL;v_root:=TRUE;
  ELSE v_parent:=v_stack_id[v_depth];v_ordinal:=v_stack_ordinal[v_depth];v_key:=CASE WHEN v_stack_kind[v_depth]=1 THEN v_pending[v_depth] ELSE NULL END;v_stack_state[v_depth]:=3;v_stack_ordinal[v_depth]:=v_stack_ordinal[v_depth]+1;END IF;
  IF v_needed>v_workspace OR (v_count+1)::NUMERIC>(v_limits->>'maxTokenCapacity')::NUMERIC THEN RAISE EXCEPTION 'SELECTION_UNAVAILABLE'; END IF;
  v_count:=v_count+1;v_parents[v_count]:=v_parent;v_ordinals[v_count]:=v_ordinal;v_starts[v_count]:=v_pos;v_keys[v_count]:=v_key;v_strings[v_count]:=NULL;
  IF v_ch IN (123,91) THEN
   IF (v_depth+1)::NUMERIC>(v_limits->>'maxDepthCapacity')::NUMERIC OR v_needed>v_workspace THEN RAISE EXCEPTION 'SELECTION_UNAVAILABLE'; END IF;
   v_kind:=CASE WHEN v_ch=123 THEN 1 ELSE 2 END;v_kinds[v_count]:=v_kind;v_ends[v_count]:=0;v_pos:=v_pos+1;v_depth:=v_depth+1;
   v_stack_kind[v_depth]:=v_kind;v_stack_state[v_depth]:=0;v_stack_id[v_depth]:=v_count;v_stack_ordinal[v_depth]:=0;v_pending[v_depth]:=NULL;CONTINUE;
  ELSIF v_ch=34 THEN v_kind:=3;v_end:=public.pro273_sel_scan_string_end(p_body,v_pos,v_len);v_units:=public.pro273_installer_metadata_string_units(p_expectation_id,p_body,v_pos,v_end);v_strings[v_count]:=v_units;
  ELSIF v_ch=116 AND pg_catalog.substring(p_body,v_pos+1,4)=pg_catalog.convert_to('true','UTF8') THEN v_kind:=4;v_end:=v_pos+4;
  ELSIF v_ch=102 AND pg_catalog.substring(p_body,v_pos+1,5)=pg_catalog.convert_to('false','UTF8') THEN v_kind:=5;v_end:=v_pos+5;
  ELSIF v_ch=110 AND pg_catalog.substring(p_body,v_pos+1,4)=pg_catalog.convert_to('null','UTF8') THEN v_kind:=6;v_end:=v_pos+4;
  ELSE RAISE EXCEPTION 'SELECTION_UNAVAILABLE'; END IF;
  v_kinds[v_count]:=v_kind;v_ends[v_count]:=v_end;v_pos:=v_end;
 END LOOP;
 RETURN ROW(v_kinds,v_parents,v_ordinals,v_starts,v_ends,v_keys,v_strings)::public.pro273_installer_metadata_tokens;
EXCEPTION WHEN OTHERS THEN RAISE EXCEPTION 'SELECTION_UNAVAILABLE'; END $$;
REVOKE ALL ON FUNCTION public.pro273_installer_metadata_tokenize(TEXT,BYTEA) FROM PUBLIC;

-- Stringify UTF16BE explicitly without a catalog tuplestore or locale sort.
CREATE FUNCTION public.pro273_installer_metadata_quote(p_expectation_id TEXT,p_units BYTEA) RETURNS BYTEA
LANGUAGE plpgsql SECURITY DEFINER SET search_path=pg_catalog AS $$
DECLARE v_context JSONB; v_limits JSONB; v_n INTEGER; v_i INTEGER:=0; v_u INTEGER; v_next INTEGER; v_cp INTEGER; v_part BYTEA; v_result BYTEA:=pg_catalog.decode('22','hex'); v_max NUMERIC; v_workspace NUMERIC; v_worst NUMERIC;
BEGIN
 IF p_expectation_id IS NULL OR p_units IS NULL OR pg_catalog.octet_length(p_units)%2<>0 OR pg_catalog.getdatabaseencoding()<>'UTF8' THEN RAISE EXCEPTION 'SELECTION_UNAVAILABLE'; END IF;
 v_context:=public.pro273_installer_metadata_context(p_expectation_id);v_limits:=v_context->'limits';
 IF COALESCE(v_limits->>'maxDecodedUnits','') !~ '^[1-9][0-9]{0,18}$' OR COALESCE(v_limits->>'maxOutputBytes','') !~ '^[1-9][0-9]{0,18}$' OR COALESCE(v_limits->>'maxParserWorkspaceBytes','') !~ '^[1-9][0-9]{0,18}$' THEN RAISE EXCEPTION 'SELECTION_UNAVAILABLE'; END IF;
 v_n:=pg_catalog.octet_length(p_units)/2;v_max:=(v_limits->>'maxOutputBytes')::NUMERIC;v_workspace:=(v_limits->>'maxParserWorkspaceBytes')::NUMERIC;v_worst:=6::NUMERIC*v_n+2;
 IF v_n::NUMERIC>(v_limits->>'maxDecodedUnits')::NUMERIC OR v_worst>v_max OR 2::NUMERIC*pg_catalog.pg_column_size(p_units)+3::NUMERIC*v_worst>v_workspace THEN RAISE EXCEPTION 'SELECTION_UNAVAILABLE'; END IF;
 WHILE v_i<v_n LOOP
  v_u:=pg_catalog.get_byte(p_units,v_i*2)*256+pg_catalog.get_byte(p_units,v_i*2+1);v_i:=v_i+1;
  IF v_u=34 THEN v_part:=pg_catalog.decode('5c22','hex');
  ELSIF v_u=92 THEN v_part:=pg_catalog.decode('5c5c','hex');
  ELSIF v_u=8 THEN v_part:=pg_catalog.decode('5c62','hex');
  ELSIF v_u=9 THEN v_part:=pg_catalog.decode('5c74','hex');
  ELSIF v_u=10 THEN v_part:=pg_catalog.decode('5c6e','hex');
  ELSIF v_u=12 THEN v_part:=pg_catalog.decode('5c66','hex');
  ELSIF v_u=13 THEN v_part:=pg_catalog.decode('5c72','hex');
  ELSIF v_u<32 THEN v_part:=pg_catalog.convert_to('\u'||pg_catalog.lpad(pg_catalog.to_hex(v_u),4,'0'),'UTF8');
  ELSIF v_u BETWEEN 55296 AND 56319 AND v_i<v_n THEN
   v_next:=pg_catalog.get_byte(p_units,v_i*2)*256+pg_catalog.get_byte(p_units,v_i*2+1);
   IF v_next BETWEEN 56320 AND 57343 THEN v_i:=v_i+1;v_cp:=65536+(v_u-55296)*1024+(v_next-56320);v_part:=pg_catalog.convert_to(pg_catalog.chr(v_cp),'UTF8');
   ELSE v_part:=pg_catalog.convert_to('\u'||pg_catalog.lpad(pg_catalog.to_hex(v_u),4,'0'),'UTF8'); END IF;
  ELSIF v_u BETWEEN 55296 AND 57343 THEN v_part:=pg_catalog.convert_to('\u'||pg_catalog.lpad(pg_catalog.to_hex(v_u),4,'0'),'UTF8');
  ELSE v_part:=pg_catalog.convert_to(pg_catalog.chr(v_u),'UTF8'); END IF;
  IF pg_catalog.octet_length(v_result)::NUMERIC+pg_catalog.octet_length(v_part)+1>v_max OR 2::NUMERIC*pg_catalog.pg_column_size(p_units)+3::NUMERIC*v_worst>v_workspace THEN RAISE EXCEPTION 'SELECTION_UNAVAILABLE'; END IF;
  v_result:=v_result||v_part;
 END LOOP;
 RETURN v_result||pg_catalog.decode('22','hex');
EXCEPTION WHEN OTHERS THEN RAISE EXCEPTION 'SELECTION_UNAVAILABLE'; END $$;
REVOKE ALL ON FUNCTION public.pro273_installer_metadata_quote(TEXT,BYTEA) FROM PUBLIC;

-- Bottom-up canonicalization of the protected transient representation.
-- Direct children only; duplicate object keys keep the final value. Array
-- indices enumerate numerically before other UTF16-sorted object keys.
CREATE FUNCTION public.pro273_installer_metadata_canonical(p_expectation_id TEXT,p_body BYTEA) RETURNS BYTEA
LANGUAGE plpgsql SECURITY DEFINER SET search_path=pg_catalog AS $$
DECLARE v_context JSONB; v_limits JSONB; v_nodes public.pro273_installer_metadata_tokens; v_n INTEGER; v_count INTEGER; v_i INTEGER; v_j INTEGER; v_k INTEGER; v_pos INTEGER; v_tmp INTEGER;
 v_child INTEGER; v_order INTEGER[]; v_order_count INTEGER; v_values BYTEA[]:=ARRAY[]::BYTEA[]; v_result BYTEA; v_part BYTEA; v_quote BYTEA; v_kind INTEGER;
 v_left_index BIGINT; v_right_index BIGINT; v_move BOOLEAN; v_max NUMERIC; v_workspace NUMERIC; v_worst NUMERIC; v_needed NUMERIC;
BEGIN
 IF p_expectation_id IS NULL OR p_body IS NULL THEN RAISE EXCEPTION 'SELECTION_UNAVAILABLE'; END IF;
 v_context:=public.pro273_installer_metadata_context(p_expectation_id);v_limits:=v_context->'limits';v_n:=pg_catalog.octet_length(p_body);
 IF COALESCE(v_limits->>'maxOutputBytes','') !~ '^[1-9][0-9]{0,18}$' OR COALESCE(v_limits->>'maxParserWorkspaceBytes','') !~ '^[1-9][0-9]{0,18}$' THEN RAISE EXCEPTION 'SELECTION_UNAVAILABLE'; END IF;
 v_max:=(v_limits->>'maxOutputBytes')::NUMERIC;v_workspace:=(v_limits->>'maxParserWorkspaceBytes')::NUMERIC;v_worst:=6::NUMERIC*v_n+2;
 -- Reserve simultaneous token arrays, decoded data, canonical buffers, old/new
 -- append values and one string decoder. Runtime/allocator overhead remains in
 -- the independently qualified holder and requires installed qualification.
 v_needed:=2::NUMERIC*v_n*(8::NUMERIC*pg_catalog.pg_column_size(ARRAY[0::INTEGER])+2::NUMERIC*pg_catalog.pg_column_size(ARRAY[0::BIGINT])+4::NUMERIC*pg_catalog.pg_column_size(ARRAY[''::BYTEA]))+32::NUMERIC*v_n+4::NUMERIC*v_worst+2::NUMERIC*pg_catalog.pg_column_size(p_body);
 IF v_n=0 OR v_worst>v_max OR v_needed>v_workspace THEN RAISE EXCEPTION 'SELECTION_UNAVAILABLE'; END IF;
 v_nodes:=public.pro273_installer_metadata_tokenize(p_expectation_id,p_body);v_count:=pg_catalog.cardinality(v_nodes.kinds);
 IF v_count IS NULL OR v_count=0 OR v_nodes.parents[1]<>0 THEN RAISE EXCEPTION 'SELECTION_UNAVAILABLE'; END IF;
 FOR v_i IN REVERSE v_count..1 LOOP
  v_kind:=v_nodes.kinds[v_i];
  IF v_kind=3 THEN v_values[v_i]:=public.pro273_installer_metadata_quote(p_expectation_id,v_nodes.string_units[v_i]);
  ELSIF v_kind=4 THEN v_values[v_i]:=pg_catalog.convert_to('true','UTF8');
  ELSIF v_kind=5 THEN v_values[v_i]:=pg_catalog.convert_to('false','UTF8');
  ELSIF v_kind=6 THEN v_values[v_i]:=pg_catalog.convert_to('null','UTF8');
  ELSIF v_kind IN (1,2) THEN
   v_order:=ARRAY[]::INTEGER[];v_order_count:=0;
   IF v_i<v_count THEN
    FOR v_j IN (v_i+1)..v_count LOOP
     IF v_nodes.parents[v_j]=v_i THEN
      IF v_values[v_j] IS NULL THEN RAISE EXCEPTION 'SELECTION_UNAVAILABLE'; END IF;
      v_pos:=0;
      IF v_kind=1 THEN
       IF v_nodes.key_units[v_j] IS NULL THEN RAISE EXCEPTION 'SELECTION_UNAVAILABLE'; END IF;
       IF v_order_count>0 THEN FOR v_k IN 1..v_order_count LOOP IF v_nodes.key_units[v_order[v_k]]=v_nodes.key_units[v_j] THEN v_pos:=v_k;EXIT; END IF; END LOOP; END IF;
      ELSIF v_nodes.key_units[v_j] IS NOT NULL THEN RAISE EXCEPTION 'SELECTION_UNAVAILABLE'; END IF;
      IF v_pos>0 THEN v_values[v_order[v_pos]]:=NULL;v_order[v_pos]:=v_j;
      ELSE v_order_count:=v_order_count+1;v_order[v_order_count]:=v_j; END IF;
     END IF;
    END LOOP;
   END IF;
   IF v_kind=1 AND v_order_count>1 THEN
    FOR v_j IN 2..v_order_count LOOP
     v_tmp:=v_order[v_j];v_pos:=v_j;
     WHILE v_pos>1 LOOP
      v_left_index:=public.pro273_sel_js_array_index(v_nodes.key_units[v_order[v_pos-1]]);v_right_index:=public.pro273_sel_js_array_index(v_nodes.key_units[v_tmp]);
      v_move:=CASE WHEN v_left_index IS NULL AND v_right_index IS NOT NULL THEN TRUE WHEN v_left_index IS NOT NULL AND v_right_index IS NULL THEN FALSE WHEN v_left_index IS NOT NULL THEN v_left_index>v_right_index ELSE public.pro273_sel_utf16_compare(v_nodes.key_units[v_order[v_pos-1]],v_nodes.key_units[v_tmp])>0 END;
      EXIT WHEN NOT v_move;v_order[v_pos]:=v_order[v_pos-1];v_pos:=v_pos-1;
     END LOOP;v_order[v_pos]:=v_tmp;
    END LOOP;
   END IF;
   v_result:=CASE WHEN v_kind=1 THEN pg_catalog.decode('7b','hex') ELSE pg_catalog.decode('5b','hex') END;
   IF v_order_count>0 THEN
    FOR v_j IN 1..v_order_count LOOP
     v_child:=v_order[v_j];v_part:=v_values[v_child];
     IF v_kind=1 THEN v_quote:=public.pro273_installer_metadata_quote(p_expectation_id,v_nodes.key_units[v_child]); ELSE v_quote:=''::BYTEA; END IF;
     IF pg_catalog.octet_length(v_result)::NUMERIC+pg_catalog.octet_length(v_quote)+pg_catalog.octet_length(v_part)+CASE WHEN v_kind=1 THEN 1 ELSE 0 END+CASE WHEN v_j>1 THEN 1 ELSE 0 END+1>v_max OR v_needed>v_workspace THEN RAISE EXCEPTION 'SELECTION_UNAVAILABLE'; END IF;
     IF v_j>1 THEN v_result:=v_result||pg_catalog.decode('2c','hex'); END IF;
     IF v_kind=1 THEN v_result:=v_result||v_quote||pg_catalog.decode('3a','hex'); END IF;
     v_result:=v_result||v_part;v_values[v_child]:=NULL;v_part:=NULL;v_quote:=NULL;
    END LOOP;
   END IF;
   IF pg_catalog.octet_length(v_result)::NUMERIC+1>v_max OR v_needed>v_workspace THEN RAISE EXCEPTION 'SELECTION_UNAVAILABLE'; END IF;
   v_values[v_i]:=v_result||CASE WHEN v_kind=1 THEN pg_catalog.decode('7d','hex') ELSE pg_catalog.decode('5d','hex') END;v_result:=NULL;
  ELSE RAISE EXCEPTION 'SELECTION_UNAVAILABLE'; END IF;
 END LOOP;
 IF v_values[1] IS NULL OR pg_catalog.octet_length(v_values[1])::NUMERIC>v_max THEN RAISE EXCEPTION 'SELECTION_UNAVAILABLE'; END IF;
 RETURN v_values[1];
EXCEPTION WHEN OTHERS THEN RAISE EXCEPTION 'SELECTION_UNAVAILABLE'; END $$;
REVOKE ALL ON FUNCTION public.pro273_installer_metadata_canonical(TEXT,BYTEA) FROM PUBLIC;

-- Fixed ASCII schema-key conversion; only source-owned schema literals use it.
CREATE FUNCTION public.pro273_installer_ascii_units(p_ascii TEXT) RETURNS BYTEA
LANGUAGE plpgsql IMMUTABLE STRICT SET search_path=pg_catalog AS $$
DECLARE v_source BYTEA; v_result BYTEA:=''::BYTEA; v_i INTEGER; v_n INTEGER;
BEGIN
 v_source:=pg_catalog.convert_to(p_ascii,'UTF8');v_n:=pg_catalog.octet_length(v_source);
 IF v_n>0 THEN FOR v_i IN 0..v_n-1 LOOP IF pg_catalog.get_byte(v_source,v_i)>127 THEN RAISE EXCEPTION 'SELECTION_UNAVAILABLE'; END IF;v_result:=v_result||pg_catalog.decode('00','hex')||pg_catalog.substring(v_source,v_i+1,1); END LOOP; END IF;
 RETURN v_result;
END $$;
REVOKE ALL ON FUNCTION public.pro273_installer_ascii_units(TEXT) FROM PUBLIC;

-- Fixed-shape raw object lookup. Duplicate keys select the last value, while
-- unknown or absent keys deny. This helper is private to the funded parser.
CREATE FUNCTION public.pro273_installer_object_members(p_expectation_id TEXT,p_nodes public.pro273_installer_metadata_tokens,p_parent INTEGER,p_keys TEXT[]) RETURNS INTEGER[]
LANGUAGE plpgsql SECURITY DEFINER SET search_path=pg_catalog AS $$
DECLARE v_context JSONB; v_limits JSONB; v_count INTEGER; v_i INTEGER; v_j INTEGER; v_found INTEGER; v_size INTEGER; v_winners INTEGER[]:=ARRAY[]::INTEGER[]; v_needed NUMERIC;
BEGIN
 IF p_expectation_id IS NULL OR p_nodes IS NULL OR p_parent IS NULL OR p_keys IS NULL THEN RAISE EXCEPTION 'SELECTION_UNAVAILABLE'; END IF;
 v_context:=public.pro273_installer_metadata_context(p_expectation_id);v_limits:=v_context->'limits';v_count:=pg_catalog.cardinality(p_nodes.kinds);v_size:=pg_catalog.cardinality(p_keys);
 IF v_count IS NULL OR p_parent<1 OR p_parent>v_count OR p_nodes.kinds[p_parent]<>1 OR v_size IS NULL OR v_size<1 OR v_size::NUMERIC>(v_limits->>'maxTokenCapacity')::NUMERIC THEN RAISE EXCEPTION 'SELECTION_UNAVAILABLE'; END IF;
 v_needed:=2::NUMERIC*pg_catalog.pg_column_size(p_nodes)+2::NUMERIC*v_size*pg_catalog.pg_column_size(ARRAY[0::INTEGER]);
 IF v_needed>(v_limits->>'maxParserWorkspaceBytes')::NUMERIC THEN RAISE EXCEPTION 'SELECTION_UNAVAILABLE'; END IF;
 FOR v_j IN 1..v_size LOOP v_winners[v_j]:=0; END LOOP;
 IF p_parent<v_count THEN FOR v_i IN (p_parent+1)..v_count LOOP
  IF p_nodes.parents[v_i]=p_parent THEN
   v_found:=0;
   FOR v_j IN 1..v_size LOOP IF p_nodes.key_units[v_i]=public.pro273_installer_ascii_units(p_keys[v_j]) THEN v_found:=v_j;EXIT; END IF; END LOOP;
   IF v_found=0 THEN RAISE EXCEPTION 'SELECTION_UNAVAILABLE'; END IF;
   v_winners[v_found]:=v_i;
  END IF;
 END LOOP; END IF;
 FOR v_j IN 1..v_size LOOP IF v_winners[v_j]=0 THEN RAISE EXCEPTION 'SELECTION_UNAVAILABLE'; END IF; END LOOP;
 RETURN v_winners;
EXCEPTION WHEN OTHERS THEN RAISE EXCEPTION 'SELECTION_UNAVAILABLE'; END $$;
REVOKE ALL ON FUNCTION public.pro273_installer_object_members(TEXT,public.pro273_installer_metadata_tokens,INTEGER,TEXT[]) FROM PUBLIC;

-- Descriptor publication alone requires duplicate rejection. The existing
-- object lookup deliberately preserves last-key semantics for other ABIs.
-- It has already checked the fixed key set and parser workspace; every direct
-- child must be the unique winning token for one of those decoded keys.
CREATE FUNCTION public.pro273_installer_unique_object_members(p_expectation_id TEXT,p_nodes public.pro273_installer_metadata_tokens,p_parent INTEGER,p_keys TEXT[]) RETURNS INTEGER[]
LANGUAGE plpgsql SECURITY DEFINER SET search_path=pg_catalog AS $$
DECLARE v_members INTEGER[]; v_count INTEGER; v_i INTEGER;
BEGIN
 v_members:=public.pro273_installer_object_members(p_expectation_id,p_nodes,p_parent,p_keys);
 v_count:=pg_catalog.cardinality(p_nodes.kinds);
 IF p_parent<v_count THEN FOR v_i IN (p_parent+1)..v_count LOOP
  IF p_nodes.parents[v_i]=p_parent AND NOT (v_i=ANY(v_members)) THEN RAISE EXCEPTION 'SELECTION_UNAVAILABLE'; END IF;
 END LOOP; END IF;
 RETURN v_members;
EXCEPTION WHEN OTHERS THEN RAISE EXCEPTION 'SELECTION_UNAVAILABLE'; END $$;
REVOKE ALL ON FUNCTION public.pro273_installer_unique_object_members(TEXT,public.pro273_installer_metadata_tokens,INTEGER,TEXT[]) FROM PUBLIC;

-- Validate canonical unsigned decimal UTF16 units without casting or imposing
-- a numeric value cap on NUMERIC resource fields.
CREATE FUNCTION public.pro273_installer_decimal_units_valid(p_units BYTEA) RETURNS BOOLEAN
LANGUAGE plpgsql IMMUTABLE STRICT SET search_path=pg_catalog AS $$
DECLARE v_n INTEGER; v_i INTEGER; v_digit INTEGER;
BEGIN
 v_n:=pg_catalog.octet_length(p_units);IF v_n=0 OR v_n%2<>0 THEN RETURN FALSE; END IF;
 FOR v_i IN 0..(v_n/2-1) LOOP
  IF pg_catalog.get_byte(p_units,v_i*2)<>0 THEN RETURN FALSE; END IF;
  v_digit:=pg_catalog.get_byte(p_units,v_i*2+1);IF v_digit NOT BETWEEN 48 AND 57 OR (v_i=0 AND v_n>2 AND v_digit=48) THEN RETURN FALSE; END IF;
 END LOOP;RETURN TRUE;
END $$;
REVOKE ALL ON FUNCTION public.pro273_installer_decimal_units_valid(BYTEA) FROM PUBLIC;

-- Raw qualifier quantities must fit PostgreSQL's integral NUMERIC domain.
-- This is only a wire primitive: the caller must already hold independently
-- qualified parser capacity and must enforce the vector and aggregate checks.
-- No caller or publication authority is created by this function.
CREATE FUNCTION public.pro273_qualifier_numeric_units_valid(p_units BYTEA,p_positive BOOLEAN) RETURNS BOOLEAN
LANGUAGE plpgsql IMMUTABLE STRICT SET search_path=pg_catalog AS $$
DECLARE v_n INTEGER; v_i INTEGER; v_digit INTEGER;
BEGIN
 v_n:=pg_catalog.octet_length(p_units);
 -- PostgreSQL NUMERIC permits at most 131072 digits before the decimal point.
 -- Check this before scanning or converting the decoded units.
 IF v_n=0 OR v_n%2<>0 OR v_n>262144 THEN RETURN FALSE; END IF;
 FOR v_i IN 0..(v_n/2-1) LOOP
  IF pg_catalog.get_byte(p_units,v_i*2)<>0 THEN RETURN FALSE; END IF;
  v_digit:=pg_catalog.get_byte(p_units,v_i*2+1);
  IF v_digit NOT BETWEEN 48 AND 57 OR (v_i=0 AND v_digit=48 AND (v_n>2 OR p_positive)) THEN RETURN FALSE; END IF;
 END LOOP;
 RETURN TRUE;
END $$;
REVOKE ALL ON FUNCTION public.pro273_qualifier_numeric_units_valid(BYTEA,BOOLEAN) FROM PUBLIC;

CREATE FUNCTION public.pro273_installer_hash_units_valid(p_units BYTEA) RETURNS BOOLEAN
LANGUAGE plpgsql IMMUTABLE STRICT SET search_path=pg_catalog AS $$
DECLARE v_i INTEGER; v_c INTEGER;
BEGIN
 IF pg_catalog.octet_length(p_units)<>128 THEN RETURN FALSE; END IF;
 FOR v_i IN 0..63 LOOP v_c:=pg_catalog.get_byte(p_units,v_i*2+1);IF pg_catalog.get_byte(p_units,v_i*2)<>0 OR NOT (v_c BETWEEN 48 AND 57 OR v_c BETWEEN 97 AND 102) THEN RETURN FALSE; END IF; END LOOP;RETURN TRUE;
END $$;
REVOKE ALL ON FUNCTION public.pro273_installer_hash_units_valid(BYTEA) FROM PUBLIC;
CREATE FUNCTION public.pro273_installer_positive_bigint_units_valid(p_units BYTEA) RETURNS BOOLEAN
LANGUAGE plpgsql IMMUTABLE STRICT SET search_path=pg_catalog AS $$
DECLARE v_max BYTEA:=pg_catalog.decode('0039003200320033003300370032003000330036003800350034003700370035003800300037','hex'); v_n INTEGER;
BEGIN
 v_n:=pg_catalog.octet_length(p_units);RETURN public.pro273_installer_decimal_units_valid(p_units) AND p_units<>pg_catalog.decode('0030','hex') AND v_n<=38 AND (v_n<38 OR p_units<=v_max);
END $$;
REVOKE ALL ON FUNCTION public.pro273_installer_positive_bigint_units_valid(BYTEA) FROM PUBLIC;

CREATE FUNCTION public.pro273_installer_oid_units_valid(p_units BYTEA) RETURNS BOOLEAN
LANGUAGE plpgsql IMMUTABLE STRICT SET search_path=pg_catalog AS $$
DECLARE v_max BYTEA:=pg_catalog.decode('0034003200390034003900360037003200390035','hex'); v_n INTEGER;
BEGIN
 v_n:=pg_catalog.octet_length(p_units);RETURN public.pro273_installer_decimal_units_valid(p_units) AND p_units<>pg_catalog.decode('0030','hex') AND v_n<=20 AND (v_n<20 OR p_units<=v_max);
END $$;
REVOKE ALL ON FUNCTION public.pro273_installer_oid_units_valid(BYTEA) FROM PUBLIC;

-- Count UTF8 bytes from scalar UTF16BE units without casting to TEXT or NAME.
-- p_max_bytes is an explicit data bound; a protected caller must bind it to
-- the installed server's UTF8 NAME limit and independently qualify costs.
CREATE FUNCTION public.pro273_initial_name_units_valid(p_units BYTEA,p_max_bytes INTEGER) RETURNS BOOLEAN
LANGUAGE plpgsql IMMUTABLE STRICT SET search_path=pg_catalog AS $initial_name$
DECLARE v_n INTEGER; v_i INTEGER:=0; v_u INTEGER; v_low INTEGER; v_bytes BIGINT:=0;
BEGIN
 v_n:=pg_catalog.octet_length(p_units);
 IF p_max_bytes<1 OR v_n=0 OR v_n%2<>0 THEN RETURN FALSE; END IF;
 WHILE v_i<v_n LOOP
  v_u:=pg_catalog.get_byte(p_units,v_i)*256+pg_catalog.get_byte(p_units,v_i+1);v_i:=v_i+2;
  IF v_u=0 OR v_u BETWEEN 56320 AND 57343 THEN RETURN FALSE;
  ELSIF v_u BETWEEN 55296 AND 56319 THEN
   IF v_i>=v_n THEN RETURN FALSE; END IF;
   v_low:=pg_catalog.get_byte(p_units,v_i)*256+pg_catalog.get_byte(p_units,v_i+1);
   IF v_low NOT BETWEEN 56320 AND 57343 THEN RETURN FALSE; END IF;
   v_i:=v_i+2;v_bytes:=v_bytes+4;
  ELSE v_bytes:=v_bytes+CASE WHEN v_u<128 THEN 1 WHEN v_u<2048 THEN 2 ELSE 3 END; END IF;
  IF v_bytes>p_max_bytes THEN RETURN FALSE; END IF;
 END LOOP;
 RETURN TRUE;
END $initial_name$;
REVOKE ALL ON FUNCTION public.pro273_initial_name_units_valid(BYTEA,INTEGER) FROM PUBLIC;

-- Data-only canonical UTC validation. This does not qualify parser resources
-- or authorize any caller; fixed-width units avoid timestamp/locale casts.
CREATE FUNCTION public.pro273_initial_utc_units_valid(p_units BYTEA) RETURNS BOOLEAN
LANGUAGE plpgsql IMMUTABLE STRICT SET search_path=pg_catalog AS $initial_utc$
DECLARE v_i INTEGER; v_c INTEGER; v_year INTEGER:=0; v_month INTEGER:=0; v_day INTEGER:=0;
 v_hour INTEGER:=0; v_minute INTEGER:=0; v_second INTEGER:=0; v_days INTEGER;
BEGIN
 IF pg_catalog.octet_length(p_units)<>48 THEN RETURN FALSE; END IF;
 FOR v_i IN 0..23 LOOP
  IF pg_catalog.get_byte(p_units,v_i*2)<>0 THEN RETURN FALSE; END IF;
  v_c:=pg_catalog.get_byte(p_units,v_i*2+1);
  IF v_i IN (4,7) THEN IF v_c<>45 THEN RETURN FALSE; END IF;
  ELSIF v_i=10 THEN IF v_c<>84 THEN RETURN FALSE; END IF;
  ELSIF v_i IN (13,16) THEN IF v_c<>58 THEN RETURN FALSE; END IF;
  ELSIF v_i=19 THEN IF v_c<>46 THEN RETURN FALSE; END IF;
  ELSIF v_i=23 THEN IF v_c<>90 THEN RETURN FALSE; END IF;
  ELSE
   IF v_c NOT BETWEEN 48 AND 57 THEN RETURN FALSE; END IF;v_c:=v_c-48;
   IF v_i<4 THEN v_year:=v_year*10+v_c;
   ELSIF v_i BETWEEN 5 AND 6 THEN v_month:=v_month*10+v_c;
   ELSIF v_i BETWEEN 8 AND 9 THEN v_day:=v_day*10+v_c;
   ELSIF v_i BETWEEN 11 AND 12 THEN v_hour:=v_hour*10+v_c;
   ELSIF v_i BETWEEN 14 AND 15 THEN v_minute:=v_minute*10+v_c;
   ELSIF v_i BETWEEN 17 AND 18 THEN v_second:=v_second*10+v_c; END IF;
  END IF;
 END LOOP;
 IF v_year=0 OR v_month NOT BETWEEN 1 AND 12 OR v_hour>23 OR v_minute>59 OR v_second>59 THEN RETURN FALSE; END IF;
 v_days:=CASE WHEN v_month=2 THEN CASE WHEN v_year%400=0 OR (v_year%4=0 AND v_year%100<>0) THEN 29 ELSE 28 END WHEN v_month IN (4,6,9,11) THEN 30 ELSE 31 END;
 RETURN v_day BETWEEN 1 AND v_days;
END $initial_utc$;
REVOKE ALL ON FUNCTION public.pro273_initial_utc_units_valid(BYTEA) FROM PUBLIC;

-- Canonical fixed-width UTC values sort chronologically as unsigned UTF16BE.
CREATE FUNCTION public.pro273_initial_utc_order_valid(p_from BYTEA,p_until BYTEA) RETURNS BOOLEAN
LANGUAGE plpgsql IMMUTABLE STRICT SET search_path=pg_catalog AS $$
BEGIN
 RETURN public.pro273_initial_utc_units_valid(p_from) AND public.pro273_initial_utc_units_valid(p_until) AND p_from<p_until;
END $$;
REVOKE ALL ON FUNCTION public.pro273_initial_utc_order_valid(BYTEA,BYTEA) FROM PUBLIC;

-- Disconnected field-level prototype, not an envelope validator. Even its
-- input may be toasted: no independent detoast, decoder, serialization, peak,
-- output or work qualification exists for this path. The first statement
-- therefore denies before inspecting either argument. The schema selector is
-- data here; only a future protected binder can authenticate its meaning.
-- Identity/name fields and cross-field ordering still require an authenticated
-- binding and independently qualified resources before the guard can change.
CREATE FUNCTION public.pro273_initial_semantic_field(p_schema INTEGER,p_ordinal INTEGER,p_units BYTEA) RETURNS BOOLEAN
LANGUAGE plpgsql IMMUTABLE SET search_path=pg_catalog AS $initial_semantic$
BEGIN
 RAISE EXCEPTION 'SELECTION_UNAVAILABLE'; -- unconditional missing independent resource proof
 IF p_schema IS NULL OR p_schema NOT IN (1,2) OR p_ordinal IS NULL OR p_units IS NULL OR pg_catalog.octet_length(p_units)=0 OR pg_catalog.octet_length(p_units)%2<>0 THEN RETURN FALSE; END IF;
 IF p_ordinal=0 THEN
  RETURN p_units=public.pro273_installer_ascii_units(CASE p_schema WHEN 1 THEN 'pro273-qualifier-layout-v1' ELSE 'pro273-qualifier-allocation-v1' END);
 ELSIF p_schema=1 AND p_ordinal IN (3,10,11,12) OR p_schema=2 AND p_ordinal IN (5,16,17,18,19,20,21,22) THEN
  RETURN public.pro273_installer_hash_units_valid(p_units);
 ELSIF p_schema=1 AND p_ordinal BETWEEN 4 AND 9 THEN
  RETURN public.pro273_qualifier_numeric_units_valid(p_units,FALSE);
 ELSIF p_schema=2 AND p_ordinal BETWEEN 26 AND 43 THEN
  RETURN public.pro273_qualifier_numeric_units_valid(p_units,TRUE);
 ELSIF p_schema=2 AND p_ordinal BETWEEN 44 AND 52 THEN
  RETURN public.pro273_qualifier_numeric_units_valid(p_units,FALSE);
 ELSIF p_schema=2 AND p_ordinal=7 THEN
  RETURN public.pro273_installer_oid_units_valid(p_units);
 ELSIF p_schema=1 AND p_ordinal IN (13,14) OR p_schema=2 AND p_ordinal IN (53,54) THEN
  RETURN public.pro273_initial_utc_units_valid(p_units);
 END IF;
 RETURN FALSE;
EXCEPTION WHEN OTHERS THEN RAISE EXCEPTION 'SELECTION_UNAVAILABLE'; END $initial_semantic$;
REVOKE ALL ON FUNCTION public.pro273_initial_semantic_field(INTEGER,INTEGER,BYTEA) FROM PUBLIC;

-- Restrict fixed metadata fields to nonempty raw strings prior to JSONB.
CREATE FUNCTION public.pro273_installer_members_are_strings(p_nodes public.pro273_installer_metadata_tokens,p_members INTEGER[],p_except INTEGER[]) RETURNS BOOLEAN
LANGUAGE plpgsql IMMUTABLE SET search_path=pg_catalog AS $$
DECLARE v_i INTEGER; v_node INTEGER;
BEGIN
 IF p_nodes IS NULL OR p_members IS NULL OR p_except IS NULL THEN RETURN FALSE; END IF;
 FOR v_i IN 1..pg_catalog.cardinality(p_members) LOOP
  IF NOT (v_i=ANY(p_except)) THEN v_node:=p_members[v_i];IF p_nodes.kinds[v_node]<>3 OR p_nodes.string_units[v_node] IS NULL OR pg_catalog.octet_length(p_nodes.string_units[v_node])=0 THEN RETURN FALSE; END IF; END IF;
 END LOOP;RETURN TRUE;
EXCEPTION WHEN OTHERS THEN RETURN FALSE; END $$;
REVOKE ALL ON FUNCTION public.pro273_installer_members_are_strings(public.pro273_installer_metadata_tokens,INTEGER[],INTEGER[]) FROM PUBLIC;

-- Pair metadata is checked over raw UTF16 token identities before any body
-- JSONB conversion. Expected hashes come only from the protected context.
CREATE FUNCTION public.pro273_installer_parse_pair_metadata(p_expectation_id TEXT,p_captured BYTEA) RETURNS JSONB
LANGUAGE plpgsql SECURITY DEFINER SET search_path=pg_catalog AS $$
DECLARE v_context JSONB; v_limits JSONB; v_nodes public.pro273_installer_metadata_tokens;
 v_envelope INTEGER[]; v_pair INTEGER[]; v_schedule INTEGER[]; v_grant INTEGER[]; v_spec INTEGER[]; v_parser INTEGER[]; v_sub INTEGER[];
 v_i INTEGER; v_j INTEGER; v_node INTEGER; v_count INTEGER; v_body_count INTEGER:=0; v_worker_scope INTEGER[]; v_len INTEGER; v_units BYTEA; v_ascii BYTEA; v_raw BYTEA; v_canonical BYTEA;
 v_target BYTEA; v_target_hash TEXT; v_schedule_hash TEXT; v_grant_hash TEXT; v_pair_hash TEXT; v_base64 TEXT; v_evidence BYTEA; v_pair_record JSONB; v_workspace NUMERIC; v_evidence_max NUMERIC; v_need NUMERIC;
BEGIN
 v_context:=public.pro273_installer_metadata_context(p_expectation_id);v_limits:=v_context->'limits';
 IF v_context->>'constructorKind' IS DISTINCT FROM 'INVOCATION_SCHEDULE_GRANT_PAIR' OR p_captured IS NULL THEN RAISE EXCEPTION 'SELECTION_UNAVAILABLE'; END IF;
 v_len:=pg_catalog.octet_length(p_captured);v_workspace:=(v_limits->>'maxParserWorkspaceBytes')::NUMERIC;v_evidence_max:=(v_limits->>'maxDecodedEvidenceBytes')::NUMERIC;
 -- Both retained outer tokens and nested canonicalization/capture/evidence
 -- copies are charged together; allocator overhead remains separately qualified.
 v_need:=4::NUMERIC*v_len*(8::NUMERIC*pg_catalog.pg_column_size(ARRAY[0::INTEGER])+2::NUMERIC*pg_catalog.pg_column_size(ARRAY[0::BIGINT])+4::NUMERIC*pg_catalog.pg_column_size(ARRAY[''::BYTEA]))+80::NUMERIC*v_len+4::NUMERIC*v_evidence_max+6::NUMERIC*pg_catalog.pg_column_size(p_captured);
 IF v_len=0 OR v_len::NUMERIC>(v_limits->>'maxInputBytes')::NUMERIC OR v_need>v_workspace THEN RAISE EXCEPTION 'SELECTION_UNAVAILABLE'; END IF;
 v_nodes:=public.pro273_installer_metadata_tokenize(p_expectation_id,p_captured);v_count:=pg_catalog.cardinality(v_nodes.kinds);
 IF v_count IS NULL OR v_count=0 OR v_nodes.parents[1]<>0 THEN RAISE EXCEPTION 'SELECTION_UNAVAILABLE'; END IF;
 v_envelope:=public.pro273_installer_object_members(p_expectation_id,v_nodes,1,ARRAY['core','evidenceBase64']);
 IF v_nodes.kinds[v_envelope[1]]<>1 OR v_nodes.kinds[v_envelope[2]]<>3 THEN RAISE EXCEPTION 'SELECTION_UNAVAILABLE'; END IF;
 v_pair:=public.pro273_installer_object_members(p_expectation_id,v_nodes,v_envelope[1],ARRAY['schemaVersion','pairId','scheduleCore','grantCore']);
 IF public.pro273_installer_members_are_strings(v_nodes,v_pair,ARRAY[3,4]) IS DISTINCT FROM TRUE OR v_nodes.string_units[v_pair[1]] IS DISTINCT FROM public.pro273_installer_ascii_units('pro273-invocation-schedule-grant-pair-v1') OR v_nodes.kinds[v_pair[3]]<>1 OR v_nodes.kinds[v_pair[4]]<>1 THEN RAISE EXCEPTION 'SELECTION_UNAVAILABLE'; END IF;
 v_schedule:=public.pro273_installer_object_members(p_expectation_id,v_nodes,v_pair[3],ARRAY['id','resourceScheduleId','resourceScheduleGeneration','resourceScheduleCoreHash','domainId','domainGeneration','resourceEnvelopeCoreHash','operation','branch','receiverIdentity','receiverPrincipalOid','receiverPrincipalName','credentialEpoch','launchEpoch','sourceClosureHash','installationClosureHash','parserAuthority','invocationCount','bodyCount','validFrom','validUntil','debitGrantId','bodySpecs']);
 v_grant:=public.pro273_installer_object_members(p_expectation_id,v_nodes,v_pair[4],ARRAY['grantId','scheduleId','scheduleCoreHash','claimantScopeKind','claimantScopeId','claimantAllocationCoreHash','claimantPrincipalOid','claimantCredentialEpoch','claimantLaunchEpoch','workerScopeKind','workerScopeId','workerScopeCoreHash','operation','branch','controlBaselineKind','maxInvocations','sourceClosureHash','installationClosureHash','physicalIdentity','physicalProofIdentity','validFrom','validUntil']);
 IF public.pro273_installer_members_are_strings(v_nodes,v_schedule,ARRAY[17,23]) IS DISTINCT FROM TRUE OR public.pro273_installer_members_are_strings(v_nodes,v_grant,ARRAY[]::INTEGER[]) IS DISTINCT FROM TRUE OR v_nodes.kinds[v_schedule[17]]<>1 OR v_nodes.kinds[v_schedule[23]]<>2 OR v_nodes.string_units[v_schedule[1]] IS DISTINCT FROM v_nodes.string_units[v_grant[2]] OR v_nodes.string_units[v_schedule[22]] IS DISTINCT FROM v_nodes.string_units[v_grant[1]] THEN RAISE EXCEPTION 'SELECTION_UNAVAILABLE'; END IF;
 FOREACH v_i IN ARRAY ARRAY[3,6,18,19] LOOP IF public.pro273_installer_positive_bigint_units_valid(v_nodes.string_units[v_schedule[v_i]]) IS DISTINCT FROM TRUE THEN RAISE EXCEPTION 'SELECTION_UNAVAILABLE'; END IF; END LOOP;
 IF public.pro273_installer_oid_units_valid(v_nodes.string_units[v_schedule[11]]) IS DISTINCT FROM TRUE OR public.pro273_installer_oid_units_valid(v_nodes.string_units[v_grant[7]]) IS DISTINCT FROM TRUE OR public.pro273_installer_positive_bigint_units_valid(v_nodes.string_units[v_grant[16]]) IS DISTINCT FROM TRUE THEN RAISE EXCEPTION 'SELECTION_UNAVAILABLE'; END IF;
 FOREACH v_i IN ARRAY ARRAY[4,7,15,16] LOOP IF public.pro273_installer_hash_units_valid(v_nodes.string_units[v_schedule[v_i]]) IS DISTINCT FROM TRUE THEN RAISE EXCEPTION 'SELECTION_UNAVAILABLE'; END IF; END LOOP;
 FOREACH v_i IN ARRAY ARRAY[3,6,12,17,18] LOOP IF public.pro273_installer_hash_units_valid(v_nodes.string_units[v_grant[v_i]]) IS DISTINCT FROM TRUE THEN RAISE EXCEPTION 'SELECTION_UNAVAILABLE'; END IF; END LOOP;
 IF pg_catalog.octet_length(v_nodes.string_units[v_schedule[18]])>pg_catalog.octet_length(v_nodes.string_units[v_grant[16]]) OR (pg_catalog.octet_length(v_nodes.string_units[v_schedule[18]])=pg_catalog.octet_length(v_nodes.string_units[v_grant[16]]) AND v_nodes.string_units[v_schedule[18]]>v_nodes.string_units[v_grant[16]]) THEN RAISE EXCEPTION 'SELECTION_UNAVAILABLE'; END IF;
 IF v_nodes.string_units[v_schedule[8]] IS DISTINCT FROM v_nodes.string_units[v_grant[13]] OR v_nodes.string_units[v_schedule[9]] IS DISTINCT FROM v_nodes.string_units[v_grant[14]] OR v_nodes.string_units[v_schedule[15]] IS DISTINCT FROM v_nodes.string_units[v_grant[17]] OR v_nodes.string_units[v_schedule[16]] IS DISTINCT FROM v_nodes.string_units[v_grant[18]] OR public.pro273_installer_metadata_quote(p_expectation_id,v_nodes.string_units[v_grant[19]]) IS DISTINCT FROM pg_catalog.convert_to(pg_catalog.to_jsonb(v_context->>'physicalIdentity')::TEXT,'UTF8') OR public.pro273_installer_metadata_quote(p_expectation_id,v_nodes.string_units[v_grant[20]]) IS DISTINCT FROM pg_catalog.convert_to(pg_catalog.to_jsonb(v_context->>'physicalProofIdentity')::TEXT,'UTF8') THEN RAISE EXCEPTION 'SELECTION_UNAVAILABLE'; END IF;
 -- Parser authority is one closed source-selected variant; nested records have
 -- fixed names and string fields, with distinct worker/claimant scope IDs.
 v_node:=v_schedule[17];v_parser:=NULL;
 IF v_node<v_count THEN FOR v_i IN (v_node+1)..v_count LOOP IF v_nodes.parents[v_i]=v_node AND v_nodes.key_units[v_i]=public.pro273_installer_ascii_units('kind') THEN v_j:=v_i; END IF; END LOOP; END IF;
 IF v_j IS NULL OR v_nodes.kinds[v_j]<>3 THEN RAISE EXCEPTION 'SELECTION_UNAVAILABLE'; END IF;
 IF v_nodes.string_units[v_j]=public.pro273_installer_ascii_units('QUALIFIED_PRIMITIVE') THEN
  v_parser:=public.pro273_installer_object_members(p_expectation_id,v_nodes,v_node,ARRAY['kind','profileId','generation','recordHash']);
  IF public.pro273_installer_members_are_strings(v_nodes,v_parser,ARRAY[]::INTEGER[]) IS DISTINCT FROM TRUE OR public.pro273_installer_positive_bigint_units_valid(v_nodes.string_units[v_parser[3]]) IS DISTINCT FROM TRUE OR public.pro273_installer_hash_units_valid(v_nodes.string_units[v_parser[4]]) IS DISTINCT FROM TRUE THEN RAISE EXCEPTION 'SELECTION_UNAVAILABLE'; END IF;
 ELSIF v_nodes.string_units[v_j]=public.pro273_installer_ascii_units('BOOTSTRAP_PROFILE_HASH') THEN
  v_parser:=public.pro273_installer_object_members(p_expectation_id,v_nodes,v_node,ARRAY['kind','parserAbiVersion','parserSourceClosureHash','semanticDomainHash','resourceEnvelopeId','resourceEnvelopeGeneration','resourceEnvelopeCoreHash','workerScope','claimantFundingRef','bootstrapGrantId','expectedPublicationCoreHash','installedExpectedClosureHash']);
  IF public.pro273_installer_members_are_strings(v_nodes,v_parser,ARRAY[8,9]) IS DISTINCT FROM TRUE OR public.pro273_installer_positive_bigint_units_valid(v_nodes.string_units[v_parser[6]]) IS DISTINCT FROM TRUE THEN RAISE EXCEPTION 'SELECTION_UNAVAILABLE'; END IF;
  v_worker_scope:=public.pro273_installer_object_members(p_expectation_id,v_nodes,v_parser[8],ARRAY['kind','controlId','descriptorCoreHash','allocationId','allocationCoreHash']);
  IF public.pro273_installer_members_are_strings(v_nodes,v_worker_scope,ARRAY[]::INTEGER[]) IS DISTINCT FROM TRUE OR v_nodes.string_units[v_worker_scope[1]] IS DISTINCT FROM public.pro273_installer_ascii_units('QUALIFIER_CONTROL') OR public.pro273_installer_hash_units_valid(v_nodes.string_units[v_worker_scope[3]]) IS DISTINCT FROM TRUE OR public.pro273_installer_hash_units_valid(v_nodes.string_units[v_worker_scope[5]]) IS DISTINCT FROM TRUE THEN RAISE EXCEPTION 'SELECTION_UNAVAILABLE'; END IF;
  v_sub:=public.pro273_installer_object_members(p_expectation_id,v_nodes,v_parser[9],ARRAY['kind','controlId','allocationId','allocationCoreHash','descriptorCoreHash','principalOid','credentialEpoch','launchEpoch']);
  IF public.pro273_installer_members_are_strings(v_nodes,v_sub,ARRAY[]::INTEGER[]) IS DISTINCT FROM TRUE OR v_nodes.string_units[v_sub[1]] IS DISTINCT FROM public.pro273_installer_ascii_units('QUALIFIER_ALLOCATION') OR public.pro273_installer_oid_units_valid(v_nodes.string_units[v_sub[6]]) IS DISTINCT FROM TRUE OR public.pro273_installer_hash_units_valid(v_nodes.string_units[v_sub[4]]) IS DISTINCT FROM TRUE OR public.pro273_installer_hash_units_valid(v_nodes.string_units[v_sub[5]]) IS DISTINCT FROM TRUE OR v_nodes.string_units[v_worker_scope[2]]=v_nodes.string_units[v_sub[2]] OR v_nodes.string_units[v_worker_scope[4]]=v_nodes.string_units[v_sub[3]] THEN RAISE EXCEPTION 'SELECTION_UNAVAILABLE'; END IF;
  FOREACH v_i IN ARRAY ARRAY[3,4,7,11,12] LOOP IF public.pro273_installer_hash_units_valid(v_nodes.string_units[v_parser[v_i]]) IS DISTINCT FROM TRUE THEN RAISE EXCEPTION 'SELECTION_UNAVAILABLE'; END IF; END LOOP;
 ELSE RAISE EXCEPTION 'SELECTION_UNAVAILABLE'; END IF;
 v_node:=v_schedule[23];IF v_node<v_count THEN FOR v_i IN (v_node+1)..v_count LOOP
  IF v_nodes.parents[v_i]=v_node THEN
   v_body_count:=v_body_count+1;IF v_nodes.ordinals[v_i]<>v_body_count-1 THEN RAISE EXCEPTION 'SELECTION_UNAVAILABLE'; END IF;
   v_spec:=public.pro273_installer_object_members(p_expectation_id,v_nodes,v_i,ARRAY['bodyOrdinal','role','sourceIdentity','sourceReference','multiplicityOrdinal','bindingMode','derivationRule','maxCatalogEvents','maxDurableBytes']);
   IF public.pro273_installer_members_are_strings(v_nodes,v_spec,ARRAY[]::INTEGER[]) IS DISTINCT FROM TRUE THEN RAISE EXCEPTION 'SELECTION_UNAVAILABLE'; END IF;
   FOREACH v_j IN ARRAY ARRAY[1,5] LOOP IF public.pro273_installer_positive_bigint_units_valid(v_nodes.string_units[v_spec[v_j]]) IS DISTINCT FROM TRUE THEN RAISE EXCEPTION 'SELECTION_UNAVAILABLE'; END IF; END LOOP;
   FOREACH v_j IN ARRAY ARRAY[8,9] LOOP IF public.pro273_installer_decimal_units_valid(v_nodes.string_units[v_spec[v_j]]) IS DISTINCT FROM TRUE OR v_nodes.string_units[v_spec[v_j]]=public.pro273_installer_ascii_units('0') THEN RAISE EXCEPTION 'SELECTION_UNAVAILABLE'; END IF; END LOOP;
   IF v_nodes.string_units[v_spec[1]] IS DISTINCT FROM public.pro273_installer_ascii_units(v_body_count::TEXT) THEN RAISE EXCEPTION 'SELECTION_UNAVAILABLE'; END IF;
  END IF;
 END LOOP; END IF;
 IF v_body_count=0 OR v_nodes.string_units[v_schedule[19]] IS DISTINCT FROM public.pro273_installer_ascii_units(v_body_count::TEXT) THEN RAISE EXCEPTION 'SELECTION_UNAVAILABLE'; END IF;
 -- Pair target is derived solely from preregistered schedule/grant IDs.
 v_target:=pg_catalog.convert_to('["pro273.invocation.schedule-grant-pair.target.v1",{"grantId":','UTF8')||public.pro273_installer_metadata_quote(p_expectation_id,v_nodes.string_units[v_grant[1]])||pg_catalog.convert_to(',"scheduleId":','UTF8')||public.pro273_installer_metadata_quote(p_expectation_id,v_nodes.string_units[v_schedule[1]])||pg_catalog.convert_to('}]','UTF8');
 v_target_hash:=pg_catalog.encode(int4_crypto.digest(v_target,'sha256'),'hex');v_target:=NULL;
 IF v_nodes.string_units[v_pair[2]] IS DISTINCT FROM public.pro273_installer_ascii_units(v_target_hash) OR v_target_hash IS DISTINCT FROM v_context->>'expectedTargetId' THEN RAISE EXCEPTION 'SELECTION_UNAVAILABLE'; END IF;
 v_raw:=pg_catalog.substring(p_captured,v_nodes.starts[v_pair[3]]+1,v_nodes.ends[v_pair[3]]-v_nodes.starts[v_pair[3]]);v_canonical:=public.pro273_installer_metadata_canonical(p_expectation_id,v_raw);
 v_schedule_hash:=pg_catalog.encode(int4_crypto.digest(pg_catalog.convert_to('["pro273.invocation.schedule.core.v1",','UTF8')||v_canonical||pg_catalog.convert_to(']','UTF8'),'sha256'),'hex');v_raw:=NULL;v_canonical:=NULL;
 IF v_nodes.string_units[v_grant[3]] IS DISTINCT FROM public.pro273_installer_ascii_units(v_schedule_hash) THEN RAISE EXCEPTION 'SELECTION_UNAVAILABLE'; END IF;
 v_raw:=pg_catalog.substring(p_captured,v_nodes.starts[v_pair[4]]+1,v_nodes.ends[v_pair[4]]-v_nodes.starts[v_pair[4]]);v_canonical:=public.pro273_installer_metadata_canonical(p_expectation_id,v_raw);
 v_grant_hash:=pg_catalog.encode(int4_crypto.digest(pg_catalog.convert_to('["pro273.invocation.debit-grant.core.v1",','UTF8')||v_canonical||pg_catalog.convert_to(']','UTF8'),'sha256'),'hex');v_raw:=NULL;v_canonical:=NULL;
 v_raw:=pg_catalog.substring(p_captured,v_nodes.starts[v_envelope[1]]+1,v_nodes.ends[v_envelope[1]]-v_nodes.starts[v_envelope[1]]);v_canonical:=public.pro273_installer_metadata_canonical(p_expectation_id,v_raw);
 v_pair_hash:=pg_catalog.encode(int4_crypto.digest(pg_catalog.convert_to('["pro273.invocation.schedule-grant-pair.core.v1",','UTF8')||v_canonical||pg_catalog.convert_to(']','UTF8'),'sha256'),'hex');
 IF v_pair_hash IS DISTINCT FROM v_context->>'expectedCoreHash' THEN RAISE EXCEPTION 'SELECTION_UNAVAILABLE'; END IF;
 v_units:=v_nodes.string_units[v_envelope[2]];IF pg_catalog.octet_length(v_units)=0 OR pg_catalog.octet_length(v_units)%2<>0 OR (pg_catalog.octet_length(v_units)/2)::NUMERIC>4::NUMERIC*pg_catalog.ceil(v_evidence_max/3::NUMERIC) THEN RAISE EXCEPTION 'SELECTION_UNAVAILABLE'; END IF;
 v_ascii:=''::BYTEA;FOR v_i IN 0..(pg_catalog.octet_length(v_units)/2-1) LOOP IF pg_catalog.get_byte(v_units,v_i*2)<>0 OR NOT (pg_catalog.get_byte(v_units,v_i*2+1) BETWEEN 65 AND 90 OR pg_catalog.get_byte(v_units,v_i*2+1) BETWEEN 97 AND 122 OR pg_catalog.get_byte(v_units,v_i*2+1) BETWEEN 48 AND 57 OR pg_catalog.get_byte(v_units,v_i*2+1) IN (43,47,61)) THEN RAISE EXCEPTION 'SELECTION_UNAVAILABLE'; END IF;v_ascii:=v_ascii||pg_catalog.substring(v_units,v_i*2+2,1); END LOOP;
 v_base64:=pg_catalog.convert_from(v_ascii,'UTF8');v_evidence:=pg_catalog.decode(v_base64,'base64');
 IF pg_catalog.octet_length(v_evidence)=0 OR pg_catalog.octet_length(v_evidence)::NUMERIC>v_evidence_max OR pg_catalog.replace(pg_catalog.encode(v_evidence,'base64'),E'\n','') IS DISTINCT FROM v_base64 OR pg_catalog.encode(int4_crypto.digest(v_evidence,'sha256'),'hex') IS DISTINCT FROM v_context->>'expectedEvidenceHash' THEN RAISE EXCEPTION 'SELECTION_UNAVAILABLE'; END IF;
 v_pair_record:=pg_catalog.convert_from(v_canonical,'UTF8')::JSONB;
 RETURN pg_catalog.jsonb_build_object('core',v_pair_record,'evidenceBase64',v_base64,'scheduleCoreHash',v_schedule_hash,'grantCoreHash',v_grant_hash,'pairCoreHash',v_pair_hash);
EXCEPTION WHEN OTHERS THEN RAISE EXCEPTION 'SELECTION_UNAVAILABLE'; END $$;
REVOKE ALL ON FUNCTION public.pro273_installer_parse_pair_metadata(TEXT,BYTEA) FROM PUBLIC;

-- The descriptor envelope is the only constructor ABI that rejects decoded
-- duplicate keys. Validate its two closed objects before any JSONB conversion.
CREATE FUNCTION public.pro273_installer_parse_descriptor_metadata(p_expectation_id TEXT,p_captured BYTEA) RETURNS JSONB
LANGUAGE plpgsql SECURITY DEFINER SET search_path=pg_catalog AS $$
DECLARE v_context JSONB; v_limits JSONB; v_nodes public.pro273_installer_metadata_tokens;
 v_envelope INTEGER[]; v_core INTEGER[]; v_len INTEGER; v_i INTEGER; v_units BYTEA; v_ascii BYTEA;
 v_raw BYTEA; v_canonical BYTEA; v_hash TEXT; v_base64 TEXT; v_evidence BYTEA; v_record JSONB; v_proof JSONB;
 v_workspace NUMERIC; v_evidence_max NUMERIC; v_need NUMERIC; v_expiry TIMESTAMPTZ;
BEGIN
 v_context:=public.pro273_installer_metadata_context(p_expectation_id);v_limits:=v_context->'limits';
 IF v_context->>'constructorKind' IS DISTINCT FROM 'QUALIFIER_DESCRIPTOR' OR p_captured IS NULL THEN RAISE EXCEPTION 'SELECTION_UNAVAILABLE'; END IF;
 v_len:=pg_catalog.octet_length(p_captured);v_workspace:=(v_limits->>'maxParserWorkspaceBytes')::NUMERIC;v_evidence_max:=(v_limits->>'maxDecodedEvidenceBytes')::NUMERIC;
 v_need:=4::NUMERIC*v_len*(8::NUMERIC*pg_catalog.pg_column_size(ARRAY[0::INTEGER])+2::NUMERIC*pg_catalog.pg_column_size(ARRAY[0::BIGINT])+4::NUMERIC*pg_catalog.pg_column_size(ARRAY[''::BYTEA]))+80::NUMERIC*v_len+4::NUMERIC*v_evidence_max+6::NUMERIC*pg_catalog.pg_column_size(p_captured);
 IF v_len=0 OR v_len::NUMERIC>(v_limits->>'maxInputBytes')::NUMERIC OR v_need>v_workspace THEN RAISE EXCEPTION 'SELECTION_UNAVAILABLE'; END IF;
 v_nodes:=public.pro273_installer_metadata_tokenize(p_expectation_id,p_captured);
 IF pg_catalog.cardinality(v_nodes.kinds) IS NULL OR v_nodes.parents[1]<>0 OR v_nodes.kinds[1]<>1 THEN RAISE EXCEPTION 'SELECTION_UNAVAILABLE'; END IF;
 v_envelope:=public.pro273_installer_unique_object_members(p_expectation_id,v_nodes,1,ARRAY['core','observerGroupProof','evidenceBase64']);
 IF v_nodes.kinds[v_envelope[1]]<>1 OR public.pro273_installer_members_are_strings(v_nodes,v_envelope,ARRAY[1]) IS DISTINCT FROM TRUE THEN RAISE EXCEPTION 'SELECTION_UNAVAILABLE'; END IF;
 v_core:=public.pro273_installer_unique_object_members(p_expectation_id,v_nodes,v_envelope[1],ARRAY['allocationCoreHash','allocationId','baselinePartitionId','controlId','credentialEpoch','deployment','environment','expiresAt','launchEpoch','namespace','physicalIdentity','physicalProofIdentity','principalName','principalOid','project','schemaVersion','sourceIdentity']);
 IF public.pro273_installer_members_are_strings(v_nodes,v_core,ARRAY[]::INTEGER[]) IS DISTINCT FROM TRUE OR
    v_nodes.string_units[v_core[16]] IS DISTINCT FROM public.pro273_installer_ascii_units('pro273-qualifier-descriptor-core-v1') OR
    public.pro273_installer_hash_units_valid(v_nodes.string_units[v_core[1]]) IS DISTINCT FROM TRUE OR
    public.pro273_installer_oid_units_valid(v_nodes.string_units[v_core[14]]) IS DISTINCT FROM TRUE OR
    public.pro273_installer_metadata_quote(p_expectation_id,v_nodes.string_units[v_core[4]]) IS DISTINCT FROM pg_catalog.convert_to(pg_catalog.to_jsonb(v_context->>'expectedTargetId')::TEXT,'UTF8') THEN RAISE EXCEPTION 'SELECTION_UNAVAILABLE'; END IF;
 v_units:=v_nodes.string_units[v_envelope[3]];
 IF pg_catalog.octet_length(v_units)=0 OR pg_catalog.octet_length(v_units)%2<>0 OR (pg_catalog.octet_length(v_units)/2)::NUMERIC>4::NUMERIC*pg_catalog.ceil(v_evidence_max/3::NUMERIC) THEN RAISE EXCEPTION 'SELECTION_UNAVAILABLE'; END IF;
 v_ascii:=''::BYTEA;FOR v_i IN 0..(pg_catalog.octet_length(v_units)/2-1) LOOP
  IF pg_catalog.get_byte(v_units,v_i*2)<>0 OR NOT (pg_catalog.get_byte(v_units,v_i*2+1) BETWEEN 65 AND 90 OR pg_catalog.get_byte(v_units,v_i*2+1) BETWEEN 97 AND 122 OR pg_catalog.get_byte(v_units,v_i*2+1) BETWEEN 48 AND 57 OR pg_catalog.get_byte(v_units,v_i*2+1) IN (43,47,61)) THEN RAISE EXCEPTION 'SELECTION_UNAVAILABLE'; END IF;
  v_ascii:=v_ascii||pg_catalog.substring(v_units,v_i*2+2,1);
 END LOOP;
 v_base64:=pg_catalog.convert_from(v_ascii,'UTF8');v_evidence:=pg_catalog.decode(v_base64,'base64');
 IF pg_catalog.octet_length(v_evidence)=0 OR pg_catalog.octet_length(v_evidence)::NUMERIC>v_evidence_max OR pg_catalog.replace(pg_catalog.encode(v_evidence,'base64'),E'\n','') IS DISTINCT FROM v_base64 OR pg_catalog.encode(int4_crypto.digest(v_evidence,'sha256'),'hex') IS DISTINCT FROM v_context->>'expectedEvidenceHash' THEN RAISE EXCEPTION 'SELECTION_UNAVAILABLE'; END IF;
 v_raw:=pg_catalog.substring(p_captured,v_nodes.starts[v_envelope[1]]+1,v_nodes.ends[v_envelope[1]]-v_nodes.starts[v_envelope[1]]);
 v_canonical:=public.pro273_installer_metadata_canonical(p_expectation_id,v_raw);
 v_hash:=pg_catalog.encode(int4_crypto.digest(pg_catalog.convert_to('["pro273.qualifier.descriptor.core.v1",','UTF8')||v_canonical||pg_catalog.convert_to(']','UTF8'),'sha256'),'hex');
 IF v_hash IS DISTINCT FROM v_context->>'expectedCoreHash' THEN RAISE EXCEPTION 'SELECTION_UNAVAILABLE'; END IF;
 -- JSONB and NAME round trips reject NUL, lone surrogates and truncation.
 v_record:=pg_catalog.convert_from(v_canonical,'UTF8')::JSONB;
 v_proof:=pg_catalog.convert_from(public.pro273_installer_metadata_quote(p_expectation_id,v_nodes.string_units[v_envelope[2]]),'UTF8')::JSONB;
 IF v_record->>'principalName' IS DISTINCT FROM (v_record->>'principalName')::NAME::TEXT OR
    v_record->>'namespace'='*' OR v_record->>'project'='*' OR v_record->>'deployment'='*' OR v_record->>'environment'='*' OR
    v_record->>'expiresAt' !~ '^[0-9]{4}-[0-9]{2}-[0-9]{2}T[0-9]{2}:[0-9]{2}:[0-9]{2}\.[0-9]{3}Z$' OR pg_catalog.substring(v_record->>'expiresAt',1,4)='0000' THEN RAISE EXCEPTION 'SELECTION_UNAVAILABLE'; END IF;
 v_expiry:=(v_record->>'expiresAt')::TIMESTAMPTZ;
 IF pg_catalog.to_char(v_expiry AT TIME ZONE 'UTC','YYYY-MM-DD"T"HH24:MI:SS.MS"Z"') IS DISTINCT FROM v_record->>'expiresAt' THEN RAISE EXCEPTION 'SELECTION_UNAVAILABLE'; END IF;
 RETURN pg_catalog.jsonb_build_object('core',v_record,'observerGroupProof',v_proof,'evidenceBase64',v_base64,'descriptorCoreHash',v_hash);
EXCEPTION WHEN OTHERS THEN RAISE EXCEPTION 'SELECTION_UNAVAILABLE'; END $$;
REVOKE ALL ON FUNCTION public.pro273_installer_parse_descriptor_metadata(TEXT,BYTEA) FROM PUBLIC;

-- Resolve last-value raw nodes, validate the fixed baseline schema and verify
-- core/evidence before any conversion of the captured core to JSONB.
CREATE FUNCTION public.pro273_installer_parse_metadata(p_expectation_id TEXT,p_captured BYTEA) RETURNS JSONB
LANGUAGE plpgsql SECURITY DEFINER SET search_path=pg_catalog AS $$
DECLARE v_context JSONB; v_limits JSONB; v_nodes public.pro273_installer_metadata_tokens; v_keys TEXT[]:=ARRAY['schemaVersion','baselineId','purpose','physicalIdentity','physicalProofIdentity','sourceClosureHash','installationClosureHash','expectedFutureLayoutCoreHash','principalOid','principalName','credentialEpoch','launchEpoch','host','boot','processTree','parentProcessTree','reservedBackendBytes','reservedSharedBytes','reservedTemporaryBytes','maxInputBytes','maxOutputBytes','maxAllocationBytes','stackBytes','parentBytes','maxProcessCount','maxBackendCount','maxLaunchAttempts','maxEvents','backendProcessBytes','qualifierRuntimeBytes','launcherSupervisorBytes','retainedParentBytes','driverSocketIpcBytes','inputEvidenceSerializationBytes','primitiveParserCacheBytes','rollbackCleanupBytes','sharedRuntimeBytes','validFrom','validUntil']; v_winners INTEGER[]:=ARRAY[]::INTEGER[];
 v_i INTEGER; v_j INTEGER; v_count INTEGER; v_core INTEGER:=0; v_evidence_node INTEGER:=0; v_found INTEGER; v_len INTEGER; v_units BYTEA; v_ascii BYTEA; v_base64 TEXT; v_evidence BYTEA;
 v_expected public."Pro273ControlPlaneInstallerExpectation"%ROWTYPE; v_raw_core BYTEA; v_canonical BYTEA; v_hash TEXT; v_record JSONB; v_workspace NUMERIC; v_need NUMERIC; v_evidence_max NUMERIC; v_input_length NUMERIC;
BEGIN
 IF p_expectation_id IS NULL OR p_captured IS NULL THEN RAISE EXCEPTION 'SELECTION_UNAVAILABLE'; END IF;
 v_context:=public.pro273_installer_metadata_context(p_expectation_id);v_limits:=v_context->'limits';
 IF v_context->>'constructorKind'='INVOCATION_SCHEDULE_GRANT_PAIR' THEN RETURN public.pro273_installer_parse_pair_metadata(p_expectation_id,p_captured); END IF;
 IF v_context->>'constructorKind'='QUALIFIER_DESCRIPTOR' THEN RETURN public.pro273_installer_parse_descriptor_metadata(p_expectation_id,p_captured); END IF;
 IF v_context->>'constructorKind' IS DISTINCT FROM 'CONTROL_PLANE_BASELINE' THEN RAISE EXCEPTION 'SELECTION_UNAVAILABLE'; END IF;
 SELECT e.* INTO STRICT v_expected FROM public."Pro273ControlPlaneInstallerExpectation" e WHERE e."expectationId"=p_expectation_id FOR SHARE NOWAIT;
 v_len:=pg_catalog.octet_length(p_captured);v_input_length:=v_len::NUMERIC;v_workspace:=(v_limits->>'maxParserWorkspaceBytes')::NUMERIC;v_evidence_max:=(v_limits->>'maxDecodedEvidenceBytes')::NUMERIC;
 -- Reserve both outer-token and inner-canonicalization representations and
 -- evidence/JSONB copies together; runtime overhead remains independently
 -- qualified by the actual installer source and holder proof.
 v_need:=4::NUMERIC*v_input_length*(8::NUMERIC*pg_catalog.pg_column_size(ARRAY[0::INTEGER])+2::NUMERIC*pg_catalog.pg_column_size(ARRAY[0::BIGINT])+4::NUMERIC*pg_catalog.pg_column_size(ARRAY[''::BYTEA]))+80::NUMERIC*v_input_length+4::NUMERIC*v_evidence_max+6::NUMERIC*pg_catalog.pg_column_size(p_captured);
 IF v_len=0 OR v_input_length>(v_limits->>'maxInputBytes')::NUMERIC OR v_need>v_workspace THEN RAISE EXCEPTION 'SELECTION_UNAVAILABLE'; END IF;
 v_nodes:=public.pro273_installer_metadata_tokenize(p_expectation_id,p_captured);v_count:=pg_catalog.cardinality(v_nodes.kinds);
 IF v_count IS NULL OR v_count=0 OR v_nodes.kinds[1]<>1 OR v_nodes.parents[1]<>0 THEN RAISE EXCEPTION 'SELECTION_UNAVAILABLE'; END IF;
 FOR v_i IN 2..v_count LOOP
  IF v_nodes.parents[v_i]=1 THEN
   IF v_nodes.key_units[v_i]=public.pro273_installer_ascii_units('core') THEN v_core:=v_i;
   ELSIF v_nodes.key_units[v_i]=public.pro273_installer_ascii_units('evidenceBase64') THEN v_evidence_node:=v_i;
   ELSE RAISE EXCEPTION 'SELECTION_UNAVAILABLE'; END IF;
  END IF;
 END LOOP;
 IF v_core=0 OR v_evidence_node=0 OR v_nodes.kinds[v_core]<>1 OR v_nodes.kinds[v_evidence_node]<>3 THEN RAISE EXCEPTION 'SELECTION_UNAVAILABLE'; END IF;
 FOR v_i IN 1..39 LOOP v_winners[v_i]:=0; END LOOP;
 IF v_core<v_count THEN FOR v_i IN (v_core+1)..v_count LOOP
  IF v_nodes.parents[v_i]=v_core THEN
   v_found:=0;FOR v_j IN 1..39 LOOP IF v_nodes.key_units[v_i]=public.pro273_installer_ascii_units(v_keys[v_j]) THEN v_found:=v_j;EXIT; END IF; END LOOP;
   IF v_found=0 THEN RAISE EXCEPTION 'SELECTION_UNAVAILABLE'; END IF;v_winners[v_found]:=v_i;
  END IF;
 END LOOP; END IF;
 FOR v_j IN 1..39 LOOP
  IF v_winners[v_j]=0 OR v_nodes.kinds[v_winners[v_j]]<>3 OR pg_catalog.octet_length(v_nodes.string_units[v_winners[v_j]])=0 THEN RAISE EXCEPTION 'SELECTION_UNAVAILABLE'; END IF;
 END LOOP;
 IF v_nodes.string_units[v_winners[1]] IS DISTINCT FROM public.pro273_installer_ascii_units('pro273-control-plane-baseline-v1') OR
    public.pro273_installer_metadata_quote(p_expectation_id,v_nodes.string_units[v_winners[2]]) IS DISTINCT FROM pg_catalog.convert_to(pg_catalog.to_jsonb(v_context->>'expectedTargetId')::TEXT,'UTF8') OR
    (v_nodes.string_units[v_winners[3]] IS DISTINCT FROM public.pro273_installer_ascii_units('QUALIFIER_BASELINE_INITIAL') AND v_nodes.string_units[v_winners[3]] IS DISTINCT FROM public.pro273_installer_ascii_units('SELECTION_PROFILE_REVOKE')) OR
    public.pro273_installer_metadata_quote(p_expectation_id,v_nodes.string_units[v_winners[4]]) IS DISTINCT FROM pg_catalog.convert_to(pg_catalog.to_jsonb(v_context->>'physicalIdentity')::TEXT,'UTF8') OR
    public.pro273_installer_metadata_quote(p_expectation_id,v_nodes.string_units[v_winners[5]]) IS DISTINCT FROM pg_catalog.convert_to(pg_catalog.to_jsonb(v_context->>'physicalProofIdentity')::TEXT,'UTF8') OR
    v_nodes.string_units[v_winners[6]] IS DISTINCT FROM public.pro273_installer_ascii_units(v_context->>'sourceClosureHash') OR v_nodes.string_units[v_winners[7]] IS DISTINCT FROM public.pro273_installer_ascii_units(v_context->>'installationClosureHash') OR v_nodes.string_units[v_winners[8]] IS DISTINCT FROM public.pro273_installer_ascii_units(v_expected."expectedFutureLayoutCoreHash") THEN RAISE EXCEPTION 'SELECTION_UNAVAILABLE'; END IF;
 FOR v_j IN 6..8 LOOP
  v_units:=v_nodes.string_units[v_winners[v_j]];
  IF pg_catalog.octet_length(v_units)<>128 THEN RAISE EXCEPTION 'SELECTION_UNAVAILABLE'; END IF;
  FOR v_i IN 0..63 LOOP IF pg_catalog.get_byte(v_units,v_i*2)<>0 OR NOT (pg_catalog.get_byte(v_units,v_i*2+1) BETWEEN 48 AND 57 OR pg_catalog.get_byte(v_units,v_i*2+1) BETWEEN 97 AND 102) THEN RAISE EXCEPTION 'SELECTION_UNAVAILABLE'; END IF; END LOOP;
 END LOOP;
 -- Numeric wire strings are checked as raw UTF16 ASCII, prior to typed JSONB.
 FOR v_j IN 17..37 LOOP
  v_units:=v_nodes.string_units[v_winners[v_j]];v_ascii:=''::BYTEA;
  IF pg_catalog.octet_length(v_units)=0 OR pg_catalog.octet_length(v_units)%2<>0 THEN RAISE EXCEPTION 'SELECTION_UNAVAILABLE'; END IF;
  FOR v_i IN 0..(pg_catalog.octet_length(v_units)/2-1) LOOP
   IF pg_catalog.get_byte(v_units,v_i*2)<>0 OR pg_catalog.get_byte(v_units,v_i*2+1) NOT BETWEEN 48 AND 57 THEN RAISE EXCEPTION 'SELECTION_UNAVAILABLE'; END IF;
   v_ascii:=v_ascii||pg_catalog.substring(v_units,v_i*2+2,1);
  END LOOP;
  IF pg_catalog.octet_length(v_ascii)>1 AND pg_catalog.get_byte(v_ascii,0)=48 THEN RAISE EXCEPTION 'SELECTION_UNAVAILABLE'; END IF;
 END LOOP;
 v_units:=v_nodes.string_units[v_winners[9]];
 IF pg_catalog.octet_length(v_units)<2 OR pg_catalog.octet_length(v_units)>20 OR pg_catalog.octet_length(v_units)%2<>0 THEN RAISE EXCEPTION 'SELECTION_UNAVAILABLE'; END IF;
 v_ascii:=''::BYTEA;FOR v_i IN 0..(pg_catalog.octet_length(v_units)/2-1) LOOP IF pg_catalog.get_byte(v_units,v_i*2)<>0 OR pg_catalog.get_byte(v_units,v_i*2+1) NOT BETWEEN 48 AND 57 THEN RAISE EXCEPTION 'SELECTION_UNAVAILABLE'; END IF;v_ascii:=v_ascii||pg_catalog.substring(v_units,v_i*2+2,1); END LOOP;
 IF pg_catalog.get_byte(v_ascii,0)=48 OR pg_catalog.convert_from(v_ascii,'UTF8')::NUMERIC>4294967295 THEN RAISE EXCEPTION 'SELECTION_UNAVAILABLE'; END IF;
 v_units:=v_nodes.string_units[v_evidence_node];
 IF pg_catalog.octet_length(v_units)=0 OR pg_catalog.octet_length(v_units)%2<>0 OR (pg_catalog.octet_length(v_units)/2)::NUMERIC>4::NUMERIC*pg_catalog.ceil(v_evidence_max/3::NUMERIC) THEN RAISE EXCEPTION 'SELECTION_UNAVAILABLE'; END IF;
 v_ascii:=''::BYTEA;
 FOR v_i IN 0..(pg_catalog.octet_length(v_units)/2-1) LOOP
  IF pg_catalog.get_byte(v_units,v_i*2)<>0 OR NOT (pg_catalog.get_byte(v_units,v_i*2+1) BETWEEN 65 AND 90 OR pg_catalog.get_byte(v_units,v_i*2+1) BETWEEN 97 AND 122 OR pg_catalog.get_byte(v_units,v_i*2+1) BETWEEN 48 AND 57 OR pg_catalog.get_byte(v_units,v_i*2+1) IN (43,47,61)) THEN RAISE EXCEPTION 'SELECTION_UNAVAILABLE'; END IF;
  v_ascii:=v_ascii||pg_catalog.substring(v_units,v_i*2+2,1);
 END LOOP;
 IF v_nodes.ends[v_core]<=v_nodes.starts[v_core] OR v_nodes.ends[v_core]>v_len THEN RAISE EXCEPTION 'SELECTION_UNAVAILABLE'; END IF;
 v_raw_core:=pg_catalog.substring(p_captured,v_nodes.starts[v_core]+1,v_nodes.ends[v_core]-v_nodes.starts[v_core]);
 v_canonical:=public.pro273_installer_metadata_canonical(p_expectation_id,v_raw_core);
 v_hash:=pg_catalog.encode(int4_crypto.digest(pg_catalog.convert_to('["pro273.control-plane.baseline.core.v1",','UTF8')||v_canonical||pg_catalog.convert_to(']','UTF8'),'sha256'),'hex');
 IF v_hash IS DISTINCT FROM v_context->>'expectedCoreHash' THEN RAISE EXCEPTION 'SELECTION_UNAVAILABLE'; END IF;
 v_base64:=pg_catalog.convert_from(v_ascii,'UTF8');v_evidence:=pg_catalog.decode(v_base64,'base64');
 IF pg_catalog.octet_length(v_evidence)=0 OR pg_catalog.octet_length(v_evidence)::NUMERIC>v_evidence_max OR pg_catalog.replace(pg_catalog.encode(v_evidence,'base64'),E'\n','') IS DISTINCT FROM v_base64 OR pg_catalog.encode(int4_crypto.digest(v_evidence,'sha256'),'hex') IS DISTINCT FROM v_context->>'expectedEvidenceHash' THEN RAISE EXCEPTION 'SELECTION_UNAVAILABLE'; END IF;
 -- Only after raw syntax, core/target and evidence identities are verified.
 v_record:=pg_catalog.convert_from(v_canonical,'UTF8')::JSONB;
 RETURN pg_catalog.jsonb_build_object('core',v_record,'evidenceBase64',v_base64);
EXCEPTION WHEN OTHERS THEN RAISE EXCEPTION 'SELECTION_UNAVAILABLE'; END $$;
REVOKE ALL ON FUNCTION public.pro273_installer_parse_metadata(TEXT,BYTEA) FROM PUBLIC;

-- Installation-only constructor. Independent installer qualification, input
-- claim and durable charge must already exist before this entry is called.
CREATE FUNCTION public.pro273_control_plane_bootstrap(p_expectation_id TEXT,p_captured BYTEA) RETURNS TEXT
LANGUAGE plpgsql SECURITY DEFINER SET search_path=pg_catalog AS $$
DECLARE v_id TEXT; v_kind TEXT; v_field TEXT; v_expected public."Pro273ControlPlaneInstallerExpectation"%ROWTYPE;
 v_global RECORD; v_domain public."Pro262CapacityPhysicalDomain"%ROWTYPE; v_boot public."Pro262CapacityBootstrapBaseline"%ROWTYPE;
 v_trust public."Pro262CapacityTrust"%ROWTYPE; v_trust_boot public."Pro262CapacityBootstrapTrust"%ROWTYPE;
 v_slot public."Pro262CapacityObserverInputReservation"%ROWTYPE; v_input_binding public."Pro273InstallerSlotBinding"%ROWTYPE; v_claim public."Pro262CapacityObserverInputClaim"%ROWTYPE;
 v_charge public."Pro262CapacityControlCharge"%ROWTYPE; v_prior public."Pro273ControlPlaneBaseline"%ROWTYPE;
 v_receipt public."Pro273ControlPlaneBaselineProvenance"%ROWTYPE; v_payload JSONB; v_record JSONB; v_evidence BYTEA; v_hash TEXT;
 v_core_token BIGINT; v_now TIMESTAMPTZ; v_oid OID; v_total_backend NUMERIC; v_total_shared NUMERIC;
BEGIN
 IF p_expectation_id IS NULL OR p_captured IS NULL OR NOT pg_catalog.pg_has_role(SESSION_USER,'pro273_install_bootstrap','MEMBER') OR pg_catalog.current_setting('transaction_isolation') IS DISTINCT FROM 'read committed' THEN RAISE EXCEPTION 'SELECTION_UNAVAILABLE'; END IF;
 -- Acquire the strongest global and physical modes before parser reentry.
 LOCK TABLE public."Pro311ControlDomain" IN ACCESS SHARE MODE NOWAIT;
 SELECT g."physicalIdentity",g."proofIdentity" INTO STRICT v_global FROM public."Pro311ControlDomain" g WHERE g."id"='global-v1' FOR UPDATE NOWAIT;
 SELECT d.* INTO STRICT v_domain FROM public."Pro262CapacityPhysicalDomain" d WHERE d."physicalIdentity"=v_global."physicalIdentity" FOR UPDATE NOWAIT;
 v_payload:=public.pro273_installer_parse_metadata(p_expectation_id,p_captured);v_record:=v_payload->'core';
 IF pg_catalog.jsonb_typeof(v_record) IS DISTINCT FROM 'object' OR
    (SELECT pg_catalog.count(*) FROM pg_catalog.jsonb_object_keys(v_record))<>39 OR NOT (v_record ?& ARRAY['schemaVersion','baselineId','purpose','physicalIdentity','physicalProofIdentity','sourceClosureHash','installationClosureHash','expectedFutureLayoutCoreHash','principalOid','principalName','credentialEpoch','launchEpoch','host','boot','processTree','parentProcessTree','reservedBackendBytes','reservedSharedBytes','reservedTemporaryBytes','maxInputBytes','maxOutputBytes','maxAllocationBytes','stackBytes','parentBytes','maxProcessCount','maxBackendCount','maxLaunchAttempts','maxEvents','backendProcessBytes','qualifierRuntimeBytes','launcherSupervisorBytes','retainedParentBytes','driverSocketIpcBytes','inputEvidenceSerializationBytes','primitiveParserCacheBytes','rollbackCleanupBytes','sharedRuntimeBytes','validFrom','validUntil']) OR p_captured IS NULL THEN RAISE EXCEPTION 'SELECTION_UNAVAILABLE'; END IF;
 FOREACH v_field IN ARRAY ARRAY['schemaVersion','baselineId','purpose','physicalIdentity','physicalProofIdentity','sourceClosureHash','installationClosureHash','expectedFutureLayoutCoreHash','principalOid','principalName','credentialEpoch','launchEpoch','host','boot','processTree','parentProcessTree','reservedBackendBytes','reservedSharedBytes','reservedTemporaryBytes','maxInputBytes','maxOutputBytes','maxAllocationBytes','stackBytes','parentBytes','maxProcessCount','maxBackendCount','maxLaunchAttempts','maxEvents','backendProcessBytes','qualifierRuntimeBytes','launcherSupervisorBytes','retainedParentBytes','driverSocketIpcBytes','inputEvidenceSerializationBytes','primitiveParserCacheBytes','rollbackCleanupBytes','sharedRuntimeBytes','validFrom','validUntil'] LOOP
  IF pg_catalog.jsonb_typeof(v_record->v_field) IS DISTINCT FROM 'string' OR COALESCE(v_record->>v_field,'')='' THEN RAISE EXCEPTION 'SELECTION_UNAVAILABLE'; END IF;
 END LOOP;
 FOREACH v_field IN ARRAY ARRAY['reservedBackendBytes','reservedSharedBytes','reservedTemporaryBytes','maxInputBytes','maxOutputBytes','maxAllocationBytes','stackBytes','parentBytes','maxProcessCount','maxBackendCount','maxLaunchAttempts','maxEvents','backendProcessBytes','qualifierRuntimeBytes','launcherSupervisorBytes','retainedParentBytes','driverSocketIpcBytes','inputEvidenceSerializationBytes','primitiveParserCacheBytes','rollbackCleanupBytes','sharedRuntimeBytes'] LOOP
  IF (v_record->>v_field) !~ '^(0|[1-9][0-9]*)$' THEN RAISE EXCEPTION 'SELECTION_UNAVAILABLE'; END IF;
 END LOOP;
 v_id:=v_record->>'baselineId';
 IF v_record->>'schemaVersion'<>'pro273-control-plane-baseline-v1' OR v_record->>'purpose' NOT IN ('QUALIFIER_BASELINE_INITIAL','SELECTION_PROFILE_REVOKE') OR v_record->>'principalOid' !~ '^[1-9][0-9]{0,9}$' OR (v_record->>'principalOid')::NUMERIC>4294967295 OR
    v_record->>'sourceClosureHash' !~ '^[a-f0-9]{64}$' OR v_record->>'installationClosureHash' !~ '^[a-f0-9]{64}$' OR v_record->>'expectedFutureLayoutCoreHash' !~ '^[a-f0-9]{64}$' THEN RAISE EXCEPTION 'SELECTION_UNAVAILABLE'; END IF;
 v_kind:=CASE v_record->>'purpose' WHEN 'QUALIFIER_BASELINE_INITIAL' THEN 'SELECTION_CONTROL_PLANE_INITIAL:' ELSE 'SELECTION_CONTROL_PLANE_REVOKE:' END||v_id;
 LOCK TABLE public."Pro311ControlDomain" IN ACCESS SHARE MODE NOWAIT;
 SELECT g."physicalIdentity",g."proofIdentity" INTO STRICT v_global FROM public."Pro311ControlDomain" g WHERE g."id"='global-v1' FOR UPDATE NOWAIT;
 SELECT d.* INTO STRICT v_domain FROM public."Pro262CapacityPhysicalDomain" d WHERE d."physicalIdentity"=v_global."physicalIdentity" FOR UPDATE NOWAIT;
 SELECT b.* INTO STRICT v_boot FROM public."Pro262CapacityBootstrapBaseline" b WHERE b."kind"=v_kind FOR SHARE NOWAIT;
 SELECT e.* INTO STRICT v_expected FROM public."Pro273ControlPlaneInstallerExpectation" e WHERE e."bootstrapKind"=v_kind AND e."expectationId"=p_expectation_id;
 PERFORM public.pro273_installer_assert_observed(v_expected."expectationId");
 SELECT e.* INTO STRICT v_expected FROM public."Pro273ControlPlaneInstallerExpectation" e WHERE e."bootstrapKind"=v_kind AND e."expectationId"=p_expectation_id FOR SHARE NOWAIT;
 SELECT t.* INTO STRICT v_trust FROM public."Pro262CapacityTrust" t WHERE (t."trustId",t."generation")=(v_expected."trustId",v_expected."trustGeneration") FOR SHARE NOWAIT;
 SELECT t.* INTO STRICT v_trust_boot FROM public."Pro262CapacityBootstrapTrust" t WHERE (t."trustId",t."generation")=(v_expected."trustId",v_expected."trustGeneration") FOR SHARE NOWAIT;
 SELECT c.* INTO STRICT v_claim FROM public."Pro262CapacityObserverInputClaim" c WHERE c."reservationId"=v_expected."constructorInputReservationId" AND c."eventKey"=v_expected."eventId" AND c."phase"=v_expected."constructorInputPhase" FOR SHARE NOWAIT;
 SELECT r.* INTO STRICT v_slot FROM public."Pro262CapacityObserverInputReservation" r WHERE r."reservationId"=v_claim."reservationId" FOR SHARE NOWAIT;
 SELECT b.* INTO STRICT v_input_binding FROM public."Pro273InstallerSlotBinding" b WHERE b."reservationId"=v_slot."reservationId" FOR SHARE NOWAIT;
 SELECT c.* INTO STRICT v_charge FROM public."Pro262CapacityControlCharge" c WHERE (c."kind",c."eventKey")=(v_expected."chargeKind",v_expected."chargeEventKey") FOR SHARE NOWAIT;
 SELECT r.oid INTO STRICT v_oid FROM pg_catalog.pg_roles r WHERE r.rolname=SESSION_USER::NAME AND r.rolcanlogin AND NOT r.rolsuper;
 v_now:=pg_catalog.clock_timestamp();
 IF NOT v_domain."enabled" OR v_domain."proofIdentity" IS DISTINCT FROM v_global."proofIdentity" OR v_expected."physicalIdentity" IS DISTINCT FROM v_domain."physicalIdentity" OR v_expected."physicalProofIdentity" IS DISTINCT FROM v_domain."proofIdentity" OR v_expected."physicalEvidenceHash" IS DISTINCT FROM v_domain."evidenceHash" OR
    v_expected."installerOid" IS DISTINCT FROM v_oid OR v_expected."installerName" IS DISTINCT FROM SESSION_USER::NAME OR v_expected."installerPid" IS DISTINCT FROM pg_catalog.pg_backend_pid() OR v_expected."installerBackendStart" IS DISTINCT FROM public.pro262_capacity_backend_start() OR
    v_expected."validFrom">v_now OR v_expected."validUntil"<=v_now OR v_boot."validUntil"<=v_now OR v_boot."publisherPrincipal" IS DISTINCT FROM SESSION_USER::NAME OR v_boot."recordHash" IS DISTINCT FROM v_expected."expectedCoreHash" OR v_boot."evidenceHash" IS DISTINCT FROM v_expected."expectedEvidenceHash" OR
    v_trust."revoked" OR v_trust."supplierPrincipal" IS DISTINCT FROM SESSION_USER::NAME OR v_trust."validFrom">v_now OR v_trust."validUntil"<=v_now OR v_trust_boot."validUntil"<=v_now OR v_trust_boot."principal" IS DISTINCT FROM SESSION_USER::NAME OR
    v_input_binding."bindingKind"<>'INSTALLER_CONSTRUCTOR_INPUT' OR v_input_binding."expectationId" IS DISTINCT FROM v_expected."expectationId" OR v_input_binding."credentialEpoch" IS DISTINCT FROM v_expected."credentialEpoch" OR v_input_binding."launchEpoch" IS DISTINCT FROM v_expected."launchEpoch" OR v_input_binding."phase" IS DISTINCT FROM v_expected."constructorInputPhase" OR v_input_binding."expectedEventKey" IS DISTINCT FROM v_expected."eventId" OR v_claim."observerPrincipalOid" IS DISTINCT FROM v_oid OR v_claim."observerPrincipalName" IS DISTINCT FROM SESSION_USER::NAME OR v_claim."eventKey" IS DISTINCT FROM v_expected."eventId" OR v_slot."observerPrincipalOid" IS DISTINCT FROM v_oid OR v_slot."physicalIdentity" IS DISTINCT FROM v_domain."physicalIdentity" OR
    v_charge."bindingHash" IS DISTINCT FROM v_expected."chargeBindingHash" OR pg_catalog.octet_length(p_captured)=0 OR pg_catalog.octet_length(p_captured)>v_expected."maxInputBytes" OR pg_catalog.octet_length(p_captured)>v_slot."maxInputBytes" OR
    v_record->>'physicalIdentity' IS DISTINCT FROM v_domain."physicalIdentity" OR v_record->>'physicalProofIdentity' IS DISTINCT FROM v_domain."proofIdentity" OR v_record->>'expectedFutureLayoutCoreHash' IS DISTINCT FROM v_expected."expectedFutureLayoutCoreHash" THEN RAISE EXCEPTION 'SELECTION_UNAVAILABLE'; END IF;

 IF pg_catalog.jsonb_typeof(v_payload) IS DISTINCT FROM 'object' OR (SELECT pg_catalog.count(*) FROM pg_catalog.jsonb_object_keys(v_payload))<>2 OR NOT (v_payload ?& ARRAY['core','evidenceBase64']) OR v_payload->'core' IS DISTINCT FROM v_record OR pg_catalog.jsonb_typeof(v_payload->'evidenceBase64') IS DISTINCT FROM 'string' THEN RAISE EXCEPTION 'SELECTION_UNAVAILABLE'; END IF;
 v_evidence:=pg_catalog.decode(v_payload->>'evidenceBase64','base64');
 IF pg_catalog.octet_length(v_evidence)=0 OR pg_catalog.replace(pg_catalog.encode(v_evidence,'base64'),E'\n','') IS DISTINCT FROM v_payload->>'evidenceBase64' OR pg_catalog.encode(int4_crypto.digest(v_evidence,'sha256'),'hex') IS DISTINCT FROM v_expected."expectedEvidenceHash" THEN RAISE EXCEPTION 'SELECTION_UNAVAILABLE'; END IF;
 -- The protected raw parser already derived and verified this semantic hash.
 v_hash:=v_expected."expectedCoreHash";
 SELECT b.* INTO v_prior FROM public."Pro273ControlPlaneBaseline" b WHERE b."baselineId"=v_id;
 IF FOUND THEN
  SELECT p.* INTO STRICT v_receipt FROM public."Pro273ControlPlaneBaselineProvenance" p WHERE p."baselineId"=v_id;
  IF v_prior."coreHash" IS DISTINCT FROM v_hash OR v_receipt."capturedBytes" IS DISTINCT FROM p_captured OR v_receipt."evidenceBytes" IS DISTINCT FROM v_evidence OR v_receipt."inputClaimId" IS DISTINCT FROM v_claim."inputClaimId" OR v_receipt."sessionClaimId" IS DISTINCT FROM v_expected."sessionClaimId" OR v_receipt."eventId" IS DISTINCT FROM v_expected."eventId" OR v_receipt."chargeBindingHash" IS DISTINCT FROM v_expected."chargeBindingHash" THEN RAISE EXCEPTION 'SELECTION_UNAVAILABLE'; END IF;
  RETURN v_id;
 END IF;
 SELECT COALESCE(pg_catalog.sum(b."reservedBackendBytes"),0),COALESCE(pg_catalog.sum(b."reservedSharedBytes"),0) INTO v_total_backend,v_total_shared FROM public."Pro273ControlPlaneBaseline" b WHERE b."physicalIdentity"=v_domain."physicalIdentity";
 IF v_total_backend+(v_record->>'reservedBackendBytes')::NUMERIC>v_expected."qualifiedNonQualifierBackend" OR v_total_shared+(v_record->>'reservedSharedBytes')::NUMERIC>v_expected."qualifiedNonQualifierShared" OR v_expected."qualifiedNonQualifierBackend">v_domain."baselineBackend" OR v_expected."qualifiedNonQualifierShared">v_domain."baselineShared" OR (v_record->>'sourceClosureHash') IS DISTINCT FROM v_expected."sourceClosureHash" OR (v_record->>'installationClosureHash') IS DISTINCT FROM v_expected."installationClosureHash" THEN RAISE EXCEPTION 'SELECTION_UNAVAILABLE'; END IF;
 INSERT INTO public."Pro273ControlPlaneBaseline" SELECT (pg_catalog.jsonb_populate_record(NULL::public."Pro273ControlPlaneBaseline",(v_record-'schemaVersion')||pg_catalog.jsonb_build_object('coreHash',v_hash))).*;
 INSERT INTO public."Pro273ControlPlaneBaselineProvenance"("baselineId","coreHash","bootstrapKind","bootstrapRecordHash","bootstrapEvidenceHash","trustId","trustGeneration","trustRecordHash","publisherPrincipalOid","publisherPrincipalName","inputClaimId","sessionClaimId","eventId","capturedBytes","capturedLength","capturedHash","evidenceBytes","evidenceLength","evidenceHash","chargeKind","chargeEventKey","chargeBindingHash","constructionTransactionId") VALUES(v_id,v_hash,v_kind,v_boot."recordHash",v_boot."evidenceHash",v_trust."trustId",v_trust."generation",v_trust_boot."recordHash",v_oid,SESSION_USER::NAME,v_claim."inputClaimId",v_expected."sessionClaimId",v_expected."eventId",p_captured,pg_catalog.octet_length(p_captured),pg_catalog.encode(int4_crypto.digest(p_captured,'sha256'),'hex'),v_evidence,pg_catalog.octet_length(v_evidence),v_expected."expectedEvidenceHash",v_expected."chargeKind",v_expected."chargeEventKey",v_expected."chargeBindingHash",pg_catalog.pg_current_xact_id());
 RETURN v_id;
EXCEPTION WHEN OTHERS THEN RAISE EXCEPTION 'SELECTION_UNAVAILABLE'; END $$;
REVOKE ALL ON FUNCTION public.pro273_control_plane_bootstrap(TEXT,BYTEA) FROM PUBLIC;

-- Shape checks confer no funding authority; currentness is joined separately.
CREATE FUNCTION public.pro273_sel_funding_shape(p_value JSONB) RETURNS BOOLEAN
LANGUAGE plpgsql IMMUTABLE SET search_path=pg_catalog AS $$
DECLARE v_key TEXT; v_keys TEXT[];
BEGIN
 IF pg_catalog.jsonb_typeof(p_value) IS DISTINCT FROM 'object' THEN RETURN FALSE; END IF;
 IF p_value->>'kind'='QUALIFIER_ALLOCATION' THEN
  v_keys:=ARRAY['kind','controlId','allocationId','allocationCoreHash','descriptorCoreHash','principalOid','credentialEpoch','launchEpoch'];
 ELSIF p_value->>'kind'='CONTROL_PLANE_BASELINE' THEN
  v_keys:=ARRAY['kind','baselineId','baselineCoreHash','purpose','sessionClaimId'];
 ELSIF p_value->>'kind'='CAP_ADMISSION' THEN
  v_keys:=ARRAY['kind','admissionId','fence','qualificationId','qualificationGeneration','proofHash'];
 ELSIF p_value->>'kind'='CAP_REPLAY' THEN
  v_keys:=ARRAY['kind','controlId','replayId','replayProfileId','replayProofHash'];
 ELSE RETURN FALSE; END IF;
 IF (SELECT pg_catalog.count(*) FROM pg_catalog.jsonb_object_keys(p_value))<>pg_catalog.cardinality(v_keys) OR NOT (p_value ?& v_keys) THEN RETURN FALSE; END IF;
 FOREACH v_key IN ARRAY v_keys LOOP IF pg_catalog.jsonb_typeof(p_value->v_key) IS DISTINCT FROM 'string' OR COALESCE(p_value->>v_key,'')='' THEN RETURN FALSE; END IF; END LOOP;
 IF p_value->>'kind'='QUALIFIER_ALLOCATION' THEN RETURN p_value->>'allocationCoreHash' ~ '^[a-f0-9]{64}$' AND p_value->>'descriptorCoreHash' ~ '^[a-f0-9]{64}$' AND p_value->>'principalOid' ~ '^[1-9][0-9]{0,9}$' AND (p_value->>'principalOid')::NUMERIC<=4294967295; END IF;
 IF p_value->>'kind'='CONTROL_PLANE_BASELINE' THEN RETURN p_value->>'baselineCoreHash' ~ '^[a-f0-9]{64}$' AND p_value->>'purpose' IN ('QUALIFIER_BASELINE_INITIAL','SELECTION_PROFILE_REVOKE'); END IF;
 IF p_value->>'kind'='CAP_ADMISSION' THEN RETURN p_value->>'fence' ~ '^[1-9][0-9]{0,18}$' AND (p_value->>'fence')::NUMERIC<=9223372036854775807 AND p_value->>'qualificationGeneration' ~ '^[1-9][0-9]{0,18}$' AND (p_value->>'qualificationGeneration')::NUMERIC<=9223372036854775807 AND p_value->>'proofHash' ~ '^[a-f0-9]{64}$'; END IF;
 RETURN p_value->>'replayProofHash' ~ '^[a-f0-9]{64}$';
EXCEPTION WHEN OTHERS THEN RETURN FALSE; END $$;
REVOKE ALL ON FUNCTION public.pro273_sel_funding_shape(JSONB) FROM PUBLIC;

-- Independently qualified schedule core. Protected provisioning, physical
-- coverage, fixed receiver and currentness assertions are still prerequisites.
CREATE TABLE public."Pro273ResourceSchedule" (
 "id" TEXT NOT NULL, "generation" BIGINT NOT NULL CHECK ("generation">0), "coreHash" TEXT NOT NULL CHECK ("coreHash" ~ '^[a-f0-9]{64}$'),
 "operation" TEXT NOT NULL, "branch" TEXT NOT NULL, "scopeKind" TEXT NOT NULL CHECK ("scopeKind" IN ('QUALIFIER_ALLOCATION','CONTROL_PLANE_BASELINE','CAP_ADMISSION','CAP_REPLAY')),
 "allocationId" TEXT, "allocationCoreHash" TEXT, "controlId" TEXT, "baselineId" TEXT, "baselineCoreHash" TEXT, "baselinePurpose" TEXT,
 "admissionId" TEXT, "fence" BIGINT, "qualificationId" TEXT, "qualificationGeneration" BIGINT, "proofHash" TEXT,
 "replayId" TEXT, "replayProfileId" TEXT, "replayProofHash" TEXT,
 "physicalIdentity" TEXT NOT NULL REFERENCES public."Pro262CapacityPhysicalDomain"("physicalIdentity") ON UPDATE RESTRICT ON DELETE RESTRICT, "physicalProofIdentity" TEXT NOT NULL,
 "sourceClosureHash" TEXT NOT NULL, "installationClosureHash" TEXT NOT NULL, "semanticDomainHash" TEXT NOT NULL,
 "parserAbiVersion" TEXT NOT NULL, "primitiveAbiVersion" TEXT NOT NULL, "primitiveFunctionClosureHash" TEXT NOT NULL,
 "workerFunding" JSONB NOT NULL, "claimantFunding" JSONB NOT NULL,
 "reservedBackendBytes" NUMERIC NOT NULL CHECK ("reservedBackendBytes" > 0 AND "reservedBackendBytes"=pg_catalog.trunc("reservedBackendBytes") AND "reservedBackendBytes"::TEXT NOT IN ('NaN','Infinity','-Infinity')),
 "reservedSharedBytes" NUMERIC NOT NULL CHECK ("reservedSharedBytes" > 0 AND "reservedSharedBytes"=pg_catalog.trunc("reservedSharedBytes") AND "reservedSharedBytes"::TEXT NOT IN ('NaN','Infinity','-Infinity')),
 "reservedTemporaryBytes" NUMERIC NOT NULL CHECK ("reservedTemporaryBytes" > 0 AND "reservedTemporaryBytes"=pg_catalog.trunc("reservedTemporaryBytes") AND "reservedTemporaryBytes"::TEXT NOT IN ('NaN','Infinity','-Infinity')),
 "maxAllocationBytes" NUMERIC NOT NULL CHECK ("maxAllocationBytes" > 0 AND "maxAllocationBytes"=pg_catalog.trunc("maxAllocationBytes") AND "maxAllocationBytes"::TEXT NOT IN ('NaN','Infinity','-Infinity')),
 "stackBytes" NUMERIC NOT NULL CHECK ("stackBytes" > 0 AND "stackBytes"=pg_catalog.trunc("stackBytes") AND "stackBytes"::TEXT NOT IN ('NaN','Infinity','-Infinity')),
 "parentBytes" NUMERIC NOT NULL CHECK ("parentBytes" > 0 AND "parentBytes"=pg_catalog.trunc("parentBytes") AND "parentBytes"::TEXT NOT IN ('NaN','Infinity','-Infinity')),
 "maxInputBytes" NUMERIC NOT NULL CHECK ("maxInputBytes" > 0 AND "maxInputBytes"=pg_catalog.trunc("maxInputBytes") AND "maxInputBytes"::TEXT NOT IN ('NaN','Infinity','-Infinity')),
 "maxOutputBytes" NUMERIC NOT NULL CHECK ("maxOutputBytes" > 0 AND "maxOutputBytes"=pg_catalog.trunc("maxOutputBytes") AND "maxOutputBytes"::TEXT NOT IN ('NaN','Infinity','-Infinity')),
 "concurrency" NUMERIC NOT NULL CHECK ("concurrency" > 0 AND "concurrency"=pg_catalog.trunc("concurrency") AND "concurrency"::TEXT NOT IN ('NaN','Infinity','-Infinity')),
 "maxProcessCount" NUMERIC NOT NULL CHECK ("maxProcessCount" > 0 AND "maxProcessCount"=pg_catalog.trunc("maxProcessCount") AND "maxProcessCount"::TEXT NOT IN ('NaN','Infinity','-Infinity')),
 "maxBackendCount" NUMERIC NOT NULL CHECK ("maxBackendCount" > 0 AND "maxBackendCount"=pg_catalog.trunc("maxBackendCount") AND "maxBackendCount"::TEXT NOT IN ('NaN','Infinity','-Infinity')),
 "maxLaunchAttempts" NUMERIC NOT NULL CHECK ("maxLaunchAttempts" > 0 AND "maxLaunchAttempts"=pg_catalog.trunc("maxLaunchAttempts") AND "maxLaunchAttempts"::TEXT NOT IN ('NaN','Infinity','-Infinity')),
 "maxPublicationEvents" NUMERIC NOT NULL CHECK ("maxPublicationEvents" > 0 AND "maxPublicationEvents"=pg_catalog.trunc("maxPublicationEvents") AND "maxPublicationEvents"::TEXT NOT IN ('NaN','Infinity','-Infinity')),
 "maxArenaBodies" NUMERIC NOT NULL CHECK ("maxArenaBodies" > 0 AND "maxArenaBodies"=pg_catalog.trunc("maxArenaBodies") AND "maxArenaBodies"::TEXT NOT IN ('NaN','Infinity','-Infinity')),
 "maxArenaTokens" NUMERIC NOT NULL CHECK ("maxArenaTokens" > 0 AND "maxArenaTokens"=pg_catalog.trunc("maxArenaTokens") AND "maxArenaTokens"::TEXT NOT IN ('NaN','Infinity','-Infinity')),
 "maxTempCatalogEvents" NUMERIC NOT NULL CHECK ("maxTempCatalogEvents" > 0 AND "maxTempCatalogEvents"=pg_catalog.trunc("maxTempCatalogEvents") AND "maxTempCatalogEvents"::TEXT NOT IN ('NaN','Infinity','-Infinity')),
 "maxDurableBytes" NUMERIC NOT NULL CHECK ("maxDurableBytes" > 0 AND "maxDurableBytes"=pg_catalog.trunc("maxDurableBytes") AND "maxDurableBytes"::TEXT NOT IN ('NaN','Infinity','-Infinity')),
 "timeoutMillis" NUMERIC NOT NULL CHECK ("timeoutMillis" > 0 AND "timeoutMillis"=pg_catalog.trunc("timeoutMillis") AND "timeoutMillis"::TEXT NOT IN ('NaN','Infinity','-Infinity')),
 "backendProcessBytes" NUMERIC NOT NULL CHECK ("backendProcessBytes" >= 0 AND "backendProcessBytes"=pg_catalog.trunc("backendProcessBytes") AND "backendProcessBytes"::TEXT NOT IN ('NaN','Infinity','-Infinity')),
 "qualifierRuntimeBytes" NUMERIC NOT NULL CHECK ("qualifierRuntimeBytes" >= 0 AND "qualifierRuntimeBytes"=pg_catalog.trunc("qualifierRuntimeBytes") AND "qualifierRuntimeBytes"::TEXT NOT IN ('NaN','Infinity','-Infinity')),
 "launcherSupervisorBytes" NUMERIC NOT NULL CHECK ("launcherSupervisorBytes" >= 0 AND "launcherSupervisorBytes"=pg_catalog.trunc("launcherSupervisorBytes") AND "launcherSupervisorBytes"::TEXT NOT IN ('NaN','Infinity','-Infinity')),
 "retainedParentBytes" NUMERIC NOT NULL CHECK ("retainedParentBytes" >= 0 AND "retainedParentBytes"=pg_catalog.trunc("retainedParentBytes") AND "retainedParentBytes"::TEXT NOT IN ('NaN','Infinity','-Infinity')),
 "driverSocketIpcBytes" NUMERIC NOT NULL CHECK ("driverSocketIpcBytes" >= 0 AND "driverSocketIpcBytes"=pg_catalog.trunc("driverSocketIpcBytes") AND "driverSocketIpcBytes"::TEXT NOT IN ('NaN','Infinity','-Infinity')),
 "inputEvidenceSerializationBytes" NUMERIC NOT NULL CHECK ("inputEvidenceSerializationBytes" >= 0 AND "inputEvidenceSerializationBytes"=pg_catalog.trunc("inputEvidenceSerializationBytes") AND "inputEvidenceSerializationBytes"::TEXT NOT IN ('NaN','Infinity','-Infinity')),
 "primitiveParserCacheBytes" NUMERIC NOT NULL CHECK ("primitiveParserCacheBytes" >= 0 AND "primitiveParserCacheBytes"=pg_catalog.trunc("primitiveParserCacheBytes") AND "primitiveParserCacheBytes"::TEXT NOT IN ('NaN','Infinity','-Infinity')),
 "rollbackCleanupBytes" NUMERIC NOT NULL CHECK ("rollbackCleanupBytes" >= 0 AND "rollbackCleanupBytes"=pg_catalog.trunc("rollbackCleanupBytes") AND "rollbackCleanupBytes"::TEXT NOT IN ('NaN','Infinity','-Infinity')),
 "sharedRuntimeBytes" NUMERIC NOT NULL CHECK ("sharedRuntimeBytes" >= 0 AND "sharedRuntimeBytes"=pg_catalog.trunc("sharedRuntimeBytes") AND "sharedRuntimeBytes"::TEXT NOT IN ('NaN','Infinity','-Infinity')),
 "maxBodies" NUMERIC NOT NULL CHECK ("maxBodies" > 0 AND "maxBodies"=pg_catalog.trunc("maxBodies") AND "maxBodies"::TEXT NOT IN ('NaN','Infinity','-Infinity')),
 "maxBodyBytes" NUMERIC NOT NULL CHECK ("maxBodyBytes" > 0 AND "maxBodyBytes"=pg_catalog.trunc("maxBodyBytes") AND "maxBodyBytes"::TEXT NOT IN ('NaN','Infinity','-Infinity')),
 "maxDepthCapacity" NUMERIC NOT NULL CHECK ("maxDepthCapacity" > 0 AND "maxDepthCapacity"=pg_catalog.trunc("maxDepthCapacity") AND "maxDepthCapacity"::TEXT NOT IN ('NaN','Infinity','-Infinity')),
 "maxTokenCapacity" NUMERIC NOT NULL CHECK ("maxTokenCapacity" > 0 AND "maxTokenCapacity"=pg_catalog.trunc("maxTokenCapacity") AND "maxTokenCapacity"::TEXT NOT IN ('NaN','Infinity','-Infinity')),
 "maxDecodedUnits" NUMERIC NOT NULL CHECK ("maxDecodedUnits" > 0 AND "maxDecodedUnits"=pg_catalog.trunc("maxDecodedUnits") AND "maxDecodedUnits"::TEXT NOT IN ('NaN','Infinity','-Infinity')),
 "maxNormalizationOutputBytes" NUMERIC NOT NULL CHECK ("maxNormalizationOutputBytes" > 0 AND "maxNormalizationOutputBytes"=pg_catalog.trunc("maxNormalizationOutputBytes") AND "maxNormalizationOutputBytes"::TEXT NOT IN ('NaN','Infinity','-Infinity')),
 "bodyMaxOutputBytes" NUMERIC NOT NULL CHECK ("bodyMaxOutputBytes" > 0 AND "bodyMaxOutputBytes"=pg_catalog.trunc("bodyMaxOutputBytes") AND "bodyMaxOutputBytes"::TEXT NOT IN ('NaN','Infinity','-Infinity')),
 "maxArenaWorkspaceBytes" NUMERIC NOT NULL CHECK ("maxArenaWorkspaceBytes" > 0 AND "maxArenaWorkspaceBytes"=pg_catalog.trunc("maxArenaWorkspaceBytes") AND "maxArenaWorkspaceBytes"::TEXT NOT IN ('NaN','Infinity','-Infinity')),
 "maxTemporaryBytes" NUMERIC NOT NULL CHECK ("maxTemporaryBytes" > 0 AND "maxTemporaryBytes"=pg_catalog.trunc("maxTemporaryBytes") AND "maxTemporaryBytes"::TEXT NOT IN ('NaN','Infinity','-Infinity')),
 "maxCatalogEventsPerBody" NUMERIC NOT NULL CHECK ("maxCatalogEventsPerBody" > 0 AND "maxCatalogEventsPerBody"=pg_catalog.trunc("maxCatalogEventsPerBody") AND "maxCatalogEventsPerBody"::TEXT NOT IN ('NaN','Infinity','-Infinity')),
 "maxDurableBytesPerBody" NUMERIC NOT NULL CHECK ("maxDurableBytesPerBody" > 0 AND "maxDurableBytesPerBody"=pg_catalog.trunc("maxDurableBytesPerBody") AND "maxDurableBytesPerBody"::TEXT NOT IN ('NaN','Infinity','-Infinity')),
 "maxCatalogEvents" NUMERIC NOT NULL CHECK ("maxCatalogEvents" > 0 AND "maxCatalogEvents"=pg_catalog.trunc("maxCatalogEvents") AND "maxCatalogEvents"::TEXT NOT IN ('NaN','Infinity','-Infinity')),
 "catalogMaxDurableBytes" NUMERIC NOT NULL CHECK ("catalogMaxDurableBytes" > 0 AND "catalogMaxDurableBytes"=pg_catalog.trunc("catalogMaxDurableBytes") AND "catalogMaxDurableBytes"::TEXT NOT IN ('NaN','Infinity','-Infinity')),
 "deliveryPolicy" TEXT NOT NULL CHECK ("deliveryPolicy"='COMMITTED_ONE_SHOT_FIXED_RECEIVER_V1'), "validFrom" TIMESTAMPTZ NOT NULL, "validUntil" TIMESTAMPTZ NOT NULL,
 PRIMARY KEY ("id","generation"), UNIQUE ("id","generation","coreHash"), CHECK ("validUntil">"validFrom"),
 FOREIGN KEY ("allocationId") REFERENCES public."Pro273QualifierAllocation"("allocationId") ON UPDATE RESTRICT ON DELETE RESTRICT,
 FOREIGN KEY ("baselineId","baselineCoreHash") REFERENCES public."Pro273ControlPlaneBaseline"("baselineId","coreHash") ON UPDATE RESTRICT ON DELETE RESTRICT,
 FOREIGN KEY ("admissionId","fence") REFERENCES public."Pro262CapacityAdmission"("admissionId","fence") ON UPDATE RESTRICT ON DELETE RESTRICT,
 FOREIGN KEY ("qualificationId","qualificationGeneration") REFERENCES public."Pro262CapacityQualification"("qualificationId","generation") ON UPDATE RESTRICT ON DELETE RESTRICT,
 FOREIGN KEY ("replayId") REFERENCES public."Pro262CapacityReplay"("replayId") ON UPDATE RESTRICT ON DELETE RESTRICT,
 CHECK (("scopeKind"='QUALIFIER_ALLOCATION' AND "allocationId" IS NOT NULL AND "allocationCoreHash" IS NOT NULL AND "controlId" IS NOT NULL AND "baselineId" IS NULL AND "baselineCoreHash" IS NULL AND "baselinePurpose" IS NULL AND "admissionId" IS NULL AND "fence" IS NULL AND "qualificationId" IS NULL AND "qualificationGeneration" IS NULL AND "proofHash" IS NULL AND "replayId" IS NULL AND "replayProfileId" IS NULL AND "replayProofHash" IS NULL)
 OR ("scopeKind"='CONTROL_PLANE_BASELINE' AND "allocationId" IS NULL AND "allocationCoreHash" IS NULL AND "controlId" IS NULL AND "baselineId" IS NOT NULL AND "baselineCoreHash" IS NOT NULL AND "baselinePurpose" IS NOT NULL AND "admissionId" IS NULL AND "fence" IS NULL AND "qualificationId" IS NULL AND "qualificationGeneration" IS NULL AND "proofHash" IS NULL AND "replayId" IS NULL AND "replayProfileId" IS NULL AND "replayProofHash" IS NULL)
 OR ("scopeKind"='CAP_ADMISSION' AND "allocationId" IS NULL AND "allocationCoreHash" IS NULL AND "controlId" IS NULL AND "baselineId" IS NULL AND "baselineCoreHash" IS NULL AND "baselinePurpose" IS NULL AND "admissionId" IS NOT NULL AND "fence" IS NOT NULL AND "fence">0 AND "qualificationId" IS NOT NULL AND "qualificationGeneration" IS NOT NULL AND "qualificationGeneration">0 AND "proofHash" IS NOT NULL AND "replayId" IS NULL AND "replayProfileId" IS NULL AND "replayProofHash" IS NULL)
 OR ("scopeKind"='CAP_REPLAY' AND "allocationId" IS NULL AND "allocationCoreHash" IS NULL AND "controlId" IS NOT NULL AND "baselineId" IS NULL AND "baselineCoreHash" IS NULL AND "baselinePurpose" IS NULL AND "admissionId" IS NULL AND "fence" IS NULL AND "qualificationId" IS NULL AND "qualificationGeneration" IS NULL AND "proofHash" IS NULL AND "replayId" IS NOT NULL AND "replayProfileId" IS NOT NULL AND "replayProofHash" IS NOT NULL)),
 CHECK (public.pro273_sel_funding_shape("workerFunding") AND public.pro273_sel_funding_shape("claimantFunding")),
 CHECK (NOT ("workerFunding"->>'kind'="claimantFunding"->>'kind' AND (("workerFunding"->>'kind'='QUALIFIER_ALLOCATION' AND "workerFunding"->>'allocationId'="claimantFunding"->>'allocationId') OR ("workerFunding"->>'kind'='CONTROL_PLANE_BASELINE' AND "workerFunding"->>'baselineId'="claimantFunding"->>'baselineId') OR ("workerFunding"->>'kind'='CAP_ADMISSION' AND "workerFunding"->>'admissionId'="claimantFunding"->>'admissionId' AND "workerFunding"->>'fence'="claimantFunding"->>'fence') OR ("workerFunding"->>'kind'='CAP_REPLAY' AND "workerFunding"->>'replayId'="claimantFunding"->>'replayId')))),
 CHECK ("reservedBackendBytes">="backendProcessBytes"+"qualifierRuntimeBytes"+"launcherSupervisorBytes"+"retainedParentBytes"+"driverSocketIpcBytes"+"inputEvidenceSerializationBytes"+"primitiveParserCacheBytes"+"rollbackCleanupBytes"),
 CHECK ("reservedSharedBytes">="sharedRuntimeBytes"+"reservedTemporaryBytes" AND "parentBytes"<="retainedParentBytes" AND "maxAllocationBytes"<="reservedBackendBytes" AND "stackBytes"<="reservedBackendBytes"),
 CHECK ("maxBodies"<="maxArenaBodies" AND "maxTokenCapacity"<="maxArenaTokens" AND "maxBodyBytes"<="maxInputBytes" AND "bodyMaxOutputBytes"<="maxOutputBytes" AND "maxTemporaryBytes"<="reservedTemporaryBytes" AND "maxCatalogEvents"<="maxTempCatalogEvents" AND "catalogMaxDurableBytes"<="maxDurableBytes"),
 CHECK ("maxCatalogEventsPerBody"*"maxBodies"<="maxCatalogEvents" AND "maxDurableBytesPerBody"*"maxBodies"<="catalogMaxDurableBytes")
);
CREATE TABLE public."Pro273QualifiedInputDomain" (
 "id" TEXT NOT NULL, "generation" BIGINT NOT NULL CHECK ("generation">0), "coreHash" TEXT NOT NULL CHECK ("coreHash" ~ '^[a-f0-9]{64}$'),
 "parserAbiVersion" TEXT NOT NULL, "primitiveAbiVersion" TEXT NOT NULL, "sourceClosureHash" TEXT NOT NULL, "callsiteClosureHash" TEXT NOT NULL, "primitiveFunctionClosureHash" TEXT NOT NULL,
 "semanticDomainHash" TEXT NOT NULL, "allowedBodyRoles" TEXT[] NOT NULL, "physicalIdentity" TEXT NOT NULL, "physicalProofIdentity" TEXT NOT NULL,
 "cardinalityRule" TEXT NOT NULL CHECK ("cardinalityRule"='RAW_UTF8_BYTES_CONSERVATIVE_V1'),
 "scheduleId" TEXT NOT NULL, "scheduleGeneration" BIGINT NOT NULL, "resourceScheduleCoreHash" TEXT NOT NULL,
 "maxBodyBytes" NUMERIC NOT NULL CHECK ("maxBodyBytes" > 0 AND "maxBodyBytes"=pg_catalog.trunc("maxBodyBytes") AND "maxBodyBytes"::TEXT NOT IN ('NaN','Infinity','-Infinity')),
 "maxDepthCapacity" NUMERIC NOT NULL CHECK ("maxDepthCapacity" > 0 AND "maxDepthCapacity"=pg_catalog.trunc("maxDepthCapacity") AND "maxDepthCapacity"::TEXT NOT IN ('NaN','Infinity','-Infinity')),
 "maxTokenCapacity" NUMERIC NOT NULL CHECK ("maxTokenCapacity" > 0 AND "maxTokenCapacity"=pg_catalog.trunc("maxTokenCapacity") AND "maxTokenCapacity"::TEXT NOT IN ('NaN','Infinity','-Infinity')),
 "maxDecodedUnits" NUMERIC NOT NULL CHECK ("maxDecodedUnits" > 0 AND "maxDecodedUnits"=pg_catalog.trunc("maxDecodedUnits") AND "maxDecodedUnits"::TEXT NOT IN ('NaN','Infinity','-Infinity')),
 "maxNormalizationOutputBytes" NUMERIC NOT NULL CHECK ("maxNormalizationOutputBytes" > 0 AND "maxNormalizationOutputBytes"=pg_catalog.trunc("maxNormalizationOutputBytes") AND "maxNormalizationOutputBytes"::TEXT NOT IN ('NaN','Infinity','-Infinity')),
 "maxOutputBytes" NUMERIC NOT NULL CHECK ("maxOutputBytes" > 0 AND "maxOutputBytes"=pg_catalog.trunc("maxOutputBytes") AND "maxOutputBytes"::TEXT NOT IN ('NaN','Infinity','-Infinity')),
 "maxBodies" NUMERIC NOT NULL CHECK ("maxBodies" > 0 AND "maxBodies"=pg_catalog.trunc("maxBodies") AND "maxBodies"::TEXT NOT IN ('NaN','Infinity','-Infinity')),
 "maxArenaWorkspaceBytes" NUMERIC NOT NULL CHECK ("maxArenaWorkspaceBytes" > 0 AND "maxArenaWorkspaceBytes"=pg_catalog.trunc("maxArenaWorkspaceBytes") AND "maxArenaWorkspaceBytes"::TEXT NOT IN ('NaN','Infinity','-Infinity')),
 "maxTemporaryBytes" NUMERIC NOT NULL CHECK ("maxTemporaryBytes" > 0 AND "maxTemporaryBytes"=pg_catalog.trunc("maxTemporaryBytes") AND "maxTemporaryBytes"::TEXT NOT IN ('NaN','Infinity','-Infinity')),
 "maxCatalogEventsPerBody" NUMERIC NOT NULL CHECK ("maxCatalogEventsPerBody" > 0 AND "maxCatalogEventsPerBody"=pg_catalog.trunc("maxCatalogEventsPerBody") AND "maxCatalogEventsPerBody"::TEXT NOT IN ('NaN','Infinity','-Infinity')),
 "maxDurableBytesPerBody" NUMERIC NOT NULL CHECK ("maxDurableBytesPerBody" > 0 AND "maxDurableBytesPerBody"=pg_catalog.trunc("maxDurableBytesPerBody") AND "maxDurableBytesPerBody"::TEXT NOT IN ('NaN','Infinity','-Infinity')),
 "maxCatalogEvents" NUMERIC NOT NULL CHECK ("maxCatalogEvents" > 0 AND "maxCatalogEvents"=pg_catalog.trunc("maxCatalogEvents") AND "maxCatalogEvents"::TEXT NOT IN ('NaN','Infinity','-Infinity')),
 "maxDurableBytes" NUMERIC NOT NULL CHECK ("maxDurableBytes" > 0 AND "maxDurableBytes"=pg_catalog.trunc("maxDurableBytes") AND "maxDurableBytes"::TEXT NOT IN ('NaN','Infinity','-Infinity')),
 "validFrom" TIMESTAMPTZ NOT NULL, "validUntil" TIMESTAMPTZ NOT NULL,
 PRIMARY KEY ("id","generation"), UNIQUE ("id","generation","coreHash"), CHECK ("validUntil">"validFrom" AND pg_catalog.cardinality("allowedBodyRoles")>0 AND pg_catalog.array_position("allowedBodyRoles",NULL) IS NULL AND "allowedBodyRoles" <@ ARRAY['request','locked input','profile','snapshot','supplement','provenance','definition','validated intent','proposed final tuple','metadata']::TEXT[]),
 FOREIGN KEY ("scheduleId","scheduleGeneration","resourceScheduleCoreHash") REFERENCES public."Pro273ResourceSchedule"("id","generation","coreHash") ON UPDATE RESTRICT ON DELETE RESTRICT
);
CREATE TABLE public."Pro273ProfileInputDomainBinding" (
 "profileId" TEXT NOT NULL, "profileGeneration" BIGINT NOT NULL, "profileRecordHash" TEXT NOT NULL,
 "domainId" TEXT NOT NULL, "domainGeneration" BIGINT NOT NULL, "resourceEnvelopeCoreHash" TEXT NOT NULL,
 "scheduleId" TEXT NOT NULL, "scheduleGeneration" BIGINT NOT NULL, "resourceScheduleCoreHash" TEXT NOT NULL,
 PRIMARY KEY ("profileId","profileGeneration","domainId","domainGeneration"),
 FOREIGN KEY ("profileId","profileGeneration","profileRecordHash") REFERENCES public."Pro273SelectionPrimitiveProfile"("profileId","generation","recordHash") ON UPDATE RESTRICT ON DELETE RESTRICT,
 FOREIGN KEY ("domainId","domainGeneration","resourceEnvelopeCoreHash") REFERENCES public."Pro273QualifiedInputDomain"("id","generation","coreHash") ON UPDATE RESTRICT ON DELETE RESTRICT,
 FOREIGN KEY ("scheduleId","scheduleGeneration","resourceScheduleCoreHash") REFERENCES public."Pro273ResourceSchedule"("id","generation","coreHash") ON UPDATE RESTRICT ON DELETE RESTRICT
);
CREATE TRIGGER "Pro273ResourceSchedule_immutable" BEFORE UPDATE OR DELETE ON public."Pro273ResourceSchedule" FOR EACH ROW EXECUTE FUNCTION public.pro273_sel_immutable();
CREATE TRIGGER "Pro273QualifiedInputDomain_immutable" BEFORE UPDATE OR DELETE ON public."Pro273QualifiedInputDomain" FOR EACH ROW EXECUTE FUNCTION public.pro273_sel_immutable();
CREATE TRIGGER "Pro273ProfileInputDomainBinding_immutable" BEFORE UPDATE OR DELETE ON public."Pro273ProfileInputDomainBinding" FOR EACH ROW EXECUTE FUNCTION public.pro273_sel_immutable();

CREATE FUNCTION public.pro273_sel_parser_authority_shape(p_value JSONB) RETURNS BOOLEAN
LANGUAGE plpgsql IMMUTABLE SET search_path=pg_catalog AS $$
DECLARE v_keys TEXT[]; v_key TEXT; v_worker JSONB;
BEGIN
 IF pg_catalog.jsonb_typeof(p_value) IS DISTINCT FROM 'object' THEN RETURN FALSE; END IF;
 IF p_value->>'kind'='QUALIFIED_PRIMITIVE' THEN
  v_keys:=ARRAY['kind','profileId','generation','recordHash'];
  IF (SELECT pg_catalog.count(*) FROM pg_catalog.jsonb_object_keys(p_value))<>pg_catalog.cardinality(v_keys) OR NOT (p_value ?& v_keys) THEN RETURN FALSE; END IF;
  FOREACH v_key IN ARRAY v_keys LOOP IF pg_catalog.jsonb_typeof(p_value->v_key) IS DISTINCT FROM 'string' OR COALESCE(p_value->>v_key,'')='' THEN RETURN FALSE; END IF; END LOOP;
  RETURN p_value->>'generation' ~ '^[1-9][0-9]{0,18}$' AND (p_value->>'generation')::NUMERIC<=9223372036854775807 AND p_value->>'recordHash' ~ '^[a-f0-9]{64}$';
 ELSIF p_value->>'kind'='BOOTSTRAP_PROFILE_HASH' THEN
  v_keys:=ARRAY['kind','parserAbiVersion','parserSourceClosureHash','semanticDomainHash','resourceEnvelopeId','resourceEnvelopeGeneration','resourceEnvelopeCoreHash','workerScope','claimantFundingRef','bootstrapGrantId','expectedPublicationCoreHash','installedExpectedClosureHash'];
  IF (SELECT pg_catalog.count(*) FROM pg_catalog.jsonb_object_keys(p_value))<>pg_catalog.cardinality(v_keys) OR NOT (p_value ?& v_keys) THEN RETURN FALSE; END IF;
  FOREACH v_key IN ARRAY ARRAY['kind','parserAbiVersion','parserSourceClosureHash','semanticDomainHash','resourceEnvelopeId','resourceEnvelopeGeneration','resourceEnvelopeCoreHash','bootstrapGrantId','expectedPublicationCoreHash','installedExpectedClosureHash'] LOOP IF pg_catalog.jsonb_typeof(p_value->v_key) IS DISTINCT FROM 'string' OR COALESCE(p_value->>v_key,'')='' THEN RETURN FALSE; END IF; END LOOP;
  FOREACH v_key IN ARRAY ARRAY['parserSourceClosureHash','semanticDomainHash','resourceEnvelopeCoreHash','expectedPublicationCoreHash','installedExpectedClosureHash'] LOOP IF p_value->>v_key !~ '^[a-f0-9]{64}$' THEN RETURN FALSE; END IF; END LOOP;
  IF p_value->>'resourceEnvelopeGeneration' !~ '^[1-9][0-9]{0,18}$' OR (p_value->>'resourceEnvelopeGeneration')::NUMERIC>9223372036854775807 OR public.pro273_sel_funding_shape(p_value->'claimantFundingRef') IS DISTINCT FROM TRUE OR p_value->'claimantFundingRef'->>'kind'<>'QUALIFIER_ALLOCATION' THEN RETURN FALSE; END IF;
  v_worker:=p_value->'workerScope';
  IF pg_catalog.jsonb_typeof(v_worker) IS DISTINCT FROM 'object' OR (SELECT pg_catalog.count(*) FROM pg_catalog.jsonb_object_keys(v_worker))<>5 OR NOT (v_worker ?& ARRAY['kind','controlId','descriptorCoreHash','allocationId','allocationCoreHash']) OR v_worker->>'kind'<>'QUALIFIER_CONTROL' THEN RETURN FALSE; END IF;
  FOREACH v_key IN ARRAY ARRAY['controlId','descriptorCoreHash','allocationId','allocationCoreHash'] LOOP IF pg_catalog.jsonb_typeof(v_worker->v_key) IS DISTINCT FROM 'string' OR COALESCE(v_worker->>v_key,'')='' THEN RETURN FALSE; END IF; END LOOP;
  RETURN v_worker->>'descriptorCoreHash' ~ '^[a-f0-9]{64}$' AND v_worker->>'allocationCoreHash' ~ '^[a-f0-9]{64}$' AND v_worker->>'allocationId' IS DISTINCT FROM p_value->'claimantFundingRef'->>'allocationId' AND v_worker->>'controlId' IS DISTINCT FROM p_value->'claimantFundingRef'->>'controlId';
 END IF;
 RETURN FALSE;
EXCEPTION WHEN OTHERS THEN RETURN FALSE; END $$;
REVOKE ALL ON FUNCTION public.pro273_sel_parser_authority_shape(JSONB) FROM PUBLIC;

-- Immutable pre-dispatch records. Transaction and receiver enforcement are
-- required before these records can authorize work; none are seeded.
CREATE TABLE public."Pro273InvocationSchedule" (
 "id" TEXT PRIMARY KEY, "coreHash" TEXT NOT NULL CHECK ("coreHash" ~ '^[a-f0-9]{64}$'),
 "resourceScheduleId" TEXT NOT NULL, "resourceScheduleGeneration" BIGINT NOT NULL, "resourceScheduleCoreHash" TEXT NOT NULL,
 "domainId" TEXT NOT NULL, "domainGeneration" BIGINT NOT NULL, "resourceEnvelopeCoreHash" TEXT NOT NULL,
 "operation" TEXT NOT NULL, "branch" TEXT NOT NULL, "receiverIdentity" TEXT NOT NULL, "receiverPrincipalOid" OID NOT NULL, "receiverPrincipalName" NAME NOT NULL,
 "credentialEpoch" TEXT NOT NULL, "launchEpoch" TEXT NOT NULL, "sourceClosureHash" TEXT NOT NULL, "installationClosureHash" TEXT NOT NULL,
 "parserAuthority" JSONB NOT NULL CHECK (public.pro273_sel_parser_authority_shape("parserAuthority")), "invocationCount" BIGINT NOT NULL CHECK ("invocationCount">0), "bodyCount" BIGINT NOT NULL CHECK ("bodyCount">0),
 "validFrom" TIMESTAMPTZ NOT NULL, "validUntil" TIMESTAMPTZ NOT NULL, CHECK ("validUntil">"validFrom"),
 UNIQUE ("id","coreHash"),
 FOREIGN KEY ("resourceScheduleId","resourceScheduleGeneration","resourceScheduleCoreHash") REFERENCES public."Pro273ResourceSchedule"("id","generation","coreHash") ON UPDATE RESTRICT ON DELETE RESTRICT,
 FOREIGN KEY ("domainId","domainGeneration","resourceEnvelopeCoreHash") REFERENCES public."Pro273QualifiedInputDomain"("id","generation","coreHash") ON UPDATE RESTRICT ON DELETE RESTRICT
);
CREATE TABLE public."Pro273InvocationBodySpec" (
 "scheduleId" TEXT NOT NULL REFERENCES public."Pro273InvocationSchedule"("id") ON UPDATE RESTRICT ON DELETE RESTRICT,
 "bodyOrdinal" BIGINT NOT NULL CHECK ("bodyOrdinal">0), "role" TEXT NOT NULL CHECK ("role" IN ('request','locked input','profile','snapshot','supplement','provenance','definition','validated intent','proposed final tuple','metadata')),
 "sourceIdentity" TEXT NOT NULL, "sourceReference" TEXT NOT NULL, "multiplicityOrdinal" BIGINT NOT NULL CHECK ("multiplicityOrdinal">0),
 "bindingMode" TEXT NOT NULL CHECK ("bindingMode" IN ('PRECAPTURED','OWNER_DERIVED')), "derivationRule" TEXT NOT NULL,
 "maxCatalogEvents" NUMERIC NOT NULL CHECK ("maxCatalogEvents">0 AND "maxCatalogEvents"=pg_catalog.trunc("maxCatalogEvents") AND "maxCatalogEvents"::TEXT NOT IN ('NaN','Infinity','-Infinity')),
 "maxDurableBytes" NUMERIC NOT NULL CHECK ("maxDurableBytes">0 AND "maxDurableBytes"=pg_catalog.trunc("maxDurableBytes") AND "maxDurableBytes"::TEXT NOT IN ('NaN','Infinity','-Infinity')),
 PRIMARY KEY ("scheduleId","bodyOrdinal"),
 UNIQUE ("scheduleId","bodyOrdinal","role","sourceIdentity","sourceReference","bindingMode","derivationRule")
);
-- The independently expected grant and schedule are published together.  The
-- deferred cycle binds actual rows while leaving the schedule core dependent
-- only on the preregistered grant ID, not its resulting provenance.
CREATE TABLE public."Pro273InvocationDebitGrant" (
 "grantId" TEXT PRIMARY KEY, "coreHash" TEXT NOT NULL CHECK ("coreHash" ~ '^[a-f0-9]{64}$'), "scheduleId" TEXT NOT NULL UNIQUE, "scheduleCoreHash" TEXT NOT NULL CHECK ("scheduleCoreHash" ~ '^[a-f0-9]{64}$'),
 "claimantScopeKind" TEXT NOT NULL, "claimantScopeId" TEXT NOT NULL, "claimantAllocationCoreHash" TEXT NOT NULL CHECK ("claimantAllocationCoreHash" ~ '^[a-f0-9]{64}$'),
 "claimantPrincipalOid" OID NOT NULL, "claimantPrincipalName" NAME NOT NULL, "claimantCredentialEpoch" TEXT NOT NULL, "claimantLaunchEpoch" TEXT NOT NULL,
 "workerScopeKind" TEXT NOT NULL, "workerScopeId" TEXT NOT NULL, "workerScopeCoreHash" TEXT NOT NULL CHECK ("workerScopeCoreHash" ~ '^[a-f0-9]{64}$'),
 "operation" TEXT NOT NULL, "branch" TEXT NOT NULL, "controlBaselineKind" TEXT NOT NULL, "maxInvocations" BIGINT NOT NULL CHECK ("maxInvocations">0),
 "sourceClosureHash" TEXT NOT NULL CHECK ("sourceClosureHash" ~ '^[a-f0-9]{64}$'), "installationClosureHash" TEXT NOT NULL CHECK ("installationClosureHash" ~ '^[a-f0-9]{64}$'),
 "physicalIdentity" TEXT NOT NULL, "physicalProofIdentity" TEXT NOT NULL, "validFrom" TIMESTAMPTZ NOT NULL, "validUntil" TIMESTAMPTZ NOT NULL CHECK ("validUntil">"validFrom"),
 UNIQUE ("grantId","scheduleId","scheduleCoreHash"), UNIQUE ("grantId","coreHash"),
 FOREIGN KEY ("scheduleId","scheduleCoreHash") REFERENCES public."Pro273InvocationSchedule"("id","coreHash") ON UPDATE RESTRICT ON DELETE RESTRICT DEFERRABLE INITIALLY DEFERRED,
 FOREIGN KEY ("physicalIdentity") REFERENCES public."Pro262CapacityPhysicalDomain"("physicalIdentity") ON UPDATE RESTRICT ON DELETE RESTRICT,
 FOREIGN KEY ("controlBaselineKind") REFERENCES public."Pro262CapacityControlBaseline"("kind") ON UPDATE RESTRICT ON DELETE RESTRICT
);
ALTER TABLE public."Pro273InvocationSchedule" ADD COLUMN "debitGrantId" TEXT NOT NULL;
ALTER TABLE public."Pro273InvocationSchedule" ADD CONSTRAINT "Pro273InvocationSchedule_debit_grant_fk" FOREIGN KEY ("debitGrantId","id","coreHash") REFERENCES public."Pro273InvocationDebitGrant"("grantId","scheduleId","scheduleCoreHash") ON UPDATE RESTRICT ON DELETE RESTRICT DEFERRABLE INITIALLY DEFERRED;
CREATE TRIGGER "Pro273InvocationDebitGrant_immutable" BEFORE UPDATE OR DELETE ON public."Pro273InvocationDebitGrant" FOR EACH ROW EXECUTE FUNCTION public.pro273_sel_immutable();
-- Atomic pair receipt: both deferred records and the complete body specs must
-- be inserted in this transaction. The receipt is never itself a dispatch.
-- Constructor still required: validate the protected installer context and
-- existing charge under the established global/physical lock order before
-- inserting schedule, all body specs, grant and receipt atomically. The raw
-- pair grant contains claimantPrincipalOid but no claimantPrincipalName; derive
-- and validate the name against the bound claimant authority, never from an
-- unrelated session or untrusted payload. Preserve the subsequent-transaction
-- receipt check below; these deferred foreign keys alone do not prove a
-- complete body-spec set or current authority.
CREATE TABLE public."Pro273InvocationPairReceipt" (
 "pairId" TEXT PRIMARY KEY, "pairCoreHash" TEXT NOT NULL CHECK ("pairCoreHash" ~ '^[a-f0-9]{64}$'),
 "scheduleId" TEXT NOT NULL UNIQUE, "scheduleCoreHash" TEXT NOT NULL, "grantId" TEXT NOT NULL UNIQUE, "grantCoreHash" TEXT NOT NULL,
 "expectationId" TEXT NOT NULL UNIQUE REFERENCES public."Pro273ControlPlaneInstallerExpectation"("expectationId") ON UPDATE RESTRICT ON DELETE RESTRICT,
 "inputClaimId" TEXT NOT NULL UNIQUE REFERENCES public."Pro262CapacityObserverInputClaim"("inputClaimId") ON UPDATE RESTRICT ON DELETE RESTRICT,
 "eventId" TEXT NOT NULL UNIQUE, "sessionClaimId" TEXT NOT NULL, "dispatchAttemptId" TEXT NOT NULL UNIQUE REFERENCES public."Pro273InstallerDispatchAttempt"("attemptId") ON UPDATE RESTRICT ON DELETE RESTRICT,
 "capturedBytes" BYTEA NOT NULL, "capturedLength" BIGINT NOT NULL, "capturedHash" TEXT NOT NULL CHECK ("capturedHash" ~ '^[a-f0-9]{64}$'),
 "evidenceBytes" BYTEA NOT NULL, "evidenceLength" BIGINT NOT NULL, "evidenceHash" TEXT NOT NULL CHECK ("evidenceHash" ~ '^[a-f0-9]{64}$'),
 "constructionTransactionId" xid8 NOT NULL, "chargeKind" TEXT NOT NULL, "chargeEventKey" TEXT NOT NULL, "chargeBindingHash" TEXT NOT NULL,
 UNIQUE ("chargeKind","chargeEventKey"),
 FOREIGN KEY ("scheduleId","scheduleCoreHash") REFERENCES public."Pro273InvocationSchedule"("id","coreHash") ON UPDATE RESTRICT ON DELETE RESTRICT DEFERRABLE INITIALLY DEFERRED,
 FOREIGN KEY ("grantId","grantCoreHash") REFERENCES public."Pro273InvocationDebitGrant"("grantId","coreHash") ON UPDATE RESTRICT ON DELETE RESTRICT DEFERRABLE INITIALLY DEFERRED,
 FOREIGN KEY ("grantId","scheduleId","scheduleCoreHash") REFERENCES public."Pro273InvocationDebitGrant"("grantId","scheduleId","scheduleCoreHash") ON UPDATE RESTRICT ON DELETE RESTRICT DEFERRABLE INITIALLY DEFERRED,
 FOREIGN KEY ("chargeKind","chargeEventKey") REFERENCES public."Pro262CapacityControlCharge"("kind","eventKey") ON UPDATE RESTRICT ON DELETE RESTRICT,
 CHECK ("capturedLength">0 AND "capturedLength"=pg_catalog.octet_length("capturedBytes") AND "evidenceLength">0 AND "evidenceLength"=pg_catalog.octet_length("evidenceBytes"))
);
CREATE TRIGGER "Pro273InvocationPairReceipt_immutable" BEFORE UPDATE OR DELETE ON public."Pro273InvocationPairReceipt" FOR EACH ROW EXECUTE FUNCTION public.pro273_sel_immutable();
CREATE FUNCTION public.pro273_sel_assert_committed_pair(p_schedule_id TEXT,p_grant_id TEXT) RETURNS VOID
LANGUAGE plpgsql SECURITY DEFINER SET search_path=pg_catalog AS $$
DECLARE v_pair public."Pro273InvocationPairReceipt"%ROWTYPE;
BEGIN
 SELECT p.* INTO STRICT v_pair FROM public."Pro273InvocationPairReceipt" p JOIN public."Pro273InvocationSchedule" s ON (s."id",s."coreHash",s."debitGrantId")=(p."scheduleId",p."scheduleCoreHash",p."grantId") JOIN public."Pro273InvocationDebitGrant" g ON (g."grantId",g."coreHash",g."scheduleId",g."scheduleCoreHash")=(p."grantId",p."grantCoreHash",p."scheduleId",p."scheduleCoreHash") WHERE p."scheduleId"=p_schedule_id AND p."grantId"=p_grant_id FOR SHARE OF p,s,g NOWAIT;
 IF v_pair."constructionTransactionId"=pg_catalog.pg_current_xact_id() THEN RAISE EXCEPTION 'SELECTION_UNAVAILABLE'; END IF;
END $$;
REVOKE ALL ON FUNCTION public.pro273_sel_assert_committed_pair(TEXT,TEXT) FROM PUBLIC;

-- Fixed pair entry prefix. The target-side provenance and qualifier receiver
-- producers are not yet present, so this entry must never construct a pair.
-- Keep the stronger accounting locks from the outset: nested installer reads
-- may reacquire them, but must not upgrade them after parsing.
CREATE FUNCTION public.pro273_sel_construct_invocation_pair(p_expectation_id TEXT,p_captured BYTEA) RETURNS TEXT
LANGUAGE plpgsql SECURITY DEFINER SET search_path=pg_catalog AS $$
DECLARE v_global RECORD; v_domain public."Pro262CapacityPhysicalDomain"%ROWTYPE;
 v_context JSONB; v_pair JSONB; v_schedule JSONB; v_grant JSONB; v_authority JSONB;
 v_resource public."Pro273ResourceSchedule"%ROWTYPE; v_input_domain public."Pro273QualifiedInputDomain"%ROWTYPE;
 v_charge public."Pro262CapacityControlCharge"%ROWTYPE; v_now TIMESTAMPTZ;
BEGIN
 IF p_expectation_id IS NULL OR p_captured IS NULL OR NOT pg_catalog.pg_has_role(SESSION_USER,'pro273_install_bootstrap','MEMBER') OR pg_catalog.current_setting('transaction_isolation') IS DISTINCT FROM 'read committed' THEN RAISE EXCEPTION 'SELECTION_UNAVAILABLE'; END IF;
 SELECT g."physicalIdentity",g."proofIdentity" INTO STRICT v_global FROM public."Pro311ControlDomain" g WHERE g."id"='global-v1' FOR UPDATE NOWAIT;
 SELECT d.* INTO STRICT v_domain FROM public."Pro262CapacityPhysicalDomain" d WHERE d."physicalIdentity"=v_global."physicalIdentity" FOR UPDATE NOWAIT;
 IF NOT v_domain."enabled" OR v_domain."proofIdentity" IS DISTINCT FROM v_global."proofIdentity" THEN RAISE EXCEPTION 'SELECTION_UNAVAILABLE'; END IF;
 PERFORM public.pro273_installer_assert_committed_delivery(p_expectation_id);
 v_context:=public.pro273_installer_metadata_context(p_expectation_id);
 IF v_context->>'constructorKind' IS DISTINCT FROM 'INVOCATION_SCHEDULE_GRANT_PAIR' OR v_context->>'physicalIdentity' IS DISTINCT FROM v_domain."physicalIdentity" OR v_context->>'physicalProofIdentity' IS DISTINCT FROM v_global."proofIdentity" THEN RAISE EXCEPTION 'SELECTION_UNAVAILABLE'; END IF;
 v_pair:=public.pro273_installer_parse_pair_metadata(p_expectation_id,p_captured);
 IF v_pair->'core'->>'pairId' IS DISTINCT FROM v_context->>'expectedTargetId' OR v_pair->>'pairCoreHash' IS DISTINCT FROM v_context->>'expectedCoreHash' THEN RAISE EXCEPTION 'SELECTION_UNAVAILABLE'; END IF;
 v_schedule:=v_pair->'core'->'scheduleCore'; v_grant:=v_pair->'core'->'grantCore'; v_authority:=v_schedule->'parserAuthority';
 -- Only the released bootstrap scalar mapping is eligible here. These
 -- comparisons are necessary but do not authenticate either funding scope.
 IF v_authority->>'kind' IS DISTINCT FROM 'BOOTSTRAP_PROFILE_HASH'
  OR v_grant->>'claimantScopeKind' IS DISTINCT FROM 'QUALIFIER_ALLOCATION'
  OR v_grant->>'claimantScopeId' IS DISTINCT FROM v_authority->'claimantFundingRef'->>'allocationId'
  OR v_grant->>'claimantAllocationCoreHash' IS DISTINCT FROM v_authority->'claimantFundingRef'->>'allocationCoreHash'
  OR v_grant->>'claimantPrincipalOid' IS DISTINCT FROM v_authority->'claimantFundingRef'->>'principalOid'
  OR v_grant->>'claimantCredentialEpoch' IS DISTINCT FROM v_authority->'claimantFundingRef'->>'credentialEpoch'
  OR v_grant->>'claimantLaunchEpoch' IS DISTINCT FROM v_authority->'claimantFundingRef'->>'launchEpoch'
  OR v_grant->>'workerScopeKind' IS DISTINCT FROM 'QUALIFIER_CONTROL'
  OR v_grant->>'workerScopeId' IS DISTINCT FROM v_authority->'workerScope'->>'controlId'
  OR v_grant->>'workerScopeCoreHash' IS DISTINCT FROM v_authority->'workerScope'->>'descriptorCoreHash'
  -- A scalar mismatch is only a necessary separation check, not proof of
  -- either protected principal or of independent funding/provenance.
  OR v_grant->>'claimantPrincipalOid' IS NOT DISTINCT FROM v_schedule->>'receiverPrincipalOid' THEN RAISE EXCEPTION 'SELECTION_UNAVAILABLE'; END IF;
 SELECT r.* INTO STRICT v_resource FROM public."Pro273ResourceSchedule" r
  WHERE (r."id",r."generation",r."coreHash")=(v_schedule->>'resourceScheduleId',(v_schedule->>'resourceScheduleGeneration')::BIGINT,v_schedule->>'resourceScheduleCoreHash') FOR SHARE NOWAIT;
 SELECT d.* INTO STRICT v_input_domain FROM public."Pro273QualifiedInputDomain" d
  WHERE (d."id",d."generation",d."coreHash")=(v_schedule->>'domainId',(v_schedule->>'domainGeneration')::BIGINT,v_schedule->>'resourceEnvelopeCoreHash') FOR SHARE NOWAIT;
 v_now:=pg_catalog.clock_timestamp();
 IF (v_input_domain."scheduleId",v_input_domain."scheduleGeneration",v_input_domain."resourceScheduleCoreHash") IS DISTINCT FROM (v_resource."id",v_resource."generation",v_resource."coreHash")
  OR (v_authority->>'resourceEnvelopeId',v_authority->>'resourceEnvelopeGeneration',v_authority->>'resourceEnvelopeCoreHash') IS DISTINCT FROM (v_input_domain."id",v_input_domain."generation"::TEXT,v_input_domain."coreHash")
  OR v_resource."operation" IS DISTINCT FROM v_schedule->>'operation' OR v_resource."branch" IS DISTINCT FROM v_schedule->>'branch'
  OR v_resource."sourceClosureHash" IS DISTINCT FROM v_schedule->>'sourceClosureHash' OR v_resource."installationClosureHash" IS DISTINCT FROM v_schedule->>'installationClosureHash'
  OR v_input_domain."sourceClosureHash" IS DISTINCT FROM v_schedule->>'sourceClosureHash'
  OR v_input_domain."semanticDomainHash" IS DISTINCT FROM v_resource."semanticDomainHash" OR v_input_domain."semanticDomainHash" IS DISTINCT FROM v_authority->>'semanticDomainHash'
  OR v_input_domain."parserAbiVersion" IS DISTINCT FROM v_resource."parserAbiVersion" OR v_input_domain."parserAbiVersion" IS DISTINCT FROM v_authority->>'parserAbiVersion'
  OR v_input_domain."primitiveAbiVersion" IS DISTINCT FROM v_resource."primitiveAbiVersion" OR v_input_domain."primitiveFunctionClosureHash" IS DISTINCT FROM v_resource."primitiveFunctionClosureHash"
  OR (v_schedule->>'bodyCount')::NUMERIC>v_resource."maxBodies" OR (v_schedule->>'bodyCount')::NUMERIC>v_input_domain."maxBodies"
  OR v_resource."scopeKind" IS DISTINCT FROM 'QUALIFIER_ALLOCATION'
  OR v_resource."controlId" IS DISTINCT FROM v_authority->'workerScope'->>'controlId'
  OR v_resource."allocationId" IS DISTINCT FROM v_authority->'workerScope'->>'allocationId'
  OR v_resource."allocationCoreHash" IS DISTINCT FROM v_authority->'workerScope'->>'allocationCoreHash'
  OR v_resource."claimantFunding" IS DISTINCT FROM v_authority->'claimantFundingRef'
  OR v_resource."workerFunding"->>'kind' IS DISTINCT FROM 'QUALIFIER_ALLOCATION'
  OR v_resource."workerFunding"->>'controlId' IS DISTINCT FROM v_authority->'workerScope'->>'controlId'
  OR v_resource."workerFunding"->>'allocationId' IS DISTINCT FROM v_authority->'workerScope'->>'allocationId'
  OR v_resource."workerFunding"->>'allocationCoreHash' IS DISTINCT FROM v_authority->'workerScope'->>'allocationCoreHash'
  OR v_resource."workerFunding"->>'descriptorCoreHash' IS DISTINCT FROM v_authority->'workerScope'->>'descriptorCoreHash'
  OR v_resource."workerFunding"->>'principalOid' IS DISTINCT FROM v_schedule->>'receiverPrincipalOid'
  OR v_resource."workerFunding"->>'credentialEpoch' IS DISTINCT FROM v_schedule->>'credentialEpoch'
  OR v_resource."workerFunding"->>'launchEpoch' IS DISTINCT FROM v_schedule->>'launchEpoch'
  OR v_resource."physicalIdentity" IS DISTINCT FROM v_domain."physicalIdentity" OR v_resource."physicalProofIdentity" IS DISTINCT FROM v_global."proofIdentity"
  OR v_input_domain."physicalIdentity" IS DISTINCT FROM v_domain."physicalIdentity" OR v_input_domain."physicalProofIdentity" IS DISTINCT FROM v_global."proofIdentity"
  OR v_now<v_resource."validFrom" OR v_now>=v_resource."validUntil" OR v_now<v_input_domain."validFrom" OR v_now>=v_input_domain."validUntil" THEN RAISE EXCEPTION 'SELECTION_UNAVAILABLE'; END IF;
 SELECT c.* INTO STRICT v_charge FROM public."Pro262CapacityControlCharge" c WHERE (c."kind",c."eventKey")=(v_context->'charge'->>'kind',v_context->'charge'->>'eventKey') FOR SHARE NOWAIT;
 IF v_charge."bindingHash" IS DISTINCT FROM v_context->'charge'->>'bindingHash' THEN RAISE EXCEPTION 'SELECTION_UNAVAILABLE'; END IF;
 -- No authority may be inferred from parsed metadata. Until the independent
 -- resource, allocation, descriptor and receiver provenance joins exist,
 -- deny rather than insert partial records or reuse a spent attempt.
 -- Before enabling, authenticate the complete worker principal/credential/launch
 -- tuple against the descriptor and allocation. Route target identities first,
 -- then acquire and revalidate all earlier-phase target locks in the reviewed
 -- global lock order before the resource and input-domain pins; do not append
 -- those locks here after the pins.
 RAISE EXCEPTION 'SELECTION_UNAVAILABLE';
EXCEPTION WHEN OTHERS THEN RAISE EXCEPTION 'SELECTION_UNAVAILABLE'; END $$;
REVOKE ALL ON FUNCTION public.pro273_sel_construct_invocation_pair(TEXT,BYTEA) FROM PUBLIC;

-- The receiver checks this in a subsequent transaction after constructor
-- COMMIT. It is outcome correlation only and never authorizes redispatch.
CREATE FUNCTION public.pro273_installer_constructor_receipt(p_expectation_id TEXT) RETURNS JSONB
LANGUAGE plpgsql SECURITY DEFINER SET search_path=pg_catalog AS $$
DECLARE v_context JSONB; v_base public."Pro273ControlPlaneBaselineProvenance"%ROWTYPE; v_pair public."Pro273InvocationPairReceipt"%ROWTYPE;
 v_result TEXT; v_core_hash TEXT; v_capture_hash TEXT; v_evidence_hash TEXT; v_creation xid8; v_input TEXT; v_session TEXT; v_event TEXT;
 v_descriptor_hint BOOLEAN;
BEGIN
 -- Deny descriptor receipts before helpers acquire their own locks. This
 -- bounded hint is routing only, not authentication or a prelock snapshot.
 SELECT e."constructorKind"='QUALIFIER_DESCRIPTOR' INTO STRICT v_descriptor_hint
 FROM public."Pro273ControlPlaneInstallerExpectation" e WHERE e."expectationId"=p_expectation_id;
 IF v_descriptor_hint THEN RAISE EXCEPTION 'SELECTION_UNAVAILABLE'; END IF;
 PERFORM public.pro273_installer_assert_committed_delivery(p_expectation_id);
 v_context:=public.pro273_installer_metadata_context(p_expectation_id);
 IF v_context->>'constructorKind'='CONTROL_PLANE_BASELINE' THEN
  SELECT p.* INTO STRICT v_base FROM public."Pro273ControlPlaneBaselineProvenance" p WHERE p."baselineId"=v_context->>'expectedTargetId' FOR SHARE NOWAIT;
  v_result:=v_base."baselineId";v_core_hash:=v_base."coreHash";v_capture_hash:=v_base."capturedHash";v_evidence_hash:=v_base."evidenceHash";v_creation:=v_base."constructionTransactionId";v_input:=v_base."inputClaimId";v_session:=v_base."sessionClaimId";v_event:=v_base."eventId";
 ELSIF v_context->>'constructorKind'='QUALIFIER_DESCRIPTOR' THEN
  -- Held until publication, lock schedule, receiver and recovery are qualified.
  RAISE EXCEPTION 'SELECTION_UNAVAILABLE';
  SELECT d."controlId",d."descriptorCoreHash",p."capturedHash",p."evidenceHash",l."constructionTransactionId",p."inputClaimId",p."sessionClaimId",p."eventId"
   INTO STRICT v_result,v_core_hash,v_capture_hash,v_evidence_hash,v_creation,v_input,v_session,v_event
  FROM public."Pro273ControlPlaneInstallerExpectation" e
  JOIN public."Pro273InstallerDelivery" delivery ON (delivery."expectationId",delivery."attemptId",delivery."sessionClaimId",delivery."inputClaimId",delivery."eventId")=(e."expectationId",e."dispatchAttemptId",v_context->>'sessionClaimId',v_context->>'inputClaimId',e."eventId")
  JOIN public."Pro273QualificationInputDescriptor" d ON (d."controlId",d."descriptorCoreHash")=(e."expectedTargetId",e."expectedCoreHash")
  JOIN public."Pro273QualifierDescriptorProvenance" p ON (p."controlId",p."coreHash")=(d."controlId",d."descriptorCoreHash")
  JOIN public."Pro273QualifierDescriptorLinkage" l ON (l."controlId",l."coreHash",l."expectationId",l."dispatchAttemptId",l."sessionClaimId",l."inputClaimId",l."eventId")=(p."controlId",p."coreHash",e."expectationId",delivery."attemptId",p."sessionClaimId",p."inputClaimId",p."eventId")
  JOIN public."Pro273QualifierDescriptorProof" q ON (q."controlId",q."coreHash")=(l."controlId",l."coreHash")
  CROSS JOIN LATERAL (SELECT public.pro273_installer_parse_descriptor_metadata(p_expectation_id,p."capturedBytes") AS payload) original
  JOIN public."Pro273QualifierAllocation" a ON (a."allocationId",a."coreHash") IS NOT DISTINCT FROM (d."allocationId",d."allocationCoreHash")
  JOIN public."Pro262CapacityControlCharge" charge ON (charge."kind",charge."eventKey",charge."bindingHash") IS NOT DISTINCT FROM (e."chargeKind",e."chargeEventKey",e."chargeBindingHash")
  JOIN public."Pro273QualificationInputState" st ON st."controlId"=d."controlId"
  JOIN public."Pro273QualificationTransitionReceipt" t ON (t."controlId",t."transitionOrdinal")=(d."controlId",1)
  JOIN public."Pro262CapacityObserverInputClaim" c ON c."inputClaimId"=delivery."inputClaimId"
  JOIN public."Pro262CapacityObserverInputReservation" r ON r."reservationId"=c."reservationId"
  JOIN public."Pro262CapacityTrust" trust ON (trust."trustId",trust."generation")=(r."observerTrustId",r."observerTrustGeneration")
  WHERE e."expectationId"=p_expectation_id AND e."constructorKind"='QUALIFIER_DESCRIPTOR'
   AND (p."sessionClaimId",p."inputClaimId",p."eventId") IS NOT DISTINCT FROM (delivery."sessionClaimId",delivery."inputClaimId",delivery."eventId")
   AND (p."bootstrapKind",p."bootstrapRecordHash",p."bootstrapEvidenceHash",p."trustId",p."trustGeneration",p."trustRecordHash",p."publisherPrincipalOid",p."publisherPrincipalName",p."chargeKind",p."chargeEventKey",p."chargeBindingHash") IS NOT DISTINCT FROM (e."bootstrapKind",e."expectedCoreHash",e."expectedEvidenceHash",e."trustId",e."trustGeneration",e."trustRecordHash",e."installerOid",e."installerName",e."chargeKind",e."chargeEventKey",e."chargeBindingHash")
   AND c."reservationId"=e."constructorInputReservationId" AND public.pro273_installer_slot_matches(r."reservationId") IS TRUE
   AND (q."observerGroupProof"=d."observerGroupProof" AND r."baselineAllocationProof"=q."observerGroupProof" AND trust."scope"->>'inputEnvelope'=q."observerGroupProof") IS TRUE
   AND (original.payload->>'descriptorCoreHash'=d."descriptorCoreHash" AND original.payload->>'observerGroupProof'=q."observerGroupProof" AND pg_catalog.decode(original.payload->>'evidenceBase64','base64')=p."evidenceBytes") IS TRUE
   AND (d."controlId",d."descriptorCoreHash",d."allocationId",d."allocationCoreHash",d."sourceIdentity",d."namespace",d."project",d."deployment",d."environment",d."principalOid"::TEXT,d."principalName"::TEXT,d."credentialEpoch",d."launchEpoch",d."observerGroupProof",d."physicalIdentity",d."physicalProofIdentity",d."baselinePartitionId",d."controlChargeKind",d."controlChargeEventKey",d."bootstrapRecordHash",d."expiresAt") IS NOT DISTINCT FROM (original.payload->'core'->>'controlId',original.payload->>'descriptorCoreHash',original.payload->'core'->>'allocationId',original.payload->'core'->>'allocationCoreHash',original.payload->'core'->>'sourceIdentity',original.payload->'core'->>'namespace',original.payload->'core'->>'project',original.payload->'core'->>'deployment',original.payload->'core'->>'environment',original.payload->'core'->>'principalOid',original.payload->'core'->>'principalName',original.payload->'core'->>'credentialEpoch',original.payload->'core'->>'launchEpoch',original.payload->>'observerGroupProof',original.payload->'core'->>'physicalIdentity',original.payload->'core'->>'physicalProofIdentity',original.payload->'core'->>'baselinePartitionId',e."chargeKind",e."chargeEventKey",e."expectedCoreHash",(original.payload->'core'->>'expiresAt')::TIMESTAMPTZ)
   AND (a."controlId",a."partitionId",a."physicalIdentity",a."physicalProofIdentity",a."principalOid",a."principalName",a."credentialEpoch",a."launchEpoch",a."sourceIdentity",a."namespace",a."project",a."deployment",a."environment") IS NOT DISTINCT FROM (d."controlId",d."baselinePartitionId",d."physicalIdentity",d."physicalProofIdentity",d."principalOid",d."principalName",d."credentialEpoch",d."launchEpoch",d."sourceIdentity",d."namespace",d."project",d."deployment",d."environment")
   AND (p."capturedLength"=pg_catalog.octet_length(p."capturedBytes") AND p."capturedHash"=pg_catalog.encode(int4_crypto.digest(p."capturedBytes",'sha256'),'hex') AND p."evidenceLength"=pg_catalog.octet_length(p."evidenceBytes") AND p."evidenceHash"=pg_catalog.encode(int4_crypto.digest(p."evidenceBytes",'sha256'),'hex')) IS TRUE
   AND (t."fromState",t."toState",t."fromConnectionState",t."toConnectionState",t."bindingHash") IS NOT DISTINCT FROM ('NONE','RESERVED','NONE','OPENING',p."capturedHash")
   AND (t."receiptId"=pg_catalog.encode(int4_crypto.digest(pg_catalog.convert_to(pg_catalog.jsonb_build_array('pro273.qualifier.transition.v1',d."controlId",'1'::TEXT,p."capturedHash")::TEXT,'UTF8'),'sha256'),'hex') AND t."occurredAt" IS NOT NULL) IS TRUE
   AND l."constructionTransactionId" IS DISTINCT FROM pg_catalog.pg_current_xact_id();
 ELSIF v_context->>'constructorKind'='INVOCATION_SCHEDULE_GRANT_PAIR' THEN
  SELECT p.* INTO STRICT v_pair FROM public."Pro273InvocationPairReceipt" p WHERE p."expectationId"=p_expectation_id FOR SHARE NOWAIT;
  PERFORM public.pro273_sel_assert_committed_pair(v_pair."scheduleId",v_pair."grantId");
  IF v_pair."pairId" IS DISTINCT FROM v_context->>'expectedTargetId' OR v_pair."dispatchAttemptId" IS DISTINCT FROM v_context->>'dispatchAttemptId' THEN RAISE EXCEPTION 'SELECTION_UNAVAILABLE'; END IF;
  v_result:=v_pair."pairId";v_core_hash:=v_pair."pairCoreHash";v_capture_hash:=v_pair."capturedHash";v_evidence_hash:=v_pair."evidenceHash";v_creation:=v_pair."constructionTransactionId";v_input:=v_pair."inputClaimId";v_session:=v_pair."sessionClaimId";v_event:=v_pair."eventId";
 ELSE RAISE EXCEPTION 'SELECTION_UNAVAILABLE'; END IF;
 IF v_creation=pg_catalog.pg_current_xact_id() OR v_core_hash IS DISTINCT FROM v_context->>'expectedCoreHash' OR v_evidence_hash IS DISTINCT FROM v_context->>'expectedEvidenceHash' OR v_input IS DISTINCT FROM v_context->>'inputClaimId' OR v_session IS DISTINCT FROM v_context->>'sessionClaimId' OR v_event IS DISTINCT FROM v_context->>'eventId' OR v_capture_hash !~ '^[a-f0-9]{64}$' THEN RAISE EXCEPTION 'SELECTION_UNAVAILABLE'; END IF;
 RETURN pg_catalog.jsonb_build_object('schemaVersion','pro273-installer-receipt-v1','phase','CONSTRUCTOR_COMMITTED','expectationId',p_expectation_id,'attemptId',v_context->>'dispatchAttemptId','sessionClaimId',v_session,'inputClaimId',v_input,'eventId',v_event,'constructorKind',v_context->>'constructorKind','resultId',v_result,'coreHash',v_core_hash,'captureHash',v_capture_hash,'evidenceHash',v_evidence_hash,'creationTransactionId',v_creation::TEXT);
EXCEPTION WHEN OTHERS THEN RAISE EXCEPTION 'SELECTION_UNAVAILABLE'; END $$;
REVOKE ALL ON FUNCTION public.pro273_installer_constructor_receipt(TEXT) FROM PUBLIC;



CREATE TABLE public."Pro273InvocationClaim" (
 "claimId" TEXT PRIMARY KEY, "scheduleId" TEXT NOT NULL, "scheduleCoreHash" TEXT NOT NULL, "dispatchAttemptId" TEXT NOT NULL, "invocationOrdinal" BIGINT NOT NULL CHECK ("invocationOrdinal">0), "deliveryEvent" TEXT NOT NULL UNIQUE,
 "receiverPrincipalOid" OID NOT NULL, "receiverPrincipalName" NAME NOT NULL, "receiverPid" INTEGER NOT NULL CHECK ("receiverPid">0), "receiverBackendStart" TIMESTAMPTZ NOT NULL,
 "credentialEpoch" TEXT NOT NULL, "launchEpoch" TEXT NOT NULL, "operation" TEXT NOT NULL, "sourceClosureHash" TEXT NOT NULL, "installationClosureHash" TEXT NOT NULL,
 "bodyCount" BIGINT NOT NULL CHECK ("bodyCount">0), "expiresAt" TIMESTAMPTZ NOT NULL,
 "chargeKind" TEXT NOT NULL, "chargeEventKey" TEXT NOT NULL, "chargeBindingHash" TEXT NOT NULL,
 UNIQUE ("scheduleId","invocationOrdinal"), UNIQUE ("scheduleId","dispatchAttemptId"), UNIQUE ("scheduleId","claimId"), UNIQUE ("chargeKind","chargeEventKey"),
 UNIQUE ("scheduleId","claimId","chargeKind","chargeEventKey","chargeBindingHash"),
 FOREIGN KEY ("scheduleId","scheduleCoreHash") REFERENCES public."Pro273InvocationSchedule"("id","coreHash") ON UPDATE RESTRICT ON DELETE RESTRICT,
 FOREIGN KEY ("chargeKind","chargeEventKey") REFERENCES public."Pro262CapacityControlCharge"("kind","eventKey") ON UPDATE RESTRICT ON DELETE RESTRICT
);
CREATE TABLE public."Pro273InvocationBodyUse" (
 "claimId" TEXT NOT NULL, "scheduleId" TEXT NOT NULL, "bodyOrdinal" BIGINT NOT NULL, "bodyUseId" TEXT NOT NULL UNIQUE,
 "bodyRole" TEXT NOT NULL, "sourceIdentity" TEXT NOT NULL, "sourceReference" TEXT NOT NULL,
 "bindingMode" TEXT NOT NULL CHECK ("bindingMode" IN ('PRECAPTURED','OWNER_DERIVED')), "derivationRule" TEXT NOT NULL,
 "capturedLength" NUMERIC CHECK ("capturedLength">=0 AND "capturedLength"=pg_catalog.trunc("capturedLength") AND "capturedLength"::TEXT NOT IN ('NaN','Infinity','-Infinity')),
 "capturedHash" TEXT CHECK ("capturedHash" ~ '^[a-f0-9]{64}$'), "catalogEventKey" TEXT NOT NULL UNIQUE,
 CHECK (("bindingMode"='PRECAPTURED' AND "capturedLength" IS NOT NULL AND "capturedHash" IS NOT NULL AND "derivationRule"='AUTHENTICATED_PRECAPTURE') OR
        ("bindingMode"='OWNER_DERIVED' AND "capturedLength" IS NULL AND "capturedHash" IS NULL AND "derivationRule" IN ('LOCKED_INPUT_FROM_OWNING_LOCKS','VALIDATED_INTENT_FROM_BOUND_REQUEST','PROPOSED_FINAL_FROM_INDEPENDENT_OWNING_DERIVATION'))),
 "chargeKind" TEXT NOT NULL, "chargeEventKey" TEXT NOT NULL, "chargeBindingHash" TEXT NOT NULL,
 PRIMARY KEY ("claimId","bodyOrdinal"), UNIQUE ("bodyUseId","claimId","bodyOrdinal","bodyRole","derivationRule","sourceIdentity","sourceReference"),
 FOREIGN KEY ("scheduleId","claimId","chargeKind","chargeEventKey","chargeBindingHash") REFERENCES public."Pro273InvocationClaim"("scheduleId","claimId","chargeKind","chargeEventKey","chargeBindingHash") ON UPDATE RESTRICT ON DELETE RESTRICT,
 FOREIGN KEY ("scheduleId","bodyOrdinal","bodyRole","sourceIdentity","sourceReference","bindingMode","derivationRule") REFERENCES public."Pro273InvocationBodySpec"("scheduleId","bodyOrdinal","role","sourceIdentity","sourceReference","bindingMode","derivationRule") ON UPDATE RESTRICT ON DELETE RESTRICT,
 FOREIGN KEY ("chargeKind","chargeEventKey") REFERENCES public."Pro262CapacityControlCharge"("kind","eventKey") ON UPDATE RESTRICT ON DELETE RESTRICT
);
-- Work bindings describe actual bytes in the worker transaction; rollback of
-- this row cannot roll back the separately committed claim or budget.
CREATE TABLE public."Pro273InvocationWorkBodyBinding" (
 "bodyUseId" TEXT PRIMARY KEY, "claimId" TEXT NOT NULL, "bodyOrdinal" BIGINT NOT NULL,
 "bodyRole" TEXT NOT NULL, "derivationRule" TEXT NOT NULL, "sourceIdentity" TEXT NOT NULL, "sourceReference" TEXT NOT NULL, "sourceBindingHash" TEXT NOT NULL CHECK ("sourceBindingHash" ~ '^[a-f0-9]{64}$'),
 "workerPrincipalOid" OID NOT NULL, "workerPrincipalName" NAME NOT NULL, "credentialEpoch" TEXT NOT NULL, "launchEpoch" TEXT NOT NULL, "backendPid" INTEGER NOT NULL CHECK ("backendPid">0), "backendStart" TIMESTAMPTZ NOT NULL, "transactionId" XID8 NOT NULL,
 "capturedLength" NUMERIC NOT NULL CHECK ("capturedLength">=0 AND "capturedLength"=pg_catalog.trunc("capturedLength") AND "capturedLength"::TEXT NOT IN ('NaN','Infinity','-Infinity')),
 "capturedHash" TEXT NOT NULL CHECK ("capturedHash" ~ '^[a-f0-9]{64}$'), "boundAt" TIMESTAMPTZ NOT NULL,
 UNIQUE ("claimId","bodyOrdinal"), FOREIGN KEY ("bodyUseId","claimId","bodyOrdinal","bodyRole","derivationRule","sourceIdentity","sourceReference") REFERENCES public."Pro273InvocationBodyUse"("bodyUseId","claimId","bodyOrdinal","bodyRole","derivationRule","sourceIdentity","sourceReference") ON UPDATE RESTRICT ON DELETE RESTRICT
);
CREATE TRIGGER "Pro273InvocationWorkBodyBinding_immutable" BEFORE UPDATE OR DELETE ON public."Pro273InvocationWorkBodyBinding" FOR EACH ROW EXECUTE FUNCTION public.pro273_sel_immutable();
CREATE TRIGGER "Pro273InvocationSchedule_immutable" BEFORE UPDATE OR DELETE ON public."Pro273InvocationSchedule" FOR EACH ROW EXECUTE FUNCTION public.pro273_sel_immutable();
CREATE TRIGGER "Pro273InvocationBodySpec_immutable" BEFORE UPDATE OR DELETE ON public."Pro273InvocationBodySpec" FOR EACH ROW EXECUTE FUNCTION public.pro273_sel_immutable();
CREATE TRIGGER "Pro273InvocationClaim_immutable" BEFORE UPDATE OR DELETE ON public."Pro273InvocationClaim" FOR EACH ROW EXECUTE FUNCTION public.pro273_sel_immutable();
CREATE TRIGGER "Pro273InvocationBodyUse_immutable" BEFORE UPDATE OR DELETE ON public."Pro273InvocationBodyUse" FOR EACH ROW EXECUTE FUNCTION public.pro273_sel_immutable();

-- Independent observer capture for the exact installer-root lane. The observer
-- reservation and constructor-input reservation are never interchangeable.
CREATE FUNCTION public.pro273_installer_accept_process_observation(p_expectation_id TEXT,p_input_claim_id TEXT,p_observation JSONB,p_captured BYTEA) RETURNS TEXT
LANGUAGE plpgsql SECURITY DEFINER SET search_path=pg_catalog AS $$
DECLARE v_global RECORD; v_domain public."Pro262CapacityPhysicalDomain"%ROWTYPE; v_expected public."Pro273ControlPlaneInstallerExpectation"%ROWTYPE;
 v_claim public."Pro262CapacityObserverInputClaim"%ROWTYPE; v_slot public."Pro262CapacityObserverInputReservation"%ROWTYPE; v_binding public."Pro273InstallerSlotBinding"%ROWTYPE;
 v_trust public."Pro262CapacityTrust"%ROWTYPE; v_prior public."Pro273InstallerProcessObservation"%ROWTYPE;
 v_field TEXT; v_lane JSONB; v_evidence BYTEA; v_hash TEXT; v_receipt TEXT; v_oid OID; v_now TIMESTAMPTZ; v_charge public."Pro262CapacityControlCharge"%ROWTYPE;
BEGIN
 IF NOT pg_catalog.pg_has_role(SESSION_USER,'pro262_install_observer','MEMBER') OR COALESCE(p_expectation_id,'')='' OR COALESCE(p_input_claim_id,'')='' OR p_captured IS NULL OR p_observation IS NULL THEN RAISE EXCEPTION 'SELECTION_UNAVAILABLE'; END IF;
 LOCK TABLE public."Pro311ControlDomain" IN ACCESS SHARE MODE NOWAIT;
 SELECT g."physicalIdentity",g."proofIdentity" INTO STRICT v_global FROM public."Pro311ControlDomain" g WHERE g."id"='global-v1' FOR UPDATE NOWAIT;
 SELECT d.* INTO STRICT v_domain FROM public."Pro262CapacityPhysicalDomain" d WHERE d."physicalIdentity"=v_global."physicalIdentity" FOR UPDATE NOWAIT;
 SELECT c.* INTO STRICT v_claim FROM public."Pro262CapacityObserverInputClaim" c WHERE c."inputClaimId"=p_input_claim_id;
 SELECT r.* INTO STRICT v_slot FROM public."Pro262CapacityObserverInputReservation" r WHERE r."reservationId"=v_claim."reservationId";
 SELECT t.* INTO STRICT v_trust FROM public."Pro262CapacityTrust" t WHERE (t."trustId",t."generation")=(v_slot."observerTrustId",v_slot."observerTrustGeneration") FOR SHARE NOWAIT;
 SELECT e.* INTO STRICT v_expected FROM public."Pro273ControlPlaneInstallerExpectation" e WHERE e."expectationId"=p_expectation_id FOR SHARE NOWAIT;
 SELECT b.* INTO STRICT v_binding FROM public."Pro273InstallerSlotBinding" b WHERE b."reservationId"=v_slot."reservationId" FOR SHARE NOWAIT;
 SELECT r.* INTO STRICT v_slot FROM public."Pro262CapacityObserverInputReservation" r WHERE r."reservationId"=v_claim."reservationId" FOR SHARE NOWAIT;
 SELECT c.* INTO STRICT v_claim FROM public."Pro262CapacityObserverInputClaim" c WHERE c."inputClaimId"=p_input_claim_id FOR SHARE NOWAIT;
 SELECT r.oid INTO STRICT v_oid FROM pg_catalog.pg_roles r WHERE r.rolname=SESSION_USER::NAME AND r.rolcanlogin AND NOT r.rolsuper;
 v_now:=pg_catalog.clock_timestamp();v_lane:=pg_catalog.jsonb_build_object('namespace',v_expected."namespace",'project',v_expected."project",'deployment',v_expected."deployment",'environment',v_expected."environment",'kind','INSTALLER_ROOT');
 IF NOT v_domain."enabled" OR v_domain."proofIdentity" IS DISTINCT FROM v_global."proofIdentity" OR v_expected."physicalIdentity" IS DISTINCT FROM v_domain."physicalIdentity" OR v_expected."physicalProofIdentity" IS DISTINCT FROM v_domain."proofIdentity" OR v_expected."physicalEvidenceHash" IS DISTINCT FROM v_domain."evidenceHash" OR
    v_expected."validFrom">v_now OR v_expected."validUntil"<=v_now OR v_trust."purpose"<>'INSTALL_OBSERVATION' OR v_trust."revoked" OR v_trust."validFrom">v_now OR v_trust."validUntil"<=v_now OR v_trust."supplierPrincipal" IS DISTINCT FROM SESSION_USER::NAME OR v_trust."scope"->'lane' IS DISTINCT FROM v_lane OR
    v_binding."bindingKind"<>'INSTALLER_OBSERVATION' OR v_binding."phase"<>'INSTALL_PROCESS' OR v_binding."expectationId" IS DISTINCT FROM p_expectation_id OR v_binding."credentialEpoch" IS DISTINCT FROM v_expected."credentialEpoch" OR v_binding."launchEpoch" IS DISTINCT FROM v_expected."launchEpoch" OR
    v_slot."record"->>'targetKind' IS DISTINCT FROM 'INSTALLER_ROOT' OR v_slot."record"->>'targetControlKey' IS DISTINCT FROM p_expectation_id OR v_slot."record"->>'targetCredentialEpoch' IS DISTINCT FROM v_expected."credentialEpoch" OR v_slot."record"->>'targetLaunchEpoch' IS DISTINCT FROM v_expected."launchEpoch" OR
    v_slot."physicalIdentity" IS DISTINCT FROM v_domain."physicalIdentity" OR v_slot."physicalProofIdentity" IS DISTINCT FROM v_domain."proofIdentity" OR v_slot."baselineAllocationProof" IS DISTINCT FROM v_trust."scope"->>'observerHolderId' OR v_slot."phase"<>'INSTALL_PROCESS' OR v_claim."phase"<>'INSTALL_PROCESS' OR v_claim."eventKey" IS DISTINCT FROM v_binding."expectedEventKey" OR
    v_oid=v_expected."installerOid" OR v_claim."observerPrincipalOid" IS DISTINCT FROM v_oid OR v_claim."observerPrincipalName" IS DISTINCT FROM SESSION_USER::NAME OR v_slot."observerPrincipalOid" IS DISTINCT FROM v_oid OR v_slot."observerPrincipalName" IS DISTINCT FROM SESSION_USER::NAME OR
    v_slot."record"->>'observerBackendPid' IS DISTINCT FROM pg_catalog.pg_backend_pid()::TEXT OR (v_slot."record"->>'observerBackendStart')::TIMESTAMPTZ IS DISTINCT FROM public.pro262_capacity_backend_start() OR pg_catalog.octet_length(p_captured)=0 OR pg_catalog.octet_length(p_captured)>v_slot."maxInputBytes" THEN RAISE EXCEPTION 'SELECTION_UNAVAILABLE'; END IF;
 PERFORM public.pro262_capacity_assert_observer_claim(p_input_claim_id,'INSTALL_PROCESS',v_binding."expectedEventKey",pg_catalog.octet_length(p_captured));
 IF pg_catalog.jsonb_typeof(p_observation) IS DISTINCT FROM 'object' OR (SELECT pg_catalog.count(*) FROM pg_catalog.jsonb_object_keys(p_observation))<>23 OR NOT (p_observation ?& ARRAY['observationVersion','observationId','trustId','trustGeneration','controlKey','kind','credentialEpoch','launchEpoch','principalName','principalOid','pid','backendStart','host','boot','processTree','installationGeneration','installationEvidenceHash','installation','observedAt','validUntil','evidence','evidenceHash','inputClaimId']) THEN RAISE EXCEPTION 'SELECTION_UNAVAILABLE'; END IF;
 FOREACH v_field IN ARRAY ARRAY['observationVersion','observationId','trustId','trustGeneration','controlKey','kind','credentialEpoch','launchEpoch','principalName','principalOid','pid','backendStart','host','boot','processTree','installationGeneration','installationEvidenceHash','observedAt','validUntil','evidence','evidenceHash','inputClaimId'] LOOP IF pg_catalog.jsonb_typeof(p_observation->v_field) IS DISTINCT FROM 'string' OR COALESCE(p_observation->>v_field,'')='' THEN RAISE EXCEPTION 'SELECTION_UNAVAILABLE'; END IF; END LOOP;
 IF pg_catalog.convert_from(p_captured,'UTF8')::JSONB IS DISTINCT FROM p_observation OR p_observation->>'observationVersion'<>'1' OR p_observation->>'kind'<>'INSTALLER_ROOT' OR p_observation->>'controlKey' IS DISTINCT FROM p_expectation_id OR p_observation->>'inputClaimId' IS DISTINCT FROM p_input_claim_id OR
    p_observation->>'trustId' IS DISTINCT FROM v_trust."trustId" OR p_observation->>'trustGeneration' IS DISTINCT FROM v_trust."generation"::TEXT OR p_observation->>'credentialEpoch' IS DISTINCT FROM v_expected."credentialEpoch" OR p_observation->>'launchEpoch' IS DISTINCT FROM v_expected."launchEpoch" OR
    p_observation->>'principalOid' IS DISTINCT FROM v_expected."installerOid"::TEXT OR p_observation->>'principalName' IS DISTINCT FROM v_expected."installerName"::TEXT OR p_observation->>'pid' IS DISTINCT FROM v_expected."installerPid"::TEXT OR (p_observation->>'backendStart')::TIMESTAMPTZ IS DISTINCT FROM v_expected."installerBackendStart" OR
    p_observation->>'host' IS DISTINCT FROM v_expected."host" OR p_observation->>'boot' IS DISTINCT FROM v_expected."boot" OR p_observation->>'processTree' IS DISTINCT FROM v_expected."processTree" OR p_observation->'installation' IS DISTINCT FROM v_trust."scope"->'installation' OR p_observation->>'installationGeneration' IS DISTINCT FROM v_trust."scope"->>'installationGeneration' OR p_observation->>'installationEvidenceHash' IS DISTINCT FROM v_trust."scope"->>'installationEvidenceHash' OR
    p_observation->'installation'->>'sourceClosure' IS DISTINCT FROM v_expected."sourceClosureHash" OR pg_catalog.encode(int4_crypto.digest(pg_catalog.convert_to((p_observation->'installation')::TEXT,'UTF8'),'sha256'),'hex') IS DISTINCT FROM v_expected."installationClosureHash" OR
    (p_observation->>'observedAt')::TIMESTAMPTZ>v_now OR (p_observation->>'validUntil')::TIMESTAMPTZ<=v_now OR (p_observation->>'validUntil')::TIMESTAMPTZ>v_trust."validUntil" THEN RAISE EXCEPTION 'SELECTION_UNAVAILABLE'; END IF;
 v_evidence:=pg_catalog.decode(p_observation->>'evidence','base64');v_hash:=pg_catalog.encode(int4_crypto.digest(p_captured,'sha256'),'hex');
 IF pg_catalog.octet_length(v_evidence)=0 OR pg_catalog.replace(pg_catalog.encode(v_evidence,'base64'),E'\n','') IS DISTINCT FROM p_observation->>'evidence' OR pg_catalog.encode(int4_crypto.digest(v_evidence,'sha256'),'hex') IS DISTINCT FROM p_observation->>'evidenceHash' THEN RAISE EXCEPTION 'SELECTION_UNAVAILABLE'; END IF;
 v_receipt:=pg_catalog.encode(int4_crypto.digest(pg_catalog.convert_to(pg_catalog.jsonb_build_array('pro273.installer.process.v1',p_expectation_id,v_expected."credentialEpoch",v_expected."launchEpoch",p_input_claim_id,v_hash)::TEXT,'UTF8'),'sha256'),'hex');
 SELECT o.* INTO v_prior FROM public."Pro273InstallerProcessObservation" o WHERE (o."expectationId",o."credentialEpoch",o."launchEpoch")=(p_expectation_id,v_expected."credentialEpoch",v_expected."launchEpoch");
 IF FOUND THEN IF v_prior."receiptId" IS DISTINCT FROM v_receipt OR v_prior."capturedBytes" IS DISTINCT FROM p_captured OR v_prior."inputClaimId" IS DISTINCT FROM p_input_claim_id OR v_prior."observerOid" IS DISTINCT FROM v_oid THEN RAISE EXCEPTION 'SELECTION_UNAVAILABLE'; END IF; RETURN v_receipt; END IF;
 IF public.pro262_capacity_backend_live(v_expected."installerName",v_expected."installerPid",v_expected."installerBackendStart") IS DISTINCT FROM TRUE THEN RAISE EXCEPTION 'SELECTION_UNAVAILABLE'; END IF;
 SELECT c.* INTO STRICT v_charge FROM public."Pro262CapacityControlCharge" c WHERE c."kind"='INSTALLER_PROCESS_OBSERVATION' AND c."eventKey"=v_receipt FOR SHARE NOWAIT;
 IF v_charge."bindingHash" IS DISTINCT FROM v_receipt THEN RAISE EXCEPTION 'SELECTION_UNAVAILABLE'; END IF;
 INSERT INTO public."Pro273InstallerProcessObservation"("expectationId","credentialEpoch","launchEpoch","observationId","receiptId","trustId","trustGeneration","inputClaimId","targetOid","targetPrincipal","targetPid","targetBackendStart","host","boot","processTree","observerOid","observerPrincipal","observerPid","observerBackendStart","lane","installation","installationGeneration","installationEvidenceHash","validUntil","capturedBytes","capturedLength","capturedHash","evidenceBytes","evidenceLength","evidenceHash","chargeKind","chargeEventKey","chargeBindingHash")
 VALUES(p_expectation_id,v_expected."credentialEpoch",v_expected."launchEpoch",p_observation->>'observationId',v_receipt,v_trust."trustId",v_trust."generation",p_input_claim_id,v_expected."installerOid",v_expected."installerName",v_expected."installerPid",v_expected."installerBackendStart",v_expected."host",v_expected."boot",v_expected."processTree",v_oid,SESSION_USER::NAME,pg_catalog.pg_backend_pid(),public.pro262_capacity_backend_start(),v_lane,p_observation->'installation',p_observation->>'installationGeneration',p_observation->>'installationEvidenceHash',(p_observation->>'validUntil')::TIMESTAMPTZ,p_captured,pg_catalog.octet_length(p_captured),v_hash,v_evidence,pg_catalog.octet_length(v_evidence),p_observation->>'evidenceHash',v_charge."kind",v_charge."eventKey",v_charge."bindingHash");
 RETURN v_receipt;
EXCEPTION WHEN OTHERS THEN RAISE EXCEPTION 'SELECTION_UNAVAILABLE'; END $$;
REVOKE ALL ON FUNCTION public.pro273_installer_accept_process_observation(TEXT,TEXT,JSONB,BYTEA) FROM PUBLIC;

-- Descriptor precedes connection launch and is immutable. The authenticated
-- allocator and durable precharge routines that can create it follow later.
CREATE TABLE public."Pro273QualificationInputDescriptor" (
 "controlId" TEXT PRIMARY KEY, "descriptorCoreHash" TEXT NOT NULL CHECK ("descriptorCoreHash" ~ '^[a-f0-9]{64}$'), "allocationId" TEXT NOT NULL UNIQUE, "allocationCoreHash" TEXT NOT NULL CHECK ("allocationCoreHash" ~ '^[a-f0-9]{64}$'), "sourceIdentity" TEXT NOT NULL, "namespace" TEXT NOT NULL, "project" TEXT NOT NULL,
 "deployment" TEXT NOT NULL, "environment" TEXT NOT NULL, "principalOid" OID NOT NULL CHECK ("principalOid"<>0), "principalName" NAME NOT NULL,
 "credentialEpoch" TEXT NOT NULL, "launchEpoch" TEXT NOT NULL, "observerGroupProof" TEXT NOT NULL,
 "physicalIdentity" TEXT NOT NULL, "physicalProofIdentity" TEXT NOT NULL, "baselinePartitionId" TEXT NOT NULL,
 "controlChargeKind" TEXT NOT NULL, "controlChargeEventKey" TEXT NOT NULL UNIQUE, "bootstrapRecordHash" TEXT NOT NULL CHECK ("bootstrapRecordHash" ~ '^[a-f0-9]{64}$'),
 "expiresAt" TIMESTAMPTZ NOT NULL, UNIQUE ("principalOid","credentialEpoch"), UNIQUE ("principalOid","launchEpoch"), UNIQUE ("controlId","credentialEpoch","launchEpoch"), UNIQUE ("controlId","descriptorCoreHash"),
 FOREIGN KEY ("controlChargeKind","controlChargeEventKey") REFERENCES public."Pro262CapacityControlCharge"("kind","eventKey") ON UPDATE RESTRICT ON DELETE RESTRICT,
 FOREIGN KEY ("physicalIdentity") REFERENCES public."Pro262CapacityPhysicalDomain"("physicalIdentity") ON UPDATE RESTRICT ON DELETE RESTRICT,
 FOREIGN KEY ("allocationId","allocationCoreHash") REFERENCES public."Pro273QualifierAllocation"("allocationId","coreHash") ON UPDATE RESTRICT ON DELETE RESTRICT,
 FOREIGN KEY ("allocationId","controlId","physicalIdentity","physicalProofIdentity","principalOid","credentialEpoch","launchEpoch","sourceIdentity") REFERENCES public."Pro273QualifierAllocation"("allocationId","controlId","physicalIdentity","physicalProofIdentity","principalOid","credentialEpoch","launchEpoch","sourceIdentity") ON UPDATE RESTRICT ON DELETE RESTRICT
);
CREATE TABLE public."Pro273QualificationInputState" (
 "controlId" TEXT PRIMARY KEY REFERENCES public."Pro273QualificationInputDescriptor"("controlId") ON UPDATE RESTRICT ON DELETE RESTRICT,
 "state" TEXT NOT NULL CHECK ("state" IN ('RESERVED','OCCUPIED','QUARANTINED','SEALED','RELEASED')),
 "connectionState" TEXT NOT NULL CHECK ("connectionState" IN ('OPENING','BOUND','NEVER_OPENED','UNKNOWN')),
 "transitionOrdinal" BIGINT NOT NULL CHECK ("transitionOrdinal">0)
);
CREATE TABLE public."Pro273QualificationTransitionReceipt" (
 "controlId" TEXT NOT NULL REFERENCES public."Pro273QualificationInputDescriptor"("controlId") ON UPDATE RESTRICT ON DELETE RESTRICT,
 "transitionOrdinal" BIGINT NOT NULL CHECK ("transitionOrdinal">0), "fromState" TEXT NOT NULL, "toState" TEXT NOT NULL,
 "fromConnectionState" TEXT NOT NULL, "toConnectionState" TEXT NOT NULL, "receiptId" TEXT NOT NULL UNIQUE,
 "bindingHash" TEXT NOT NULL CHECK ("bindingHash" ~ '^[a-f0-9]{64}$'), "occurredAt" TIMESTAMPTZ NOT NULL, PRIMARY KEY ("controlId","transitionOrdinal")
);
CREATE TABLE public."Pro273QualificationSlotBinding" (
 "reservationId" TEXT PRIMARY KEY REFERENCES public."Pro262CapacityObserverInputReservation"("reservationId") ON UPDATE RESTRICT ON DELETE RESTRICT,
 "controlId" TEXT NOT NULL, "credentialEpoch" TEXT NOT NULL, "launchEpoch" TEXT NOT NULL, "phase" TEXT NOT NULL, "expectedEventKey" TEXT NOT NULL,
 FOREIGN KEY ("controlId","credentialEpoch","launchEpoch") REFERENCES public."Pro273QualificationInputDescriptor"("controlId","credentialEpoch","launchEpoch") ON UPDATE RESTRICT ON DELETE RESTRICT
);
CREATE TRIGGER "Pro273QualificationInputDescriptor_immutable" BEFORE UPDATE OR DELETE ON public."Pro273QualificationInputDescriptor" FOR EACH ROW EXECUTE FUNCTION public.pro273_sel_immutable();
-- Data storage only: no writer or publication authority is granted here.
-- Exact delivery linkage is retained separately from the closed provenance.
ALTER TABLE public."Pro273InstallerDelivery" ADD UNIQUE ("attemptId","expectationId","sessionClaimId","inputClaimId","eventId");
ALTER TABLE public."Pro273ControlPlaneInstallerExpectation" ADD UNIQUE ("expectationId","expectedTargetId","expectedCoreHash","sessionClaimId","eventId");
CREATE TABLE public."Pro273QualifierDescriptorProvenance" (
 "controlId" TEXT NOT NULL, "coreHash" TEXT NOT NULL, "bootstrapKind" TEXT NOT NULL REFERENCES public."Pro262CapacityBootstrapBaseline"("kind") ON UPDATE RESTRICT ON DELETE RESTRICT,
 "bootstrapRecordHash" TEXT NOT NULL, "bootstrapEvidenceHash" TEXT NOT NULL, "trustId" TEXT NOT NULL, "trustGeneration" BIGINT NOT NULL,
 "trustRecordHash" TEXT NOT NULL, "publisherPrincipalOid" OID NOT NULL, "publisherPrincipalName" NAME NOT NULL,
 "inputClaimId" TEXT NOT NULL UNIQUE REFERENCES public."Pro262CapacityObserverInputClaim"("inputClaimId") ON UPDATE RESTRICT ON DELETE RESTRICT,
 "sessionClaimId" TEXT NOT NULL, "eventId" TEXT NOT NULL UNIQUE,
 "capturedBytes" BYTEA NOT NULL, "capturedLength" BIGINT NOT NULL, "capturedHash" TEXT NOT NULL,
 "evidenceBytes" BYTEA NOT NULL, "evidenceLength" BIGINT NOT NULL, "evidenceHash" TEXT NOT NULL,
 "chargeKind" TEXT NOT NULL, "chargeEventKey" TEXT NOT NULL, "chargeBindingHash" TEXT NOT NULL,
 PRIMARY KEY ("controlId","coreHash"), UNIQUE ("controlId","coreHash","sessionClaimId","inputClaimId","eventId"),
 FOREIGN KEY ("controlId","coreHash") REFERENCES public."Pro273QualificationInputDescriptor"("controlId","descriptorCoreHash") ON UPDATE RESTRICT ON DELETE RESTRICT,
 FOREIGN KEY ("trustId","trustGeneration") REFERENCES public."Pro262CapacityTrust"("trustId","generation") ON UPDATE RESTRICT ON DELETE RESTRICT,
 FOREIGN KEY ("trustId","trustGeneration") REFERENCES public."Pro262CapacityBootstrapTrust"("trustId","generation") ON UPDATE RESTRICT ON DELETE RESTRICT,
 FOREIGN KEY ("chargeKind","chargeEventKey") REFERENCES public."Pro262CapacityControlCharge"("kind","eventKey") ON UPDATE RESTRICT ON DELETE RESTRICT,
 CHECK ("coreHash" ~ '^[a-f0-9]{64}$' AND "bootstrapRecordHash"="coreHash" AND "bootstrapEvidenceHash"="evidenceHash" AND "trustRecordHash" ~ '^[a-f0-9]{64}$' AND "chargeBindingHash" ~ '^[a-f0-9]{64}$'),
 CHECK ("capturedLength">0 AND "capturedLength"=pg_catalog.octet_length("capturedBytes") AND "capturedHash"=pg_catalog.encode(int4_crypto.digest("capturedBytes",'sha256'),'hex') AND "evidenceLength">0 AND "evidenceLength"=pg_catalog.octet_length("evidenceBytes") AND "evidenceHash"=pg_catalog.encode(int4_crypto.digest("evidenceBytes",'sha256'),'hex'))
);
CREATE TABLE public."Pro273QualifierDescriptorLinkage" (
 "controlId" TEXT NOT NULL, "coreHash" TEXT NOT NULL, "expectationId" TEXT NOT NULL UNIQUE, "dispatchAttemptId" TEXT NOT NULL UNIQUE,
 "sessionClaimId" TEXT NOT NULL, "inputClaimId" TEXT NOT NULL, "eventId" TEXT NOT NULL, "constructionTransactionId" xid8 NOT NULL DEFAULT pg_catalog.pg_current_xact_id(),
 PRIMARY KEY ("controlId","coreHash"),
 FOREIGN KEY ("controlId","coreHash","sessionClaimId","inputClaimId","eventId") REFERENCES public."Pro273QualifierDescriptorProvenance"("controlId","coreHash","sessionClaimId","inputClaimId","eventId") ON UPDATE RESTRICT ON DELETE RESTRICT,
 FOREIGN KEY ("expectationId","controlId","coreHash","sessionClaimId","eventId") REFERENCES public."Pro273ControlPlaneInstallerExpectation"("expectationId","expectedTargetId","expectedCoreHash","sessionClaimId","eventId") ON UPDATE RESTRICT ON DELETE RESTRICT,
 FOREIGN KEY ("dispatchAttemptId","expectationId","sessionClaimId","inputClaimId","eventId") REFERENCES public."Pro273InstallerDelivery"("attemptId","expectationId","sessionClaimId","inputClaimId","eventId") ON UPDATE RESTRICT ON DELETE RESTRICT
);
CREATE TABLE public."Pro273QualifierDescriptorProof" (
 "controlId" TEXT NOT NULL, "coreHash" TEXT NOT NULL, "observerGroupProof" TEXT NOT NULL CHECK ("observerGroupProof"<>''), PRIMARY KEY ("controlId","coreHash"),
 FOREIGN KEY ("controlId","coreHash") REFERENCES public."Pro273QualifierDescriptorLinkage"("controlId","coreHash") ON UPDATE RESTRICT ON DELETE RESTRICT
);
