-- Private prototype: comparison of partial discovery facts only; no authority or funding claim.
CREATE FUNCTION public.pro273_qualifier_snapshot_equal(p_before public.pro273_qualifier_discovery_snapshot,p_after public.pro273_qualifier_discovery_snapshot) RETURNS BOOLEAN
LANGUAGE plpgsql SECURITY DEFINER SET search_path=pg_catalog AS $pro273_snapshot_equal$
DECLARE v_i INTEGER; v_j INTEGER;
BEGIN
 -- Held pending independent qualification.
 RAISE EXCEPTION 'SELECTION_UNAVAILABLE';
 -- field: route_current_expectation
 IF p_before.route_current_expectation IS NULL OR p_after.route_current_expectation IS NULL OR p_before.route_current_expectation COLLATE "C" IS DISTINCT FROM p_after.route_current_expectation COLLATE "C" THEN RAISE EXCEPTION 'SELECTION_UNAVAILABLE'; END IF;
 -- field: route_historical_expectation
 IF p_before.route_historical_expectation IS NULL OR p_after.route_historical_expectation IS NULL OR p_before.route_historical_expectation COLLATE "C" IS DISTINCT FROM p_after.route_historical_expectation COLLATE "C" THEN RAISE EXCEPTION 'SELECTION_UNAVAILABLE'; END IF;
 -- field: route_control_id
 IF p_before.route_control_id IS NULL OR p_after.route_control_id IS NULL OR p_before.route_control_id COLLATE "C" IS DISTINCT FROM p_after.route_control_id COLLATE "C" THEN RAISE EXCEPTION 'SELECTION_UNAVAILABLE'; END IF;
 -- field: route_physical_id
 IF p_before.route_physical_id IS NULL OR p_after.route_physical_id IS NULL OR p_before.route_physical_id COLLATE "C" IS DISTINCT FROM p_after.route_physical_id COLLATE "C" THEN RAISE EXCEPTION 'SELECTION_UNAVAILABLE'; END IF;
 -- field: route_proof_id
 IF p_before.route_proof_id IS NULL OR p_after.route_proof_id IS NULL OR p_before.route_proof_id COLLATE "C" IS DISTINCT FROM p_after.route_proof_id COLLATE "C" THEN RAISE EXCEPTION 'SELECTION_UNAVAILABLE'; END IF;
 -- field: route_allocation_id
 IF p_before.route_allocation_id IS NULL OR p_after.route_allocation_id IS NULL OR p_before.route_allocation_id COLLATE "C" IS DISTINCT FROM p_after.route_allocation_id COLLATE "C" THEN RAISE EXCEPTION 'SELECTION_UNAVAILABLE'; END IF;
 -- field: route_allocation_hash
 IF p_before.route_allocation_hash IS NULL OR p_after.route_allocation_hash IS NULL OR p_before.route_allocation_hash COLLATE "C" IS DISTINCT FROM p_after.route_allocation_hash COLLATE "C" THEN RAISE EXCEPTION 'SELECTION_UNAVAILABLE'; END IF;
 -- field: route_layout_hash
 IF p_before.route_layout_hash IS NULL OR p_after.route_layout_hash IS NULL OR p_before.route_layout_hash COLLATE "C" IS DISTINCT FROM p_after.route_layout_hash COLLATE "C" THEN RAISE EXCEPTION 'SELECTION_UNAVAILABLE'; END IF;
 -- field: route_baseline_id
 IF p_before.route_baseline_id IS NULL OR p_after.route_baseline_id IS NULL OR p_before.route_baseline_id COLLATE "C" IS DISTINCT FROM p_after.route_baseline_id COLLATE "C" THEN RAISE EXCEPTION 'SELECTION_UNAVAILABLE'; END IF;
 -- field: route_baseline_hash
 IF p_before.route_baseline_hash IS NULL OR p_after.route_baseline_hash IS NULL OR p_before.route_baseline_hash COLLATE "C" IS DISTINCT FROM p_after.route_baseline_hash COLLATE "C" THEN RAISE EXCEPTION 'SELECTION_UNAVAILABLE'; END IF;
 -- field: v_history_text
 IF p_before.v_history_text IS NULL OR pg_catalog.array_ndims(p_before.v_history_text) IS DISTINCT FROM 1 OR pg_catalog.array_lower(p_before.v_history_text,1) IS DISTINCT FROM 1 OR pg_catalog.array_length(p_before.v_history_text,1) IS DISTINCT FROM 50 THEN RAISE EXCEPTION 'SELECTION_UNAVAILABLE'; END IF;
 IF p_after.v_history_text IS NULL OR pg_catalog.array_ndims(p_after.v_history_text) IS DISTINCT FROM 1 OR pg_catalog.array_lower(p_after.v_history_text,1) IS DISTINCT FROM 1 OR pg_catalog.array_length(p_after.v_history_text,1) IS DISTINCT FROM 50 THEN RAISE EXCEPTION 'SELECTION_UNAVAILABLE'; END IF;
