CREATE FUNCTION public.pro273_qualifier_discover(p_expectation_id TEXT) RETURNS public.pro273_qualifier_discovery_snapshot
LANGUAGE plpgsql SECURITY DEFINER SET search_path=pg_catalog AS $$
DECLARE v_route RECORD; v_installer RECORD;
 v_allocation_text TEXT[];
 v_allocation_hashes TEXT[];
 v_allocation_oids OID[];
 v_allocation_names NAME[];
 v_allocation_numbers BIGINT[];
 v_allocation_times TIMESTAMPTZ[];
 v_allocation_closures TEXT[];
