 v_allocation_resources NUMERIC[];
 v_physical_capacity NUMERIC[];
 v_physical_fence BIGINT[];
 v_physical_text TEXT[];
 v_physical_hashes TEXT[];
 v_physical_enabled BOOLEAN[];
 v_source RECORD; v_history RECORD; v_key RECORD; v_fact RECORD;
 v_charge_candidates TEXT[][] := ARRAY[]::TEXT[][]; v_charge_inventory TEXT[][] := ARRAY[]::TEXT[][]; v_candidate_index INTEGER;
 v_history_text TEXT[];
 v_history_numbers NUMERIC[];
 v_history_oids OID[];
