 v_history_bigints BIGINT[];
 v_history_times TIMESTAMPTZ[];
 v_history_transactions xid8[];
 v_baseline_provenance_text TEXT[];
 v_baseline_provenance_hashes TEXT[];
 v_baseline_provenance_oid OID[];
 v_baseline_provenance_name NAME[];
 v_baseline_provenance_bigints BIGINT[];
 v_baseline_provenance_xid xid8[];
 v_control_baseline_inventory TEXT[][] := ARRAY[]::TEXT[][];
 -- Typed bounded snapshots; no lock, funding or currentness claim.
 v_charge_source_text TEXT[][] := ARRAY[]::TEXT[][]; v_charge_source_amount NUMERIC[] := ARRAY[]::NUMERIC[];
 v_control_baseline_source_text TEXT[][] := ARRAY[]::TEXT[][]; v_control_baseline_source_numbers NUMERIC[][] := ARRAY[]::NUMERIC[][];
 v_control_baseline_source_enabled BOOLEAN[] := ARRAY[]::BOOLEAN[]; v_snapshot_charge RECORD; v_snapshot_baseline RECORD;
 v_trust_candidates TEXT[][] := ARRAY[]::TEXT[][]; v_trust_inventory TEXT[][] := ARRAY[]::TEXT[][];
 v_bootstrap_trust_inventory TEXT[][] := ARRAY[]::TEXT[][];
 -- Source occurrences remain aligned with all 20 roles before deduplication.
 -- The bootstrap principal is the original provisioner, not the supplier or issuer.
 v_trust_source_text TEXT[][] := ARRAY[]::TEXT[][]; v_trust_source_hashes TEXT[][] := ARRAY[]::TEXT[][];
 v_trust_source_names NAME[][] := ARRAY[]::NAME[][]; v_trust_source_generations BIGINT[][] := ARRAY[]::BIGINT[][];
 v_trust_source_revoked BOOLEAN[] := ARRAY[]::BOOLEAN[]; v_trust_source_times TIMESTAMPTZ[][] := ARRAY[]::TIMESTAMPTZ[][];
 v_bootstrap_candidates TEXT[][] := ARRAY[]::TEXT[][]; v_bootstrap_inventory TEXT[][] := ARRAY[]::TEXT[][];
 -- Actual protected baseline rows, aligned with all 12 original roles.
 v_bootstrap_source_keys TEXT[] := ARRAY[]::TEXT[]; v_bootstrap_source_hashes TEXT[][] := ARRAY[]::TEXT[][];
 v_bootstrap_source_publishers NAME[] := ARRAY[]::NAME[]; v_bootstrap_source_times TIMESTAMPTZ[] := ARRAY[]::TIMESTAMPTZ[];
 -- Fixed scalar discovery snapshots, not locks or authority.
 v_installer_keys TEXT[][] := ARRAY[]::TEXT[][]; v_installer_facts TEXT[][] := ARRAY[]::TEXT[][];
 -- Preserve stored E/H facts; native identity and time types remain typed.
 v_expectation_text TEXT[][] := ARRAY[]::TEXT[][]; v_expectation_hashes TEXT[][] := ARRAY[]::TEXT[][];
 v_expectation_oids OID[] := ARRAY[]::OID[]; v_expectation_names NAME[] := ARRAY[]::NAME[];
 v_expectation_pids INTEGER[] := ARRAY[]::INTEGER[]; v_expectation_times TIMESTAMPTZ[][] := ARRAY[]::TIMESTAMPTZ[][];
 v_expectation_generations BIGINT[] := ARRAY[]::BIGINT[];
 -- Separately retained stored session and observation scalar facts; not authority.
 -- Stored dispatch and delivery facts follow the same E/H ordering.
 v_dispatch_text TEXT[][] := ARRAY[]::TEXT[][]; v_dispatch_hashes TEXT[][] := ARRAY[]::TEXT[][];
 v_dispatch_transactions xid8[] := ARRAY[]::xid8[]; v_dispatch_times TIMESTAMPTZ[] := ARRAY[]::TIMESTAMPTZ[];
 v_delivery_text TEXT[][] := ARRAY[]::TEXT[][]; v_delivery_hashes TEXT[][] := ARRAY[]::TEXT[][];
 v_delivery_transactions xid8[] := ARRAY[]::xid8[]; v_delivery_times TIMESTAMPTZ[] := ARRAY[]::TIMESTAMPTZ[];
 v_session_text TEXT[][] := ARRAY[]::TEXT[][];
 v_session_hashes TEXT[][] := ARRAY[]::TEXT[][];
 v_session_oids OID[] := ARRAY[]::OID[];
 v_session_names NAME[] := ARRAY[]::NAME[];
 v_session_transactions xid8[] := ARRAY[]::xid8[];
 v_session_times TIMESTAMPTZ[] := ARRAY[]::TIMESTAMPTZ[];
 v_observation_text TEXT[][] := ARRAY[]::TEXT[][];
 v_observation_hashes TEXT[][] := ARRAY[]::TEXT[][];
 v_observation_oids OID[][] := ARRAY[]::OID[][];
 v_observation_names NAME[][] := ARRAY[]::NAME[][];
 v_observation_pids INTEGER[][] := ARRAY[]::INTEGER[][];
 v_observation_times TIMESTAMPTZ[][] := ARRAY[]::TIMESTAMPTZ[][];
 v_observation_generations BIGINT[] := ARRAY[]::BIGINT[];
 v_observation_lengths BIGINT[][] := ARRAY[]::BIGINT[][];

 -- Four E/H constructor/observation occurrences before alias deduplication.
 -- Stored scalar facts only; neither source table has a claim transaction ID.
 v_installer_slot_text TEXT[][] := ARRAY[]::TEXT[][];
 v_installer_binding_text TEXT[][] := ARRAY[]::TEXT[][];
 v_installer_slot_hashes TEXT[][] := ARRAY[]::TEXT[][];
