 v_installer_slot_limits NUMERIC[] := ARRAY[]::NUMERIC[];
 v_installer_slot_resources NUMERIC[][] := ARRAY[]::NUMERIC[][];
 v_installer_slot_concurrency TEXT[] := ARRAY[]::TEXT[];
 v_installer_slot_event TEXT[] := ARRAY[]::TEXT[];
 v_installer_claim_times TIMESTAMPTZ[] := ARRAY[]::TIMESTAMPTZ[];
 v_initial_slot_text TEXT[][] := ARRAY[]::TEXT[][];
 v_initial_slot_hashes TEXT[][] := ARRAY[]::TEXT[][];
