 v_initial_slot_generations BIGINT[] := ARRAY[]::BIGINT[];
 v_initial_slot_limits NUMERIC[] := ARRAY[]::NUMERIC[];
 v_initial_slot_resources NUMERIC[][] := ARRAY[]::NUMERIC[][];
 v_initial_slot_concurrency TEXT[] := ARRAY[]::TEXT[];
 v_initial_slot_event TEXT[] := ARRAY[]::TEXT[];
 v_initial_claim_times TIMESTAMPTZ[] := ARRAY[]::TIMESTAMPTZ[];
 -- Fixed L/A stored session and observation facts, aligned with v_initial_keys.
 v_initial_attempt_text TEXT[][] := ARRAY[]::TEXT[][];
 v_initial_attempt_hashes TEXT[][] := ARRAY[]::TEXT[][];
 v_initial_attempt_ordinal BIGINT[] := ARRAY[]::BIGINT[];
