 v_initial_receipt_xid xid8[] := ARRAY[]::xid8[];
 v_initial_keys TEXT[][] := ARRAY[]::TEXT[][]; v_initial_facts TEXT[][] := ARRAY[]::TEXT[][];
 v_slot_occurrences TEXT[][] := ARRAY[]::TEXT[][]; v_snapshot_i INTEGER; v_snapshot_j INTEGER;
 -- Route, relation and exact primary-key components; empty components are unused.
 v_relation_keys TEXT[][] := ARRAY[]::TEXT[][];
 v_descriptor_presence BOOLEAN[]; v_descriptor_present BOOLEAN;
 v_descriptor_text TEXT[];
 v_descriptor_hashes TEXT[];
 v_descriptor_oids OID[];
 v_descriptor_names NAME[];
 v_descriptor_numbers BIGINT[];
 v_descriptor_times TIMESTAMPTZ[];
 v_descriptor_companion_text TEXT[];
 v_descriptor_companion_hashes TEXT[];
 v_descriptor_companion_numbers BIGINT[];
 v_descriptor_companion_transactions xid8[];
 v_descriptor_companion_times TIMESTAMPTZ[];
 v_projection public.pro273_qualifier_discovery_snapshot;
BEGIN
 -- Discovery is held pending qualification.
 RAISE EXCEPTION 'SELECTION_UNAVAILABLE';
 -- Denied discovery prototype only: fixed unique E/A/L and same-baseline
 -- INITIAL route, with scalar keys and hashes. Text sizes, detoast costs and
 -- aggregate resource bounds are not qualified. This is not a lock prelude.
 SELECT e."expectationId" AS current_expectation, e."expectedTargetId" AS control_id,
        base."baselineId" AS history_base_baselineId,base."purpose" AS history_base_purpose,base."physicalIdentity" AS history_base_physicalIdentity,base."physicalProofIdentity" AS history_base_physicalProofIdentity,base."sourceClosureHash" AS history_base_sourceClosureHash,base."installationClosureHash" AS history_base_installationClosureHash,base."expectedFutureLayoutCoreHash" AS history_base_expectedFutureLayoutCoreHash,base."credentialEpoch" AS history_base_credentialEpoch,base."launchEpoch" AS history_base_launchEpoch,base."host" AS history_base_host,base."boot" AS history_base_boot,base."processTree" AS history_base_processTree,base."parentProcessTree" AS history_base_parentProcessTree,base."coreHash" AS history_base_coreHash,prov."baselineId" AS history_prov_baselineId,prov."coreHash" AS history_prov_coreHash,prov."bootstrapKind" AS history_prov_bootstrapKind,prov."bootstrapRecordHash" AS history_prov_bootstrapRecordHash,prov."bootstrapEvidenceHash" AS history_prov_bootstrapEvidenceHash,prov."trustId" AS history_prov_trustId,prov."trustRecordHash" AS history_prov_trustRecordHash,prov."inputClaimId" AS history_prov_inputClaimId,prov."sessionClaimId" AS history_prov_sessionClaimId,prov."eventId" AS history_prov_eventId,prov."capturedHash" AS history_prov_capturedHash,prov."evidenceHash" AS history_prov_evidenceHash,prov."chargeKind" AS history_prov_chargeKind,prov."chargeEventKey" AS history_prov_chargeEventKey,prov."chargeBindingHash" AS history_prov_chargeBindingHash,lp."inputClaimId" AS history_lp_inputClaimId,lp."admissionReceiptId" AS history_lp_admissionReceiptId,lp."eventId" AS history_lp_eventId,lp."baselineId" AS history_lp_baselineId,lp."baselineCoreHash" AS history_lp_baselineCoreHash,lp."physicalIdentity" AS history_lp_physicalIdentity,lp."physicalProofIdentity" AS history_lp_physicalProofIdentity,lp."layoutCoreHash" AS history_lp_layoutCoreHash,lp."receiptHash" AS history_lp_receiptHash,ap."inputClaimId" AS history_ap_inputClaimId,ap."admissionReceiptId" AS history_ap_admissionReceiptId,ap."eventId" AS history_ap_eventId,ap."baselineId" AS history_ap_baselineId,ap."baselineCoreHash" AS history_ap_baselineCoreHash,ap."layoutInputClaimId" AS history_ap_layoutInputClaimId,ap."allocationId" AS history_ap_allocationId,ap."allocationCoreHash" AS history_ap_allocationCoreHash,ap."receiptHash" AS history_ap_receiptHash,lb."baselineId" AS history_lb_baselineId,lb."baselineCoreHash" AS history_lb_baselineCoreHash,lb."layoutInputClaimId" AS history_lb_layoutInputClaimId,
        base."reservedBackendBytes" AS history_base_reservedBackendBytes,base."reservedSharedBytes" AS history_base_reservedSharedBytes,base."reservedTemporaryBytes" AS history_base_reservedTemporaryBytes,base."maxInputBytes" AS history_base_maxInputBytes,base."maxOutputBytes" AS history_base_maxOutputBytes,base."maxAllocationBytes" AS history_base_maxAllocationBytes,base."stackBytes" AS history_base_stackBytes,base."parentBytes" AS history_base_parentBytes,base."maxProcessCount" AS history_base_maxProcessCount,base."maxBackendCount" AS history_base_maxBackendCount,base."maxLaunchAttempts" AS history_base_maxLaunchAttempts,base."maxEvents" AS history_base_maxEvents,base."backendProcessBytes" AS history_base_backendProcessBytes,base."qualifierRuntimeBytes" AS history_base_qualifierRuntimeBytes,base."launcherSupervisorBytes" AS history_base_launcherSupervisorBytes,base."retainedParentBytes" AS history_base_retainedParentBytes,base."driverSocketIpcBytes" AS history_base_driverSocketIpcBytes,base."inputEvidenceSerializationBytes" AS history_base_inputEvidenceSerializationBytes,base."primitiveParserCacheBytes" AS history_base_primitiveParserCacheBytes,base."rollbackCleanupBytes" AS history_base_rollbackCleanupBytes,base."sharedRuntimeBytes" AS history_base_sharedRuntimeBytes,
        base."principalOid" AS history_base_principalOid,prov."publisherPrincipalOid" AS history_prov_publisherPrincipalOid,
        base."principalName" AS history_base_principalName,prov."publisherPrincipalName" AS history_prov_publisherPrincipalName,
        prov."trustGeneration" AS history_prov_trustGeneration,prov."capturedLength" AS history_prov_capturedLength,prov."evidenceLength" AS history_prov_evidenceLength,
        base."validFrom" AS history_base_validFrom,base."validUntil" AS history_base_validUntil,
        prov."constructionTransactionId" AS history_prov_constructionTransactionId,lp."constructionTransactionId" AS history_lp_constructionTransactionId,ap."constructionTransactionId" AS history_ap_constructionTransactionId,lb."constructionTransactionId" AS history_lb_constructionTransactionId,
        e."physicalIdentity" AS physical_id, e."physicalProofIdentity" AS proof_id,
        a."allocationId" AS allocation_id, a."coreHash" AS allocation_hash,
        l."coreHash" AS layout_hash,l."evidenceHash" AS layout_evidence,a."evidenceHash" AS allocation_evidence, lp."inputClaimId" AS layout_claim,
        lp."admissionReceiptId" AS layout_admission,lp."eventId" AS layout_event,lp."receiptHash" AS layout_receipt,
        ap."inputClaimId" AS allocation_claim,ap."admissionReceiptId" AS allocation_admission,ap."eventId" AS allocation_event,ap."receiptHash" AS allocation_receipt,
        l."sessionClaimId" AS layout_session,a."sessionClaimId" AS allocation_session,
        l."publisherPrincipalOid" AS layout_publisher_oid,l."publisherPrincipalName" AS layout_publisher_name,
        a."publisherPrincipalOid" AS allocation_publisher_oid,a."publisherPrincipalName" AS allocation_publisher_name,
        l."trustRecordHash" AS layout_trust_hash,a."trustRecordHash" AS allocation_trust_hash,
        l."bootstrapKind" AS layout_bootstrap,l."bootstrapRecordHash" AS layout_boot_hash,l."bootstrapEvidenceHash" AS layout_boot_evidence,
        a."bootstrapKind" AS allocation_bootstrap,a."bootstrapRecordHash" AS allocation_boot_hash,a."bootstrapEvidenceHash" AS allocation_boot_evidence,
        l."capturedHash" AS layout_capture_hash,a."capturedHash" AS allocation_capture_hash,
        base."baselineId" AS baseline_id,
        base."coreHash" AS baseline_hash, prov."inputClaimId" AS baseline_input_claim,hist."expectationId" AS historical_expectation,prov."trustRecordHash" AS historical_trust_hash,
        a."trustId" AS allocation_trust, a."trustGeneration" AS allocation_generation,
        l."trustId" AS layout_trust, l."trustGeneration" AS layout_generation,
        a."controlChargeKind" AS allocation_charge_kind, a."controlChargeEventKey" AS allocation_charge_event,
        a."chargeBindingHash" AS allocation_charge_hash,
        l."controlChargeKind" AS layout_charge_kind, l."controlChargeEventKey" AS layout_charge_event,
        l."chargeBindingHash" AS layout_charge_hash
 INTO STRICT v_route
 FROM public."Pro273ControlPlaneInstallerExpectation" e
 JOIN public."Pro273QualifierAllocation" a ON a."controlId"=e."expectedTargetId"
 JOIN public."Pro273QualifierBaselineLayout" l ON (l."physicalIdentity",l."physicalProofIdentity",l."coreHash")=(a."physicalIdentity",a."physicalProofIdentity",a."layoutCoreHash")
 JOIN public."Pro273InitialAllocationPublication" ap ON (ap."allocationId",ap."allocationCoreHash",ap."inputClaimId")=(a."allocationId",a."coreHash",a."inputClaimId") AND ap."eventId"=a."eventId"
 JOIN public."Pro273InitialBaselineLayoutBinding" lb ON (lb."baselineId",lb."baselineCoreHash",lb."layoutInputClaimId")=(ap."baselineId",ap."baselineCoreHash",ap."layoutInputClaimId")
 JOIN public."Pro273InitialLayoutPublication" lp ON (lp."baselineId",lp."baselineCoreHash",lp."inputClaimId",lp."physicalIdentity",lp."physicalProofIdentity",lp."layoutCoreHash",lp."eventId")=(lb."baselineId",lb."baselineCoreHash",lb."layoutInputClaimId",l."physicalIdentity",l."physicalProofIdentity",l."coreHash",l."eventId") AND lp."inputClaimId"=l."inputClaimId"
 JOIN public."Pro273ControlPlaneBaseline" base ON (base."baselineId",base."coreHash")=(ap."baselineId",ap."baselineCoreHash")
 JOIN public."Pro273ControlPlaneBaselineProvenance" prov ON (prov."baselineId",prov."coreHash")=(base."baselineId",base."coreHash")
 JOIN public."Pro273ControlPlaneInstallerExpectation" hist ON hist."bootstrapKind"=prov."bootstrapKind"
 WHERE e."expectationId"=p_expectation_id AND e."constructorKind"='QUALIFIER_DESCRIPTOR'
   AND (e."physicalIdentity",e."physicalProofIdentity",e."expectedFutureLayoutCoreHash")=(a."physicalIdentity",a."physicalProofIdentity",a."layoutCoreHash")
   AND (base."physicalIdentity",base."physicalProofIdentity",base."expectedFutureLayoutCoreHash")=(l."physicalIdentity",l."physicalProofIdentity",l."coreHash")
   AND (prov."bootstrapRecordHash",prov."bootstrapEvidenceHash")=(hist."expectedCoreHash",hist."expectedEvidenceHash")
   AND (hist."constructorKind",hist."expectedTargetId",hist."expectedCoreHash",hist."expectedEvidenceHash",hist."sessionClaimId",hist."eventId",hist."installerOid",hist."installerName",hist."trustId",hist."trustGeneration",hist."chargeKind",hist."chargeEventKey",hist."chargeBindingHash")=('CONTROL_PLANE_BASELINE',prov."baselineId",prov."coreHash",prov."evidenceHash",prov."sessionClaimId",prov."eventId",prov."publisherPrincipalOid",prov."publisherPrincipalName",prov."trustId",prov."trustGeneration",prov."chargeKind",prov."chargeEventKey",prov."chargeBindingHash");
 -- Selected original rows: bounded scalar retention only; hashes do not authenticate bytes.
 -- Partial scope/record/byte qualification; no historical authority or resource proof.
 v_history_text:=ARRAY[v_route.history_base_baselineId,v_route.history_base_purpose,v_route.history_base_physicalIdentity,v_route.history_base_physicalProofIdentity,v_route.history_base_sourceClosureHash,v_route.history_base_installationClosureHash,v_route.history_base_expectedFutureLayoutCoreHash,v_route.history_base_credentialEpoch,v_route.history_base_launchEpoch,v_route.history_base_host,v_route.history_base_boot,v_route.history_base_processTree,v_route.history_base_parentProcessTree,v_route.history_base_coreHash,v_route.history_prov_baselineId,v_route.history_prov_coreHash,v_route.history_prov_bootstrapKind,v_route.history_prov_bootstrapRecordHash,v_route.history_prov_bootstrapEvidenceHash,v_route.history_prov_trustId,v_route.history_prov_trustRecordHash,v_route.history_prov_inputClaimId,v_route.history_prov_sessionClaimId,v_route.history_prov_eventId,v_route.history_prov_capturedHash,v_route.history_prov_evidenceHash,v_route.history_prov_chargeKind,v_route.history_prov_chargeEventKey,v_route.history_prov_chargeBindingHash,v_route.history_lp_inputClaimId,v_route.history_lp_admissionReceiptId,v_route.history_lp_eventId,v_route.history_lp_baselineId,v_route.history_lp_baselineCoreHash,v_route.history_lp_physicalIdentity,v_route.history_lp_physicalProofIdentity,v_route.history_lp_layoutCoreHash,v_route.history_lp_receiptHash,v_route.history_ap_inputClaimId,v_route.history_ap_admissionReceiptId,v_route.history_ap_eventId,v_route.history_ap_baselineId,v_route.history_ap_baselineCoreHash,v_route.history_ap_layoutInputClaimId,v_route.history_ap_allocationId,v_route.history_ap_allocationCoreHash,v_route.history_ap_receiptHash,v_route.history_lb_baselineId,v_route.history_lb_baselineCoreHash,v_route.history_lb_layoutInputClaimId];
 IF pg_catalog.array_length(v_history_text,1) IS DISTINCT FROM 50 THEN RAISE EXCEPTION 'SELECTION_UNAVAILABLE'; END IF;
 FOR v_snapshot_i IN 1..50 LOOP
  -- 17 is the baseline-derived bootstrap key. The installer charge key at 28 is not the trust-provision key.
  -- Opaque source roles without a reviewed producer cap provisionally use 256 bytes; compatibility remains held.
  IF v_history_text[v_snapshot_i] IS NULL OR (CASE WHEN v_snapshot_i=ANY(ARRAY[5,6,7,14,16,18,19,21,25,26,29,34,37,38,43,46,47,49]) THEN v_history_text[v_snapshot_i] !~ '^[a-f0-9]{64}$' ELSE pg_catalog.octet_length(pg_catalog.convert_to(v_history_text[v_snapshot_i],'UTF8')) NOT BETWEEN 1 AND CASE WHEN v_snapshot_i=17 THEN 288 ELSE 256 END END) THEN RAISE EXCEPTION 'SELECTION_UNAVAILABLE'; END IF;
 END LOOP;
 IF v_history_text[2] NOT IN ('QUALIFIER_BASELINE_INITIAL','SELECTION_PROFILE_REVOKE') THEN RAISE EXCEPTION 'SELECTION_UNAVAILABLE'; END IF;
 v_history_numbers:=ARRAY[v_route.history_base_reservedBackendBytes,v_route.history_base_reservedSharedBytes,v_route.history_base_reservedTemporaryBytes,v_route.history_base_maxInputBytes,v_route.history_base_maxOutputBytes,v_route.history_base_maxAllocationBytes,v_route.history_base_stackBytes,v_route.history_base_parentBytes,v_route.history_base_maxProcessCount,v_route.history_base_maxBackendCount,v_route.history_base_maxLaunchAttempts,v_route.history_base_maxEvents,v_route.history_base_backendProcessBytes,v_route.history_base_qualifierRuntimeBytes,v_route.history_base_launcherSupervisorBytes,v_route.history_base_retainedParentBytes,v_route.history_base_driverSocketIpcBytes,v_route.history_base_inputEvidenceSerializationBytes,v_route.history_base_primitiveParserCacheBytes,v_route.history_base_rollbackCleanupBytes,v_route.history_base_sharedRuntimeBytes];
 IF pg_catalog.array_length(v_history_numbers,1) IS DISTINCT FROM 21 THEN RAISE EXCEPTION 'SELECTION_UNAVAILABLE'; END IF;
 -- Schema fidelity only; resource and allocation qualification remains held.
 FOR v_snapshot_i IN 1..21 LOOP
  IF v_history_numbers[v_snapshot_i] IS NULL OR v_history_numbers[v_snapshot_i]::TEXT IN ('NaN','Infinity','-Infinity') OR v_history_numbers[v_snapshot_i]<>pg_catalog.trunc(v_history_numbers[v_snapshot_i]) OR v_history_numbers[v_snapshot_i]<0 OR (v_snapshot_i<=12 AND v_history_numbers[v_snapshot_i]=0) THEN RAISE EXCEPTION 'SELECTION_UNAVAILABLE'; END IF;
 END LOOP;
 IF v_history_numbers[1]<v_history_numbers[13]+v_history_numbers[14]+v_history_numbers[15]+v_history_numbers[16]+v_history_numbers[17]+v_history_numbers[18]+v_history_numbers[19]+v_history_numbers[20] OR v_history_numbers[2]<v_history_numbers[21]+v_history_numbers[3] OR v_history_numbers[8]>v_history_numbers[16] OR v_history_numbers[6]>v_history_numbers[1] OR v_history_numbers[7]>v_history_numbers[1] THEN RAISE EXCEPTION 'SELECTION_UNAVAILABLE'; END IF;
 v_history_oids:=ARRAY[v_route.history_base_principalOid,v_route.history_prov_publisherPrincipalOid];
 IF pg_catalog.array_length(v_history_oids,1) IS DISTINCT FROM 2 THEN RAISE EXCEPTION 'SELECTION_UNAVAILABLE'; END IF;
 FOR v_snapshot_i IN 1..2 LOOP
  IF v_history_oids[v_snapshot_i] IS NULL THEN RAISE EXCEPTION 'SELECTION_UNAVAILABLE'; END IF;
 END LOOP;
 IF v_history_oids[1]=0 THEN RAISE EXCEPTION 'SELECTION_UNAVAILABLE'; END IF;
 v_history_names:=ARRAY[v_route.history_base_principalName,v_route.history_prov_publisherPrincipalName];
 IF pg_catalog.array_length(v_history_names,1) IS DISTINCT FROM 2 THEN RAISE EXCEPTION 'SELECTION_UNAVAILABLE'; END IF;
 FOR v_snapshot_i IN 1..2 LOOP
  IF v_history_names[v_snapshot_i] IS NULL OR pg_catalog.octet_length(v_history_names[v_snapshot_i]::TEXT) NOT BETWEEN 1 AND 256 THEN RAISE EXCEPTION 'SELECTION_UNAVAILABLE'; END IF;
 END LOOP;
 v_history_bigints:=ARRAY[v_route.history_prov_trustGeneration,v_route.history_prov_capturedLength,v_route.history_prov_evidenceLength];
 IF pg_catalog.array_length(v_history_bigints,1) IS DISTINCT FROM 3 THEN RAISE EXCEPTION 'SELECTION_UNAVAILABLE'; END IF;
 FOR v_snapshot_i IN 1..3 LOOP
  IF v_history_bigints[v_snapshot_i] IS NULL THEN RAISE EXCEPTION 'SELECTION_UNAVAILABLE'; END IF;
 END LOOP;
 v_history_times:=ARRAY[v_route.history_base_validFrom,v_route.history_base_validUntil];
 IF pg_catalog.array_length(v_history_times,1) IS DISTINCT FROM 2 THEN RAISE EXCEPTION 'SELECTION_UNAVAILABLE'; END IF;
 FOR v_snapshot_i IN 1..2 LOOP
  IF v_history_times[v_snapshot_i] IS NULL THEN RAISE EXCEPTION 'SELECTION_UNAVAILABLE'; END IF;
 END LOOP;
 IF v_history_times[1]>=v_history_times[2] THEN RAISE EXCEPTION 'SELECTION_UNAVAILABLE'; END IF;
 v_history_transactions:=ARRAY[v_route.history_prov_constructionTransactionId,v_route.history_lp_constructionTransactionId,v_route.history_ap_constructionTransactionId,v_route.history_lb_constructionTransactionId];
 IF pg_catalog.array_length(v_history_transactions,1) IS DISTINCT FROM 4 THEN RAISE EXCEPTION 'SELECTION_UNAVAILABLE'; END IF;
 FOR v_snapshot_i IN 1..4 LOOP
  IF v_history_transactions[v_snapshot_i] IS NULL THEN RAISE EXCEPTION 'SELECTION_UNAVAILABLE'; END IF;
 END LOOP;
 -- Shared original provenance from the L/A baseline and historical installer H; no authority or resource qualification.
 v_baseline_provenance_text:=ARRAY[v_route.history_prov_baselineId,v_route.history_prov_bootstrapKind,v_route.history_prov_trustId,v_route.history_prov_inputClaimId,v_route.history_prov_sessionClaimId,v_route.history_prov_eventId,v_route.history_prov_chargeKind,v_route.history_prov_chargeEventKey];
 v_baseline_provenance_hashes:=ARRAY[v_route.history_prov_coreHash,v_route.history_prov_bootstrapRecordHash,v_route.history_prov_bootstrapEvidenceHash,v_route.history_prov_trustRecordHash,v_route.history_prov_capturedHash,v_route.history_prov_evidenceHash,v_route.history_prov_chargeBindingHash];
 v_baseline_provenance_oid:=ARRAY[v_route.history_prov_publisherPrincipalOid];
 v_baseline_provenance_name:=ARRAY[v_route.history_prov_publisherPrincipalName];
