  v_session_text:=pg_catalog.array_cat(v_session_text,ARRAY[[v_installer.sess_sessionClaimId,v_installer.sess_expectationId,v_installer.sess_credentialEpoch,v_installer.sess_launchEpoch,v_installer.sess_chargeKind,v_installer.sess_chargeEventKey]]);
  v_session_hashes:=pg_catalog.array_cat(v_session_hashes,ARRAY[[v_installer.sess_sourceClosureHash,v_installer.sess_installationClosureHash,v_installer.sess_receiverClosureHash,v_installer.sess_chargeBindingHash]]);
  v_session_oids:=pg_catalog.array_cat(v_session_oids,ARRAY[v_installer.sess_principalOid]);
  v_session_names:=pg_catalog.array_cat(v_session_names,ARRAY[v_installer.sess_principalName]);
  v_session_transactions:=pg_catalog.array_cat(v_session_transactions,ARRAY[v_installer.sess_creationTransactionId]);
  v_session_times:=pg_catalog.array_cat(v_session_times,ARRAY[v_installer.sess_claimedAt]);
  v_observation_text:=pg_catalog.array_cat(v_observation_text,ARRAY[[v_installer.obs_expectationId,v_installer.obs_credentialEpoch,v_installer.obs_launchEpoch,v_installer.obs_observationId,v_installer.obs_receiptId,v_installer.obs_trustId,v_installer.obs_inputClaimId,v_installer.obs_host,v_installer.obs_boot,v_installer.obs_processTree,v_installer.obs_installationGeneration,v_installer.obs_chargeKind,v_installer.obs_chargeEventKey]]);
  v_observation_hashes:=pg_catalog.array_cat(v_observation_hashes,ARRAY[[v_installer.obs_installationEvidenceHash,v_installer.obs_capturedHash,v_installer.obs_evidenceHash,v_installer.obs_chargeBindingHash]]);
  v_observation_oids:=pg_catalog.array_cat(v_observation_oids,ARRAY[[v_installer.obs_targetOid,v_installer.obs_observerOid]]);
  v_observation_names:=pg_catalog.array_cat(v_observation_names,ARRAY[[v_installer.obs_targetPrincipal,v_installer.obs_observerPrincipal]]);
  v_observation_pids:=pg_catalog.array_cat(v_observation_pids,ARRAY[[v_installer.obs_targetPid,v_installer.obs_observerPid]]);
  v_observation_times:=pg_catalog.array_cat(v_observation_times,ARRAY[[v_installer.obs_targetBackendStart,v_installer.obs_observerBackendStart,v_installer.obs_validUntil]]);
  v_observation_generations:=pg_catalog.array_cat(v_observation_generations,ARRAY[v_installer.obs_trustGeneration]);
  v_observation_lengths:=pg_catalog.array_cat(v_observation_lengths,ARRAY[[v_installer.obs_capturedLength,v_installer.obs_evidenceLength]]);
  v_expectation_text:=pg_catalog.array_cat(v_expectation_text,ARRAY[[v_installer."expectationId",v_installer."bootstrapKind",v_installer."physicalIdentity",v_installer."physicalProofIdentity",v_installer."namespace",v_installer."project",v_installer."deployment",v_installer."environment",v_installer."kind",v_installer."credentialEpoch",v_installer."launchEpoch",v_installer."host",v_installer."boot",v_installer."processTree",v_installer."parentProcessTree",v_installer."constructorKind",v_installer."expectedTargetId",v_installer."parserAbiVersion",v_installer."dispatchAttemptId",v_installer."constructorInputReservationId",v_installer."constructorInputPhase",v_installer."sessionClaimId",v_installer."eventId",v_installer."trustId",v_installer."chargeKind",v_installer."chargeEventKey"]]);
  v_expectation_hashes:=pg_catalog.array_cat(v_expectation_hashes,ARRAY[[v_installer."physicalEvidenceHash",v_installer."sourceClosureHash",v_installer."installationClosureHash",v_installer."expectedCoreHash",v_installer."expectedEvidenceHash",v_installer."parserSourceClosureHash",v_installer."receiverClosureHash",v_installer."expectedFutureLayoutCoreHash",v_installer."chargeBindingHash",v_installer."trustRecordHash"]]);
  v_expectation_oids:=pg_catalog.array_cat(v_expectation_oids,ARRAY[v_installer."installerOid"]);
  v_expectation_names:=pg_catalog.array_cat(v_expectation_names,ARRAY[v_installer."installerName"]);
  v_expectation_pids:=pg_catalog.array_cat(v_expectation_pids,ARRAY[v_installer."installerPid"]);
  v_expectation_times:=pg_catalog.array_cat(v_expectation_times,ARRAY[[v_installer."installerBackendStart",v_installer."validFrom",v_installer."validUntil"]]);
  v_expectation_generations:=pg_catalog.array_cat(v_expectation_generations,ARRAY[v_installer."trustGeneration"]);
  v_installer_keys:=pg_catalog.array_cat(v_installer_keys,ARRAY[[v_key.id,v_installer.constructor_claim,v_installer.constructor_slot,v_installer."observationId",v_installer."receiptId",v_installer.observation_claim,v_installer.observation_slot,v_installer."sessionClaimId",v_installer."attemptId"]]);
  v_installer_facts:=pg_catalog.array_cat(v_installer_facts,ARRAY[[v_installer."expectedCoreHash",v_installer."expectedEvidenceHash",CASE WHEN v_key.id=v_route.historical_expectation THEN v_route.historical_trust_hash ELSE v_installer."trustRecordHash" END,v_installer.constructor_slot_hash,v_installer.observation_slot_hash]]);
  v_slot_occurrences:=pg_catalog.array_cat(v_slot_occurrences,ARRAY[[v_installer.constructor_claim,v_installer.constructor_slot,v_installer.constructor_slot_hash],[v_installer.observation_claim,v_installer.observation_slot,v_installer.observation_slot_hash]]);
  -- Keys come from the same joined occurrences, before alias deduplication.
  v_relation_keys:=pg_catalog.array_cat(v_relation_keys,ARRAY[
   [v_key.id,'Pro273ControlPlaneInstallerExpectation',v_key.id,'',''],
   [v_key.id,'Pro273InstallerDispatchAttempt',v_installer."attemptId",'',''],
   [v_key.id,'Pro273InstallerSessionClaim',v_installer."sessionClaimId",'',''],
   [v_key.id,'Pro262CapacityObserverInputClaim',v_installer.constructor_claim,'',''],
   [v_key.id,'Pro262CapacityObserverInputClaim',v_installer.observation_claim,'',''],
   [v_key.id,'Pro262CapacityObserverInputReservation',v_installer.constructor_slot,'',''],
   [v_key.id,'Pro262CapacityObserverInputReservation',v_installer.observation_slot,'',''],
   [v_key.id,'Pro273InstallerSlotBinding',v_installer.constructor_slot,'',''],
   [v_key.id,'Pro273InstallerSlotBinding',v_installer.observation_slot,'',''],
   [v_key.id,'Pro273InstallerProcessObservation',v_key.id,v_installer.observation_credential,v_installer.observation_launch],
   [v_key.id,'Pro273InstallerDelivery',v_installer."attemptId",'','']]);
  -- Preserve role occurrences before deduplication; unknown hashes and original
  -- trust provisioners are not inferred from installer or publisher subjects.
  FOR v_fact IN SELECT * FROM (VALUES
   (v_installer."trustId",v_installer."trustGeneration",CASE WHEN v_key.id=v_route.historical_expectation THEN v_route.historical_trust_hash ELSE v_installer."trustRecordHash" END,NULL::TEXT),
   (v_installer.observation_trust,v_installer.observation_generation,NULL::TEXT,NULL::TEXT),
   (v_installer.constructor_trust,v_installer.constructor_generation,NULL::TEXT,NULL::TEXT),
   (v_installer.slot_trust,v_installer.slot_generation,NULL::TEXT,NULL::TEXT)
  ) AS x(trust_id,generation,expected_hash,issuer) LOOP
   v_trust_candidates:=pg_catalog.array_cat(v_trust_candidates,ARRAY[[v_fact.trust_id,v_fact.generation::TEXT,v_fact.expected_hash,v_fact.issuer]]);
  END LOOP;
  FOR v_fact IN SELECT * FROM (VALUES
   (v_installer."bootstrapKind",v_installer."expectedCoreHash",v_installer."expectedEvidenceHash",v_installer."installerName"::TEXT),
   (v_installer.constructor_bootstrap,v_installer.constructor_slot_hash,v_installer.constructor_proof,NULL::TEXT),
   (v_installer.observation_bootstrap,v_installer.observation_slot_hash,v_installer.observation_proof,NULL::TEXT)
  ) AS x(kind,record_hash,evidence_hash,publisher) LOOP
   v_bootstrap_candidates:=pg_catalog.array_cat(v_bootstrap_candidates,ARRAY[[v_fact.kind,v_fact.record_hash,v_fact.evidence_hash,v_fact.publisher]]);
  END LOOP;
  -- Seven facts per E/H route: five producer charges and both slot prepayments.
  FOR v_fact IN SELECT * FROM (VALUES
   (v_installer."chargeKind",v_installer."chargeEventKey",v_installer."chargeBindingHash"),
   (v_installer.observation_charge_kind,v_installer.observation_charge_event,v_installer.observation_charge_hash),
   (v_installer.dispatch_charge_kind,v_installer.dispatch_charge_event,v_installer.dispatch_charge_hash),
   (v_installer.session_charge_kind,v_installer.session_charge_event,v_installer.session_charge_hash),
   (v_installer.delivery_charge_kind,v_installer.delivery_charge_event,v_installer.delivery_charge_hash),
   ('OBSERVER_INPUT_SLOT',v_installer.constructor_prepaid,v_installer.constructor_slot_hash),
   ('OBSERVER_INPUT_SLOT',v_installer.observation_prepaid,v_installer.observation_slot_hash)
  ) AS x(kind,event_key,binding_hash) LOOP
   IF v_fact.kind IS NULL OR pg_catalog.octet_length(v_fact.kind) NOT BETWEEN 1 AND 256
      OR v_fact.event_key IS NULL OR pg_catalog.octet_length(v_fact.event_key) NOT BETWEEN 1 AND 256
      OR v_fact.binding_hash IS NULL OR v_fact.binding_hash !~ '^[a-f0-9]{64}$'
   THEN RAISE EXCEPTION 'SELECTION_UNAVAILABLE'; END IF;
   v_charge_candidates:=pg_catalog.array_cat(v_charge_candidates,ARRAY[[v_fact.kind,v_fact.event_key,v_fact.binding_hash,'ordinary']]);
  END LOOP;
  -- Original provisioning requires OBSERVER_INPUT:<reservationId> bootstrap
  -- records; recording these keys does not authenticate those records.
  FOR v_fact IN
   SELECT x.trust_id COLLATE "C" AS trust_id,x.generation FROM (VALUES
    (v_installer."trustId",v_installer."trustGeneration"),
    (v_installer.constructor_trust,v_installer.constructor_generation),
    (v_installer.observation_trust,v_installer.observation_generation),
    (v_installer.slot_trust,v_installer.slot_generation),
    (v_route.allocation_trust,v_route.allocation_generation),
    (v_route.layout_trust,v_route.layout_generation)
   ) AS x(trust_id,generation)
   GROUP BY x.trust_id COLLATE "C",x.generation ORDER BY x.trust_id COLLATE "C",x.generation
  LOOP
   IF NOT EXISTS (SELECT 1 FROM public."Pro262CapacityTrust" t JOIN public."Pro262CapacityBootstrapTrust" bt ON (bt."trustId",bt."generation")=(t."trustId",t."generation") WHERE (t."trustId",t."generation")=(v_fact.trust_id,v_fact.generation)) THEN RAISE EXCEPTION 'SELECTION_UNAVAILABLE'; END IF;
  END LOOP;
  FOR v_fact IN
   SELECT x.kind COLLATE "C" AS kind,x.event_key COLLATE "C" AS event_key,pg_catalog.min(x.binding_hash COLLATE "C") AS low_hash,pg_catalog.max(x.binding_hash COLLATE "C") AS high_hash
   FROM (VALUES
    (v_installer."chargeKind",v_installer."chargeEventKey",v_installer."chargeBindingHash"),
    (v_installer.observation_charge_kind,v_installer.observation_charge_event,v_installer.observation_charge_hash),
    (v_installer.session_charge_kind,v_installer.session_charge_event,v_installer.session_charge_hash),
    (v_installer.dispatch_charge_kind,v_installer.dispatch_charge_event,v_installer.dispatch_charge_hash),
    (v_installer.delivery_charge_kind,v_installer.delivery_charge_event,v_installer.delivery_charge_hash),
    (v_route.allocation_charge_kind,v_route.allocation_charge_event,v_route.allocation_charge_hash),
    (v_route.layout_charge_kind,v_route.layout_charge_event,v_route.layout_charge_hash)
   ) AS x(kind,event_key,binding_hash)
   GROUP BY x.kind COLLATE "C",x.event_key COLLATE "C" ORDER BY x.kind COLLATE "C",x.event_key COLLATE "C"
  LOOP
   IF v_fact.low_hash IS DISTINCT FROM v_fact.high_hash OR NOT EXISTS (SELECT 1 FROM public."Pro262CapacityControlCharge" ch WHERE (ch."kind",ch."eventKey",ch."bindingHash")=(v_fact.kind,v_fact.event_key,v_fact.low_hash)) THEN RAISE EXCEPTION 'SELECTION_UNAVAILABLE'; END IF;
   -- Compare the other already-discovered installer route without retaining an
   -- unbounded union. Allocation/layout facts are already in each local set.
   IF EXISTS (
    SELECT 1 FROM public."Pro273ControlPlaneInstallerExpectation" other
    JOIN public."Pro273InstallerDispatchAttempt" od ON (od."attemptId",od."expectationId",od."sessionClaimId")=(other."dispatchAttemptId",other."expectationId",other."sessionClaimId")
    JOIN public."Pro273InstallerSessionClaim" os ON (os."expectationId",os."sessionClaimId")=(other."expectationId",other."sessionClaimId")
    JOIN public."Pro273InstallerProcessObservation" oo ON (oo."expectationId",oo."credentialEpoch",oo."launchEpoch")=(other."expectationId",other."credentialEpoch",other."launchEpoch")
    JOIN public."Pro273InstallerDelivery" oy ON (oy."attemptId",oy."expectationId",oy."sessionClaimId")=(od."attemptId",other."expectationId",os."sessionClaimId")
    CROSS JOIN LATERAL (VALUES
     (other."chargeKind",other."chargeEventKey",other."chargeBindingHash"),
     (oo."chargeKind",oo."chargeEventKey",oo."chargeBindingHash"),
     (os."chargeKind",os."chargeEventKey",os."chargeBindingHash"),
     (od."chargeKind",od."chargeEventKey",od."chargeBindingHash"),
     (oy."chargeKind",oy."chargeEventKey",oy."chargeBindingHash")
    ) AS other_fact(kind,event_key,binding_hash)
    WHERE other."expectationId"=CASE WHEN v_key.id=v_route.current_expectation THEN v_route.historical_expectation ELSE v_route.current_expectation END
      AND other_fact.kind COLLATE "C"=v_fact.kind COLLATE "C"
      AND other_fact.event_key COLLATE "C"=v_fact.event_key COLLATE "C"
      AND other_fact.binding_hash COLLATE "C" IS DISTINCT FROM v_fact.low_hash COLLATE "C"
   ) THEN RAISE EXCEPTION 'SELECTION_UNAVAILABLE'; END IF;
  END LOOP;
 END LOOP;
 -- Follow the original publication claims separately; neither historical
 -- principal is inferred from the current session. STRICT and the equalities
 -- reject missing or conflicting stored routing facts, not authenticate them.
 IF v_route.layout_claim=v_route.allocation_claim THEN RAISE EXCEPTION 'SELECTION_UNAVAILABLE'; END IF;
 FOR v_key IN SELECT x.route_kind,x.claim_id,x.admission_id,x.event_id,x.receipt_hash,x.session_id,x.publisher_oid,x.publisher_name,x.trust_id,x.generation,x.trust_hash,x.capture_hash,x.charge_kind,x.charge_event,x.charge_hash,x.target_bootstrap,x.target_core,x.target_evidence FROM (VALUES
  ('LAYOUT',v_route.layout_claim,v_route.layout_admission,v_route.layout_event,v_route.layout_receipt,v_route.layout_session,v_route.layout_publisher_oid,v_route.layout_publisher_name,v_route.layout_trust,v_route.layout_generation,v_route.layout_trust_hash,v_route.layout_capture_hash,v_route.layout_charge_kind,v_route.layout_charge_event,v_route.layout_charge_hash,'SELECTION_QUALIFIER_LAYOUT:'||v_route.physical_id,v_route.layout_hash,v_route.layout_evidence),
  ('ALLOCATION',v_route.allocation_claim,v_route.allocation_admission,v_route.allocation_event,v_route.allocation_receipt,v_route.allocation_session,v_route.allocation_publisher_oid,v_route.allocation_publisher_name,v_route.allocation_trust,v_route.allocation_generation,v_route.allocation_trust_hash,v_route.allocation_capture_hash,v_route.allocation_charge_kind,v_route.allocation_charge_event,v_route.allocation_charge_hash,'SELECTION_QUALIFIER_ALLOCATION:'||v_route.allocation_id,v_route.allocation_hash,v_route.allocation_evidence)
 ) AS x(route_kind,claim_id,admission_id,event_id,receipt_hash,session_id,publisher_oid,publisher_name,trust_id,generation,trust_hash,capture_hash,charge_kind,charge_event,charge_hash,target_bootstrap,target_core,target_evidence) ORDER BY x.route_kind COLLATE "C" LOOP
  SELECT r."receiptId",r."attemptId",r."sessionClaimId",r."eventId",r."backendPid",r."backendStart",
         c."inputClaimId",c."reservationId",c."chargeKind",c."chargeEventKey",c."chargeBindingHash",
         r."inputClaimId" AS initial_receipt_inputClaimId,
         r."receiptId" AS initial_receipt_receiptId,
         r."reservationId" AS initial_receipt_reservationId,
         r."baselineId" AS initial_receipt_baselineId,
         r."baselineCoreHash" AS initial_receipt_baselineCoreHash,
         r."sessionClaimId" AS initial_receipt_sessionClaimId,
         r."attemptId" AS initial_receipt_attemptId,
         r."eventId" AS initial_receipt_eventId,
         r."receiverIdentity" AS initial_receipt_receiverIdentity,
         r."principalOid" AS initial_receipt_principalOid,
         r."principalName" AS initial_receipt_principalName,
         r."credentialEpoch" AS initial_receipt_credentialEpoch,
         r."launchEpoch" AS initial_receipt_launchEpoch,
         r."backendPid" AS initial_receipt_backendPid,
         r."backendStart" AS initial_receipt_backendStart,
         r."sourceClosureHash" AS initial_receipt_sourceClosureHash,
         r."installationClosureHash" AS initial_receipt_installationClosureHash,
         r."chargeKind" AS initial_receipt_chargeKind,
         r."chargeEventKey" AS initial_receipt_chargeEventKey,
         r."chargeBindingHash" AS initial_receipt_chargeBindingHash,
         r."creationTransactionId" AS initial_receipt_creationTransactionId,
         r."target"->>'kind' AS initial_receipt_target_kind,
         r."target"->>'bootstrapKind' AS initial_receipt_target_bootstrapKind,
         r."target"->>'expectedCoreHash' AS initial_receipt_target_expectedCoreHash,
         r."target"->>'expectedEvidenceHash' AS initial_receipt_target_expectedEvidenceHash,
         c."inputClaimId" AS initial_claim_id,
         c."creationTransactionId" AS initial_claim_xid,
         c."baselineId" AS initial_claim_baseline,
         c."sessionClaimId" AS initial_claim_session,
         c."reservationId" AS initial_claim_reservation,
         c."purpose" AS initial_claim_purpose,
         c."eventId" AS initial_claim_event,
         c."chargeKind" AS initial_claim_charge_kind,
         c."chargeEventKey" AS initial_claim_charge_event,
         c."chargeBindingHash" AS initial_claim_charge_hash,
         c."target"->>'kind' AS initial_claim_target_kind,
         c."target"->>'bootstrapKind' AS initial_claim_target_bootstrap,
         c."target"->>'expectedCoreHash' AS initial_claim_target_core,
         c."target"->>'expectedEvidenceHash' AS initial_claim_target_evidence,
         b."reservationId" AS initial_binding_reservation, b."creationTransactionId" AS initial_binding_xid,
         b."baselineId" AS initial_binding_baseline, b."purpose" AS initial_binding_purpose, b."eventId" AS initial_binding_event,
         b."trustId" AS initial_binding_trust, b."trustGeneration" AS initial_binding_generation,
         b."chargeKind" AS initial_binding_charge_kind, b."chargeEventKey" AS initial_binding_charge_event, b."chargeBindingHash" AS initial_binding_charge_hash,
         b."target"->>'kind' AS initial_binding_target_kind, b."target"->>'bootstrapKind' AS initial_binding_target_bootstrap,
         b."target"->>'expectedCoreHash' AS initial_binding_target_core, b."target"->>'expectedEvidenceHash' AS initial_binding_target_evidence,
         b."trustId" AS binding_trust,b."trustGeneration" AS binding_generation,
         slot."recordHash" AS input_slot_hash,slot."prepaidEventKey" AS input_prepaid,
         slot."observerTrustId" AS input_slot_trust,slot."observerTrustGeneration" AS input_slot_generation,'OBSERVER_INPUT:'||slot."reservationId" AS input_bootstrap,slot."baselineAllocationProof" AS input_proof,
         prov."bootstrapKind" AS baseline_bootstrap,prov."trustId" AS baseline_trust,prov."trustGeneration" AS baseline_generation,prov."trustRecordHash" AS baseline_trust_hash,prov."publisherPrincipalName" AS baseline_publisher,
         prov."chargeKind" AS baseline_charge_kind,prov."chargeEventKey" AS baseline_charge_event,prov."chargeBindingHash" AS baseline_charge_hash,
         a."attemptId" AS initial_attempt_id,
         a."baselineId" AS initial_attempt_baseline,
         a."receiverIdentity" AS initial_attempt_receiver,
         a."chargeKind" AS initial_attempt_charge_kind,
         a."chargeEventKey" AS initial_attempt_charge_event,
         a."sessionChargeKind" AS initial_attempt_session_charge_kind,
         a."sessionChargeEventKey" AS initial_attempt_session_charge_event,
         a."requestHash" AS initial_attempt_request_hash,
         a."chargeBindingHash" AS initial_attempt_charge_hash,
         a."sessionChargeBindingHash" AS initial_attempt_session_charge_hash,
         a."attemptOrdinal" AS initial_attempt_ordinal,
         a."creationTransactionId" AS initial_attempt_xid,
         a."claimedAt" AS initial_attempt_time,
         a."chargeKind" AS launch_charge_kind,a."chargeEventKey" AS launch_charge_event,a."chargeBindingHash" AS launch_charge_hash,
         a."sessionChargeKind",a."sessionChargeEventKey",a."sessionChargeBindingHash",
         o."inputClaimId" AS capture_claim,cc."eventKey" AS capture_event,o."trustId" AS observer_trust,o."trustGeneration" AS observer_generation,
         cs."reservationId" AS capture_slot,cs."recordHash" AS capture_slot_hash,cs."prepaidEventKey" AS capture_prepaid,
         cs."observerTrustId" AS capture_slot_trust,cs."observerTrustGeneration" AS capture_slot_generation,'OBSERVER_INPUT:'||cs."reservationId" AS capture_bootstrap,cs."baselineAllocationProof" AS capture_proof,
         tp."chargeKind" AS publisher_charge_kind,tp."chargeEventKey" AS publisher_charge_event,tp."recordHash" AS publisher_charge_hash,
         s."sessionClaimId" AS initial_s_sessionClaimId,
         s."baselineId" AS initial_s_baselineId,
         s."attemptId" AS initial_s_attemptId,
         s."credentialEpoch" AS initial_s_credentialEpoch,
         s."launchEpoch" AS initial_s_launchEpoch,
         s."receiverIdentity" AS initial_s_receiverIdentity,
         s."principalOid" AS initial_s_principalOid,
         s."principalName" AS initial_s_principalName,
         s."creationTransactionId" AS initial_s_creationTransactionId,
         s."claimedAt" AS initial_s_claimedAt,
         o."sessionClaimId" AS initial_o_sessionClaimId,
         o."trustId" AS initial_o_trustId,
         o."credentialEpoch" AS initial_o_credentialEpoch,
         o."launchEpoch" AS initial_o_launchEpoch,
         o."host" AS initial_o_host,
         o."boot" AS initial_o_boot,
         o."processTree" AS initial_o_processTree,
         o."parentProcessTree" AS initial_o_parentProcessTree,
         o."inputClaimId" AS initial_o_inputClaimId,
         o."sourceClosureHash" AS initial_o_sourceClosureHash,
         o."installationClosureHash" AS initial_o_installationClosureHash,
         o."capturedHash" AS initial_o_capturedHash,
         o."observerOid" AS initial_o_observerOid,
         o."principalOid" AS initial_o_principalOid,
         o."observerPrincipal" AS initial_o_observerPrincipal,
         o."principalName" AS initial_o_principalName,
         o."backendPid" AS initial_o_backendPid,
         o."backendStart" AS initial_o_backendStart,
         o."validUntil" AS initial_o_validUntil,
         o."trustGeneration" AS initial_o_trustGeneration,
         pg_catalog.octet_length(o."capturedBytes") AS initial_o_capturedLength,
         ic."inputClaimId" AS initial_input_claim_inputClaimId,
         ic."reservationId" AS initial_input_claim_reservationId,
         ic."eventKey" AS initial_input_claim_eventKey,
         ic."phase" AS initial_input_claim_phase,
         ic."observerPrincipalOid" AS initial_input_claim_observerPrincipalOid,
         ic."observerPrincipalName" AS initial_input_claim_observerPrincipalName,
         ic."claimedAt" AS initial_input_claim_claimedAt,
         slot."reservationId" AS initial_input_slot_reservationId,
         slot."physicalIdentity" AS initial_input_slot_physicalIdentity,
         slot."physicalProofIdentity" AS initial_input_slot_physicalProofIdentity,
         slot."baselineAllocationProof" AS initial_input_slot_baselineAllocationProof,
         slot."observerPrincipalOid" AS initial_input_slot_observerPrincipalOid,
         slot."observerPrincipalName" AS initial_input_slot_observerPrincipalName,
         slot."observerTrustId" AS initial_input_slot_observerTrustId,
         slot."observerTrustGeneration" AS initial_input_slot_observerTrustGeneration,
         slot."phase" AS initial_input_slot_phase,
         slot."maxInputBytes" AS initial_input_slot_maxInputBytes,
         slot."recordHash" AS initial_input_slot_recordHash,
         slot."prepaidEventKey" AS initial_input_slot_prepaidEventKey,
         slot."backendBytes" AS initial_input_slot_backendBytes,
         slot."sharedBytes" AS initial_input_slot_sharedBytes,
         slot."otherBaselineBackend" AS initial_input_slot_otherBaselineBackend,
         slot."otherBaselineShared" AS initial_input_slot_otherBaselineShared,
         slot."concurrencySlot" AS initial_input_slot_concurrencySlot,
         CASE WHEN pg_catalog.jsonb_typeof(slot."record"->'expectedEventKey')='string' THEN slot."record"->>'expectedEventKey' ELSE NULL END AS initial_input_slot_expectedEvent,
         CASE WHEN pg_catalog.jsonb_typeof(slot."record"->'observerBackendPid')='string' THEN slot."record"->>'observerBackendPid' ELSE NULL END AS initial_input_slot_backendPid,
         cc."inputClaimId" AS initial_capture_claim_inputClaimId,
         cc."reservationId" AS initial_capture_claim_reservationId,
         cc."eventKey" AS initial_capture_claim_eventKey,
         cc."phase" AS initial_capture_claim_phase,
         cc."observerPrincipalOid" AS initial_capture_claim_observerPrincipalOid,
         cc."observerPrincipalName" AS initial_capture_claim_observerPrincipalName,
         cc."claimedAt" AS initial_capture_claim_claimedAt,
         cs."reservationId" AS initial_capture_slot_reservationId,
         cs."physicalIdentity" AS initial_capture_slot_physicalIdentity,
         cs."physicalProofIdentity" AS initial_capture_slot_physicalProofIdentity,
         cs."baselineAllocationProof" AS initial_capture_slot_baselineAllocationProof,
         cs."observerPrincipalOid" AS initial_capture_slot_observerPrincipalOid,
         cs."observerPrincipalName" AS initial_capture_slot_observerPrincipalName,
         cs."observerTrustId" AS initial_capture_slot_observerTrustId,
         cs."observerTrustGeneration" AS initial_capture_slot_observerTrustGeneration,
         cs."phase" AS initial_capture_slot_phase,
         cs."maxInputBytes" AS initial_capture_slot_maxInputBytes,
         cs."recordHash" AS initial_capture_slot_recordHash,
         cs."prepaidEventKey" AS initial_capture_slot_prepaidEventKey,
         cs."backendBytes" AS initial_capture_slot_backendBytes,
         cs."sharedBytes" AS initial_capture_slot_sharedBytes,
         cs."otherBaselineBackend" AS initial_capture_slot_otherBaselineBackend,
         cs."otherBaselineShared" AS initial_capture_slot_otherBaselineShared,
         cs."concurrencySlot" AS initial_capture_slot_concurrencySlot,
         CASE WHEN pg_catalog.jsonb_typeof(cs."record"->'expectedEventKey')='string' THEN cs."record"->>'expectedEventKey' ELSE NULL END AS initial_capture_slot_expectedEvent,
         cap."inputClaimId" AS input_receipt_claim,cap."capturedLength" AS input_receipt_length,
         cap."capturedHash" AS input_capture_hash,cap."operationReceipt" AS input_receipt_operation
  INTO STRICT v_history
  FROM public."Pro273InitialPreinputReceipt" r
  JOIN public."Pro273ControlPlaneInputClaim" c ON (c."inputClaimId",c."reservationId",c."baselineId",c."sessionClaimId",c."eventId",c."chargeKind",c."chargeEventKey",c."chargeBindingHash")=(r."inputClaimId",r."reservationId",r."baselineId",r."sessionClaimId",r."eventId",r."chargeKind",r."chargeEventKey",r."chargeBindingHash")
  JOIN public."Pro273ControlPlaneInputBinding" b ON (b."reservationId",b."baselineId",b."purpose",b."eventId",b."chargeKind",b."chargeEventKey",b."chargeBindingHash")=(c."reservationId",c."baselineId",c."purpose",c."eventId",c."chargeKind",c."chargeEventKey",c."chargeBindingHash")
  JOIN public."Pro262CapacityObserverInputClaim" ic ON (ic."inputClaimId",ic."reservationId",ic."eventKey",ic."phase")=(c."inputClaimId",c."reservationId",c."eventId",c."purpose")
  JOIN public."Pro262CapacityObserverInputReservation" slot ON (slot."reservationId",slot."phase",slot."observerPrincipalOid",slot."observerPrincipalName",slot."observerTrustId",slot."observerTrustGeneration",slot."physicalIdentity",slot."physicalProofIdentity")=(ic."reservationId",ic."phase",ic."observerPrincipalOid",ic."observerPrincipalName",b."trustId",b."trustGeneration",v_route.physical_id,v_route.proof_id)
  JOIN public."Pro273ControlPlaneBaseline" base ON (base."baselineId",base."coreHash",base."physicalIdentity",base."physicalProofIdentity",base."expectedFutureLayoutCoreHash",base."purpose")=(r."baselineId",r."baselineCoreHash",v_route.physical_id,v_route.proof_id,v_route.layout_hash,c."purpose")
  JOIN public."Pro273ControlPlaneBaselineProvenance" prov ON (prov."baselineId",prov."coreHash")=(base."baselineId",base."coreHash")
  JOIN public."Pro273ControlPlaneSessionClaim" s ON (s."baselineId",s."sessionClaimId",s."attemptId",s."receiverIdentity",s."principalOid",s."principalName",s."credentialEpoch",s."launchEpoch")=(r."baselineId",r."sessionClaimId",r."attemptId",r."receiverIdentity",r."principalOid",r."principalName",r."credentialEpoch",r."launchEpoch")
  JOIN public."Pro273ControlPlaneLaunchAttempt" a ON (a."baselineId",a."attemptId",a."receiverIdentity")=(s."baselineId",s."attemptId",s."receiverIdentity")
  JOIN public."Pro273ControlPlaneProcessObservation" o ON (o."sessionClaimId",o."principalOid",o."principalName",o."credentialEpoch",o."launchEpoch",o."backendPid",o."backendStart",o."sourceClosureHash",o."installationClosureHash",o."host",o."boot",o."processTree",o."parentProcessTree")=(s."sessionClaimId",r."principalOid",r."principalName",r."credentialEpoch",r."launchEpoch",r."backendPid",r."backendStart",r."sourceClosureHash",r."installationClosureHash",base."host",base."boot",base."processTree",base."parentProcessTree")
  JOIN public."Pro262CapacityObserverInputClaim" cc ON cc."inputClaimId"=o."inputClaimId"
  JOIN public."Pro262CapacityObserverInputReservation" cs ON (cs."reservationId",cs."phase",cs."observerPrincipalOid",cs."observerPrincipalName",cs."observerTrustId",cs."observerTrustGeneration",cs."physicalIdentity",cs."physicalProofIdentity")=(cc."reservationId",cc."phase",cc."observerPrincipalOid",cc."observerPrincipalName",o."trustId",o."trustGeneration",v_route.physical_id,v_route.proof_id)
  JOIN public."Pro273ControlPlaneInputReceipt" cap ON cap."inputClaimId"=c."inputClaimId"
  JOIN public."Pro273PublisherTrustProvenance" tp ON (tp."trustId",tp."generation",tp."recordHash")=(v_key.trust_id,v_key.generation,v_key.trust_hash)
  JOIN public."Pro262CapacityTrust" it ON (it."trustId",it."generation")=(b."trustId",b."trustGeneration")
  JOIN public."Pro262CapacityBootstrapTrust" ibt ON (ibt."trustId",ibt."generation",ibt."recordHash")=(it."trustId",it."generation",tp."recordHash")
  JOIN public."Pro262CapacityTrust" ot ON (ot."trustId",ot."generation")=(o."trustId",o."trustGeneration")
  JOIN public."Pro262CapacityBootstrapTrust" obt ON (obt."trustId",obt."generation")=(ot."trustId",ot."generation")
  JOIN public."Pro262CapacityBootstrapBaseline" sb ON (sb."kind",sb."recordHash",sb."evidenceHash")=('OBSERVER_INPUT:'||slot."reservationId",slot."recordHash",slot."baselineAllocationProof")
  JOIN public."Pro262CapacityBootstrapBaseline" cb ON (cb."kind",cb."recordHash",cb."evidenceHash")=('OBSERVER_INPUT:'||cs."reservationId",cs."recordHash",cs."baselineAllocationProof")
  WHERE (r."inputClaimId",r."receiptId",r."eventId",r."baselineId",r."baselineCoreHash",r."sessionClaimId")=(v_key.claim_id,v_key.admission_id,v_key.event_id,v_route.baseline_id,v_route.baseline_hash,v_key.session_id)
    AND c."purpose"='QUALIFIER_BASELINE_INITIAL'
    AND r."target" IS NOT DISTINCT FROM c."target" AND r."target" IS NOT DISTINCT FROM b."target"
    AND c."target"->>'kind'='INITIAL' AND c."target"->>'bootstrapKind'=v_key.target_bootstrap
    AND c."target"->>'expectedCoreHash'=v_key.target_core AND c."target"->>'expectedEvidenceHash'=v_key.target_evidence
    AND c."target" IS NOT DISTINCT FROM pg_catalog.jsonb_build_object('kind','INITIAL','bootstrapKind',v_key.target_bootstrap,'expectedCoreHash',v_key.target_core,'expectedEvidenceHash',v_key.target_evidence)
    AND (r."principalOid",r."principalName",r."credentialEpoch",r."launchEpoch",r."sourceClosureHash",r."installationClosureHash")=(base."principalOid",base."principalName",base."credentialEpoch",base."launchEpoch",base."sourceClosureHash",base."installationClosureHash")
    AND (slot."observerPrincipalOid",slot."observerPrincipalName",b."trustId",b."trustGeneration")=(v_key.publisher_oid,v_key.publisher_name,v_key.trust_id,v_key.generation)
    AND (slot."observerPrincipalOid",slot."observerPrincipalName")=(r."principalOid",r."principalName")
    AND (cc."observerPrincipalOid",cc."observerPrincipalName")=(o."observerOid",o."observerPrincipal")
    AND o."observerOid" IS DISTINCT FROM r."principalOid"
    AND slot."record"->>'expectedEventKey'=ic."eventKey" AND cs."record"->>'expectedEventKey'=cc."eventKey"
    AND (slot."record"->>'phase',slot."record"->>'reservationId')=(ic."phase",ic."reservationId")
    AND (cs."record"->>'phase',cs."record"->>'reservationId')=(cc."phase",cc."reservationId") AND cc."phase"='INSTALL_PROCESS'
    AND (slot."record"->>'physicalIdentity',slot."record"->>'physicalProofIdentity',slot."record"->>'baselineAllocationProof',slot."record"->>'observerPrincipalOid',slot."record"->>'observerPrincipalName',slot."record"->>'observerTrustId',slot."record"->>'observerTrustGeneration',slot."record"->>'prepaidEventKey')=(slot."physicalIdentity",slot."physicalProofIdentity",slot."baselineAllocationProof",slot."observerPrincipalOid"::TEXT,slot."observerPrincipalName"::TEXT,slot."observerTrustId",slot."observerTrustGeneration"::TEXT,slot."prepaidEventKey")
    AND (cs."record"->>'physicalIdentity',cs."record"->>'physicalProofIdentity',cs."record"->>'baselineAllocationProof',cs."record"->>'observerPrincipalOid',cs."record"->>'observerPrincipalName',cs."record"->>'observerTrustId',cs."record"->>'observerTrustGeneration',cs."record"->>'prepaidEventKey')=(cs."physicalIdentity",cs."physicalProofIdentity",cs."baselineAllocationProof",cs."observerPrincipalOid"::TEXT,cs."observerPrincipalName"::TEXT,cs."observerTrustId",cs."observerTrustGeneration"::TEXT,cs."prepaidEventKey")
    AND (slot."record"->>'targetKind',slot."record"->>'targetControlKey',slot."record"->>'targetCredentialEpoch',slot."record"->>'targetLaunchEpoch')=('CONTROL_PLANE',base."baselineId",r."credentialEpoch",r."launchEpoch")
    AND (cs."record"->>'targetKind',cs."record"->>'targetControlKey',cs."record"->>'targetCredentialEpoch',cs."record"->>'targetLaunchEpoch')=('CONTROL_PLANE',base."baselineId",o."credentialEpoch",o."launchEpoch")
    AND (slot."record"->>'observerBackendPid',(slot."record"->>'observerBackendStart')::TIMESTAMPTZ,slot."record"->>'observerCredentialEpoch',slot."record"->>'observerLaunchEpoch',slot."record"->>'observerSourceClosure',slot."record"->>'observerHost',slot."record"->>'observerBoot',slot."record"->>'observerProcessTree')=(r."backendPid"::TEXT,r."backendStart",r."credentialEpoch",r."launchEpoch",r."sourceClosureHash",base."host",base."boot",base."processTree")
    AND it."purpose"='QUALIFIER_BASELINE_PUBLISHER' AND it."supplierPrincipal"=r."principalName"
    AND (it."scope"->>'physicalIdentity',it."scope"->>'physicalProofIdentity',it."scope"->>'publisherPrincipalOid',it."scope"->>'publisherPrincipalName',it."scope"->>'sourceClosureHash',it."scope"->>'inputEnvelope',it."scope"->>'bootstrapKind')=(v_route.physical_id,v_route.proof_id,r."principalOid"::TEXT,r."principalName"::TEXT,r."sourceClosureHash",slot."baselineAllocationProof",v_key.target_bootstrap)
    AND it."scope"->'target' IS NOT DISTINCT FROM c."target"
    AND ot."purpose"='INSTALL_OBSERVATION' AND ot."supplierPrincipal"=o."observerPrincipal" AND ot."scope"->>'observerHolderId'=cs."baselineAllocationProof"
    AND (c."chargeKind",c."chargeEventKey",c."chargeBindingHash")=(v_key.charge_kind,v_key.charge_event,v_key.charge_hash)
    AND (cap."capturedHash",cap."operationReceipt")=(v_key.capture_hash,v_key.receipt_hash);
  IF v_key.trust_hash IS NULL OR v_key.trust_hash !~ '^[a-f0-9]{64}$'
     OR v_history.baseline_trust_hash IS NULL OR v_history.baseline_trust_hash !~ '^[a-f0-9]{64}$'
     OR v_history."reservationId" IS NULL OR pg_catalog.octet_length(v_history."reservationId") NOT BETWEEN 1 AND 256
     OR v_history.capture_slot IS NULL OR pg_catalog.octet_length(v_history.capture_slot) NOT BETWEEN 1 AND 256
  THEN RAISE EXCEPTION 'SELECTION_UNAVAILABLE'; END IF;
  -- Retain the L/A route independently of the overwritten history record.
  FOR v_fact IN SELECT x.value FROM (VALUES
   (v_key.route_kind),(v_key.claim_id),(v_key.admission_id),(v_key.event_id),(v_key.session_id),
   (v_history."reservationId"),(v_history.capture_claim),(v_history.capture_event),(v_history.capture_slot),(v_history."attemptId")
  ) AS x(value) LOOP
   IF v_fact.value IS NULL OR pg_catalog.octet_length(v_fact.value) NOT BETWEEN 1 AND 256 THEN RAISE EXCEPTION 'SELECTION_UNAVAILABLE'; END IF;
  END LOOP;
  FOR v_fact IN SELECT x.value FROM (VALUES
   (v_key.capture_hash),(v_key.receipt_hash),(v_history.input_slot_hash),(v_history.capture_slot_hash)
  ) AS x(value) LOOP
   IF v_fact.value IS NULL OR v_fact.value !~ '^[a-f0-9]{64}$' THEN RAISE EXCEPTION 'SELECTION_UNAVAILABLE'; END IF;
  END LOOP;
  IF COALESCE(pg_catalog.array_length(v_initial_keys,1),0)>=2 THEN RAISE EXCEPTION 'SELECTION_UNAVAILABLE'; END IF;
  -- Original receipt scalars only; JSON/detoast and runtime remain unqualified.
  IF EXISTS (SELECT 1 FROM (VALUES (v_history.initial_receipt_inputClaimId),(v_history.initial_receipt_receiptId),(v_history.initial_receipt_reservationId),(v_history.initial_receipt_baselineId),(v_history.initial_receipt_sessionClaimId),(v_history.initial_receipt_attemptId),(v_history.initial_receipt_eventId),(v_history.initial_receipt_receiverIdentity),(v_history.initial_receipt_credentialEpoch),(v_history.initial_receipt_launchEpoch),(v_history.initial_receipt_chargeKind),(v_history.initial_receipt_chargeEventKey),(v_history.initial_receipt_target_kind)) AS t(value) WHERE t.value IS NULL OR pg_catalog.octet_length(t.value) NOT BETWEEN 1 AND 256)
     OR v_history.initial_receipt_target_bootstrapKind IS NULL OR NOT pg_catalog.starts_with(v_history.initial_receipt_target_bootstrapKind,CASE WHEN v_key.route_kind='ALLOCATION' THEN 'SELECTION_QUALIFIER_ALLOCATION:' ELSE 'SELECTION_QUALIFIER_LAYOUT:' END) OR pg_catalog.octet_length(v_history.initial_receipt_target_bootstrapKind) NOT BETWEEN 1 AND CASE WHEN v_key.route_kind='ALLOCATION' THEN 287 ELSE 283 END
     OR pg_catalog.octet_length(pg_catalog.substr(v_history.initial_receipt_target_bootstrapKind,pg_catalog.length(CASE WHEN v_key.route_kind='ALLOCATION' THEN 'SELECTION_QUALIFIER_ALLOCATION:' ELSE 'SELECTION_QUALIFIER_LAYOUT:' END)+1)) NOT BETWEEN 1 AND 256
     OR EXISTS (SELECT 1 FROM (VALUES (v_history.initial_receipt_baselineCoreHash),(v_history.initial_receipt_sourceClosureHash),(v_history.initial_receipt_installationClosureHash),(v_history.initial_receipt_chargeBindingHash),(v_history.initial_receipt_target_expectedCoreHash),(v_history.initial_receipt_target_expectedEvidenceHash)) AS t(value) WHERE t.value IS NULL OR t.value !~ '^[a-f0-9]{64}$')
     OR v_history.initial_receipt_principalOid IS NULL OR v_history.initial_receipt_principalName IS NULL OR v_history.initial_receipt_backendPid IS NULL OR v_history.initial_receipt_backendStart IS NULL OR v_history.initial_receipt_creationTransactionId IS NULL OR v_history.initial_receipt_backendPid<=0 THEN RAISE EXCEPTION 'SELECTION_UNAVAILABLE'; END IF;
  v_initial_receipt_text:=pg_catalog.array_cat(v_initial_receipt_text,ARRAY[[v_history.initial_receipt_inputClaimId,v_history.initial_receipt_receiptId,v_history.initial_receipt_reservationId,v_history.initial_receipt_baselineId,v_history.initial_receipt_sessionClaimId,v_history.initial_receipt_attemptId,v_history.initial_receipt_eventId,v_history.initial_receipt_receiverIdentity,v_history.initial_receipt_credentialEpoch,v_history.initial_receipt_launchEpoch,v_history.initial_receipt_chargeKind,v_history.initial_receipt_chargeEventKey,v_history.initial_receipt_target_kind,v_history.initial_receipt_target_bootstrapKind]]);
  v_initial_receipt_hashes:=pg_catalog.array_cat(v_initial_receipt_hashes,ARRAY[[v_history.initial_receipt_baselineCoreHash,v_history.initial_receipt_sourceClosureHash,v_history.initial_receipt_installationClosureHash,v_history.initial_receipt_chargeBindingHash,v_history.initial_receipt_target_expectedCoreHash,v_history.initial_receipt_target_expectedEvidenceHash]]);
  v_initial_receipt_oid:=pg_catalog.array_cat(v_initial_receipt_oid,ARRAY[v_history.initial_receipt_principalOid]);
  v_initial_receipt_name:=pg_catalog.array_cat(v_initial_receipt_name,ARRAY[v_history.initial_receipt_principalName]);
  -- Non-string historical event keys and observer PIDs are incompatible with this projection.
  -- These scalar bounds do not qualify detoast or resource safety.
  IF v_history.initial_input_slot_backendPid IS NULL OR pg_catalog.octet_length(v_history.initial_input_slot_backendPid) NOT BETWEEN 1 AND 10 OR v_history.initial_input_slot_backendPid COLLATE "C" !~ '^[1-9][0-9]{0,9}$' OR (pg_catalog.octet_length(v_history.initial_input_slot_backendPid)=10 AND v_history.initial_input_slot_backendPid COLLATE "C">'2147483647' COLLATE "C") OR v_history.initial_input_slot_backendPid COLLATE "C" IS DISTINCT FROM v_history.initial_receipt_backendPid::TEXT COLLATE "C" THEN RAISE EXCEPTION 'SELECTION_UNAVAILABLE'; END IF;
  v_initial_receipt_pid:=pg_catalog.array_cat(v_initial_receipt_pid,ARRAY[v_history.initial_receipt_backendPid]);
  v_initial_input_slot_pid:=pg_catalog.array_cat(v_initial_input_slot_pid,ARRAY[v_history.initial_input_slot_backendPid]);
  v_initial_receipt_time:=pg_catalog.array_cat(v_initial_receipt_time,ARRAY[v_history.initial_receipt_backendStart]);
  v_initial_receipt_xid:=pg_catalog.array_cat(v_initial_receipt_xid,ARRAY[v_history.initial_receipt_creationTransactionId]);
  -- Scalar receipt facts do not authenticate bytes; BYTEA/detoast and issuer remain unqualified.
  IF v_history.input_receipt_claim IS NULL OR pg_catalog.octet_length(v_history.input_receipt_claim) NOT BETWEEN 1 AND 256
     OR v_history.input_receipt_claim COLLATE "C" IS DISTINCT FROM v_key.claim_id COLLATE "C"
     OR v_history.input_receipt_length IS NULL OR v_history.input_receipt_length<=0
     OR v_history.input_capture_hash IS NULL OR v_history.input_capture_hash !~ '^[a-f0-9]{64}$'
     OR v_history.input_receipt_operation IS NULL OR v_history.input_receipt_operation !~ '^[a-f0-9]{64}$'
     OR v_history.input_capture_hash COLLATE "C" IS DISTINCT FROM v_key.capture_hash COLLATE "C"
