  v_initial_claim_text:=pg_catalog.array_cat(v_initial_claim_text,ARRAY[[v_history.initial_claim_id,v_history.initial_claim_baseline,v_history.initial_claim_session,v_history.initial_claim_reservation,v_history.initial_claim_purpose,v_history.initial_claim_event,v_history.initial_claim_charge_kind,v_history.initial_claim_charge_event,v_history.initial_claim_target_kind,v_history.initial_claim_target_bootstrap] ]);
