       WHERE t.value IS NULL OR pg_catalog.octet_length(t.value) NOT BETWEEN 1 AND 256)
     OR v_history.initial_binding_target_bootstrap IS NULL OR pg_catalog.octet_length(v_history.initial_binding_target_bootstrap) NOT BETWEEN 1 AND 288
     OR v_history.initial_binding_target_bootstrap COLLATE "C" IS DISTINCT FROM v_key.target_bootstrap COLLATE "C"
     OR v_history.initial_binding_xid IS NULL OR v_history.initial_binding_generation IS NULL
     OR v_history.initial_binding_charge_hash IS NULL OR v_history.initial_binding_charge_hash !~ '^[a-f0-9]{64}$'
     OR v_history.initial_binding_target_core IS NULL OR v_history.initial_binding_target_core !~ '^[a-f0-9]{64}$'
     OR v_history.initial_binding_target_evidence IS NULL OR v_history.initial_binding_target_evidence !~ '^[a-f0-9]{64}$'
  THEN RAISE EXCEPTION 'SELECTION_UNAVAILABLE'; END IF;
  v_initial_binding_text:=pg_catalog.array_cat(v_initial_binding_text,ARRAY[[v_history.initial_binding_reservation,v_history.initial_binding_baseline,v_history.initial_binding_purpose,v_history.initial_binding_event,v_history.initial_binding_trust,v_history.initial_binding_charge_kind,v_history.initial_binding_charge_event,v_history.initial_binding_target_kind,v_history.initial_binding_target_bootstrap]]);
  v_initial_binding_hashes:=pg_catalog.array_cat(v_initial_binding_hashes,ARRAY[[v_history.initial_binding_charge_hash,v_history.initial_binding_target_core,v_history.initial_binding_target_evidence]]);
  v_initial_binding_generation:=pg_catalog.array_cat(v_initial_binding_generation,ARRAY[v_history.initial_binding_generation]);
  v_initial_binding_xid:=pg_catalog.array_cat(v_initial_binding_xid,ARRAY[v_history.initial_binding_xid]);
  -- Preserve original L/A input and capture claim/reservation roles.
  FOR v_fact IN SELECT * FROM (VALUES
