   (v_history.initial_capture_claim_inputClaimId,v_history.initial_capture_claim_reservationId,v_history.initial_capture_claim_eventKey,v_history.initial_capture_claim_phase,v_history.initial_capture_claim_observerPrincipalOid,v_history.initial_capture_claim_observerPrincipalName,v_history.initial_capture_claim_claimedAt,v_history.initial_capture_slot_reservationId,v_history.initial_capture_slot_physicalIdentity,v_history.initial_capture_slot_physicalProofIdentity,v_history.initial_capture_slot_baselineAllocationProof,v_history.initial_capture_slot_observerPrincipalOid,v_history.initial_capture_slot_observerPrincipalName,v_history.initial_capture_slot_observerTrustId,v_history.initial_capture_slot_observerTrustGeneration,v_history.initial_capture_slot_phase,v_history.initial_capture_slot_maxInputBytes,v_history.initial_capture_slot_recordHash,v_history.initial_capture_slot_prepaidEventKey,v_history.initial_capture_slot_backendBytes,v_history.initial_capture_slot_sharedBytes,v_history.initial_capture_slot_otherBaselineBackend,v_history.initial_capture_slot_otherBaselineShared,v_history.initial_capture_slot_concurrencySlot,v_history.initial_capture_slot_expectedEvent)
  ) AS x(claim_id,claim_reservation,claim_event,claim_phase,claim_oid,claim_name,claim_time,slot_id,physical_id,physical_proof,allocation_proof,slot_oid,slot_name,trust_id,generation,slot_phase,max_input,record_hash,prepaid,backend,shared,other_backend,other_shared,concurrency_slot,expected_event) LOOP
