      OR pg_catalog.octet_length(v_fact.claim_name::TEXT) NOT BETWEEN 1 AND 256
      OR pg_catalog.octet_length(v_fact.slot_name::TEXT) NOT BETWEEN 1 AND 256
      OR v_fact.claim_time IS NULL OR v_fact.generation IS NULL OR v_fact.generation<=0
      OR v_fact.max_input IS NULL OR v_fact.max_input<=0 OR v_fact.max_input>9223372036854775807
