   v_initial_slot_event:=pg_catalog.array_cat(v_initial_slot_event,ARRAY[v_fact.expected_event]);
   v_initial_slot_text:=pg_catalog.array_cat(v_initial_slot_text,ARRAY[[v_fact.claim_id,v_fact.claim_reservation,v_fact.claim_event,v_fact.claim_phase,v_fact.slot_id,v_fact.physical_id,v_fact.physical_proof,v_fact.trust_id,v_fact.slot_phase,v_fact.prepaid]]);
   v_initial_slot_hashes:=pg_catalog.array_cat(v_initial_slot_hashes,ARRAY[[v_fact.allocation_proof,v_fact.record_hash]]);
