  v_initial_attempt_hashes:=pg_catalog.array_cat(v_initial_attempt_hashes,ARRAY[[v_history.initial_attempt_request_hash,v_history.initial_attempt_charge_hash,v_history.initial_attempt_session_charge_hash]]);
