  END LOOP;
  FOR v_fact IN SELECT x.value FROM (VALUES (v_history.initial_o_sourceClosureHash),(v_history.initial_o_installationClosureHash),(v_history.initial_o_capturedHash)) AS x(value) LOOP
   IF v_fact.value IS NULL OR v_fact.value !~ '^[a-f0-9]{64}$'
 THEN RAISE EXCEPTION 'SELECTION_UNAVAILABLE'; END IF;
  END LOOP;
  IF v_history.initial_s_principalOid IS NULL OR
