  v_initial_keys:=pg_catalog.array_cat(v_initial_keys,ARRAY[[v_key.route_kind,v_key.claim_id,v_key.admission_id,v_key.event_id,v_key.session_id,v_history."reservationId",v_history.capture_claim,v_history.capture_event,v_history.capture_slot,v_history."attemptId"]]);
  v_initial_facts:=pg_catalog.array_cat(v_initial_facts,ARRAY[[v_key.capture_hash,v_key.receipt_hash,v_history.input_slot_hash,v_history.capture_slot_hash]]);
