    CASE WHEN v_key.route_kind='LAYOUT' THEN v_route.layout_boot_evidence ELSE v_route.allocation_boot_evidence END,v_key.publisher_name::TEXT),
   (v_history.input_bootstrap,v_history.input_slot_hash,v_history.input_proof,NULL::TEXT),
