  IF v_key.trust_id IS NULL OR pg_catalog.octet_length(v_key.trust_id) NOT BETWEEN 1 AND 256
     OR v_key.generation IS NULL OR v_key.generation<=0
     OR v_history.publisher_charge_kind IS DISTINCT FROM 'TRUST_PROVISION'
     OR v_history.publisher_charge_event IS DISTINCT FROM v_key.trust_id||':'||v_key.generation::TEXT
  THEN RAISE EXCEPTION 'SELECTION_UNAVAILABLE'; END IF;
  FOR v_fact IN SELECT * FROM (VALUES
