   (v_history.launch_charge_kind,v_history.launch_charge_event,v_history.launch_charge_hash,'ordinary'),
   (v_history."sessionChargeKind",v_history."sessionChargeEventKey",v_history."sessionChargeBindingHash",'ordinary'),
   (v_history.publisher_charge_kind,v_history.publisher_charge_event,v_history.publisher_charge_hash,'publisher'),
   ('OBSERVER_INPUT_SLOT',v_history.input_prepaid,v_history.input_slot_hash,'ordinary'),
   ('OBSERVER_INPUT_SLOT',v_history.capture_prepaid,v_history.capture_slot_hash,'ordinary')
  ) AS x(kind,event_key,binding_hash,event_class) LOOP
   IF v_fact.kind IS NULL OR pg_catalog.octet_length(v_fact.kind) NOT BETWEEN 1 AND 256
      OR v_fact.event_key IS NULL OR pg_catalog.octet_length(v_fact.event_key) NOT BETWEEN 1 AND
         CASE WHEN v_fact.event_class='publisher' THEN 276 ELSE 256 END
