   THEN RAISE EXCEPTION 'SELECTION_UNAVAILABLE'; END IF;
   v_charge_candidates:=pg_catalog.array_cat(v_charge_candidates,ARRAY[[v_fact.kind,v_fact.event_key,v_fact.binding_hash,v_fact.event_class]]);
  END LOOP;
  FOR v_fact IN SELECT x.kind COLLATE "C" AS kind,x.event_key COLLATE "C" AS event_key,pg_catalog.min(x.binding_hash COLLATE "C") AS low_hash,pg_catalog.max(x.binding_hash COLLATE "C") AS high_hash FROM (VALUES
   (v_history."chargeKind",v_history."chargeEventKey",v_history."chargeBindingHash"),
   (v_history.baseline_charge_kind,v_history.baseline_charge_event,v_history.baseline_charge_hash),
   (v_history.launch_charge_kind,v_history.launch_charge_event,v_history.launch_charge_hash),
   (v_history."sessionChargeKind",v_history."sessionChargeEventKey",v_history."sessionChargeBindingHash"),
   (v_history.publisher_charge_kind,v_history.publisher_charge_event,v_history.publisher_charge_hash),
   ('OBSERVER_INPUT_SLOT',v_history.input_prepaid,v_history.input_slot_hash),
   ('OBSERVER_INPUT_SLOT',v_history.capture_prepaid,v_history.capture_slot_hash)
  ) AS x(kind,event_key,binding_hash) GROUP BY x.kind COLLATE "C",x.event_key COLLATE "C" ORDER BY x.kind COLLATE "C",x.event_key COLLATE "C" LOOP
   IF v_fact.low_hash IS DISTINCT FROM v_fact.high_hash OR NOT EXISTS (SELECT 1 FROM public."Pro262CapacityControlCharge" ch WHERE (ch."kind",ch."eventKey",ch."bindingHash")=(v_fact.kind,v_fact.event_key,v_fact.low_hash)) THEN RAISE EXCEPTION 'SELECTION_UNAVAILABLE'; END IF;
  END LOOP;
 END LOOP;
 -- Shared primary keys include the full original baseline/layout binding tuple.
 v_relation_keys:=pg_catalog.array_cat(v_relation_keys,ARRAY[
  ['SHARED','Pro273QualifierBaselineLayout',v_route.physical_id,'',''],
  ['SHARED','Pro273QualifierAllocation',v_route.allocation_id,'',''],
  ['SHARED','Pro273ControlPlaneBaseline',v_route.baseline_id,'',''],
  ['SHARED','Pro273ControlPlaneBaselineProvenance',v_route.baseline_id,'',''],
  ['SHARED','Pro273InitialBaselineLayoutBinding',v_route.baseline_id,v_route.baseline_hash,v_route.layout_claim]]);
 IF pg_catalog.array_length(v_relation_keys,1) IS DISTINCT FROM 53 OR pg_catalog.array_length(v_relation_keys,2) IS DISTINCT FROM 5 THEN RAISE EXCEPTION 'SELECTION_UNAVAILABLE'; END IF;
 FOR v_snapshot_i IN 1..53 LOOP
  IF v_relation_keys[v_snapshot_i][1] IS NULL OR pg_catalog.octet_length(v_relation_keys[v_snapshot_i][1]) NOT BETWEEN 1 AND 256
     OR v_relation_keys[v_snapshot_i][2] IS NULL OR pg_catalog.octet_length(v_relation_keys[v_snapshot_i][2]) NOT BETWEEN 1 AND 256
     OR v_relation_keys[v_snapshot_i][3] IS NULL OR pg_catalog.octet_length(v_relation_keys[v_snapshot_i][3]) NOT BETWEEN 1 AND 256
     OR v_relation_keys[v_snapshot_i][4] IS NULL OR pg_catalog.octet_length(v_relation_keys[v_snapshot_i][4])>256
     OR v_relation_keys[v_snapshot_i][5] IS NULL OR pg_catalog.octet_length(v_relation_keys[v_snapshot_i][5])>256
  THEN RAISE EXCEPTION 'SELECTION_UNAVAILABLE'; END IF;
 END LOOP;
 -- This is not a full fact snapshot. Reread all routed keys, facts and presence
 -- under complete locks and after helper reentry; no partial locking is authorized.
 -- Require two aligned rows per route family, then compare aliases before deduplication.
 IF pg_catalog.array_length(v_expectation_text,1) IS DISTINCT FROM 2 OR pg_catalog.array_length(v_expectation_text,2) IS DISTINCT FROM 26
    OR pg_catalog.array_length(v_expectation_hashes,1) IS DISTINCT FROM 2 OR pg_catalog.array_length(v_expectation_hashes,2) IS DISTINCT FROM 10
    OR pg_catalog.array_length(v_expectation_oids,1) IS DISTINCT FROM 2 OR pg_catalog.array_length(v_expectation_names,1) IS DISTINCT FROM 2
    OR pg_catalog.array_length(v_expectation_pids,1) IS DISTINCT FROM 2 OR pg_catalog.array_length(v_expectation_generations,1) IS DISTINCT FROM 2
    OR pg_catalog.array_length(v_expectation_times,1) IS DISTINCT FROM 2 OR pg_catalog.array_length(v_expectation_times,2) IS DISTINCT FROM 3
    OR pg_catalog.array_length(v_dispatch_text,1) IS DISTINCT FROM 2 OR pg_catalog.array_length(v_dispatch_text,2) IS DISTINCT FROM 8
    OR pg_catalog.array_length(v_dispatch_hashes,1) IS DISTINCT FROM 2 OR pg_catalog.array_length(v_dispatch_hashes,2) IS DISTINCT FROM 3
    OR pg_catalog.array_length(v_dispatch_transactions,1) IS DISTINCT FROM 2 OR pg_catalog.array_length(v_dispatch_times,1) IS DISTINCT FROM 2
    OR pg_catalog.array_length(v_delivery_text,1) IS DISTINCT FROM 2 OR pg_catalog.array_length(v_delivery_text,2) IS DISTINCT FROM 7
    OR pg_catalog.array_length(v_delivery_hashes,1) IS DISTINCT FROM 2 OR pg_catalog.array_length(v_delivery_hashes,2) IS DISTINCT FROM 2
    OR pg_catalog.array_length(v_delivery_transactions,1) IS DISTINCT FROM 2 OR pg_catalog.array_length(v_delivery_times,1) IS DISTINCT FROM 2
    OR pg_catalog.array_length(v_session_text,1) IS DISTINCT FROM 2 OR pg_catalog.array_length(v_session_text,2) IS DISTINCT FROM 6
    OR pg_catalog.array_length(v_session_hashes,1) IS DISTINCT FROM 2 OR pg_catalog.array_length(v_session_hashes,2) IS DISTINCT FROM 4
