    OR pg_catalog.array_length(v_initial_binding_text,1) IS DISTINCT FROM 2 OR pg_catalog.array_length(v_initial_binding_text,2) IS DISTINCT FROM 9
    OR pg_catalog.array_length(v_initial_binding_hashes,1) IS DISTINCT FROM 2 OR pg_catalog.array_length(v_initial_binding_hashes,2) IS DISTINCT FROM 3
    OR pg_catalog.array_length(v_initial_binding_generation,1) IS DISTINCT FROM 2 OR pg_catalog.array_length(v_initial_binding_xid,1) IS DISTINCT FROM 2
    OR pg_catalog.array_length(v_initial_receipt_text,1) IS DISTINCT FROM 2 OR pg_catalog.array_length(v_initial_receipt_text,2) IS DISTINCT FROM 14
    OR pg_catalog.array_length(v_initial_receipt_hashes,1) IS DISTINCT FROM 2 OR pg_catalog.array_length(v_initial_receipt_hashes,2) IS DISTINCT FROM 6
