 THEN RAISE EXCEPTION 'SELECTION_UNAVAILABLE'; END IF;
 IF v_initial_keys[1][1] COLLATE "C" IS DISTINCT FROM 'ALLOCATION' OR v_initial_keys[2][1] COLLATE "C" IS DISTINCT FROM 'LAYOUT'
    OR v_initial_binding_text[1][1] COLLATE "C" IS NOT DISTINCT FROM v_initial_binding_text[2][1] COLLATE "C"
    OR v_initial_binding_text[1][1] COLLATE "C" IS DISTINCT FROM v_initial_keys[1][6] COLLATE "C"
    OR v_initial_binding_text[2][1] COLLATE "C" IS DISTINCT FROM v_initial_keys[2][6] COLLATE "C"
 THEN RAISE EXCEPTION 'SELECTION_UNAVAILABLE'; END IF;
 FOR v_snapshot_i IN 1..8 LOOP
  FOR v_snapshot_j IN 1..8 LOOP
   IF (v_slot_occurrences[v_snapshot_i][1] COLLATE "C"=v_slot_occurrences[v_snapshot_j][1] COLLATE "C"
       AND v_slot_occurrences[v_snapshot_i][2] COLLATE "C" IS DISTINCT FROM v_slot_occurrences[v_snapshot_j][2] COLLATE "C")
      OR (v_slot_occurrences[v_snapshot_i][2] COLLATE "C"=v_slot_occurrences[v_snapshot_j][2] COLLATE "C"
       AND v_slot_occurrences[v_snapshot_i][3] COLLATE "C" IS DISTINCT FROM v_slot_occurrences[v_snapshot_j][3] COLLATE "C")
   THEN RAISE EXCEPTION 'SELECTION_UNAVAILABLE'; END IF;
  END LOOP;
 END LOOP;
 -- Equal keys must retain equal stored facts, without collapsing occurrences.
 FOR v_snapshot_i IN 1..4 LOOP
  FOR v_snapshot_j IN 1..4 LOOP
   IF v_installer_slot_text[v_snapshot_i][1] COLLATE "C"=v_installer_slot_text[v_snapshot_j][1] COLLATE "C"
      AND (v_installer_slot_text[v_snapshot_i:v_snapshot_i][1:4] COLLATE "C" IS DISTINCT FROM v_installer_slot_text[v_snapshot_j:v_snapshot_j][1:4] COLLATE "C"
        OR v_installer_slot_oids[v_snapshot_i][1] IS DISTINCT FROM v_installer_slot_oids[v_snapshot_j][1]
        OR v_installer_slot_names[v_snapshot_i][1] IS DISTINCT FROM v_installer_slot_names[v_snapshot_j][1]
        OR v_installer_claim_times[v_snapshot_i] IS DISTINCT FROM v_installer_claim_times[v_snapshot_j])
   THEN RAISE EXCEPTION 'SELECTION_UNAVAILABLE'; END IF;
   IF v_installer_slot_text[v_snapshot_i][5] COLLATE "C"=v_installer_slot_text[v_snapshot_j][5] COLLATE "C"
      AND (v_installer_slot_text[v_snapshot_i:v_snapshot_i][5:10] COLLATE "C" IS DISTINCT FROM v_installer_slot_text[v_snapshot_j:v_snapshot_j][5:10] COLLATE "C"
        OR v_installer_binding_text[v_snapshot_i:v_snapshot_i][1:7] COLLATE "C" IS DISTINCT FROM v_installer_binding_text[v_snapshot_j:v_snapshot_j][1:7] COLLATE "C"
        OR v_installer_slot_hashes[v_snapshot_i:v_snapshot_i][1:2] COLLATE "C" IS DISTINCT FROM v_installer_slot_hashes[v_snapshot_j:v_snapshot_j][1:2] COLLATE "C"
        OR v_installer_slot_oids[v_snapshot_i][2] IS DISTINCT FROM v_installer_slot_oids[v_snapshot_j][2]
        OR v_installer_slot_names[v_snapshot_i][2] IS DISTINCT FROM v_installer_slot_names[v_snapshot_j][2]
        OR v_installer_slot_generations[v_snapshot_i] IS DISTINCT FROM v_installer_slot_generations[v_snapshot_j]
        OR v_installer_slot_limits[v_snapshot_i] IS DISTINCT FROM v_installer_slot_limits[v_snapshot_j]
        OR v_installer_slot_resources[v_snapshot_i:v_snapshot_i][1:4] IS DISTINCT FROM v_installer_slot_resources[v_snapshot_j:v_snapshot_j][1:4]
        OR v_installer_slot_concurrency[v_snapshot_i] COLLATE "C" IS DISTINCT FROM v_installer_slot_concurrency[v_snapshot_j] COLLATE "C"
        OR v_installer_slot_event[v_snapshot_i] COLLATE "C" IS DISTINCT FROM v_installer_slot_event[v_snapshot_j] COLLATE "C")
   THEN RAISE EXCEPTION 'SELECTION_UNAVAILABLE'; END IF;
  END LOOP;
 END LOOP;
 -- Compare historical role aliases before deduplication.
 FOR v_snapshot_i IN 1..4 LOOP
  FOR v_snapshot_j IN 1..4 LOOP
   IF v_initial_slot_text[v_snapshot_i][1] COLLATE "C"=v_initial_slot_text[v_snapshot_j][1] COLLATE "C"
      AND (v_initial_slot_text[v_snapshot_i:v_snapshot_i][1:4] COLLATE "C" IS DISTINCT FROM v_initial_slot_text[v_snapshot_j:v_snapshot_j][1:4] COLLATE "C"
        OR v_initial_slot_oids[v_snapshot_i][1] IS DISTINCT FROM v_initial_slot_oids[v_snapshot_j][1]
        OR v_initial_slot_names[v_snapshot_i][1] IS DISTINCT FROM v_initial_slot_names[v_snapshot_j][1]
        OR v_initial_claim_times[v_snapshot_i] IS DISTINCT FROM v_initial_claim_times[v_snapshot_j])
   THEN RAISE EXCEPTION 'SELECTION_UNAVAILABLE'; END IF;
   IF v_initial_slot_text[v_snapshot_i][5] COLLATE "C"=v_initial_slot_text[v_snapshot_j][5] COLLATE "C"
      AND (v_initial_slot_text[v_snapshot_i:v_snapshot_i][5:10] COLLATE "C" IS DISTINCT FROM v_initial_slot_text[v_snapshot_j:v_snapshot_j][5:10] COLLATE "C"
        OR v_initial_slot_hashes[v_snapshot_i:v_snapshot_i][1:2] COLLATE "C" IS DISTINCT FROM v_initial_slot_hashes[v_snapshot_j:v_snapshot_j][1:2] COLLATE "C"
        OR v_initial_slot_oids[v_snapshot_i][2] IS DISTINCT FROM v_initial_slot_oids[v_snapshot_j][2]
        OR v_initial_slot_names[v_snapshot_i][2] IS DISTINCT FROM v_initial_slot_names[v_snapshot_j][2]
        OR v_initial_slot_generations[v_snapshot_i] IS DISTINCT FROM v_initial_slot_generations[v_snapshot_j]
        OR v_initial_slot_limits[v_snapshot_i] IS DISTINCT FROM v_initial_slot_limits[v_snapshot_j]
        OR v_initial_slot_resources[v_snapshot_i:v_snapshot_i][1:4] IS DISTINCT FROM v_initial_slot_resources[v_snapshot_j:v_snapshot_j][1:4]
        OR v_initial_slot_concurrency[v_snapshot_i] COLLATE "C" IS DISTINCT FROM v_initial_slot_concurrency[v_snapshot_j] COLLATE "C"
        OR v_initial_slot_event[v_snapshot_i] COLLATE "C" IS DISTINCT FROM v_initial_slot_event[v_snapshot_j] COLLATE "C")
   THEN RAISE EXCEPTION 'SELECTION_UNAVAILABLE'; END IF;
  END LOOP;
 END LOOP;
 -- Compare historical and installer aliases on shared stored facts.
 FOR v_snapshot_i IN 1..4 LOOP
  FOR v_snapshot_j IN 1..4 LOOP
   IF v_initial_slot_text[v_snapshot_i][1] COLLATE "C"=v_installer_slot_text[v_snapshot_j][1] COLLATE "C"
      AND (v_initial_slot_text[v_snapshot_i:v_snapshot_i][1:4] COLLATE "C" IS DISTINCT FROM v_installer_slot_text[v_snapshot_j:v_snapshot_j][1:4] COLLATE "C"
        OR v_initial_slot_oids[v_snapshot_i][1] IS DISTINCT FROM v_installer_slot_oids[v_snapshot_j][1]
        OR v_initial_slot_names[v_snapshot_i][1] IS DISTINCT FROM v_installer_slot_names[v_snapshot_j][1]
        OR v_initial_claim_times[v_snapshot_i] IS DISTINCT FROM v_installer_claim_times[v_snapshot_j])
   THEN RAISE EXCEPTION 'SELECTION_UNAVAILABLE'; END IF;
   IF v_initial_slot_text[v_snapshot_i][5] COLLATE "C"=v_installer_slot_text[v_snapshot_j][5] COLLATE "C"
      AND (v_initial_slot_text[v_snapshot_i:v_snapshot_i][5:10] COLLATE "C" IS DISTINCT FROM v_installer_slot_text[v_snapshot_j:v_snapshot_j][5:10] COLLATE "C"
        OR v_initial_slot_hashes[v_snapshot_i:v_snapshot_i][1:2] COLLATE "C" IS DISTINCT FROM v_installer_slot_hashes[v_snapshot_j:v_snapshot_j][1:2] COLLATE "C"
        OR v_initial_slot_oids[v_snapshot_i][2] IS DISTINCT FROM v_installer_slot_oids[v_snapshot_j][2]
        OR v_initial_slot_names[v_snapshot_i][2] IS DISTINCT FROM v_installer_slot_names[v_snapshot_j][2]
        OR v_initial_slot_generations[v_snapshot_i] IS DISTINCT FROM v_installer_slot_generations[v_snapshot_j]
        OR v_initial_slot_limits[v_snapshot_i] IS DISTINCT FROM v_installer_slot_limits[v_snapshot_j]
        OR v_initial_slot_resources[v_snapshot_i:v_snapshot_i][1:4] IS DISTINCT FROM v_installer_slot_resources[v_snapshot_j:v_snapshot_j][1:4]
        OR v_initial_slot_concurrency[v_snapshot_i] COLLATE "C" IS DISTINCT FROM v_installer_slot_concurrency[v_snapshot_j] COLLATE "C"
        OR v_initial_slot_event[v_snapshot_i] COLLATE "C" IS DISTINCT FROM v_installer_slot_event[v_snapshot_j] COLLATE "C")
   THEN RAISE EXCEPTION 'SELECTION_UNAVAILABLE'; END IF;
  END LOOP;
 END LOOP;
 -- Validate all fixed role occurrences against protected rows before deduplication.
 -- These source bounds do not qualify detoast, memory, execution, or wait costs.
 IF pg_catalog.array_length(v_trust_candidates,1) IS DISTINCT FROM 20 OR pg_catalog.array_length(v_trust_candidates,2) IS DISTINCT FROM 4
    OR pg_catalog.array_length(v_bootstrap_candidates,1) IS DISTINCT FROM 12 OR pg_catalog.array_length(v_bootstrap_candidates,2) IS DISTINCT FROM 4
 THEN RAISE EXCEPTION 'SELECTION_UNAVAILABLE'; END IF;
 FOR v_candidate_index IN 1..20 LOOP
  IF v_trust_candidates[v_candidate_index][1] IS NULL OR pg_catalog.octet_length(v_trust_candidates[v_candidate_index][1]) NOT BETWEEN 1 AND 256
     OR v_trust_candidates[v_candidate_index][2] IS NULL OR v_trust_candidates[v_candidate_index][2] !~ '^[1-9][0-9]{0,18}$'
     OR (v_trust_candidates[v_candidate_index][3] IS NOT NULL AND v_trust_candidates[v_candidate_index][3] !~ '^[a-f0-9]{64}$')
     OR NOT EXISTS (SELECT 1 FROM public."Pro262CapacityTrust" t JOIN public."Pro262CapacityBootstrapTrust" bt ON (bt."trustId",bt."generation")=(t."trustId",t."generation")
       WHERE t."trustId"=v_trust_candidates[v_candidate_index][1] AND t."generation"::TEXT=v_trust_candidates[v_candidate_index][2]
         AND (v_trust_candidates[v_candidate_index][3] IS NULL OR bt."recordHash"=v_trust_candidates[v_candidate_index][3])
         AND (v_trust_candidates[v_candidate_index][4] IS NULL OR bt."principal"::TEXT=v_trust_candidates[v_candidate_index][4]))
  THEN RAISE EXCEPTION 'SELECTION_UNAVAILABLE'; END IF;
  SELECT t."trustId" AS trust_id,t."generation" AS generation,t."issuer" AS issuer,
    t."supplierPrincipal" AS supplier,t."channelId" AS channel,t."verifierKeyId" AS verifier_key,
    t."trustRootId" AS trust_root,t."policyRevision" AS policy_revision,t."policyHash" AS policy_hash,
    t."purpose" AS purpose,t."validFrom" AS valid_from,t."validUntil" AS valid_until,t."revoked" AS revoked,
    bt."trustId" AS bootstrap_trust_id,bt."generation" AS bootstrap_generation,bt."principal" AS provisioner,
    bt."channelId" AS bootstrap_channel,bt."recordHash" AS record_hash,bt."evidenceHash" AS evidence_hash,
    bt."validUntil" AS bootstrap_valid_until
   INTO STRICT v_fact FROM public."Pro262CapacityTrust" t JOIN public."Pro262CapacityBootstrapTrust" bt
     ON (bt."trustId",bt."generation")=(t."trustId",t."generation")
   WHERE t."trustId"=v_trust_candidates[v_candidate_index][1] AND t."generation"::TEXT=v_trust_candidates[v_candidate_index][2];
  FOR v_key IN SELECT value FROM (VALUES (v_fact.trust_id),(v_fact.issuer),(v_fact.channel),(v_fact.verifier_key),
    (v_fact.trust_root),(v_fact.policy_revision),(v_fact.purpose),(v_fact.bootstrap_trust_id),(v_fact.bootstrap_channel)) AS x(value) LOOP
   IF v_key.value IS NULL OR pg_catalog.octet_length(v_key.value) NOT BETWEEN 1 AND 256 THEN RAISE EXCEPTION 'SELECTION_UNAVAILABLE'; END IF;
  END LOOP;
  FOR v_key IN SELECT value FROM (VALUES (v_fact.policy_hash),(v_fact.record_hash),(v_fact.evidence_hash)) AS x(value) LOOP
   IF v_key.value IS NULL OR v_key.value !~ '^[a-f0-9]{64}$' THEN RAISE EXCEPTION 'SELECTION_UNAVAILABLE'; END IF;
  END LOOP;
  IF v_fact.generation IS NULL OR v_fact.generation<=0 OR v_fact.bootstrap_generation IS DISTINCT FROM v_fact.generation
     OR v_fact.supplier IS NULL OR v_fact.provisioner IS NULL OR v_fact.revoked IS NULL
     OR v_fact.valid_from IS NULL OR v_fact.valid_until IS NULL OR v_fact.bootstrap_valid_until IS NULL
  THEN RAISE EXCEPTION 'SELECTION_UNAVAILABLE'; END IF;
  v_trust_source_text:=pg_catalog.array_cat(v_trust_source_text,ARRAY[[v_fact.trust_id,v_fact.issuer,v_fact.channel,v_fact.verifier_key,v_fact.trust_root,v_fact.policy_revision,v_fact.purpose,v_fact.bootstrap_trust_id,v_fact.bootstrap_channel]]);
  v_trust_source_hashes:=pg_catalog.array_cat(v_trust_source_hashes,ARRAY[[v_fact.policy_hash,v_fact.record_hash,v_fact.evidence_hash]]);
  v_trust_source_names:=pg_catalog.array_cat(v_trust_source_names,ARRAY[[v_fact.supplier,v_fact.provisioner]]);
  v_trust_source_generations:=pg_catalog.array_cat(v_trust_source_generations,ARRAY[[v_fact.generation,v_fact.bootstrap_generation]]);
  v_trust_source_revoked:=pg_catalog.array_cat(v_trust_source_revoked,ARRAY[v_fact.revoked]);
  v_trust_source_times:=pg_catalog.array_cat(v_trust_source_times,ARRAY[[v_fact.valid_from,v_fact.valid_until,v_fact.bootstrap_valid_until]]);
 END LOOP;
 IF pg_catalog.array_length(v_trust_source_text,1) IS DISTINCT FROM 20 OR pg_catalog.array_length(v_trust_source_text,2) IS DISTINCT FROM 9
    OR pg_catalog.array_length(v_trust_source_hashes,1) IS DISTINCT FROM 20 OR pg_catalog.array_length(v_trust_source_hashes,2) IS DISTINCT FROM 3
    OR pg_catalog.array_length(v_trust_source_names,1) IS DISTINCT FROM 20 OR pg_catalog.array_length(v_trust_source_names,2) IS DISTINCT FROM 2
    OR pg_catalog.array_length(v_trust_source_generations,1) IS DISTINCT FROM 20 OR pg_catalog.array_length(v_trust_source_generations,2) IS DISTINCT FROM 2
    OR pg_catalog.array_length(v_trust_source_revoked,1) IS DISTINCT FROM 20
    OR pg_catalog.array_length(v_trust_source_times,1) IS DISTINCT FROM 20 OR pg_catalog.array_length(v_trust_source_times,2) IS DISTINCT FROM 3
 THEN RAISE EXCEPTION 'SELECTION_UNAVAILABLE'; END IF;
 -- Compare source facts for aliases; keep nullable role expectations separately.
 FOR v_snapshot_i IN 1..20 LOOP
  FOR v_snapshot_j IN 1..20 LOOP
   IF v_trust_candidates[v_snapshot_i][1] COLLATE "C"=v_trust_candidates[v_snapshot_j][1] COLLATE "C"
      AND v_trust_candidates[v_snapshot_i][2]=v_trust_candidates[v_snapshot_j][2]
      AND (v_trust_source_text[v_snapshot_i:v_snapshot_i][1:9] COLLATE "C" IS DISTINCT FROM v_trust_source_text[v_snapshot_j:v_snapshot_j][1:9] COLLATE "C"
       OR v_trust_source_hashes[v_snapshot_i:v_snapshot_i][1:3] COLLATE "C" IS DISTINCT FROM v_trust_source_hashes[v_snapshot_j:v_snapshot_j][1:3] COLLATE "C"
       OR v_trust_source_names[v_snapshot_i:v_snapshot_i][1:2] IS DISTINCT FROM v_trust_source_names[v_snapshot_j:v_snapshot_j][1:2]
       OR v_trust_source_generations[v_snapshot_i:v_snapshot_i][1:2] IS DISTINCT FROM v_trust_source_generations[v_snapshot_j:v_snapshot_j][1:2]
       OR v_trust_source_revoked[v_snapshot_i] IS DISTINCT FROM v_trust_source_revoked[v_snapshot_j]
       OR v_trust_source_times[v_snapshot_i:v_snapshot_i][1:3] IS DISTINCT FROM v_trust_source_times[v_snapshot_j:v_snapshot_j][1:3])
   THEN RAISE EXCEPTION 'SELECTION_UNAVAILABLE'; END IF;
  END LOOP;
 END LOOP;
 FOR v_fact IN SELECT v_trust_candidates[i][1] COLLATE "C" AS trust_id,v_trust_candidates[i][2]::BIGINT AS generation,
    pg_catalog.min(v_trust_candidates[i][3] COLLATE "C") AS low_hash,pg_catalog.max(v_trust_candidates[i][3] COLLATE "C") AS high_hash,
    pg_catalog.min(v_trust_candidates[i][4] COLLATE "C") AS low_issuer,pg_catalog.max(v_trust_candidates[i][4] COLLATE "C") AS high_issuer
   FROM pg_catalog.generate_subscripts(v_trust_candidates,1) AS indexes(i)
   GROUP BY v_trust_candidates[i][1] COLLATE "C",v_trust_candidates[i][2]::BIGINT ORDER BY 1,2 LOOP
  IF v_fact.low_hash IS DISTINCT FROM v_fact.high_hash OR v_fact.low_issuer IS DISTINCT FROM v_fact.high_issuer THEN RAISE EXCEPTION 'SELECTION_UNAVAILABLE'; END IF;
  v_trust_inventory:=pg_catalog.array_cat(v_trust_inventory,ARRAY[[v_fact.trust_id,v_fact.generation::TEXT]]);
  v_bootstrap_trust_inventory:=pg_catalog.array_cat(v_bootstrap_trust_inventory,ARRAY[[v_fact.trust_id,v_fact.generation::TEXT]]);
 END LOOP;
 FOR v_candidate_index IN 1..12 LOOP
  -- The combined ceiling permits a 288-byte opaque historical kind; it does
  -- not establish compatibility for every historical kind. Derived roles retain
  -- their exact prefixes and their separately bounded 1..256-byte suffixes.
  IF v_bootstrap_candidates[v_candidate_index][1] IS NULL OR pg_catalog.octet_length(v_bootstrap_candidates[v_candidate_index][1]) NOT BETWEEN 1 AND 288
     OR v_bootstrap_candidates[v_candidate_index][2] IS NULL OR v_bootstrap_candidates[v_candidate_index][2] !~ '^[a-f0-9]{64}$'
     OR v_bootstrap_candidates[v_candidate_index][3] IS NULL OR v_bootstrap_candidates[v_candidate_index][3] !~ '^[a-f0-9]{64}$'
     OR NOT EXISTS (SELECT 1 FROM public."Pro262CapacityBootstrapBaseline" b WHERE b."kind"=v_bootstrap_candidates[v_candidate_index][1]
       AND b."recordHash"=v_bootstrap_candidates[v_candidate_index][2] AND b."evidenceHash"=v_bootstrap_candidates[v_candidate_index][3]
       AND (v_bootstrap_candidates[v_candidate_index][4] IS NULL OR b."publisherPrincipal"::TEXT=v_bootstrap_candidates[v_candidate_index][4]))
  THEN RAISE EXCEPTION 'SELECTION_UNAVAILABLE'; END IF;
  SELECT b."kind" AS kind,b."publisherPrincipal" AS publisher,b."recordHash" AS record_hash,
    b."evidenceHash" AS evidence_hash,b."validUntil" AS valid_until
   INTO STRICT v_fact FROM public."Pro262CapacityBootstrapBaseline" b
   WHERE b."kind"=v_bootstrap_candidates[v_candidate_index][1]
     AND b."recordHash"=v_bootstrap_candidates[v_candidate_index][2] AND b."evidenceHash"=v_bootstrap_candidates[v_candidate_index][3]
     AND (v_bootstrap_candidates[v_candidate_index][4] IS NULL OR b."publisherPrincipal"::TEXT=v_bootstrap_candidates[v_candidate_index][4]);
  IF v_fact.kind IS NULL OR pg_catalog.octet_length(v_fact.kind) NOT BETWEEN 1 AND 288
     OR v_fact.record_hash IS NULL OR v_fact.record_hash !~ '^[a-f0-9]{64}$'
     OR v_fact.evidence_hash IS NULL OR v_fact.evidence_hash !~ '^[a-f0-9]{64}$'
     OR v_fact.publisher IS NULL OR v_fact.valid_until IS NULL
  THEN RAISE EXCEPTION 'SELECTION_UNAVAILABLE'; END IF;
  v_bootstrap_source_keys:=pg_catalog.array_cat(v_bootstrap_source_keys,ARRAY[v_fact.kind]);
  v_bootstrap_source_hashes:=pg_catalog.array_cat(v_bootstrap_source_hashes,ARRAY[[v_fact.record_hash,v_fact.evidence_hash]]);
  v_bootstrap_source_publishers:=pg_catalog.array_cat(v_bootstrap_source_publishers,ARRAY[v_fact.publisher]);
  v_bootstrap_source_times:=pg_catalog.array_cat(v_bootstrap_source_times,ARRAY[v_fact.valid_until]);
 END LOOP;
 IF pg_catalog.array_length(v_bootstrap_source_keys,1) IS DISTINCT FROM 12
    OR pg_catalog.array_length(v_bootstrap_source_hashes,1) IS DISTINCT FROM 12 OR pg_catalog.array_length(v_bootstrap_source_hashes,2) IS DISTINCT FROM 2
    OR pg_catalog.array_length(v_bootstrap_source_publishers,1) IS DISTINCT FROM 12
    OR pg_catalog.array_length(v_bootstrap_source_times,1) IS DISTINCT FROM 12
 THEN RAISE EXCEPTION 'SELECTION_UNAVAILABLE'; END IF;
 -- Compare actual source rows for equal keys before grouping role expectations.
 FOR v_snapshot_i IN 1..12 LOOP
  FOR v_snapshot_j IN 1..12 LOOP
   IF v_bootstrap_source_keys[v_snapshot_i] COLLATE "C"=v_bootstrap_source_keys[v_snapshot_j] COLLATE "C"
      AND (v_bootstrap_source_hashes[v_snapshot_i:v_snapshot_i][1:2] COLLATE "C" IS DISTINCT FROM v_bootstrap_source_hashes[v_snapshot_j:v_snapshot_j][1:2] COLLATE "C"
       OR v_bootstrap_source_publishers[v_snapshot_i] IS DISTINCT FROM v_bootstrap_source_publishers[v_snapshot_j]
       OR v_bootstrap_source_times[v_snapshot_i] IS DISTINCT FROM v_bootstrap_source_times[v_snapshot_j])
   THEN RAISE EXCEPTION 'SELECTION_UNAVAILABLE'; END IF;
  END LOOP;
 END LOOP;
 FOR v_fact IN SELECT v_bootstrap_candidates[i][1] COLLATE "C" AS kind,
    pg_catalog.min(v_bootstrap_candidates[i][2] COLLATE "C") AS low_record,pg_catalog.max(v_bootstrap_candidates[i][2] COLLATE "C") AS high_record,
    pg_catalog.min(v_bootstrap_candidates[i][3] COLLATE "C") AS low_evidence,pg_catalog.max(v_bootstrap_candidates[i][3] COLLATE "C") AS high_evidence,
    pg_catalog.min(v_bootstrap_candidates[i][4] COLLATE "C") AS low_publisher,pg_catalog.max(v_bootstrap_candidates[i][4] COLLATE "C") AS high_publisher
   FROM pg_catalog.generate_subscripts(v_bootstrap_candidates,1) AS indexes(i)
   GROUP BY v_bootstrap_candidates[i][1] COLLATE "C" ORDER BY 1 LOOP
  IF v_fact.low_record IS DISTINCT FROM v_fact.high_record OR v_fact.low_evidence IS DISTINCT FROM v_fact.high_evidence OR v_fact.low_publisher IS DISTINCT FROM v_fact.high_publisher
  THEN RAISE EXCEPTION 'SELECTION_UNAVAILABLE'; END IF;
  v_bootstrap_inventory:=pg_catalog.array_cat(v_bootstrap_inventory,ARRAY[[v_fact.kind,v_fact.low_record,v_fact.low_evidence]]);
 END LOOP;
 -- Validate all 28 raw facts before grouping; these structural caps do not
 -- qualify detoast, allocation, SQL execution, or wait bounds.
 IF pg_catalog.array_length(v_charge_candidates,1) IS DISTINCT FROM 28
    OR pg_catalog.array_length(v_charge_candidates,2) IS DISTINCT FROM 4
 THEN RAISE EXCEPTION 'SELECTION_UNAVAILABLE'; END IF;
 FOR v_candidate_index IN 1..28 LOOP
  IF v_charge_candidates[v_candidate_index][1] IS NULL
     OR pg_catalog.octet_length(v_charge_candidates[v_candidate_index][1]) NOT BETWEEN 1 AND 256
     OR v_charge_candidates[v_candidate_index][2] IS NULL
     OR pg_catalog.octet_length(v_charge_candidates[v_candidate_index][2]) NOT BETWEEN 1 AND
        CASE WHEN v_charge_candidates[v_candidate_index][4]='publisher' THEN 276 ELSE 256 END
     OR v_charge_candidates[v_candidate_index][3] IS NULL
     OR v_charge_candidates[v_candidate_index][3] !~ '^[a-f0-9]{64}$'
     OR v_charge_candidates[v_candidate_index][4] NOT IN ('ordinary','publisher')
  THEN RAISE EXCEPTION 'SELECTION_UNAVAILABLE'; END IF;
 END LOOP;
 -- Retain each protected charge occurrence and compare aliases before deduplication.
 FOR v_candidate_index IN 1..28 LOOP
  SELECT c."kind" AS kind,c."eventKey" AS event_key,c."bindingHash" AS binding_hash,c."amount" AS amount
   INTO STRICT v_snapshot_charge FROM public."Pro262CapacityControlCharge" c
   WHERE c."kind" COLLATE "C"=v_charge_candidates[v_candidate_index][1] COLLATE "C"
     AND c."eventKey" COLLATE "C"=v_charge_candidates[v_candidate_index][2] COLLATE "C";
  IF v_snapshot_charge.binding_hash IS DISTINCT FROM v_charge_candidates[v_candidate_index][3]
     OR v_snapshot_charge.amount IS NULL OR v_snapshot_charge.amount<=0
     OR v_snapshot_charge.amount>9223372036854775807 OR pg_catalog.scale(v_snapshot_charge.amount)>19
     OR v_snapshot_charge.amount<>pg_catalog.trunc(v_snapshot_charge.amount)
  THEN RAISE EXCEPTION 'SELECTION_UNAVAILABLE'; END IF;
  v_charge_source_text:=pg_catalog.array_cat(v_charge_source_text,ARRAY[[v_snapshot_charge.kind,v_snapshot_charge.event_key,v_snapshot_charge.binding_hash]]);
  v_charge_source_amount:=pg_catalog.array_cat(v_charge_source_amount,ARRAY[v_snapshot_charge.amount]);
 END LOOP;
 IF pg_catalog.array_length(v_charge_source_text,1) IS DISTINCT FROM 28 OR pg_catalog.array_length(v_charge_source_text,2) IS DISTINCT FROM 3
    OR pg_catalog.array_length(v_charge_source_amount,1) IS DISTINCT FROM 28
 THEN RAISE EXCEPTION 'SELECTION_UNAVAILABLE'; END IF;
 FOR v_snapshot_i IN 1..28 LOOP
  FOR v_snapshot_j IN 1..28 LOOP
   IF (v_charge_source_text[v_snapshot_i][1] COLLATE "C",v_charge_source_text[v_snapshot_i][2] COLLATE "C")
      IS NOT DISTINCT FROM (v_charge_source_text[v_snapshot_j][1] COLLATE "C",v_charge_source_text[v_snapshot_j][2] COLLATE "C")
      AND (v_charge_source_text[v_snapshot_i][3] COLLATE "C" IS DISTINCT FROM v_charge_source_text[v_snapshot_j][3] COLLATE "C"
        OR v_charge_source_amount[v_snapshot_i] IS DISTINCT FROM v_charge_source_amount[v_snapshot_j]
        OR pg_catalog.scale(v_charge_source_amount[v_snapshot_i]) IS DISTINCT FROM pg_catalog.scale(v_charge_source_amount[v_snapshot_j]))
   THEN RAISE EXCEPTION 'SELECTION_UNAVAILABLE'; END IF;
  END LOOP;
 END LOOP;
 -- Compare hashes across every route before deduplication, in C key order.
 FOR v_fact IN
  SELECT v_charge_candidates[i][1] COLLATE "C" AS kind,
         v_charge_candidates[i][2] COLLATE "C" AS event_key,
         pg_catalog.min(v_charge_candidates[i][3] COLLATE "C") AS low_hash,
         pg_catalog.max(v_charge_candidates[i][3] COLLATE "C") AS high_hash
  FROM pg_catalog.generate_subscripts(v_charge_candidates,1) AS indexes(i)
  GROUP BY v_charge_candidates[i][1] COLLATE "C",v_charge_candidates[i][2] COLLATE "C"
  ORDER BY v_charge_candidates[i][1] COLLATE "C",v_charge_candidates[i][2] COLLATE "C"
 LOOP
  IF v_fact.low_hash IS DISTINCT FROM v_fact.high_hash THEN RAISE EXCEPTION 'SELECTION_UNAVAILABLE'; END IF;
  v_charge_inventory:=pg_catalog.array_cat(v_charge_inventory,ARRAY[[v_fact.kind,v_fact.event_key,v_fact.low_hash]]);
  -- Inventory only; this does not establish charge qualification or locks.
 END LOOP;
 -- Derive only exact kind keys from the same 28 validated facts. No baseline
 -- attributes, enabled state or amounts are inferred from charge occurrences.
 FOR v_fact IN
  SELECT v_charge_candidates[i][1] COLLATE "C" AS kind
  FROM pg_catalog.generate_subscripts(v_charge_candidates,1) AS indexes(i)
  GROUP BY v_charge_candidates[i][1] COLLATE "C"
  ORDER BY v_charge_candidates[i][1] COLLATE "C"
 LOOP
  SELECT cb."kind" AS kind,cb."physicalIdentity" AS physical_identity,cb."controlProofIdentity" AS proof_identity,
    cb."coverageEvidenceHash" AS evidence_hash,cb."coverageContract" AS coverage_contract,
    cb."allocated" AS allocated,cb."archiveBaselineUsed" AS archive_used,cb."eventWorstCase" AS event_worst,
    cb."maxClosedScopeBytes" AS max_closed,cb."spent" AS spent,cb."enabled" AS enabled
   INTO STRICT v_snapshot_baseline FROM public."Pro262CapacityControlBaseline" cb
   WHERE cb."kind" COLLATE "C"=v_fact.kind COLLATE "C";
  FOR v_key IN SELECT x.value FROM (VALUES (v_snapshot_baseline.physical_identity),(v_snapshot_baseline.proof_identity),(v_snapshot_baseline.coverage_contract)) AS x(value) LOOP
   IF v_key.value IS NULL OR pg_catalog.octet_length(v_key.value) NOT BETWEEN 1 AND 256 THEN RAISE EXCEPTION 'SELECTION_UNAVAILABLE'; END IF;
  END LOOP;
  IF v_snapshot_baseline.evidence_hash IS NULL OR v_snapshot_baseline.evidence_hash !~ '^[a-f0-9]{64}$'
     OR v_snapshot_baseline.enabled IS NULL THEN RAISE EXCEPTION 'SELECTION_UNAVAILABLE'; END IF;
  FOR v_key IN SELECT x.value FROM (VALUES (v_snapshot_baseline.allocated),(v_snapshot_baseline.archive_used),(v_snapshot_baseline.event_worst),(v_snapshot_baseline.max_closed),(v_snapshot_baseline.spent)) AS x(value) LOOP
   IF v_key.value IS NULL OR v_key.value<0 OR v_key.value>9223372036854775807 OR pg_catalog.scale(v_key.value)>19
      OR v_key.value<>pg_catalog.trunc(v_key.value) THEN RAISE EXCEPTION 'SELECTION_UNAVAILABLE'; END IF;
  END LOOP;
  IF v_snapshot_baseline.allocated=0 OR v_snapshot_baseline.event_worst=0 OR v_snapshot_baseline.max_closed=0
     OR v_snapshot_baseline.spent>v_snapshot_baseline.allocated THEN RAISE EXCEPTION 'SELECTION_UNAVAILABLE'; END IF;
  v_control_baseline_inventory:=pg_catalog.array_cat(v_control_baseline_inventory,ARRAY[[v_fact.kind]]);
  v_control_baseline_source_text:=pg_catalog.array_cat(v_control_baseline_source_text,ARRAY[[v_snapshot_baseline.kind,v_snapshot_baseline.physical_identity,v_snapshot_baseline.proof_identity,v_snapshot_baseline.evidence_hash,v_snapshot_baseline.coverage_contract]]);
  v_control_baseline_source_numbers:=pg_catalog.array_cat(v_control_baseline_source_numbers,ARRAY[[v_snapshot_baseline.allocated,v_snapshot_baseline.archive_used,v_snapshot_baseline.event_worst,v_snapshot_baseline.max_closed,v_snapshot_baseline.spent]]);
  v_control_baseline_source_enabled:=pg_catalog.array_cat(v_control_baseline_source_enabled,ARRAY[v_snapshot_baseline.enabled]);
 END LOOP;
 IF pg_catalog.array_length(v_control_baseline_source_text,1) IS DISTINCT FROM pg_catalog.array_length(v_control_baseline_inventory,1)
    OR pg_catalog.array_length(v_control_baseline_source_text,1) NOT BETWEEN 1 AND 28
    OR pg_catalog.array_length(v_control_baseline_source_text,2) IS DISTINCT FROM 5
    OR pg_catalog.array_length(v_control_baseline_source_numbers,1) IS DISTINCT FROM pg_catalog.array_length(v_control_baseline_inventory,1)
    OR pg_catalog.array_length(v_control_baseline_source_numbers,2) IS DISTINCT FROM 5
    OR pg_catalog.array_length(v_control_baseline_source_enabled,1) IS DISTINCT FROM pg_catalog.array_length(v_control_baseline_inventory,1)
 THEN RAISE EXCEPTION 'SELECTION_UNAVAILABLE'; END IF;
 -- Fixed presence snapshot keyed only by the selected control ID. It does not
 -- exclude absent keys or establish concurrency safety. After qualified locks,
 -- re-read all six and validate exact identities using the existing checks.
 SELECT ARRAY[
  EXISTS (SELECT 1 FROM public."Pro273QualificationInputDescriptor" d WHERE d."controlId"=v_route.control_id),
  EXISTS (SELECT 1 FROM public."Pro273QualifierDescriptorProvenance" p WHERE p."controlId"=v_route.control_id),
  EXISTS (SELECT 1 FROM public."Pro273QualifierDescriptorLinkage" l WHERE l."controlId"=v_route.control_id),
  EXISTS (SELECT 1 FROM public."Pro273QualifierDescriptorProof" q WHERE q."controlId"=v_route.control_id),
  EXISTS (SELECT 1 FROM public."Pro273QualificationInputState" st WHERE st."controlId"=v_route.control_id),
  EXISTS (SELECT 1 FROM public."Pro273QualificationTransitionReceipt" t WHERE t."controlId"=v_route.control_id AND t."transitionOrdinal"=1)
 ] INTO v_descriptor_presence;
 IF v_descriptor_presence=ARRAY[FALSE,FALSE,FALSE,FALSE,FALSE,FALSE] THEN
  v_descriptor_present:=FALSE;
 ELSIF v_descriptor_presence=ARRAY[TRUE,TRUE,TRUE,TRUE,TRUE,TRUE] THEN
  v_descriptor_present:=TRUE;
  SELECT ARRAY[d."controlId",d."allocationId",d."sourceIdentity",d."namespace",d."project",d."deployment",d."environment",d."credentialEpoch",d."launchEpoch",d."observerGroupProof",d."physicalIdentity",d."physicalProofIdentity",d."baselinePartitionId",d."controlChargeKind",d."controlChargeEventKey",p."controlId",p."bootstrapKind",p."trustId",p."inputClaimId",p."sessionClaimId",p."eventId",p."chargeKind",p."chargeEventKey"],
         ARRAY[d."descriptorCoreHash",d."allocationCoreHash",d."bootstrapRecordHash",p."coreHash",p."bootstrapRecordHash",p."bootstrapEvidenceHash",p."trustRecordHash",p."capturedHash",p."evidenceHash",p."chargeBindingHash"],
         ARRAY[d."principalOid",p."publisherPrincipalOid"],
         ARRAY[d."principalName",p."publisherPrincipalName"],
         ARRAY[p."trustGeneration",p."capturedLength",p."evidenceLength"],
         ARRAY[d."expiresAt"]
   INTO v_descriptor_text,v_descriptor_hashes,v_descriptor_oids,v_descriptor_names,v_descriptor_numbers,v_descriptor_times
   FROM public."Pro273QualificationInputDescriptor" d
   JOIN public."Pro273QualifierDescriptorProvenance" p ON (p."controlId",p."coreHash")=(d."controlId",d."descriptorCoreHash")
   WHERE d."controlId"=v_route.control_id;
  IF pg_catalog.array_length(v_descriptor_text,1) IS DISTINCT FROM 23
     OR pg_catalog.array_length(v_descriptor_hashes,1) IS DISTINCT FROM 10
     OR pg_catalog.array_length(v_descriptor_oids,1) IS DISTINCT FROM 2
     OR pg_catalog.array_length(v_descriptor_names,1) IS DISTINCT FROM 2
     OR pg_catalog.array_length(v_descriptor_numbers,1) IS DISTINCT FROM 3
     OR pg_catalog.array_length(v_descriptor_times,1) IS DISTINCT FROM 1
     OR EXISTS (SELECT 1 FROM pg_catalog.unnest(v_descriptor_text) WITH ORDINALITY AS x(value,cell) WHERE x.value IS NULL OR pg_catalog.octet_length(x.value) NOT BETWEEN 1 AND CASE WHEN x.cell=17 THEN 288 ELSE 256 END OR (x.cell=17 AND (NOT pg_catalog.starts_with(x.value,'SELECTION_QUALIFIER_CONTROL:') OR pg_catalog.octet_length(pg_catalog.substring(x.value,29)) NOT BETWEEN 1 AND 256)))
     OR EXISTS (SELECT 1 FROM pg_catalog.unnest(v_descriptor_hashes) x WHERE x IS NULL OR x !~ '^[a-f0-9]{64}$')
     OR EXISTS (SELECT 1 FROM pg_catalog.unnest(v_descriptor_names) x WHERE x IS NULL OR pg_catalog.octet_length(x::TEXT) NOT BETWEEN 1 AND 256)
     OR EXISTS (SELECT 1 FROM pg_catalog.unnest(v_descriptor_oids) x WHERE x IS NULL OR x=0)
     OR EXISTS (SELECT 1 FROM pg_catalog.unnest(v_descriptor_numbers) x WHERE x IS NULL OR x<=0)
     OR v_descriptor_times[1] IS NULL THEN RAISE EXCEPTION 'SELECTION_UNAVAILABLE'; END IF;
  -- Retain the four companion rows under their stored composite identities.
  -- The 256-byte router bound is a provisional compatibility restriction,
  -- not qualified detoast or resource safety.
  SELECT ARRAY[l."controlId",l."expectationId",l."dispatchAttemptId",l."sessionClaimId",l."inputClaimId",l."eventId",q."controlId",q."observerGroupProof",st."controlId",st."state",st."connectionState",t."controlId",t."fromState",t."toState",t."fromConnectionState",t."toConnectionState",t."receiptId"],
         ARRAY[l."coreHash",q."coreHash",t."bindingHash"], ARRAY[st."transitionOrdinal",t."transitionOrdinal"],
         ARRAY[l."constructionTransactionId"], ARRAY[t."occurredAt"]
   INTO v_descriptor_companion_text,v_descriptor_companion_hashes,v_descriptor_companion_numbers,v_descriptor_companion_transactions,v_descriptor_companion_times
   FROM public."Pro273QualificationInputDescriptor" d
   JOIN public."Pro273QualifierDescriptorProvenance" p ON (p."controlId",p."coreHash")=(d."controlId",d."descriptorCoreHash")
   JOIN public."Pro273QualifierDescriptorLinkage" l ON (l."controlId",l."coreHash",l."sessionClaimId",l."inputClaimId",l."eventId")=(p."controlId",p."coreHash",p."sessionClaimId",p."inputClaimId",p."eventId")
   JOIN public."Pro273QualifierDescriptorProof" q ON (q."controlId",q."coreHash")=(l."controlId",l."coreHash")
   JOIN public."Pro273QualificationInputState" st ON st."controlId"=d."controlId"
   JOIN public."Pro273QualificationTransitionReceipt" t ON (t."controlId",t."transitionOrdinal")=(d."controlId",1)
   WHERE d."controlId"=v_route.control_id;
  IF pg_catalog.array_length(v_descriptor_companion_text,1) IS DISTINCT FROM 17
     OR pg_catalog.array_length(v_descriptor_companion_hashes,1) IS DISTINCT FROM 3
     OR pg_catalog.array_length(v_descriptor_companion_numbers,1) IS DISTINCT FROM 2
     OR pg_catalog.array_length(v_descriptor_companion_transactions,1) IS DISTINCT FROM 1
     OR pg_catalog.array_length(v_descriptor_companion_times,1) IS DISTINCT FROM 1
     OR EXISTS (SELECT 1 FROM pg_catalog.unnest(v_descriptor_companion_text) x WHERE x IS NULL OR pg_catalog.octet_length(x) NOT BETWEEN 1 AND 256)
     OR EXISTS (SELECT 1 FROM pg_catalog.unnest(v_descriptor_companion_hashes) x WHERE x IS NULL OR x !~ '^[a-f0-9]{64}$')
     OR EXISTS (SELECT 1 FROM pg_catalog.unnest(v_descriptor_companion_numbers) x WHERE x IS NULL OR x<=0)
     OR v_descriptor_companion_transactions[1] IS NULL OR v_descriptor_companion_times[1] IS NULL THEN RAISE EXCEPTION 'SELECTION_UNAVAILABLE'; END IF;
 ELSE RAISE EXCEPTION 'SELECTION_UNAVAILABLE'; END IF;
 -- These sorted deduplicated unions are unqualified inventory subsets.
 -- Missing: full relation lock schedule, receipt pre-helper dispatch, and
 -- post-lock and post-reentry reread of these snapshots and descriptor rows.
 -- Missing: retained/locked charge inventory; complete combined bootstrap/trust and
 -- capacity ControlBaseline inventories and accounting locks; descriptor post-lock reread;
 -- qualified bounds, issuer/fence/currentness and ordered locking; exact raw
 -- accounting expiry checks and qualification remain missing;
 -- bytes, canonical hash, prior-xid and authentication checks; full reservation,
 -- funding and lock qualification and full reservation-record validation. Historical
 -- slot/bootstrap hash equality is not issuer or original provisioning authentication;
 -- constructor/installer slot provisioning and observer scope coverage remain unresolved. This scalar
 -- subset is neither authenticated authority nor a complete prelock.
 v_projection:=ROW(
