CREATE TABLE public."Pro273QualificationProcessObservation" (
 "controlId" TEXT NOT NULL, "credentialEpoch" TEXT NOT NULL, "launchEpoch" TEXT NOT NULL, "observationId" TEXT NOT NULL UNIQUE, "receiptId" TEXT NOT NULL UNIQUE,
 "trustId" TEXT NOT NULL, "trustGeneration" BIGINT NOT NULL, "inputClaimId" TEXT NOT NULL UNIQUE,
 "targetPrincipal" NAME NOT NULL, "targetOid" OID NOT NULL, "targetPid" INTEGER NOT NULL CHECK ("targetPid">0), "targetBackendStart" TIMESTAMPTZ NOT NULL,
 "host" TEXT NOT NULL, "boot" TEXT NOT NULL, "processTree" TEXT NOT NULL, "observerPrincipal" NAME NOT NULL, "observerOid" OID NOT NULL,
 "validUntil" TIMESTAMPTZ NOT NULL, "observation" JSONB NOT NULL, "captured" BYTEA NOT NULL,
 "capturedHash" TEXT NOT NULL CHECK ("capturedHash" ~ '^[a-f0-9]{64}$'), "evidence" BYTEA NOT NULL, "evidenceHash" TEXT NOT NULL CHECK ("evidenceHash" ~ '^[a-f0-9]{64}$'),
 PRIMARY KEY ("controlId","credentialEpoch","launchEpoch"),
 FOREIGN KEY ("controlId","credentialEpoch","launchEpoch") REFERENCES public."Pro273QualificationInputDescriptor"("controlId","credentialEpoch","launchEpoch") ON UPDATE RESTRICT ON DELETE RESTRICT,
 FOREIGN KEY ("inputClaimId") REFERENCES public."Pro262CapacityObserverInputClaim"("inputClaimId") ON UPDATE RESTRICT ON DELETE RESTRICT,
 FOREIGN KEY ("trustId","trustGeneration") REFERENCES public."Pro262CapacityTrust"("trustId","generation") ON UPDATE RESTRICT ON DELETE RESTRICT
);
CREATE TABLE public."Pro273QualifierCleanupReceipt" (
 "controlId" TEXT NOT NULL, "credentialEpoch" TEXT NOT NULL, "launchEpoch" TEXT NOT NULL, "receiptId" TEXT NOT NULL UNIQUE,
 "inputClaimId" TEXT NOT NULL UNIQUE, "trustId" TEXT NOT NULL, "trustGeneration" BIGINT NOT NULL, "observerPrincipal" NAME NOT NULL, "observerOid" OID NOT NULL,
 "observation" JSONB NOT NULL, "captured" BYTEA NOT NULL, "capturedLength" BIGINT NOT NULL, "capturedHash" TEXT NOT NULL CHECK ("capturedHash" ~ '^[a-f0-9]{64}$'),
 "evidence" BYTEA NOT NULL, "evidenceLength" BIGINT NOT NULL, "evidenceHash" TEXT NOT NULL CHECK ("evidenceHash" ~ '^[a-f0-9]{64}$'),
 PRIMARY KEY ("controlId","credentialEpoch","launchEpoch","receiptId"), UNIQUE ("controlId","credentialEpoch","launchEpoch"),
 FOREIGN KEY ("controlId","credentialEpoch","launchEpoch") REFERENCES public."Pro273QualificationInputDescriptor"("controlId","credentialEpoch","launchEpoch") ON UPDATE RESTRICT ON DELETE RESTRICT,
 FOREIGN KEY ("inputClaimId") REFERENCES public."Pro262CapacityObserverInputClaim"("inputClaimId") ON UPDATE RESTRICT ON DELETE RESTRICT,
 FOREIGN KEY ("trustId","trustGeneration") REFERENCES public."Pro262CapacityTrust"("trustId","generation") ON UPDATE RESTRICT ON DELETE RESTRICT,
 CHECK ("capturedLength">0 AND "capturedLength"=pg_catalog.octet_length("captured")), CHECK ("evidenceLength">0 AND "evidenceLength"=pg_catalog.octet_length("evidence"))
);
CREATE TABLE public."Pro273QualifierClosedScopeReceipt" (
 "controlId" TEXT NOT NULL, "credentialEpoch" TEXT NOT NULL, "launchEpoch" TEXT NOT NULL, "receiptId" TEXT NOT NULL UNIQUE,
 "inputClaimId" TEXT NOT NULL UNIQUE, "trustId" TEXT NOT NULL, "trustGeneration" BIGINT NOT NULL, "observerPrincipal" NAME NOT NULL, "observerOid" OID NOT NULL,
 "observation" JSONB NOT NULL, "captured" BYTEA NOT NULL, "capturedLength" BIGINT NOT NULL, "capturedHash" TEXT NOT NULL CHECK ("capturedHash" ~ '^[a-f0-9]{64}$'),
 "evidence" BYTEA NOT NULL, "evidenceLength" BIGINT NOT NULL, "evidenceHash" TEXT NOT NULL CHECK ("evidenceHash" ~ '^[a-f0-9]{64}$'),
 PRIMARY KEY ("controlId","credentialEpoch","launchEpoch","receiptId"), UNIQUE ("controlId","credentialEpoch","launchEpoch"),
 FOREIGN KEY ("controlId","credentialEpoch","launchEpoch") REFERENCES public."Pro273QualificationInputDescriptor"("controlId","credentialEpoch","launchEpoch") ON UPDATE RESTRICT ON DELETE RESTRICT,
 FOREIGN KEY ("inputClaimId") REFERENCES public."Pro262CapacityObserverInputClaim"("inputClaimId") ON UPDATE RESTRICT ON DELETE RESTRICT,
 FOREIGN KEY ("trustId","trustGeneration") REFERENCES public."Pro262CapacityTrust"("trustId","generation") ON UPDATE RESTRICT ON DELETE RESTRICT,
 CHECK ("capturedLength">0 AND "capturedLength"=pg_catalog.octet_length("captured")), CHECK ("evidenceLength">0 AND "evidenceLength"=pg_catalog.octet_length("evidence"))
);
